function loadSession() {
  const saved = localStorage.getItem("jackson-syncerp-session");
  return saved ? JSON.parse(saved) : null;
}

function saveSession(user) {
  state.user = user;
  state.role = user.role;
  state.view = "dashboard";
  if (!canView(state.view)) state.view = roleConfig[user.role]?.defaultView || "dashboard";
  applyMapOwnerView(ownerViewForRole(user.role));
  localStorage.setItem("jackson-syncerp-session", JSON.stringify(user));
}

function clearSession() {
  state.user = null;
  localStorage.removeItem("jackson-syncerp-session");
}

function loadData() {
  const saved = localStorage.getItem("jackson-syncerp-data");
  if (!saved) return normalizeDataShape(structuredClone(seedData));
  const parsed = JSON.parse(saved);
  if (parsed?.meta?.dataVersion !== seedData?.meta?.dataVersion) {
    localStorage.setItem("jackson-syncerp-data-stale", "true");
    return normalizeDataShape(structuredClone(seedData));
  }
  return normalizeDataShape(parsed);
}

function normalizeDataShape(data) {
  const arrayCollections = [
    "users", "roles", "crews", "projects", "tasks", "documents", "fieldEvidence", "photoEvidence", "siteSurveys", "obstacles",
    "dailies", "dailyProduction", "dailyLabor", "dailyEquipment", "dailyMaterials", "timeEntries", "people",
    "equipment", "invoices", "invoiceSubmissions", "billingReadiness", "retainageLedger", "safety", "qcCloseouts",
    "formSubmissions", "offlineSyncQueue", "fieldUploadQueue", "customerContactLog", "packetLocks", "alertControls",
    "cashReceipts", "cashDepositBatches", "collectionSubmissions", "collectionDecisionPackets", "billingTaskCloseouts",
    "packageSnapshots", "contractRules", "costBlockers", "squanScores", "costCodes", "unitPrices", "priceSheetItems",
    "squanImports", "squanProductionLines", "squanMapFeatures", "productionDailies", "productionLines", "contractorPayables",
    "techWorkEntries", "billingLedger", "quantityReconciliation", "projectUnits"
  ];
  arrayCollections.forEach(key => {
    if (!Array.isArray(data[key])) data[key] = [];
  });
  data.company = data.company || structuredClone(seedData.company || {});
  data.meta = { ...(data.meta || {}), dataVersion: seedData?.meta?.dataVersion };
  ensureProductionDefaults(data);
  return data;
}

function persist(message = "") {
  const savedAt = new Date().toISOString();
  state.lastSavedAt = savedAt;
  state.saveMessage = message || (state.apiOnline ? "Saved locally; server API online" : "Saved locally");
  state.data.meta = {
    ...(state.data.meta || {}),
    dataVersion: seedData?.meta?.dataVersion,
    lastLocalSaveAt: savedAt,
    saveMode: state.apiOnline ? "Server API + local browser backup" : "Local browser draft"
  };
  localStorage.setItem("jackson-syncerp-data", JSON.stringify(state.data));
  localStorage.setItem("jackson-syncerp-last-saved-at", savedAt);
  localStorage.setItem("jackson-syncerp-save-message", state.saveMessage);
}

async function syncFromApi() {
  try {
    const response = await fetch("/api/bootstrap", { cache: "no-store" });
    if (!response.ok) throw new Error("API bootstrap failed");
    const data = await response.json();
    state.data = normalizeDataShape(data);
    state.apiOnline = true;
    state.lastSyncedAt = new Date().toISOString();
    localStorage.setItem("jackson-syncerp-last-synced-at", state.lastSyncedAt);
    localStorage.removeItem("jackson-syncerp-data-stale");
    persist("Synced from server");
    render();
  } catch (error) {
    state.apiOnline = false;
    state.saveMessage = "Working from local browser data";
  }
}

function resetLocalDemoData() {
  state.data = structuredClone(seedData);
  state.apiOnline = false;
  state.selectedRecord = null;
  state.search = "";
  state.lastSyncedAt = "";
  localStorage.removeItem("jackson-syncerp-data-stale");
  localStorage.removeItem("jackson-syncerp-last-synced-at");
  appendAuditLocal("data.reset-local-demo", { by: state.user?.name || "User" });
  persist("Local demo data reset");
  render();
}

async function saveToApi(collectionKey, record, isNew) {
  if (!state.apiOnline) return;
  const url = isNew ? `/api/${collectionKey}` : `/api/${collectionKey}/${encodeURIComponent(record.id)}`;
  const method = isNew ? "POST" : "PUT";
  try {
    const response = await fetch(url, {
      method,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(record)
    });
    if (!response.ok) throw new Error("API save failed");
  } catch (error) {
    state.apiOnline = false;
  }
}

