async function saveDailyPackageIntakeApi(payload) {
  if (!state.apiOnline) return;
  try {
    const response = await fetch("/api/workflows/daily-package-intake", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...payload,
        by: state.user?.name || "Billing"
      })
    });
    if (!response.ok) throw new Error("Daily package intake sync failed");
    const body = await response.json();
    if (body.project) {
      const projectIndex = state.data.projects.findIndex(item => item.id === body.project.id);
      if (projectIndex !== -1) state.data.projects[projectIndex] = { ...state.data.projects[projectIndex], ...body.project };
    }
    if (body.snapshot) {
      state.data.packageSnapshots = state.data.packageSnapshots || [];
      const snapshotIndex = state.data.packageSnapshots.findIndex(item => item.id === body.snapshot.id);
      if (snapshotIndex === -1) state.data.packageSnapshots.push(body.snapshot);
      else state.data.packageSnapshots[snapshotIndex] = { ...state.data.packageSnapshots[snapshotIndex], ...body.snapshot };
    }
    (body.tasks || []).forEach(task => {
      state.data.tasks = state.data.tasks || [];
      const taskIndex = state.data.tasks.findIndex(item => item.id === task.id);
      if (taskIndex === -1) state.data.tasks.push(task);
      else state.data.tasks[taskIndex] = { ...state.data.tasks[taskIndex], ...task };
    });
    if (body.readiness) {
      state.data.billingReadiness = state.data.billingReadiness || [];
      const readinessIndex = state.data.billingReadiness.findIndex(item => item.id === body.readiness.id || item.project === body.readiness.project);
      if (readinessIndex === -1) state.data.billingReadiness.push(body.readiness);
      else state.data.billingReadiness[readinessIndex] = { ...state.data.billingReadiness[readinessIndex], ...body.readiness };
    }
    persist("Daily package intake synced to server");
  } catch (error) {
    state.apiOnline = false;
  }
}

