function navBadgeCount(key) {
  if (key === "tasks") return scopedRows("tasks").filter(item => item.status !== "Closed").length;
  if (key === "projects") return scopedRows("projects").filter(item => !["Completed / Billed", "Closed"].includes(item.status)).length;
  if (key === "documents") {
    return scopedRows("documents").filter(item => ["Missing", "Pending Review", "Needs Review", "Rejected"].includes(item.status)).length;
  }
  if (key === "field") return scopedRows("dailies").filter(item => !["Submitted", "Accepted", "Closed"].includes(item.status)).length;
  if (key === "production") return productionLedgerRows().filter(item => ["Submitted", "Needs Review", "Needs Proof"].includes(item.status)).length;
  if (key === "time") return scopedRows("timeEntries").filter(item => !["Approved", "Ready for export", "Exported"].includes(item.approvalStatus || item.status || "")).length;
  if (key === "people") return scopedRows("people").filter(item => item.compliance === "Blocked" || daysUntil(item.nextExpiration) !== null && daysUntil(item.nextExpiration) <= 30).length;
  if (key === "equipment") return scopedRows("equipment").filter(item => item.status === "Unavailable" || daysUntil(item.inspectionDue) !== null && daysUntil(item.inspectionDue) <= 30).length;
  if (key === "money") {
    return scopedRows("billingReadiness").filter(item => item.status === "Ready to Bill").length
      + paymentFollowUpRows().filter(item => !item.paid90Complete && item.daysUntilFollowUp !== null && item.daysUntilFollowUp <= 0).length;
  }
  if (key === "risk") return scopedRows("safety").filter(item => item.status !== "Closed").length;
  return 0;
}

function matches(record) {
  if (!state.search.trim()) return true;
  return Object.values(record).join(" ").toLowerCase().includes(state.search.trim().toLowerCase());
}

function render() {
  document.getElementById("app").innerHTML = appTemplate();
  bindEvents();
}

function appTemplate() {
  if (state.user && !roleConfig[state.user.role]) {
    clearSession();
  }
  if (!state.user) return loginTemplate();
  if (state.role !== state.user.role) {
    state.role = state.user.role;
    applyMapOwnerView(ownerViewForRole(state.role));
  }
  ensureAllowedView();
  syncCollectionEvidenceSlaTasks();
  syncEndOfDayDailyTasks();
  const allowedNav = navigationForRole();
  const canCreateRecord = canCreate(collectionForView());
  const alerts = buildAlerts();
  const urgentAlerts = alerts.filter(alert => ["Critical", "High"].includes(alert.severity)).length;
  return `
    <div class="app-shell">
      <aside class="sidebar" id="sidebar">
        <div class="brand">
          <div class="brand-mark">JT</div>
          <div>
            <strong>Jackson Telcom ERP</strong>
            <span>SQUAN operating system</span>
          </div>
        </div>
        <div class="sidebar-section">Workspace</div>
        <nav class="nav">
          ${allowedNav.map(item => {
            const count = navBadgeCount(item.key);
            return `
              <button type="button" class="${state.view === item.key ? "active" : ""}" data-view="${item.key}" aria-label="Open ${item.label}">
                <span class="nav-icon">${navIcon(item.icon)}</span>
                <span>${item.label}</span>
                ${count ? `<span class="count" title="${count} item${count === 1 ? "" : "s"} need attention">${count}</span>` : `<span class="count empty"></span>`}
              </button>
            `;
          }).join("")}
        </nav>
      </aside>
      <main class="main">
        <header class="topbar">
          <button class="icon-btn mobile-menu" id="mobileMenu" title="Open navigation">☰</button>
          <div class="title-area">
            <h1>${pageTitle()}</h1>
          </div>
          <div class="toolbar">
            <input class="search" id="search" type="search" value="${state.search}" placeholder="Search records">
            <button class="alert-button ${alerts.length ? "has-alerts" : ""}" id="alertButton" title="Open alerts">
              <span>Alerts</span>
              <strong>${urgentAlerts || alerts.length}</strong>
            </button>
            <span class="api-pill ${state.apiOnline ? "online" : "offline"}">${state.apiOnline ? "Server" : "Local"}</span>
            <span class="save-chip" title="${state.saveMessage}">
              <strong>${state.apiOnline ? "Server synced" : "Local draft"}</strong>
              <span>${state.lastSavedAt ? `Saved ${formatShortDateTime(state.lastSavedAt)}` : "Not saved yet"}</span>
            </span>
            <div class="user-chip">
              <strong>${state.user.name}</strong>
              <span>${state.user.role}</span>
            </div>
            <button class="secondary-btn" id="syncNow">Sync server</button>
            ${canCreateRecord ? `<button class="primary-btn" id="newRecord">${newButtonLabel()}</button>` : ""}
            <button class="secondary-btn" id="signOut">Sign out</button>
          </div>
        </header>
        <section class="content">${renderDataVersionNotice()}${renderRecordDetail()}${renderView()}</section>
      </main>
    </div>
    <div class="drawer-backdrop" id="drawerBackdrop"></div>
    <aside class="drawer" id="drawer" aria-hidden="true"></aside>
    ${renderAlertDrawer(alerts)}
    ${renderCommunicationsBar()}
  `;
}

function renderCommunicationsBar() {
  if (!state.user) return "";
  const directMessages = communicationDirectMessages();
  const messages = communicationChannelMessages();
  const unread = directMessages.filter(message => !message.readBy.includes(state.user.email));
  const channels = communicationChannels();
  const contacts = communicationContacts();
  const announcements = communicationAnnouncements();
  const reminders = communicationReminders();
  const tab = state.commsTab;
  return `
    <section class="comms-bar ${state.commsOpen ? "open" : ""}">
      <div class="comms-panel">
        ${tab === "Unread" ? renderUnreadChats(unread) : ""}
        ${tab === "Channels" ? renderChatChannels(channels, messages) : ""}
        ${tab === "Contacts" ? renderChatContacts(contacts) : ""}
        ${tab === "Announcements" ? renderAnnouncements(announcements) : ""}
        ${tab === "Reminders" ? renderReminders(reminders) : ""}
      </div>
      <div class="comms-tabs">
        ${["Unread", "Channels", "Contacts", "Announcements", "Reminders"].map(label => {
          const count = label === "Unread" ? unread.length : label === "Channels" ? channels.length : label === "Contacts" ? contacts.length : label === "Announcements" ? announcements.length : reminders.filter(item => item.status !== "Done").length;
          return `
            <button class="${tab === label ? "active" : ""}" data-comms-tab="${label}">
              <span>${label}</span>
              ${count ? `<strong>${count}</strong>` : ""}
            </button>
          `;
        }).join("")}
        <button class="comms-toggle" id="toggleComms">${state.commsOpen ? "Close" : "Chat"}</button>
      </div>
    </section>
  `;
}

function renderUnreadChats(messages) {
  return `
    <div class="comms-list">
      ${messages.map(message => `
        <article class="comms-card">
          <div class="card-topline">
            <strong>${message.author}</strong>
            <span class="status ${statusClass(message.priority)}">${message.priority}</span>
          </div>
          <p>${message.body}</p>
          <small>Direct message · ${formatDateTime(message.at)} · ${message.project || "Company"}</small>
          <button class="secondary-btn" data-comms-action="${message.action}" data-comms-project="${message.project || ""}">${message.actionLabel}</button>
        </article>
      `).join("") || `<div class="empty">No unread messages.</div>`}
    </div>
  `;
}

function renderChatChannels(channels, messages) {
  return `
    <div class="comms-panel-head">
      <strong>Group channels</strong>
      <button class="primary-btn" id="createChannel">Create Channel</button>
    </div>
    <div class="comms-list">
      ${channels.map(channel => {
        const latest = messages.find(message => message.channel === channel.name);
        const unread = messages.filter(message => message.channel === channel.name && !message.readBy.includes(state.user.email)).length;
        return `
          <article class="comms-card">
            <div class="card-topline">
              <strong>${channel.name}</strong>
              <span class="status ${unread ? "bad" : "ok"}">${unread ? `${unread} unread` : "Current"}</span>
            </div>
            <p>${channel.purpose}</p>
            <small>${latest ? `${latest.author}: ${latest.body}` : "No recent messages"}</small>
            <button class="secondary-btn" data-comms-action="${channel.action}" data-comms-project="${channel.project || ""}">${channel.actionLabel}</button>
          </article>
        `;
      }).join("")}
    </div>
  `;
}

function renderChatContacts(contacts) {
  return `
    <div class="comms-list contacts">
      ${contacts.map(contact => `
        <article class="contact-card">
          <span class="presence ${presenceClass(contact.status)}"></span>
          <div>
            <strong>${contact.name}</strong>
            <small>${contact.role}${contact.crew ? ` · ${contact.crew}` : ""}${contact.assignment ? ` · ${contact.assignment}` : ""}</small>
          </div>
          <span class="status ${statusClass(contact.status)}">${contact.status}</span>
        </article>
      `).join("")}
    </div>
  `;
}

function renderAnnouncements(announcements) {
  return `
    <div class="comms-panel-head">
      <strong>Admin announcements</strong>
      <span>${announcements.length} visible</span>
    </div>
    <div class="comms-list">
      ${announcements.map(item => `
        <article class="comms-card">
          <div class="card-topline">
            <strong>${item.title}</strong>
            <span class="priority ${String(item.priority).toLowerCase()}">${item.priority}</span>
          </div>
          <p>${item.message}</p>
          <small>${item.audience} · ${item.effectiveDate} to ${item.expiresAt}${item.ackRequired ? " · acknowledgment required" : ""}</small>
          <button class="secondary-btn" data-comms-action="${item.action}" data-comms-project="${item.project || ""}">${item.actionLabel}</button>
        </article>
      `).join("") || `<div class="empty">No announcements for your role.</div>`}
    </div>
  `;
}

function renderReminders(reminders) {
  return `
    <div class="comms-panel-head">
      <strong>My reminders</strong>
      <button class="primary-btn" id="createReminder">Create Reminder</button>
    </div>
    <div class="comms-list">
      ${reminders.map(item => `
        <article class="comms-card">
          <div class="card-topline">
            <strong>${item.title}</strong>
            <span class="status ${statusClass(item.status)}">${item.status}</span>
          </div>
          <p>${item.note}</p>
          <small>${item.owner} · due ${item.dueAt} · ${item.repeat}</small>
          <button class="secondary-btn" data-comms-action="${item.action}" data-comms-project="${item.project || ""}">${item.actionLabel}</button>
        </article>
      `).join("") || `<div class="empty">No reminders.</div>`}
    </div>
  `;
}

function presenceClass(status) {
  return String(status).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function communicationChannels() {
  const projects = state.data.projects || [];
  const projectChannels = projects.map(project => ({
    name: project.map || project.id,
    purpose: `${project.scope} · ${project.status}`,
    project: project.id,
    action: "Project & Map Hub",
    actionLabel: "Open Map"
  }));
  return [
    ...projectChannels,
    { name: "Foremen", purpose: "Daily starts, crew questions, blockers, and closeout notes.", action: "Field Operations", actionLabel: "Open Field Daily" },
    { name: "Billing", purpose: "Invoice support, retainage, AR, disputes, and missing documents.", action: "Billing", actionLabel: "Open Billing" },
    { name: "Safety", purpose: "Hazards, near misses, Form 12 actions, certs, and equipment concerns.", action: "Safety & Risk", actionLabel: "Open Safety" },
    { name: "Operations", purpose: "Map intake, crew assignment, schedule, maps, permits, and release to field.", action: "Project & Map Hub", actionLabel: "Open Maps" },
    ...state.createdChannels
  ];
}

function communicationContacts() {
  return (state.data.users || []).map(user => {
    const person = (state.data.people || []).find(item => item.id === user.personId || item.name === user.name);
    return {
      name: user.name,
      role: user.role,
      crew: user.crew || person?.crew || "",
      assignment: user.crew ? selectedProjectForCrew(user.crew) : "",
      status: contactPresence(user)
    };
  });
}

function contactPresence(user) {
  if (user.email === state.user?.email) return "Active";
  if (user.role === "Foreman") return "In field";
  if (user.fieldType === "Traffic Control") return "On job";
  if (user.email === "operator@jacksontelcom.example") return "Driving / unavailable";
  if (["Billing", "Operations", "Safety/Compliance"].includes(user.role)) return "Away";
  return "Offline";
}

function selectedProjectForCrew(crew) {
  const project = (state.data.projects || []).find(item => item.crew === crew && item.status !== "Completed / Billed");
  return project?.map || project?.id || "";
}

