function workspaceSummary(role) {
  return {
    Admin: "Executive exceptions, profit, cash, compliance, and audit exports",
    Foreman: "Today’s field daily, JSA, inspections, production, and submit",
    Operations: "Active maps, crew assignment, production progress, and blockers",
    Billing: "Invoice packages, missing support, AR, retainage, and disputes",
    "Safety/Compliance": "Cert expirations, incidents, inspections, Form 12, and SQUAN score",
    "Crew Member": "My assignment, JSA/PPE signoff, safety plan, obstacles, and time confirmation"
  }[role] || "Role workspace";
}

function canView(view) {
  return Boolean(roleConfig[state.role]?.views?.includes(view));
}

function canCreate(collectionKey) {
  return Boolean(roleConfig[state.role]?.create?.includes(collectionKey));
}

function canManageAdmin() {
  return state.role === "Admin";
}

function canManageOperations() {
  return ["Admin", "Operations"].includes(state.role);
}

function canManageSafety() {
  return ["Admin", "Operations", "Safety/Compliance"].includes(state.role);
}

function canManageBilling() {
  return ["Admin", "Billing", "Operations"].includes(state.role);
}

function canManagePackets() {
  return state.role === "Admin";
}

function canManageCash() {
  return state.role === "Admin";
}

function canViewFinancials() {
  return ["Admin", "Billing"].includes(state.role);
}

function canUseAction(actionKey) {
  return {
    admin: canManageAdmin(),
    adminCollection: canManageAdmin(),
    collectionEvidence: state.role === "Admin",
    billing: canManageBilling(),
    collectionSubmission: canManageBilling(),
    deposit: canManageBilling(),
    arEscalation: canManageBilling(),
    evidenceReview: canManageBilling(),
    cash: canManageCash(),
    cashControls: canManageAdmin(),
    qc: canManageSafety(),
    beginning: canManageOperations(),
    release: canManageOperations(),
    production: ["Admin", "Operations", "Billing"].includes(state.role),
    dailyReview: ["Admin", "Operations"].includes(state.role),
    packet: canManagePackets(),
    dataControl: canManageAdmin(),
    users: canManageAdmin(),
    exceptions: ["Admin", "Operations", "Safety/Compliance"].includes(state.role)
  }[actionKey] ?? true;
}

function guardAction(actionKey) {
  if (canUseAction(actionKey)) return true;
  alert(`This action is limited to ${permissionLabel(actionKey)}.`);
  return false;
}

function permissionLabel(actionKey) {
  return {
    admin: "Admin users",
    adminCollection: "Admin users",
    collectionEvidence: "Admin users",
    billing: "Admin users",
    collectionSubmission: "Admin users",
    deposit: "Admin users",
    arEscalation: "Admin users",
    evidenceReview: "Admin users",
    cash: "Admin users",
    cashControls: "Admin users",
    qc: "Admin, Operations, or Safety/Compliance users",
    beginning: "Admin or Operations users",
    release: "Admin or Operations users",
    production: "Admin, Operations, or Billing users",
    dailyReview: "Admin or Operations users",
    packet: "Admin users",
    dataControl: "Admin users",
    users: "Admin users",
    exceptions: "Admin, Operations, or Safety/Compliance users"
  }[actionKey] || "authorized users";
}

function ensureAllowedView() {
  if (!canView(state.view)) {
    state.view = roleConfig[state.role]?.defaultView || "dashboard";
    state.search = "";
  }
}

function navigateToView(view) {
  if (!view || !canView(view)) return false;
  state.view = view;
  state.search = "";
  state.selectedRecord = null;
  state.workflowFocus = "";
  state.alertsOpen = false;
  return true;
}

function scopedRows(collectionKey) {
  const rows = state.data[collectionKey] || [];
  if (state.role === "Admin") return rows;
  if (state.role === "Foreman") return scopeForeman(collectionKey, rows);
  if (state.role === "Crew Member") return scopeCrewMember(collectionKey, rows);
  if (state.role === "Billing") return scopeBilling(collectionKey, rows);
  if (state.role === "Safety/Compliance") return scopeSafety(collectionKey, rows);
  return rows;
}

function buildAlerts() {
  const alerts = [];
  const projects = scopedRows("projects");
  const readiness = scopedRows("billingReadiness");
  const safety = scopedRows("safety");
  const people = scopedRows("people");
  const equipment = scopedRows("equipment");
  const dailies = scopedRows("dailies");
  const tasks = scopedRows("tasks");
  const retainage = scopedRows("retainageLedger");
  const documents = scopedRows("documents");
  const projectIds = new Set(projects.map(project => project.id));
  const packetLocks = (state.data.packetLocks || []).filter(lock => projectIds.has(lock.project));
  const packetMismatches = packetScopeMismatchEvents(projects);

  const add = alert => {
    if (!canView(workflowTarget(alert.action, alert.project))) return;
    if (alert.id && isAlertSuppressed(alert)) return;
    alerts.push(alert);
  };

  projects.forEach(project => {
    if (["Admin", "Billing", "Operations"].includes(state.role)) {
      const buildGate = billingPackageBuildGate(project);
      if (!buildGate.ready) {
        add({
          id: `invoice-package-build:${project.id}:${buildGate.blockers.map(item => item.label).join("|")}`,
          source: "Invoice package build guard",
          revision: `${buildGate.status}:${buildGate.blockers.length}:${project.modifiedAt || ""}`,
          dismissible: true,
          severity: buildGate.blockers.some(item => ["Accepted field daily", "Support package evidence"].includes(item.label)) ? "High" : "Medium",
          title: "Invoice package build blocked",
          detail: `${project.map || project.id}: ${buildGate.blockers.map(item => item.label).join(", ")}.`,
          project: project.id,
          due: project.billBy,
          action: "Billing",
          actionLabel: "Review build guard"
        });
      }
    }
    if (state.role === "Admin") {
      dailyPackageAlertRows(project).forEach(row => add(row));
    }
    const gis = fieldMapsReadiness(project);
    if (["Admin", "Operations", "Foreman", "Safety/Compliance"].includes(state.role) && !gis.ready) {
      add({
        id: `field-maps-readiness:${project.id}`,
        source: "ArcGIS Field Maps",
        revision: `${gis.status}:${project.arcgis?.lastSyncedAt || ""}:${project.arcgis?.primeAcceptanceStatus || ""}:${project.arcgis?.obstaclePins || 0}`,
        dismissible: true,
        severity: gis.status === "Blocked" ? "High" : "Medium",
        title: "Field Maps readiness blocker",
        detail: `${project.map || project.id}: ${gis.blockers.join(", ")}.`,
        project: project.id,
        due: project.start || project.billBy,
        action: "Project & Map Hub",
        actionLabel: "Review GIS"
      });
    }
    if (margin(project) < 12 && ["Admin", "Operations"].includes(state.role)) {
      add({
        severity: "High",
        title: "Map margin below target",
        detail: `${project.map || project.id} is forecast at ${margin(project)}% margin.`,
        project: project.id,
        action: "Project & Map Hub",
        actionLabel: "Open Map"
      });
    }
    if (["Blocked", "At Risk"].includes(project.status) && ["Admin", "Operations", "Foreman"].includes(state.role)) {
      add({
        severity: "Critical",
        title: "Map blocked",
        detail: `${project.map || project.id} needs action before work can move cleanly.`,
        project: project.id,
        action: "Project & Map Hub",
        actionLabel: "Review map"
      });
    }
    if (state.role === "Admin") {
      const financialGate = mapFinancialCloseoutGate(project);
      const financialPacket = financialCloseoutPacketLockState(project);
      const financialCloseout = project.adminApprovals?.financialCloseout;
      if (financialGate.ready && financialCloseout?.status === "Closed" && financialPacket.status === "Open") {
        add({
          id: `packet-financial-closeout-unlocked:${project.id}`,
          source: "Packet lock",
          revision: `${financialCloseout.at || ""}:${project.modifiedAt || ""}:${financialGate.status}`,
          dismissible: true,
          severity: "High",
          title: "Financial Closeout packet not finalized",
          detail: `${project.map || project.id} is financially closed and the gate is clean, but the Financial Closeout packet is not locked for audit.`,
          project: project.id,
          due: financialCloseout.at ? String(financialCloseout.at).slice(0, 10) : project.billBy,
          action: "Reports",
          reportScope: "Financial Closeout",
          actionLabel: "Finalize packet"
        });
      }
      const packetTask = packetReopenTaskForProject(project.id);
      if (packetTask && (packetTask.reopenScopes || []).includes("Financial Closeout")) {
        const guard = packetReopenTaskGuard(packetTask);
        add({
          id: `packet-financial-closeout-refinalization:${packetTask.id}`,
          source: "Packet lock",
          revision: `${packetTask.modifiedAt || packetTask.createdAt || ""}:${guard.blockers.join("|")}`,
          dismissible: true,
          severity: guard.ok ? "Medium" : "High",
          title: guard.ok ? "Financial Closeout packet ready to re-finalize" : "Financial Closeout packet re-finalization blocked",
          detail: `${project.map || project.id}: ${guard.ok ? guard.message : guard.blockers.join(" ")}`,
          project: project.id,
          taskId: packetTask.id,
          due: packetTask.dueDate,
          action: "Reports",
          reportScope: "Financial Closeout",
          actionLabel: "Review closeout packet"
        });
      }
    }
    const exceptionRisk = projectExceptionStatus(project);
    const exceptionAlertStatus = exceptionRisk?.exception?.status;
    if (exceptionRisk && ["Accepted", "Blocked", "Reopened"].includes(exceptionAlertStatus) && ["Admin", "Operations", "Safety/Compliance"].includes(state.role)) {
      add({
        severity: exceptionAlertStatus === "Reopened" ? "High" : exceptionRisk.severity,
        title: exceptionAlertStatus === "Reopened" ? "Exception reopened" : exceptionRisk.expired ? "Exception expired" : "Exception follow-up",
        detail: `${project.map || project.id} has an exception ${exceptionAlertStatus === "Reopened" ? "reopened for change control" : exceptionRisk.expired ? "past its expiration date" : `expiring ${exceptionRisk.label}`}. Owner: ${exceptionRisk.owner}.`,
        project: project.id,
        due: exceptionRisk.expiresOn,
        action: "Project & Map Hub",
        actionLabel: "Review exception"
      });
    }
  });

  readiness.forEach(item => {
    const days = daysUntil(item.billingDeadline);
    if (days !== null && days <= 7 && item.status !== "Submitted" && ["Admin", "Billing", "Operations"].includes(state.role)) {
      add({
        severity: days < 0 ? "Critical" : "High",
        title: "Invoice deadline approaching",
        detail: `${item.project} has ${days < 0 ? "missed" : `${days} day(s) until`} the billing deadline. Missing: ${item.missingItems}.`,
        project: item.project,
        due: item.billingDeadline,
        action: "Billing",
        actionLabel: "Build invoice"
      });
    }
    if (item.status !== "Ready to Bill" && ["Admin", "Billing", "Operations"].includes(state.role)) {
      add({
        severity: "Medium",
        title: "Invoice support missing",
        detail: `${item.project} is not ready to bill. Missing: ${item.missingItems}.`,
        project: item.project,
        due: item.billingDeadline,
        action: "Documents",
        actionLabel: "Review support"
      });
    }
  });

  safety.filter(item => item.status !== "Closed").forEach(item => {
    add({
      severity: item.severity === "High" ? "High" : "Medium",
      title: `${item.type} open`,
      detail: item.correctiveAction || item.rootCause || "Safety item needs review.",
      project: item.project,
      due: item.due,
      action: "Safety & Risk",
      actionLabel: "Open safety"
    });
  });

  people.forEach(person => {
    const days = daysUntil(person.nextExpiration);
    if (days !== null && days <= 30 && ["Admin", "Operations", "Safety/Compliance"].includes(state.role)) {
      add({
        severity: days <= 7 ? "High" : "Medium",
        title: "Certification expiring",
        detail: `${person.name} has ${person.certs} expiring ${person.nextExpiration}.`,
        due: person.nextExpiration,
        action: "People & Compliance",
        actionLabel: "Review person"
      });
    }
    if (person.compliance === "Blocked" && ["Admin", "Operations", "Safety/Compliance"].includes(state.role)) {
      add({
        severity: "Critical",
        title: "Crew member blocked",
        detail: `${person.name} cannot be assigned until compliance is cleared.`,
        action: "People & Compliance",
        actionLabel: "Fix block"
      });
    }
  });

  equipment.forEach(asset => {
    const days = daysUntil(asset.inspectionDue);
    if (days !== null && days <= 30 && ["Admin", "Operations", "Foreman", "Safety/Compliance"].includes(state.role)) {
      add({
        severity: days <= 7 || asset.status === "Unavailable" ? "High" : "Medium",
        title: "Equipment inspection due",
        detail: `${asset.asset} inspection/calibration is due ${asset.inspectionDue}.`,
        due: asset.inspectionDue,
        action: "Equipment",
        actionLabel: "Review equipment"
      });
    }
  });

  dailies.forEach(daily => {
    if (daily.jsa === "Blocked" && ["Admin", "Foreman", "Operations"].includes(state.role)) {
      add({
        severity: "Critical",
        title: "Daily blocked",
        detail: `${daily.project} cannot start until the JSA/equipment block is resolved.`,
        project: daily.project,
        due: daily.date,
        action: "Field Operations",
        actionLabel: "Open daily"
      });
    }
    if (daily.status !== "Submitted" && ["Admin", "Foreman", "Operations"].includes(state.role)) {
      add({
        severity: "Medium",
        title: "Daily not submitted",
        detail: `${daily.project} daily is still ${daily.status || daily.jsa || "not submitted"}.`,
        project: daily.project,
        due: daily.date,
        action: "Field Operations",
        actionLabel: "Submit daily"
      });
    }
  });

  if (["Admin", "Operations", "Foreman"].includes(state.role)) {
    incompleteDailyRows()
      .filter(row => ["Draft", "Missing"].includes(row.status))
      .forEach(row => {
        const blocked = !row.gate.clear;
        add({
          id: `end-of-day-daily:${row.project.id}:${row.daily?.id || isoDate(today)}:${row.status}`,
          source: "Field Daily",
          revision: `${row.status}:${row.daily?.modifiedAt || row.daily?.date || ""}:${row.gate.status}`,
          dismissible: true,
          severity: blocked ? "Critical" : row.status === "Missing" ? "High" : "Medium",
          title: row.status === "Draft" ? "Draft daily needs submission" : "End-of-day daily missing",
          detail: `${row.project.map || row.project.id}: ${row.detail}${blocked ? `; gate blockers: ${row.gate.blockers.map(item => item.label).join(", ")}` : "."}`,
          project: row.project.id,
          due: row.daily?.date || isoDate(today),
          action: "Field Operations",
          actionLabel: row.status === "Draft" ? "Resume draft" : "Open daily"
        });
      });
  }

  if (["Admin", "Operations", "Foreman"].includes(state.role)) {
    dailySupervisorReviewRows(projects)
      .filter(row => ["Pending Review", "Returned"].includes(row.status))
      .forEach(row => {
        add({
          id: `daily-review:${row.daily.id}:${row.status}`,
          source: "Daily review",
          revision: `${row.status}:${row.review.at || row.daily.modifiedAt || ""}:${row.daily.correctionCount || 0}`,
          dismissible: true,
          severity: row.status === "Returned" ? "High" : "Medium",
          title: row.status === "Returned" ? "Daily returned for correction" : "Daily awaiting supervisor review",
          detail: `${row.project.map || row.daily.project} ${row.daily.id}: ${row.review.note || row.daily.production || "Review submitted daily."}`,
          project: row.daily.project,
          taskId: row.task?.id || "",
          due: row.daily.date,
          action: "Field Operations",
          actionLabel: row.status === "Returned" ? "Correct daily" : "Review daily"
        });
      });
  }

  tasks.filter(task => task.status !== "Closed").forEach(task => {
    const days = daysUntil(task.dueDate);
    if (days !== null && days <= 2) {
      add({
        severity: days < 0 ? "High" : "Medium",
        title: task.title,
        detail: task.notes || `${task.owner} has an open task.`,
        project: task.project,
        due: task.dueDate,
        action: task.workflowArea || "Tasks",
        actionLabel: "Open task"
      });
    }
  });

  closeoutReadinessAgingRows(projects)
    .filter(row => row.needsEscalation || row.severity !== "Info")
    .forEach(row => {
      if (!["Admin", "Billing", "Operations"].includes(state.role)) return;
      add({
        id: `billing-closeout-readiness-aging:${row.task.id}`,
        source: "Billing closeout",
        revision: `${row.task.status}:${row.task.owner}:${row.task.dueDate}:${row.task.modifiedAt || row.task.createdAt || ""}:${row.status}`,
        dismissible: true,
        severity: row.severity,
        title: row.severity === "Critical" ? "Closeout readiness escalation" : "Closeout readiness aging",
        detail: `${row.project.map || row.project.id} ${row.item.label}: ${row.detail} Owner ${row.task.owner || "Unassigned"}; recommended ${row.handoff.owner}.`,
        project: row.project.id,
        taskId: row.task.id,
        due: row.task.dueDate,
        action: "Tasks",
        actionLabel: "Open readiness task"
      });
    });

  packetLocks.filter(lock => lock.status === "Reopened").forEach(lock => {
    if (!["Admin", "Operations", "Billing", "Safety/Compliance"].includes(state.role)) return;
    const project = projects.find(item => item.id === lock.project) || {};
    const age = ageDays(lock.reopenedAt || lock.modifiedAt) || 0;
    const severity = age >= 2 ? "Critical" : "High";
    const revision = packetAlertRevision(lock);
    const task = packetReopenTaskForProject(lock.project);
    add({
      id: packetAlertId(lock),
      source: "Packet lock",
      revision,
      dismissible: true,
      severity,
      title: lock.scope === "Financial Closeout" ? age >= 2 ? "Financial Closeout packet reopen aging" : "Financial Closeout packet needs re-finalization" : age >= 2 ? "Packet lock reopen aging" : "Packet needs re-finalization",
      detail: `${project.map || lock.project} ${lock.scope} was reopened${lock.reopenReason ? `: ${lock.reopenReason}` : "."} ${task ? `Linked task ${task.id} is assigned to ${task.owner} and due ${task.dueDate}.` : "No linked re-finalization task found."}`,
      project: lock.project,
      taskId: task?.id || "",
      due: lock.reopenedAt ? String(lock.reopenedAt).slice(0, 10) : undefined,
      action: "Reports",
      reportScope: lock.scope,
      actionLabel: lock.scope === "Financial Closeout" ? "Review closeout packet" : "Review packet locks"
    });
  });

  packetLocks
    .filter(lock => lock.scope === "Financial Closeout" && lock.status === "Finalized")
    .forEach(lock => {
      if (!state.role === "Admin") return;
      const followUp = financialCloseoutReceiptFollowUpState(lock);
      if (!followUp.alert) return;
      const project = projects.find(item => item.id === lock.project) || {};
      add({
        id: `packet-financial-closeout-receipt:${lock.id}`,
        source: "Packet lock",
        revision: `${lock.modifiedAt || lock.finalizedAt || ""}:${followUp.sent?.id || ""}:${followUp.receipt?.id || ""}:${followUp.sent?.followUpDate || ""}`,
        dismissible: true,
        severity: followUp.severity || "Medium",
        title: followUp.status === "Receipt Overdue" ? "Financial Closeout receipt overdue" : "Financial Closeout receipt follow-up",
        detail: `${project.map || lock.project}: ${followUp.detail}`,
        project: lock.project,
        due: followUp.due,
        action: "Reports",
        reportScope: "Financial Closeout",
        actionLabel: "Record receipt"
      });
    });

  packetMismatches.forEach(event => {
    if (!["Admin", "Operations", "Billing", "Safety/Compliance"].includes(state.role)) return;
    const detail = event.detail || {};
    const project = projects.find(item => item.id === detail.project) || {};
    add({
      id: `packet-scope-mismatch:${event.id}`,
      source: "Packet lock",
      revision: event.at || event.id,
      dismissible: true,
      severity: "High",
      title: "Packet scope mismatch",
      detail: `${project.map || detail.project} finalized ${detail.finalizedScope || "a different scope"} while task ${detail.task || "unknown"} expected ${uniqueList(detail.expectedScopes || []).join(", ") || "another reopened scope"}. Review before closing packet work.`,
      project: detail.project,
      taskId: detail.task || "",
      due: event.at ? String(event.at).slice(0, 10) : undefined,
      action: "Reports",
      actionLabel: "Review packet locks"
    });
  });

  retainage.forEach(item => {
    if (["Released / Paid", "Paid"].includes(item.status)) return;
    const releaseDays = daysUntil(item.releaseDate);
    const followUpDays = daysUntil(item.followUpDate);
    const followUpDue = followUpDays !== null && followUpDays <= 60 && item.followUpStatus !== "Closed";
    const releaseDue = releaseDays !== null && releaseDays <= 60;
    if ((followUpDue || releaseDue) && state.role === "Admin") {
      const due = followUpDue ? item.followUpDate : item.releaseDate;
      const days = followUpDue ? followUpDays : releaseDays;
      add({
        id: `retainage-release:${item.id}`,
        source: "Retainage",
        revision: `${item.status}:${item.releaseDate}:${item.followUpDate || ""}:${item.followUpStatus || ""}`,
        dismissible: true,
        severity: days < 0 ? "High" : days <= 14 ? "Medium" : "Info",
        title: followUpDue ? "Retainage follow-up due" : "Retainage release coming up",
        detail: `${item.project} has ${currency(item.heldAmount)} held. Follow-up ${item.followUpDate || "not scheduled"}; release ${item.releaseDate}.`,
        project: item.project,
        due,
        action: "Billing",
        actionLabel: "Track retainage"
      });
    }
  });

  if (state.role === "Admin") {
    (state.data.billingTaskCloseouts || [])
      .filter(item => item.finalizedStatus === "Reopened" || item.adminReview?.status === "Reopened")
      .forEach(item => {
        const task = (state.data.tasks || []).find(openTask => openTask.billingCloseoutId === item.id && openTask.source === "Billing closeout final reopen" && openTask.status !== "Closed");
        const age = ageDays(item.reopenedAt || item.adminReview?.at || item.modifiedAt) || 0;
        add({
          id: `billing-closeout-reopened:${item.id}`,
          source: "Billing closeout",
          revision: `${item.finalizedStatus}:${item.reopenedAt || ""}:${item.modifiedAt || ""}:${task?.status || ""}`,
          dismissible: true,
          severity: age >= 2 || daysUntil(task?.dueDate) < 0 ? "High" : "Medium",
          title: age >= 2 ? "Reopened closeout aging" : "Final closeout reopened",
          detail: `${item.map || item.project} closeout ${item.id} was reopened${item.reopenReason ? `: ${item.reopenReason}` : "."} Attach current evidence, accept evidence, resubmit, and final-accept.`,
          project: item.project,
          taskId: task?.id || "",
          due: task?.dueDate || (item.reopenedAt ? String(item.reopenedAt).slice(0, 10) : undefined),
          action: "Reports",
          actionLabel: "Review closeout"
        });
      });

    (state.data.billingTaskCloseouts || [])
      .filter(item => item.finalizedStatus === "Pending Final Review")
      .forEach(item => {
        add({
          id: `billing-closeout-pending-final:${item.id}`,
          source: "Billing closeout",
          revision: `${item.finalizedStatus}:${item.adminReview?.at || ""}:${item.resubmissionLog?.length || 0}`,
          dismissible: true,
          severity: state.role === "Admin" ? "High" : "Medium",
          title: "Closeout pending final acceptance",
          detail: `${item.map || item.project} closeout ${item.id} was resubmitted after reopen and needs Admin final acceptance.`,
          project: item.project,
          due: item.adminReview?.at ? String(item.adminReview.at).slice(0, 10) : undefined,
          action: "Reports",
          actionLabel: "Final review"
        });
      });

    (state.data.billingTaskCloseouts || [])
      .flatMap(closeout => closeoutCorrectionEvidenceSplit(closeout).current
        .filter(evidence => evidence.status === "Rejected")
        .map(evidence => ({ closeout, evidence })))
      .forEach(({ closeout, evidence }) => {
        add({
          id: `billing-closeout-rejected-evidence:${closeout.id}:${evidence.id}`,
          source: "Billing closeout",
          revision: `${evidence.status}:${evidence.reviewedAt || ""}:${evidence.replacedBy || ""}`,
          dismissible: true,
          severity: "High",
          title: "Closeout evidence rejected",
          detail: `${closeout.map || closeout.project} evidence ${evidence.id} was rejected. Billing must replace or correct it before closeout can be final-accepted.`,
          project: closeout.project,
          due: evidence.reviewedAt ? String(evidence.reviewedAt).slice(0, 10) : undefined,
          action: "Reports",
          actionLabel: "Review evidence"
        });
      });

    (state.data.billingTaskCloseouts || [])
      .flatMap(closeout => closeoutCorrectionEvidenceSplit(closeout).current
        .filter(evidence => ["Submitted", "Pending Review", "Needs Review"].includes(evidence.status || ""))
        .map(evidence => ({ closeout, evidence })))
      .forEach(({ closeout, evidence }) => {
        add({
          id: `billing-closeout-evidence-review:${closeout.id}:${evidence.id}`,
          source: "Billing closeout",
          revision: `${evidence.status}:${evidence.attachedAt || ""}:${evidence.version || ""}`,
          dismissible: true,
          severity: state.role === "Admin" ? "Medium" : "Info",
          title: "Closeout evidence awaiting review",
          detail: `${closeout.map || closeout.project} evidence ${evidence.id} is waiting for Admin evidence review.`,
          project: closeout.project,
          due: evidence.attachedAt ? String(evidence.attachedAt).slice(0, 10) : undefined,
          action: "Reports",
          actionLabel: "Review evidence"
        });
      });

    (state.data.billingTaskCloseouts || [])
      .filter(item => ["Returned", "Pending Review"].includes(item.adminReview?.status))
      .forEach(item => {
        const reviewAt = item.adminReview?.at || item.resubmissionLog?.at(-1)?.at || item.closedAt;
        const age = ageDays(reviewAt) || 0;
        const status = item.adminReview?.status || "Pending Review";
        const isReturned = status === "Returned";
        const overdue = isReturned ? age >= 1 : age >= 2;
        add({
          id: `billing-closeout-review:${item.id}`,
          source: "Billing closeout review",
          revision: `${status}:${item.adminReview?.at || ""}:${item.resubmissionLog?.length || 0}`,
          dismissible: true,
          severity: overdue ? "High" : "Medium",
          title: overdue ? "Billing closeout review aging" : `Billing closeout ${status.toLowerCase()}`,
          detail: `${item.map || item.project} closeout ${item.id} is ${status.toLowerCase()} for ${age} day(s). ${item.adminReview?.note || item.evidenceSummary || ""}`,
          project: item.project,
          due: reviewAt ? String(reviewAt).slice(0, 10) : undefined,
          action: "Reports",
          actionLabel: "Review closeout"
        });
      });

    paymentFollowUpRows()
      .filter(item => !item.paid90Complete && ["Pay-when-paid hold", "Past Due", "Disputed", "Short-paid", "Chargeback received"].includes(item.status))
      .forEach(item => {
        add({
          id: `cash-exposure:${item.invoice}`,
          source: "AR cash forecast",
          revision: `${item.status}:${item.followUpDate}:${item.open90}`,
          dismissible: true,
          severity: item.status === "Past Due" || item.status === "Chargeback received" ? "High" : "Medium",
          title: item.status === "Pay-when-paid hold" ? "Pay-when-paid cash exposure" : "AR cash risk",
          detail: `${item.map} has ${currency(item.open90)} open against expected 90% payment. Follow-up ${item.followUpDate || "not scheduled"}.`,
          project: item.project,
          due: item.followUpDate,
          action: "Billing",
          actionLabel: "Review cash"
        });
      });
  }

  if (state.role === "Admin") {
    collectionResponseRows()
      .filter(item => ["Overdue", "Pending Response", "Disputed", "Payment Promised"].includes(item.status))
      .forEach(item => {
        add({
          id: `collection-response:${item.id}`,
          source: "Collections submission",
          revision: `${item.status}:${item.nextFollowUpDate || ""}:${item.responseStatus || ""}:${item.promisedPaymentDate || ""}`,
          dismissible: true,
          severity: item.status === "Overdue" || item.status === "Disputed" ? "High" : item.status === "Payment Promised" ? "Medium" : "Info",
          title: item.status === "Overdue" ? "Collections follow-up overdue" : item.status === "Pending Response" ? "SQUAN response pending" : item.status,
          detail: `${item.map} collections packet ${item.id} is ${item.status.toLowerCase()}. Follow-up ${item.nextFollowUpDate || "not scheduled"}.`,
          project: item.project,
          due: item.nextFollowUpDate || item.promisedPaymentDate,
          action: "Reports",
          actionLabel: "Review collections"
        });
      });
  }

  if (state.role === "Admin") {
    adminCollectionsDecisionRows().forEach(item => {
      const evidence = collectionDecisionEvidenceStatus(item);
      add({
        id: `collections-decision:${item.id}`,
        source: "Collections decision",
        revision: `${item.writeOffStatus || ""}:${item.escalationStatus || ""}:${item.amountAtRisk || ""}:${item.writeOffAmount || ""}:${evidence.ready}/${evidence.total}:${item.modifiedAt || ""}`,
        dismissible: true,
        severity: evidence.missing.length || item.writeOffStatus === "Requested" || Number(item.writeOffAmount || item.amountAtRisk || 0) > 1000 ? "High" : "Medium",
        title: item.writeOffStatus ? "Collections write-off decision" : "Collections dispute decision",
        detail: `${item.map} needs Admin decision. At risk ${currency(item.amountAtRisk || item.writeOffAmount || item.arExposure || 0)}. Evidence ${evidence.ready}/${evidence.total}; missing ${evidence.missingLabels.join(", ") || "none"}. ${item.writeOffReason || item.disputeOutcome || ""}`,
        project: item.project,
        due: item.nextFollowUpDate,
        action: "Home",
        actionLabel: "Review decision"
      });
    });
  }

  if (state.role === "Admin") {
    collectionDecisionEvidenceReviewRows()
      .filter(row => ["Rejected", "Missing", "Pending Review"].includes(row.reviewStatus))
      .filter(row => row.slaStatus === "Overdue" || row.daysUntilDue !== null && row.daysUntilDue <= 1)
      .forEach(row => {
        const documentId = row.document?.id || `${row.submission.id}-${row.key}`;
        add({
          id: `collection-evidence-sla:${documentId}`,
          source: "Collections decision evidence",
          revision: `${row.reviewStatus}:${row.dueDate}:${row.version || 1}:${row.document?.modifiedAt || row.submission.modifiedAt || ""}`,
          dismissible: true,
          severity: row.slaStatus === "Overdue" ? "High" : "Medium",
          title: row.slaStatus === "Overdue" ? "Decision evidence overdue" : "Decision evidence due",
          detail: `${row.project.map || row.submission.map || row.submission.project} ${row.label} is ${row.reviewStatus.toLowerCase()}. Due ${row.dueDate}; aging ${row.daysAging} day(s).`,
          project: row.submission.project,
          due: row.dueDate,
          action: state.role === "Billing" ? "Billing" : "Home",
          actionLabel: state.role === "Billing" ? "Open corrections" : "Review evidence"
        });
      });
  }

  documents.filter(doc => ["Needs Review", "Pending Review", "Pending"].includes(doc.status)).forEach(doc => {
    if (["Admin", "Operations", "Billing", "Safety/Compliance"].includes(state.role)) {
      add({
        severity: doc.requiredForBilling === "Yes" || doc.requiredForSafety === "Yes" ? "Medium" : "Info",
        title: "Document needs review",
        detail: `${doc.name} is ${doc.status}.`,
        project: doc.project,
        action: "Documents",
        actionLabel: "Review document"
      });
    }
  });

  projects.forEach(project => {
    const missingEvidence = fieldEvidenceManifest(project).filter(item => ["Missing", "Needs Review", "Rejected"].includes(item.status));
    const readinessRow = readiness.find(item => item.project === project.id);
    if (missingEvidence.length && ["Admin", "Operations", "Billing", "Foreman"].includes(state.role) && (readinessRow || project.status !== "Beginning Phase")) {
      add({
        severity: missingEvidence.some(item => item.status === "Missing") ? "High" : "Medium",
        title: "Billing evidence incomplete",
        detail: `${project.map || project.id} is missing ${missingEvidence.map(item => item.label).join(", ")} before clean billing/export.`,
        project: project.id,
        due: readinessRow?.billingDeadline || project.billBy,
        action: "Field Operations",
        actionLabel: "Review evidence"
      });
    }
  });

  projects.forEach(project => {
    const approvals = project.adminApprovals || {};
    if (!approvals.release && project.status === "Beginning Phase" && state.role === "Admin") {
      add({
        severity: "High",
        title: "Release approval needed",
        detail: `${project.map || project.id} is waiting on Admin release before field work.`,
        project: project.id,
        action: "Project & Map Hub",
        actionLabel: "Review release"
      });
    }
    const ready = readiness.find(item => item.project === project.id);
    if (!approvals.invoice && ready?.status === "Ready to Bill" && state.role === "Admin") {
      add({
        severity: "High",
        title: "Invoice approval needed",
        detail: `${project.map || project.id} is ready to bill and needs Admin approval before SQUAN submission.`,
        project: project.id,
        due: ready.billingDeadline,
        action: "Billing",
        actionLabel: "Approve invoice"
      });
    }
    if (!approvals.closeout && project.status !== "Completed / Billed" && state.role === "Admin") {
      add({
        severity: "Info",
        title: "Closeout not approved",
        detail: `${project.map || project.id} has not been closed by Admin.`,
        project: project.id,
        action: "Project & Map Hub",
        actionLabel: "Review closeout"
      });
    }
  });

  communicationAnnouncements().filter(item => ["Urgent", "Important"].includes(item.priority)).forEach(item => {
    add({
      severity: item.priority === "Urgent" ? "High" : "Medium",
      title: item.title,
      detail: item.message,
      project: item.project,
      due: item.expiresAt,
      action: item.action,
      actionLabel: item.actionLabel
    });
  });

  communicationReminders().filter(item => item.status !== "Done").forEach(item => {
    add({
      severity: daysUntil(String(item.dueAt).slice(0, 10)) <= 1 ? "High" : "Info",
      title: item.title,
      detail: item.note,
      project: item.project,
      due: item.dueAt,
      action: item.action,
      actionLabel: item.actionLabel
    });
  });

  return alerts.sort((a, b) => severityRank(b.severity) - severityRank(a.severity)).slice(0, 25);
}

function packetAlertId(lock) {
  return `packet-lock:${lock.id}`;
}

function packetAlertRevision(lock) {
  return lock.modifiedAt || lock.reopenedAt || lock.finalizedAt || lock.createdAt || "";
}

function packetScopeMismatchEvents(projects = scopedRows("projects")) {
  const projectIds = new Set(projects.map(project => project.id));
  return (state.data.auditLog || [])
    .filter(item => item.action === "packet.refinalization-scope-mismatch" && projectIds.has(item.detail?.project))
    .filter(item => !isPacketScopeMismatchResolved(item))
    .slice()
    .sort((a, b) => String(b.at || "").localeCompare(String(a.at || "")));
}

function isPacketScopeMismatchResolved(event) {
  return (state.data.alertControls || []).some(control => control.alertId === `packet-scope-mismatch:${event.id}` && control.revision === (event.at || event.id) && control.kind === "Resolved" && control.status === "Active");
}

function packetReopenTaskId(projectId) {
  return `TASK-PACKET-${String(projectId).replace(/[^a-z0-9]/gi, "")}`;
}

function packetReopenTaskForProject(projectId) {
  return (state.data.tasks || []).find(task => task.id === packetReopenTaskId(projectId) && task.status !== "Closed");
}

function uniqueList(items) {
  return [...new Set((items || []).filter(Boolean))];
}

function isAlertSuppressed(alert) {
  const controls = state.data.alertControls || [];
  const control = controls.find(item => item.alertId === alert.id && item.revision === alert.revision && item.status === "Active");
  if (!control) return false;
  if (control.kind === "Dismissed") return true;
  if (control.kind === "Snoozed" && control.snoozedUntil && new Date(control.snoozedUntil) > new Date()) return true;
  return false;
}

function setAlertControl(kind, alertId, project, revision, source = "") {
  if (!alertId) return;
  state.data.alertControls = state.data.alertControls || [];
  const now = new Date().toISOString();
  const existing = state.data.alertControls.find(item => item.alertId === alertId && item.revision === revision && item.status === "Active");
  const controlSource = source || alertControlSourceFromId(alertId);
  const control = existing || {
    id: `ALERTCTRL-${String(state.data.alertControls.length + 1).padStart(4, "0")}`,
    alertId,
    project,
    source: controlSource,
    revision,
    createdAt: now,
    activityLog: []
  };
  control.source = controlSource;
  control.kind = kind;
  control.status = "Active";
  control.modifiedAt = now;
  control.updatedBy = state.user?.name || "User";
  control.snoozedUntil = kind === "Snoozed" ? new Date(Date.now() + 86400000).toISOString() : "";
  control.dismissedAt = kind === "Dismissed" ? now : "";
  control.resolvedAt = kind === "Resolved" ? now : "";
  control.notes = kind === "Snoozed"
    ? `${controlSource} alert snoozed for 24 hours.`
    : kind === "Resolved"
      ? "Packet scope mismatch reviewed and resolved for this audit event."
      : `${controlSource} alert dismissed for this alert revision.`;
  control.activityLog = [...(control.activityLog || []), {
    at: now,
    by: state.user?.name || "User",
    note: control.notes
  }];
  if (!existing) state.data.alertControls.push(control);
  appendAuditLocal(`${controlSource.toLowerCase().replaceAll(" ", "-")}.alert-${kind.toLowerCase()}`, { alertId, project, revision, by: state.user?.name || "User" });
  persist(`${controlSource} alert ${kind.toLowerCase()}`);
  void saveToApi("alertControls", control, !existing);
  state.alertsOpen = true;
  render();
}

function setPacketAlertControl(kind, alertId, project, revision) {
  setAlertControl(kind, alertId, project, revision, "Packet lock");
}

function alertControlSourceFromId(alertId = "") {
  if (String(alertId).startsWith("billing-closeout-")) return "Billing closeout";
  if (String(alertId).startsWith("daily-package-")) return "Daily package intake";
  if (String(alertId).startsWith("packet-")) return "Packet lock";
  if (String(alertId).startsWith("collection-")) return "Collections";
  if (String(alertId).startsWith("cash-") || String(alertId).startsWith("retainage-")) return "Billing";
  return "Alert";
}

function resolvePacketScopeMismatch(eventId) {
  const event = (state.data.auditLog || []).find(item => item.id === eventId && item.action === "packet.refinalization-scope-mismatch");
  if (!event) return;
  const detail = event.detail || {};
  setPacketAlertControl("Resolved", `packet-scope-mismatch:${event.id}`, detail.project || "", event.at || event.id);
}

function reactivatePacketAlertControl(controlId) {
  const control = (state.data.alertControls || []).find(item => item.id === controlId);
  if (!control) return;
  const now = new Date().toISOString();
  control.status = "Reactivated";
  control.reactivatedAt = now;
  control.reactivatedBy = state.user?.name || "User";
  control.modifiedAt = now;
  control.notes = appendInlineNote(control.notes, "Alert suppression was reactivated; packet alert can appear again if still applicable.");
  control.activityLog = [...(control.activityLog || []), {
    at: now,
    by: state.user?.name || "User",
    note: "Alert suppression reactivated by admin."
  }];
  appendAuditLocal("packet.alert-reactivated", {
    control: control.id,
    alertId: control.alertId,
    project: control.project,
    by: state.user?.name || "User"
  });
  if (control.source === "Billing closeout" && control.project) {
    autoCloseCloseoutReadinessTasks(control.project, `Auto-closed after closeout alert control ${control.id} was reactivated.`);
  }
  persist("Packet alert reactivated");
  void saveToApi("alertControls", control, false);
  state.alertsOpen = true;
  render();
}

function severityRank(severity) {
  return { Critical: 4, High: 3, Medium: 2, Info: 1 }[severity] || 0;
}

function scopeCrewMember(collectionKey, rows) {
  const crew = state.user?.crew;
  const personId = state.user?.personId;
  const projectIds = (state.data.projects || [])
    .filter(project => project.crew === crew)
    .map(project => project.id);
  if (collectionKey === "projects") return rows.filter(row => projectIds.includes(row.id));
  if (collectionKey === "tasks") return rows.filter(row => row.owner === state.user?.name || (row.role === "Crew Member" && projectIds.includes(row.project)));
  if (collectionKey === "dailies") return rows.filter(row => row.crew === crew || projectIds.includes(row.project));
  if (collectionKey === "timeEntries") return rows.filter(row => row.employeeId === personId);
  if (collectionKey === "people") return rows.filter(row => row.id === personId);
  if (collectionKey === "equipment") return rows.filter(row => row.assigned === crew || projectIds.includes(row.assigned));
  if (["documents", "photoEvidence", "siteSurveys", "obstacles", "qcCloseouts", "costBlockers", "formSubmissions"].includes(collectionKey)) return rows.filter(row => projectIds.includes(row.project));
  if (collectionKey === "safety") return rows.filter(row => projectIds.includes(row.project) || row.owner === state.user?.name);
  if (["projectUnits", "dailyProduction", "dailyLabor", "dailyEquipment", "dailyMaterials"].includes(collectionKey)) return rows.filter(row => projectIds.includes(row.project));
  if (["contractRules", "squanScores"].includes(collectionKey)) return rows;
  return [];
}

function scopeForeman(collectionKey, rows) {
  const role = roleConfig.Foreman;
  const projectIds = (state.data.projects || [])
    .filter(project => project.crew === role.crew)
    .map(project => project.id);
  if (collectionKey === "projects") return rows.filter(row => row.crew === role.crew);
  if (collectionKey === "tasks") return rows.filter(row => row.owner === role.person || row.role === "Foreman" || projectIds.includes(row.project));
  if (collectionKey === "dailies") return rows.filter(row => row.crew === role.crew || row.foreman === role.person);
  if (collectionKey === "timeEntries") return rows.filter(row => row.crew === role.crew || row.foremanApproval === role.person);
  if (collectionKey === "equipment") return rows.filter(row => row.assigned === role.crew || projectIds.includes(row.assigned));
  if (collectionKey === "safety") return rows.filter(row => projectIds.includes(row.project));
  if (["documents", "photoEvidence", "siteSurveys", "obstacles", "qcCloseouts", "costBlockers", "formSubmissions"].includes(collectionKey)) return rows.filter(row => projectIds.includes(row.project));
  if (["projectUnits", "dailyProduction", "dailyLabor", "dailyEquipment", "dailyMaterials"].includes(collectionKey)) return rows.filter(row => projectIds.includes(row.project));
  if (["contractRules", "squanScores"].includes(collectionKey)) return rows;
  return [];
}

function scopeBilling(collectionKey, rows) {
  if (collectionKey === "projects") return rows;
  if (collectionKey === "tasks") return rows.filter(row => row.role === "Billing" || ["Money", "Billing", "Retainage"].some(term => `${row.workflowArea} ${row.relatedType} ${row.title}`.includes(term)));
  if (collectionKey === "dailies") return rows;
  if (collectionKey === "timeEntries") return rows;
  if (collectionKey === "invoices") return rows;
  if (collectionKey === "invoiceSubmissions") return rows;
  if (collectionKey === "collectionSubmissions") return rows;
  if (collectionKey === "billingReadiness") return rows;
  if (["documents", "photoEvidence", "siteSurveys", "obstacles", "qcCloseouts", "retainageLedger", "contractRules", "costBlockers", "squanScores", "formSubmissions", "cashReceipts", "cashDepositBatches"].includes(collectionKey)) return rows;
  if (["projectUnits", "dailyProduction", "dailyLabor", "dailyEquipment", "dailyMaterials"].includes(collectionKey)) return rows;
  return [];
}

function scopeSafety(collectionKey, rows) {
  if (collectionKey === "tasks") return rows.filter(row => row.role === "Safety/Compliance" || String(row.workflowArea).includes("Safety") || String(row.workflowArea).includes("People"));
  if (["projects", "dailies", "timeEntries", "people", "equipment", "safety", "documents", "photoEvidence", "siteSurveys", "obstacles", "qcCloseouts", "contractRules", "costBlockers", "squanScores", "formSubmissions"].includes(collectionKey)) return rows;
  return [];
}

