function renderView() {
  if (state.view === "dashboard") return renderRoleHome();
  if (state.view === "tasks") return renderTasks();
  if (state.view === "documents") return renderDocuments();
  if (state.view === "projects") return state.role === "Operations" ? renderOperationsBoard() : renderProjectHub();
  if (state.view === "field" && state.role === "Crew Member") return renderCrewMemberToday();
  if (state.view === "field") return state.role === "Foreman" ? renderForemanToday() : renderField();
  if (state.view === "production") return renderProductionControl();
  if (state.view === "time") return renderTimeTracking();
  if (state.view === "people") return renderPeopleCompliance();
  if (state.view === "equipment") return renderEquipmentAvailability();
  if (state.view === "money") return renderMoney();
  if (state.view === "risk") return state.role === "Safety/Compliance" ? renderSafetyRiskQueue() : renderRisk();
  if (state.view === "reports") return renderReports();
  if (state.view === "settings") return renderAdminSettings();
  return renderTablePanel(tableConfig()[state.view]);
}

function renderRoleHome() {
  if (state.role === "Foreman") return renderForemanHome();
  return renderSimpleRoleHome(state.role);
}

function renderWorkflowPathHome(role = state.role) {
  const project = selectedMapContext();
  const paths = roleWorkflowPaths(role, project);
  const primary = paths[0];
  return `
    <section class="panel workflow-path-home">
      <div class="workflow-path-hero">
        <div>
          <span class="eyebrow">${roleConfig[role]?.label || role}</span>
          <h2>Pick one path</h2>
          <p>Use one workflow at a time. Each path has clear steps, one next action, and details only when you need them.</p>
        </div>
        <span class="status ${statusClass(primary?.status || "Ready")}">${plainStatus(primary?.status || "Ready")}</span>
      </div>
      <div class="workflow-path-card-grid">
        ${paths.map((path, index) => `
          <button class="workflow-path-card ${index === 0 ? "active" : ""}" data-workflow-action="${path.action}" data-workflow-id="${project?.id || state.selectedProjectId || ""}" data-workflow-focus="${path.focus}" ${path.reportScope ? `data-report-scope="${path.reportScope}"` : ""}>
            <span>${index + 1}</span>
            <strong>${path.title}</strong>
            <small>${path.summary}</small>
            <em>${plainStatus(path.status)}</em>
          </button>
        `).join("")}
      </div>
    </section>
    ${primary ? renderWorkflowStepper(primary, project) : ""}
  `;
}

function roleWorkflowPaths(role, project = selectedMapContext()) {
  const all = workflowPathDefinitions(project);
  const allowed = {
    Admin: ["map-ready", "bill-squan", "fix-problems", "finish-report"],
    Operations: ["map-ready", "fix-problems", "field-work", "finish-report"],
    Foreman: ["field-work", "fix-problems", "map-ready"],
    "Crew Member": ["field-work", "fix-problems"],
    Billing: ["finish-report", "fix-problems"],
    "Safety/Compliance": ["fix-problems", "map-ready", "finish-report"]
  }[role] || ["map-ready", "field-work", "fix-problems", "bill-squan", "finish-report"];
  return allowed.map(key => all.find(path => path.key === key)).filter(Boolean);
}

function workflowPathDefinitions(project = selectedMapContext()) {
  const path = project ? mapCriticalPath(project) : null;
  const release = project ? releaseGateReview(project) : null;
  const fieldContext = selectedFieldContext();
  const startGate = fieldContext.project ? fieldStartGate(fieldContext.project, fieldContext.daily) : null;
  const safety = project ? safetyMapRiskRow(project) : null;
  const packageGate = project ? billingPackageBuildGate(project) : null;
  const readiness = project ? scopedRows("billingReadiness").find(item => item.project === project.id) : null;
  const reportStatus = project?.status === "Completed / Billed" ? "Ready" : packageGate?.ready ? "Needs Review" : "Pending";
  return [
    {
      key: "map-ready",
      title: "Get Map Ready",
      summary: "Intake through owner approval before field work starts.",
      status: release?.released ? "Ready" : release?.ready ? "Needs Approval" : path?.status || "Pending",
      action: "Project & Map Hub",
      focus: "Release gate",
      nextLabel: release?.released ? "Open Map" : release?.ready ? "Get owner approval" : "Continue setup",
      blockers: release?.blockers?.map(item => item.label) || [],
      steps: [
        ["Intake", "Map, customer, scope, and price are recorded.", "Ready"],
        ["Site survey", "Maps, site notes, and route review.", path?.steps?.find(step => step.key === "survey")?.status || "Pending"],
        ["811 / permits", "Locate tickets, permits, and traffic plan.", path?.steps?.find(step => step.key === "locates")?.status || "Pending"],
        ["Obstacles", "Photos, pins, notes, and owner assigned.", path?.steps?.find(step => step.key === "obstacles")?.status || "Pending"],
        ["Crew / equipment", "Crew and trucks/tools are clear.", path?.steps?.find(step => step.key === "resources")?.status || "Pending"],
        ["Owner approval", "Final yes before field work.", release?.released ? "Ready" : release?.ready ? "Needs Approval" : "Blocked"]
      ]
    },
    {
      key: "field-work",
      title: "Do Today’s Work",
      summary: "Pre-Check, photos, production, time, and daily submit.",
      status: startGate?.clear ? "Ready" : "Blocked",
      action: "Field Operations",
      focus: "Daily start",
      nextLabel: startGate?.clear ? "Start daily" : "Fix start problems",
      blockers: startGate?.blockers?.map(item => item.label) || [],
      steps: [
        ["Confirm Map", "Open the assigned Map and crew.", fieldContext.project ? "Ready" : "Pending"],
        ["Pre-Check", "Safety, equipment, crew, and 811.", startGate?.clear ? "Ready" : "Blocked"],
        ["Photos / obstacles", "Add field proof and site problems.", "Open"],
        ["Work done", "Production, materials, equipment, and time.", fieldContext.daily?.status || "Pending"],
        ["Submit daily", "One end-of-shift submit.", fieldContext.daily?.status === "Submitted" ? "Ready" : "Pending"]
      ]
    },
    {
      key: "fix-problems",
      title: "Fix Problems",
      summary: "Safety, proof, crew, equipment, and returned items.",
      status: safety?.status || "Pending",
      action: "Safety & Risk",
      focus: "Safety",
      nextLabel: safety?.status === "Clear" ? "Check safety" : "Fix first problem",
      blockers: safety?.detail && safety.status !== "Clear" ? [safety.detail] : [],
      steps: [
        ["See problem", "Find what is blocking work, proof, or billing.", safety?.status || "Pending"],
        ["Assign owner", "Know who must fix it.", "Open"],
        ["Add proof", "Upload photo, form, note, or record.", "Open"],
        ["Review", "Safety, Operations, Billing, or Admin checks it.", "Needs Review"],
        ["Clear or send back", "Move forward only when the fix is accepted.", safety?.status === "Clear" ? "Ready" : "Open"]
      ]
    },
    {
      key: "bill-squan",
      title: "Bill SQUAN",
      summary: "Proof, billing package, SQUAN response, unpaid money, held-back money.",
      status: readiness?.status === "Ready to Bill" || packageGate?.ready ? "Ready" : readiness?.status || packageGate?.status || "Pending",
      action: "Billing",
      focus: "Invoice package",
      nextLabel: packageGate?.ready ? "Build package" : "Check proof",
      blockers: packageGate?.blockers?.map(item => item.label) || [],
      steps: [
        ["Check proof", "Daily, SOT, photos, as-builts, QC.", readiness?.status || "Pending"],
        ["Build package", "Create billing package for SQUAN.", packageGate?.status || "Pending"],
        ["Send to SQUAN", "Record what was sent and when.", "Open"],
        ["Record response", "Receipt, rejection, dispute, or promise.", "Open"],
        ["Follow unpaid money", "90% invoice follow-up.", "Open"],
        ["Track money held back", "10% release clock.", "Open"]
      ]
    },
    {
      key: "finish-report",
      title: "Finish / Report",
      summary: "QC closeout, final proof, locked package, export, and history.",
      status: reportStatus,
      action: "Reports",
      focus: "Financial Closeout",
      reportScope: "Financial Closeout",
      nextLabel: "Open report",
      blockers: reportStatus === "Pending" ? ["Billing package and closeout proof are not ready yet."] : [],
      steps: [
        ["QC closeout", "Confirm work is complete.", project?.status === "Completed / Billed" ? "Ready" : "Pending"],
        ["Final proof check", "Proof is accepted and linked.", packageGate?.ready ? "Ready" : "Needs Review"],
        ["Lock package", "Prevent accidental changes.", "Open"],
        ["Export report", "Print or export for SQUAN/audit.", "Open"],
        ["History", "Keep decisions and changes recorded.", "Tracked"]
      ]
    }
  ];
}

function renderWorkflowStepper(path, project) {
  const complete = path.steps.filter(step => ["Ready", "Clear", "Tracked", "Submitted", "Accepted"].includes(step[2])).length;
  const currentIndex = Math.max(0, path.steps.findIndex(step => !["Ready", "Clear", "Tracked", "Submitted", "Accepted"].includes(step[2])));
  const currentStep = path.steps[currentIndex] || path.steps[path.steps.length - 1];
  const needsFix = guidedNeedsFixRows(project, path.key);
  return `
    <section class="panel workflow-stepper-panel">
      <div class="workflow-stepper-head">
        <div>
          <span class="eyebrow">${project?.map || project?.id || "No Map selected"}</span>
          <h2>${path.title}</h2>
          <p>Step ${Math.min(currentIndex + 1, path.steps.length)} of ${path.steps.length}: ${currentStep?.[0] || "Review"}</p>
        </div>
        <button class="primary-btn" data-workflow-action="${path.action}" data-workflow-id="${project?.id || state.selectedProjectId || ""}" data-workflow-focus="${path.focus}" ${path.reportScope ? `data-report-scope="${path.reportScope}"` : ""}>${path.nextLabel}</button>
      </div>
      <div class="workflow-stepper">
        ${path.steps.map((step, index) => `
          <button class="workflow-stepper-step ${index === currentIndex ? "current" : ""} ${statusClass(step[2])}" data-workflow-action="${path.action}" data-workflow-id="${project?.id || state.selectedProjectId || ""}" data-workflow-focus="${path.focus}">
            <span>${index + 1}</span>
            <strong>${step[0]}</strong>
            <small>${step[1]}</small>
            <em>${plainStatus(step[2])}</em>
          </button>
        `).join("")}
      </div>
      ${renderGuidedNeedsFixCenter(needsFix, path, project)}
      <details class="workflow-related">
        <summary>Related files, tasks, and history <span>${complete}/${path.steps.length} clear</span></summary>
        <div>
          <button class="secondary-btn" data-workflow-action="Project & Map Hub" data-workflow-id="${project?.id || state.selectedProjectId || ""}" data-workflow-focus="Map detail">Open Map</button>
          ${canView("documents") ? `<button class="secondary-btn" data-workflow-action="Documents" data-workflow-id="${project?.id || state.selectedProjectId || ""}" data-workflow-focus="Map evidence">Files / Proof</button>` : ""}
          ${canView("tasks") ? `<button class="secondary-btn" data-workflow-action="Tasks" data-workflow-id="${project?.id || state.selectedProjectId || ""}">Tasks</button>` : ""}
          ${canView("reports") ? `<button class="secondary-btn" data-workflow-action="Reports" data-workflow-id="${project?.id || state.selectedProjectId || ""}" data-report-scope="${path.reportScope || "Executive Report"}">Reports</button>` : ""}
        </div>
      </details>
    </section>
  `;
}

function guidedNeedsFixRows(project, pathKey = "fix-problems") {
  if (!project) return [];
  const rows = [];
  const add = row => {
    if (!row?.title) return;
    rows.push({
      id: row.id || `${row.group}-${row.title}`.replace(/[^a-z0-9]+/gi, "-").toLowerCase(),
      group: row.group || "Needs Fix",
      title: row.title,
      owner: row.owner || "Unassigned",
      proof: row.proof || "Add a note, file, photo, or review decision.",
      next: row.next || "Open the owning workflow and complete the guided fix.",
      status: row.status || "Needs Fix",
      action: row.action || "Tasks",
      focus: row.focus || row.group || "Needs Fix",
      severity: row.severity || "Medium",
      task: row.task || null
    });
  };

  const release = releaseGateReview(project);
  (release?.blockers || []).forEach(item => add({
    group: "Start Work",
    title: item.label,
    owner: releaseBlockerTaskConfig(item).owner || "Operations",
    proof: item.detail || "Clear the setup item and attach supporting proof.",
    next: "Complete the setup step, then recheck Ready for field work.",
    status: item.status || "Needs Fix",
    action: releaseBlockerTaskConfig(item).workflowArea || "Project & Map Hub",
    focus: "Release gate",
    severity: "High"
  }));

  const fieldContext = selectedFieldContext();
  const startGate = fieldContext.project?.id === project.id ? fieldStartGate(project, fieldContext.daily) : null;
  (startGate?.blockers || []).forEach(item => add({
    group: "Pre-Check",
    title: item.label,
    owner: "Foreman",
    proof: item.detail || "Complete the required check before the daily can start.",
    next: "Open Today’s Work and finish Pre-Check.",
    status: item.status || "Needs Fix",
    action: "Field Operations",
    focus: "Daily start",
    severity: "High"
  }));

  returnedDailyRows(project).forEach(row => add({
    id: `returned-daily-${row.daily.id}`,
    group: "Returned Daily",
    title: row.sourceLabel || `Fix returned daily ${row.daily.id}`,
    owner: "Foreman",
    proof: row.proofNeeded || "Correct the returned daily fields, attach proof if needed, then resubmit.",
    next: row.next || "Open the returned daily correction path, fix the requested item, then resubmit for Operations acceptance.",
    status: row.status || "Returned",
    action: "Field Operations",
    focus: "Returned daily correction",
    severity: "High",
    task: row.task || null
  }));

  const safety = safetyMapRiskRow(project);
  if (safety?.detail && safety.status !== "Clear") add({
    group: "Safety",
    title: safety.title || "Safety item needs review",
    owner: "Safety/Compliance",
    proof: safety.detail,
    next: "Review the safety item, add corrective proof, then clear or return it.",
    status: safety.status,
    action: "Safety & Risk",
    focus: "Safety fixes",
    severity: safety.status === "Blocked" ? "High" : "Medium"
  });

  const packageGate = canView("money") || canManageBilling() ? billingPackageBuildGate(project) : null;
  (packageGate?.blockers || []).forEach(item => add({
    group: "Billing Proof",
    title: item.label,
    owner: item.action === "Field Operations" ? "Foreman" : item.action === "Documents" ? "Billing Support" : "Admin",
    proof: item.detail || "Attach or accept the proof needed for Admin billing.",
    next: "Open the linked workflow, fix the proof, then recheck Billing.",
    status: item.status || "Needs Fix",
    action: item.action || "Billing",
    focus: "Invoice package",
    severity: "Medium"
  }));

  const submissionGate = canManageBilling() ? billingSubmissionGate(project) : null;
  (submissionGate?.blockers || []).forEach(item => add({
    group: "Admin Submission",
    title: item.label,
    owner: "Admin",
    proof: item.detail || "Clear the submission gate item before SQUAN submission.",
    next: "Open Billing, complete the guarded step, then submit only when clear.",
    status: item.status || "Needs Fix",
    action: item.action || "Billing",
    focus: "SQUAN submission",
    severity: "High"
  }));

  const roleGroups = {
    "map-ready": new Set(["Start Work"]),
    "field-work": new Set(["Pre-Check", "Start Work"]),
    "bill-squan": new Set(["Billing Proof", "Admin Submission"]),
    "finish-report": new Set(["Billing Proof", "Admin Submission", "Safety"]),
    "fix-problems": null
  };
  const allowed = roleGroups[pathKey];
  return uniqueList(rows.map(row => row.id))
    .map(id => rows.find(row => row.id === id))
    .filter(row => !allowed || allowed.has(row.group))
    .filter(row => !isNeedsFixExceptionAccepted(project, row))
    .slice(0, pathKey === "fix-problems" ? 12 : 6)
    .map(row => ({ ...row, why: needsFixWhy(row), task: row.task || ensureNeedsFixTask(project, row) }));
}

function needsFixTaskId(project, row) {
  return `TASK-NEEDS-FIX-${project.id}-${String(row.group)}-${String(row.title)}`
    .replace(/[^A-Z0-9-]/gi, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .toUpperCase();
}

function needsFixRoleForAction(action) {
  if (action === "Field Operations") return "Foreman";
  if (action === "People & Compliance" || action === "Safety & Risk") return "Safety/Compliance";
  if (action === "Equipment" || action === "Project & Map Hub") return "Operations";
  if (action === "Billing") return "Admin";
  if (action === "Documents") return "Billing";
  return "Admin";
}

function ensureNeedsFixTask(project, row) {
  if (!project || !row?.title) return null;
  state.data.tasks = state.data.tasks || [];
  const id = needsFixTaskId(project, row);
  const existing = state.data.tasks.find(task => task.id === id);
  if (existing) {
    if (existing.status === "Closed") return existing;
    const patch = {
      title: `Needs Fix: ${row.title}`,
      workflowArea: row.action || existing.workflowArea || "Tasks",
      owner: row.owner || existing.owner || "Unassigned",
      role: needsFixRoleForAction(row.action),
      notes: `${project.map || project.id}: ${row.next} Proof needed: ${row.proof}`,
      needsFixGroup: row.group,
      needsFixStatus: row.status,
      needsFixAction: row.action,
      needsFixFocus: row.focus
    };
    const changed = Object.entries(patch).some(([key, value]) => existing[key] !== value);
    Object.assign(existing, patch);
    if (changed) {
      existing.modifiedAt = new Date().toISOString();
      void saveToApi("tasks", existing, false);
    }
    return existing;
  }
  const task = {
    id,
    title: `Needs Fix: ${row.title}`,
    relatedType: "Map",
    relatedId: project.id,
    project: project.id,
    owner: row.owner || "Unassigned",
    role: needsFixRoleForAction(row.action),
    dueDate: addDays(isoDate(today), row.severity === "High" ? 1 : 2),
    priority: row.severity === "High" ? "High" : "Medium",
    status: "Open",
    workflowArea: row.action || "Tasks",
    notes: `${project.map || project.id}: ${row.next} Proof needed: ${row.proof}`,
    source: "Needs Fix",
    needsFixGroup: row.group,
    needsFixStatus: row.status,
    needsFixAction: row.action,
    needsFixFocus: row.focus,
    activityLog: [{ at: new Date().toISOString(), by: "System", note: "Auto-created from guided Needs Fix workflow." }],
    createdAt: new Date().toISOString(),
    modifiedAt: new Date().toISOString()
  };
  state.data.tasks.push(task);
  void saveToApi("tasks", task, true);
  return task;
}

function needsFixWhy(row) {
  const group = row?.group || "";
  if (group === "Start Work") return "A crew should not be released until the Map setup is complete and documented.";
  if (group === "Pre-Check") return "The crew cannot start work safely until Pre-Check is complete.";
  if (group === "Returned Daily") return "A submitted daily cannot feed proof or billing until the Foreman fixes it and Operations accepts it.";
  if (group === "Safety") return "Safety items protect the crew and keep audit records ready for SQUAN review.";
  if (group === "Billing Proof") return "Admin cannot bill SQUAN unless the required proof is attached and accepted.";
  if (group === "Admin Submission") return "SQUAN submission should wait until the packet is clean and review-ready.";
  return "This item must be handled before the next workflow step is trusted.";
}

function isNeedsFixExceptionAccepted(project, row) {
  const task = (state.data.tasks || []).find(item => item.id === needsFixTaskId(project, row));
  return task?.source === "Needs Fix" && task?.status === "Closed" && task?.needsFixResolution === "Exception accepted";
}

function returnNeedsFixTask(taskId) {
  const task = (state.data.tasks || []).find(item => item.id === taskId);
  if (!task) return;
  const note = prompt("Return this item with a short note for the owner:", "Please add the missing proof and resubmit.");
  if (!note) return;
  task.status = "Open";
  task.needsFixResolution = "Returned";
  task.notes = appendInlineNote(task.notes, `Returned: ${note}`);
  task.activityLog = [...(task.activityLog || []), {
    at: new Date().toISOString(),
    by: state.user?.name || "User",
    note: `Returned with note: ${note}`
  }];
  task.modifiedAt = new Date().toISOString();
  void saveToApi("tasks", task, false);
  persist("Needs Fix item returned");
  render();
}

function acceptNeedsFixException(taskId) {
  const task = (state.data.tasks || []).find(item => item.id === taskId);
  if (!task || !canManageBilling()) return;
  const note = prompt("Why is Admin accepting this exception?", "Authorized exception accepted by Admin.");
  if (!note) return;
  task.status = "Closed";
  task.needsFixResolution = "Exception accepted";
  task.closedAt = new Date().toISOString();
  task.closedBy = state.user?.name || "Admin";
  task.notes = appendInlineNote(task.notes, `Admin exception accepted: ${note}`);
  task.activityLog = [...(task.activityLog || []), {
    at: task.closedAt,
    by: task.closedBy,
    note: `Admin exception accepted: ${note}`
  }];
  void saveToApi("tasks", task, false);
  appendAuditLocal("needs-fix.exception-accepted", { task: task.id, project: task.project, note });
  persist("Needs Fix exception accepted");
  closeDrawer();
  render();
}

function renderNeedsFixStepButton(project, row, number, label, detail, action = row.action, focus = row.focus) {
  const target = workflowTarget(action, project?.id || "");
  const canOpen = canView(target);
  const attrs = canOpen
    ? `data-workflow-action="${action}" data-workflow-id="${project.id}" data-workflow-focus="${focus || row.focus || label}"`
    : "disabled";
  return `
    <button class="needs-fix-step" ${attrs}>
      <span>${number}</span>
      <strong>${label}</strong>
      <small>${detail}</small>
    </button>
  `;
}

function canActOnNeedsFix(row) {
  if (!row) return false;
  if (state.role === "Foreman") {
    return row.owner === "Foreman" || row.task?.role === "Foreman" || row.action === "Field Operations";
  }
  return canView(workflowTarget(row.action, state.selectedProjectId || ""));
}

function findNeedsFixRow(project, rowId, pathKey = "fix-problems") {
  if (!project) return null;
  return guidedNeedsFixRows(project, pathKey).find(item => item.id === rowId)
    || guidedNeedsFixRows(project, "fix-problems").find(item => item.id === rowId)
    || null;
}

function startNeedsFixRemedy(project, row) {
  if (!project || !row) return false;
  const target = workflowTarget(row.action, project.id);
  configureWorkflowRoute(target, project.id, row.action, row.focus);
  state.selectedProjectId = project.id;
  state.workflowFocus = row.focus || row.group || "Needs Fix";
  if (!canView(target)) return false;
  state.view = target;
  render();
  return true;
}

function openNeedsFixWorkflow(projectId, rowId, pathKey = "fix-problems") {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return;
  const row = findNeedsFixRow(project, rowId, pathKey);
  if (!row) return;
  if (!startNeedsFixRemedy(project, row)) openNeedsFixDrawer(project.id, row.id, pathKey);
}

function requestNeedsFixOwnerRemedy(projectId, rowId, pathKey = "fix-problems") {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  const row = findNeedsFixRow(project, rowId, pathKey);
  if (!project || !row) return;
  const task = row.task || ensureNeedsFixTask(project, row);
  if (!task) return;
  const by = state.user?.name || "User";
  const note = `${by} requested remedy from ${row.owner || task.owner || "the owner"}. Needed: ${row.proof}`;
  task.status = "Open";
  task.priority = row.severity === "High" ? "High" : task.priority || "Medium";
  task.needsFixResolution = "Owner remedy requested";
  task.notes = appendInlineNote(task.notes, `Remedy requested: ${row.next}`);
  task.activityLog = [...(task.activityLog || []), {
    at: new Date().toISOString(),
    by,
    note
  }];
  task.modifiedAt = new Date().toISOString();
  void saveToApi("tasks", task, false);
  appendAuditLocal("needs-fix.owner-remedy-requested", { task: task.id, project: project.id, owner: row.owner, requestedBy: by });
  persist("Fix request sent");
  closeDrawer();
  render();
}

function openNeedsFixRemedyDrawer(projectId, rowId, pathKey = "fix-problems") {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return;
  const row = findNeedsFixRow(project, rowId, pathKey);
  if (!row) return;
  const task = row.task || ensureNeedsFixTask(project, row);
  const canAct = canActOnNeedsFix(row);
  const target = workflowTarget(row.action, project.id);
  const canOpenTarget = canView(target);
  const drawer = document.getElementById("drawer");
  const backdrop = document.getElementById("drawerBackdrop");
  drawer.innerHTML = `
    <header>
      <div>
        <h2>Start remedy</h2>
        <span>${project.map || project.id} · ${row.group} · ${plainStatus(row.status)}</span>
      </div>
      <button class="icon-btn" id="closeDrawer" title="Close">×</button>
    </header>
    <div class="drawer-body needs-fix-drawer">
      <section class="needs-fix-remedy-hero ${canAct ? "" : "waiting"}">
        <div>
          <span class="eyebrow">${canAct ? "You can fix this" : "Waiting on owner"}</span>
          <h3>${row.title}</h3>
          <p>${canAct ? row.next : `${row.owner} owns this fix. Send the request so the work is tracked instead of guessing what to do next.`}</p>
        </div>
        <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
      </section>
      <section>
        <h3>What must happen</h3>
        <div class="needs-fix-steps">
          <article><span>1</span><strong>Owner</strong><small>${row.owner}</small></article>
          <article><span>2</span><strong>Do this</strong><small>${row.next}</small></article>
          <article><span>3</span><strong>Proof needed</strong><small>${row.proof}</small></article>
          <article><span>4</span><strong>Then</strong><small>Review the result, clear it, or return it with a note.</small></article>
        </div>
      </section>
      <section>
        <h3>Tracking</h3>
        <div class="packet-task-guard ${task?.status === "Closed" ? "clear" : ""}">
          <strong>${task?.id || "No task"}</strong>
          <span>${task ? `${task.owner || "Unassigned"} · due ${task.dueDate || "not set"} · ${task.status}` : "A task will be created automatically for this fix."}</span>
        </div>
      </section>
    </div>
    <footer>
      ${canAct && canOpenTarget ? `<button class="primary-btn" id="needsFixStartRemedy">Start remedy now</button>` : ""}
      ${!canAct && task ? `<button class="primary-btn" id="needsFixRequestOwner">Request owner fix</button>` : ""}
      ${canView("projects") ? `<button class="secondary-btn" id="needsFixOpenMapFromRemedy">Open Map</button>` : ""}
      ${task ? `<button class="secondary-btn" id="needsFixOpenTaskFromRemedy">Details</button>` : ""}
    </footer>
  `;
  drawer.classList.add("open");
  backdrop.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");
  document.getElementById("closeDrawer").addEventListener("click", closeDrawer);
  const startButton = document.getElementById("needsFixStartRemedy");
  if (startButton) startButton.addEventListener("click", () => {
    closeDrawer();
    if (!startNeedsFixRemedy(project, row)) openNeedsFixDrawer(project.id, row.id, pathKey);
  });
  const requestButton = document.getElementById("needsFixRequestOwner");
  if (requestButton) requestButton.addEventListener("click", () => requestNeedsFixOwnerRemedy(project.id, row.id, pathKey));
  const mapButton = document.getElementById("needsFixOpenMapFromRemedy");
  if (mapButton) mapButton.addEventListener("click", () => {
    closeDrawer();
    handleWorkflowClick({ dataset: { workflowAction: "Project & Map Hub", workflowId: project.id, workflowFocus: "Needs Fix" } });
  });
  const taskButton = document.getElementById("needsFixOpenTaskFromRemedy");
  if (taskButton && task) taskButton.addEventListener("click", () => openNeedsFixDrawer(project.id, row.id, pathKey));
}

function openNeedsFixWorkflowDirect(projectId, rowId, pathKey = "fix-problems") {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return;
  const row = findNeedsFixRow(project, rowId, pathKey);
  if (!row) return;
  if (!canActOnNeedsFix(row)) {
    openNeedsFixDrawer(project.id, row.id, pathKey);
    return;
  }
  if (!startNeedsFixRemedy(project, row)) openNeedsFixDrawer(project.id, row.id, pathKey);
}

function renderGuidedNeedsFixCenter(rows, path, project) {
  if (!rows.length) {
    return `
      <section class="guided-needs-fix clear">
        <div>
          <h3>No Needs Fix item first in line</h3>
          <p>Continue the workflow when ready.</p>
        </div>
        <span class="status ${statusClass("Ready")}">Ready</span>
      </section>
    `;
  }
  return `
    <section class="guided-needs-fix">
      <div class="guided-fix-head">
        <div>
          <h3>Needs Fix</h3>
          <p>Use these guided cards instead of guessing what “blocked” means.</p>
        </div>
        <span class="status ${statusClass("Needs Review")}">${rows.length} item${rows.length === 1 ? "" : "s"}</span>
      </div>
      <div class="guided-fix-grid">
        ${rows.map(row => `
          <article class="guided-fix-card ${statusClass(row.status)}">
            <div class="guided-fix-top">
              <span>${row.group}</span>
              <em class="status ${statusClass(row.status)}">${plainStatus(row.status)}</em>
            </div>
            <h4>${row.title}</h4>
            <ol>
              <li><strong>Owner:</strong> ${row.owner}</li>
              <li><strong>Why:</strong> ${row.why}</li>
              <li><strong>Do this:</strong> ${row.next}</li>
              <li><strong>Proof needed:</strong> ${row.proof}</li>
              <li><strong>After review:</strong> clear it or return it with a note.</li>
            </ol>
            <div class="guided-fix-actions">
              <button class="primary-btn" data-needs-fix-open="${row.id}" data-project-id="${project?.id || state.selectedProjectId || ""}" data-path-key="${path.key}">Open</button>
              ${row.task ? `<button class="secondary-btn" data-needs-fix-details="${row.id}" data-project-id="${project?.id || state.selectedProjectId || ""}" data-path-key="${path.key}">Details</button>` : ""}
            </div>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function openNeedsFixDrawer(projectId, rowId, pathKey = "fix-problems") {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return;
  const row = guidedNeedsFixRows(project, pathKey).find(item => item.id === rowId)
    || guidedNeedsFixRows(project, "fix-problems").find(item => item.id === rowId);
  if (!row) return;
  const task = row.task || ensureNeedsFixTask(project, row);
  const canAct = canActOnNeedsFix(row);
  const drawer = document.getElementById("drawer");
  const backdrop = document.getElementById("drawerBackdrop");
  drawer.innerHTML = `
    <header>
      <div>
        <h2>${row.title}</h2>
        <span>${row.group} · ${plainStatus(row.status)}</span>
      </div>
      <button class="icon-btn" id="closeDrawer" title="Close">×</button>
    </header>
    <div class="drawer-body needs-fix-drawer">
      <section>
        <div class="section-heading">
          <div>
            <h3>What needs fixing?</h3>
            <p>${row.proof}</p>
          </div>
          <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
        </div>
      </section>
      <section>
        <h3>${canAct ? "Fix workflow preview" : "Waiting on another owner"}</h3>
        <div class="needs-fix-steps">
          ${canAct ? `
            ${renderNeedsFixStepButton(project, row, 1, "Open owner work", `${row.owner} owns this fix.`, row.action, row.focus)}
            ${renderNeedsFixStepButton(project, row, 2, "Open Map", row.why, "Project & Map Hub", "Needs Fix")}
            ${renderNeedsFixStepButton(project, row, 3, "Do this", row.next, row.action, row.focus)}
            ${renderNeedsFixStepButton(project, row, 4, "Add proof", row.proof, row.action === "Documents" ? "Documents" : row.action, row.focus)}
            ${renderNeedsFixStepButton(project, row, 5, "Review result", "Clear it, return it with a note, or Admin accepts an exception.", row.group === "Safety" ? "Safety & Risk" : row.group === "Billing Proof" || row.group === "Admin Submission" ? "Billing" : "Tasks", row.focus)}
          ` : `
            <article><span>1</span><strong>Owner</strong><small>${row.owner} owns this fix.</small></article>
            <article><span>2</span><strong>What you are waiting on</strong><small>${row.next}</small></article>
            <article><span>3</span><strong>Proof needed</strong><small>${row.proof}</small></article>
            <article><span>4</span><strong>What you can do</strong><small>Continue Foreman-owned daily steps that are not blocked by this item.</small></article>
          `}
        </div>
      </section>
      <section>
        <h3>Task link</h3>
        <div class="packet-task-guard ${task?.status === "Closed" ? "clear" : ""}">
          <strong>${task?.id || "No task"}</strong>
          <span>${task ? `${task.owner || "Unassigned"} · due ${task.dueDate || "not set"} · ${task.status}` : "A task will be created automatically for this Needs Fix item."}</span>
        </div>
      </section>
    </div>
    <footer>
      ${canAct ? `<button class="primary-btn" id="needsFixOpenWorkflow">Open workflow</button>` : `<button class="secondary-btn" id="needsFixOpenMap">Open Map</button>`}
      ${task ? `<button class="secondary-btn" id="needsFixOpenTask">Task record</button>` : ""}
      ${task && task.status !== "Closed" && canAct ? `<button class="secondary-btn" id="needsFixReturnTask">Return with note</button>` : ""}
      ${task && task.status !== "Closed" && canManageBilling() ? `<button class="secondary-btn" id="needsFixAcceptException">Accept exception</button>` : ""}
      ${task && task.status !== "Closed" && canAct ? `<button class="primary-btn" id="needsFixCompleteTask">Clear after fixed</button>` : ""}
    </footer>
  `;
  drawer.classList.add("open");
  backdrop.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");
  document.getElementById("closeDrawer").addEventListener("click", closeDrawer);
  drawer.querySelectorAll("[data-workflow-action]").forEach(button => {
    button.addEventListener("click", () => {
      closeDrawer();
      handleWorkflowClick(button);
    });
  });
  const workflowButton = document.getElementById("needsFixOpenWorkflow");
  if (workflowButton) workflowButton.addEventListener("click", () => {
    closeDrawer();
    openNeedsFixWorkflowDirect(project.id, row.id, pathKey);
  });
  const mapButton = document.getElementById("needsFixOpenMap");
  if (mapButton) mapButton.addEventListener("click", () => {
    closeDrawer();
    handleWorkflowClick({ dataset: { workflowAction: "Project & Map Hub", workflowId: project.id, workflowFocus: "Needs Fix" } });
  });
  const taskButton = document.getElementById("needsFixOpenTask");
  if (taskButton && task) taskButton.addEventListener("click", () => openTaskWorkflow(task.id));
  const returnButton = document.getElementById("needsFixReturnTask");
  if (returnButton && task) returnButton.addEventListener("click", () => returnNeedsFixTask(task.id));
  const exceptionButton = document.getElementById("needsFixAcceptException");
  if (exceptionButton && task) exceptionButton.addEventListener("click", () => acceptNeedsFixException(task.id));
  const completeButton = document.getElementById("needsFixCompleteTask");
  if (completeButton && task) completeButton.addEventListener("click", () => {
    completeTask(task.id);
    closeDrawer();
  });
}

function renderRoleCommandCenter(role = state.role) {
  const project = selectedMapContext();
  const config = roleCommandCenterConfig(role, project);
  const visibleActions = config.actions.filter(action => canView(workflowTarget(action.workflow, action.project || project?.id || "")));
  return `
    <section class="panel role-command-center">
      <div class="panel-header">
        <div>
          <h2>${config.title}</h2>
          <p>${config.description}</p>
        </div>
        <span>${project?.map || project?.id || "No Map selected"}</span>
      </div>
      <div class="role-command-grid">
        ${visibleActions.map(action => `
          <button class="${action.primary ? "primary-command" : ""}" data-workflow-action="${action.workflow}" data-workflow-id="${action.project || project?.id || ""}" data-workflow-focus="${action.focus || ""}">
            <strong>${action.label}</strong>
            <span>${action.detail}</span>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function roleHomeProfile(role = state.role) {
  const project = selectedMapContext();
  const tasks = scopedRows("tasks").filter(item => item.status !== "Closed");
  const safety = scopedRows("safety").filter(item => item.status !== "Closed");
  const readiness = scopedRows("billingReadiness").find(item => item.project === project?.id);
  const release = project ? releaseGateReview(project) : null;
  const startContext = selectedFieldContext();
  const startGate = startContext.project ? fieldStartGate(startContext.project, startContext.daily) : null;
  const billingReady = scopedRows("billingReadiness").filter(item => item.status === "Ready to Bill");
  const overdueFollowUps = paymentFollowUpRows().filter(item => !item.paid90Complete && item.daysUntilFollowUp !== null && item.daysUntilFollowUp < 0);
  const roleRows = tasks.filter(task => task.role === role || task.owner === state.user?.name || (role === "Admin" && (task.role === "Admin" || task.owner === "Ronald Jackson")));
  const mapLabel = project?.map || project?.id || "No Map selected";
  const common = {
    project,
    mapLabel,
    status: project?.status || "Select Map",
    tasks,
    roleRows,
    safety,
    readiness,
    release,
    startGate,
    billingReady,
    overdueFollowUps
  };
  const profiles = {
    Admin: {
      title: "Owner decisions today",
      primary: { label: "See owner decisions", workflow: "Tasks", focus: "Admin decision" },
      cards: [
        { label: "Ready to start?", value: scopedRows("projects").filter(item => item.status === "Beginning Phase" && !item.adminApprovals?.release).length, detail: "Maps waiting for owner approval" },
        { label: "Can bill now", value: currency(sum(billingReady, "billableAmount")), detail: `${billingReady.length} Map(s) ready to bill` },
        { label: "Safety problems", value: safety.length, detail: "Open safety items" },
        { label: "Unpaid follow-up", value: overdueFollowUps.length, detail: "Late payment follow-ups" }
      ],
      next: roleRows[0]?.title || "Check Maps, billing, safety, and cash problems.",
      nextDetail: roleRows[0] ? `${roleRows[0].owner || "Unassigned"}; due ${roleRows[0].dueDate || "N/A"}` : "No owner problem is first in line."
    },
    Operations: {
      title: "Get Maps ready for work",
      primary: { label: "Check if ready to work", workflow: "Project & Map Hub", focus: "Release gate" },
      cards: [
        { label: "Selected Map", value: mapLabel, detail: project?.scope || "Choose a Map" },
        { label: "Phase", value: project?.status || "None", detail: "Current Map stage" },
        { label: "Ready to work?", value: release?.released ? "Approved" : release?.ready ? "Ready" : "Blocked", detail: release?.blockers?.map(item => item.label).join(", ") || "No problems stopping work" },
        { label: "Setup tasks", value: roleRows.length, detail: "Operations items still open" }
      ],
      next: release?.released ? "Tell the Foreman the daily can start." : release?.ready ? "Get owner approval to start." : "Fix setup problems before field work.",
      nextDetail: release?.blockers?.map(item => item.label).join(", ") || "Map can move to the next step."
    },
    Foreman: {
      title: "Run today’s job",
      primary: { label: "Open Pre-Check", workflow: "Field Operations", focus: "Daily start" },
      cards: [
        { label: "Assigned Map", value: mapLabel, detail: project?.crew || state.user?.crew || "Crew assignment" },
        { label: "Ready to work?", value: startGate?.clear ? "Ready" : "Blocked", detail: startGate?.blockers?.map(item => item.label).join(", ") || "Safety, equipment, and 811 are ready" },
        { label: "Daily status", value: startContext.daily?.status || "Not started", detail: startContext.daily?.date || "Open today’s daily" },
        { label: "Fixes needed", value: roleRows.filter(item => /correction|returned|capture/i.test(`${item.source} ${item.title}`)).length, detail: "Returned field items" }
      ],
      next: startGate?.clear ? "Finish today’s steps and submit once." : "Fix start problems before work begins.",
      nextDetail: startGate?.blockers?.map(item => item.label).join(", ") || "Capture photos, production, materials, and time."
    },
    "Crew Member": {
      title: "My assignment today",
      primary: { label: "Open my work", workflow: "Field Operations", focus: "Daily start" },
      cards: [
        { label: "Crew", value: state.user?.crew || "Unassigned", detail: state.user?.fieldType || "Crew member" },
        { label: "Map", value: mapLabel, detail: project?.scope || "Today’s assigned work" },
        { label: "Safety", value: safety.length ? "Check" : "Clear", detail: "Report hazards or obstacles" },
        { label: "Time", value: scopedRows("timeEntries").filter(item => item.employee === state.user?.name || item.employeeId === state.user?.personId).length, detail: "Entries to confirm" }
      ],
      next: "Sign safety, report anything unsafe, then confirm time.",
      nextDetail: "Crew members only see the work they need for today."
    },
    Billing: {
      title: "Support billing proof",
      primary: { label: "Check proof files", workflow: "Documents", focus: "Evidence viewer" },
      cards: [
        { label: "Ready for Admin", value: currency(sum(billingReady, "billableAmount")), detail: `${billingReady.length} Map package(s)` },
        { label: "Selected Map", value: readiness?.status || "Not Ready", detail: readiness?.missingItems || "No missing support" },
        { label: "Proof tasks", value: scopedRows("tasks").filter(item => item.role === "Billing" || item.owner === "Office Billing").length, detail: "Support items to finish" },
        { label: "Proof files", value: scopedRows("documents").filter(item => item.requiredForBilling === "Yes").length, detail: "Files that feed Admin billing" }
      ],
      next: billingReady.length ? "Confirm proof is complete for Admin review." : "Fix missing proof before Admin billing.",
      nextDetail: readiness?.missingItems || "Crew daily inputs, photos, SOT, time, materials, and closeout proof feed Admin billing."
    },
    "Safety/Compliance": {
      title: "Fix safety problems",
      primary: { label: "Open safety work", workflow: "Safety & Risk", focus: "Safety" },
      cards: [
        { label: "Open safety", value: safety.length, detail: "Incidents, hazards, safety forms" },
        { label: "Crew problems", value: scopedRows("people").filter(item => ["Blocked", "Expiring"].includes(item.compliance)).length, detail: "Training cards or required checks" },
        { label: "Equipment problems", value: scopedRows("equipment").filter(item => item.status === "Unavailable").length, detail: "Inspection or calibration issues" },
        { label: "Map status", value: mapLabel, detail: project?.status || "Select a Map" }
      ],
      next: safety[0]?.correctiveAction || "Check problems and either clear them or return them to be fixed.",
      nextDetail: safety[0] ? `${safety[0].project}; due ${safety[0].due}` : "No safety item is first in line."
    }
  };
  return { ...common, ...(profiles[role] || profiles.Admin) };
}

