function renderCloseoutAlertAdminSummary(projects) {
  if (!state.role === "Admin") return "";
  const projectIds = new Set(projects.map(project => project.id));
  const closeouts = (state.data.billingTaskCloseouts || []).filter(item => projectIds.has(item.project));
  const rollup = billingCloseoutFinalizationRollup(closeouts);
  const readinessAging = closeoutReadinessAgingRows(projects);
  const escalatedReadiness = readinessAging.filter(item => item.needsEscalation);
  const controls = closeoutAlertControlsForProjects(projects);
  const activeControls = controls.filter(control => control.status === "Active");
  const activeSnoozes = activeControls.filter(control => control.kind === "Snoozed" && control.snoozedUntil && new Date(control.snoozedUntil) > new Date());
  const activeDismissals = activeControls.filter(control => control.kind === "Dismissed");
  const rows = [
    ...escalatedReadiness.slice(0, 2).map(item => closeoutReadinessAgingHomeRow(item)),
    ...rollup.agingReopenTasks.slice(0, 2).map(task => billingCloseoutAlertTaskRow(task)),
    ...rollup.rejectedEvidence.slice(0, 2).map(item => billingCloseoutAlertEvidenceRow(item)),
    ...rollup.pendingFinalReview.slice(0, 2).map(closeout => billingCloseoutAlertFinalRow(closeout)),
    ...activeControls.slice(0, 3).map(control => closeoutAlertControlRow(control, projects))
  ].slice(0, 6);
  if (!rows.length && !activeControls.length && !readinessAging.length) return "";
  return `
    <section class="panel packet-home-summary billing-closeout-alert-summary">
      <div class="panel-header">
        <div>
          <h2>Closeout alert summary</h2>
          <p>Snoozed, dismissed, and active Billing closeout finalization alerts.</p>
        </div>
        <button class="secondary-btn" data-workflow-action="Reports" data-workflow-id="${state.selectedProjectId || projects[0]?.id || ""}" data-report-scope="Billing Closeouts">Open closeout report</button>
      </div>
      <div class="packet-home-metrics">
        ${metric("Active controls", activeControls.length, "Closeout alert controls")}
        ${metric("Snoozed", activeSnoozes.length, "Hidden until due")}
        ${metric("Dismissed", activeDismissals.length, "Hidden for revision")}
        ${metric("Reopened", rollup.reopened.length, "Need correction path")}
        ${metric("Pending final", rollup.pendingFinalReview.length, "Need Admin review")}
        ${metric("Rejected evidence", rollup.rejectedEvidence.length, "Needs replacement")}
        ${metric("Readiness aging", readinessAging.filter(item => item.severity !== "Info").length, `${escalatedReadiness.length} escalated`)}
      </div>
      <div class="packet-home-list">
        ${rows.join("") || `<p class="empty-state">No closeout alert controls need review.</p>`}
      </div>
    </section>
  `;
}

