function renderCrewMemberToday() {
  const person = scopedRows("people")[0] || {};
  const project = scopedRows("projects").find(item => item.id === state.selectedProjectId) || scopedRows("projects")[0];
  const daily = scopedRows("dailies").find(item => item.project === project?.id) || scopedRows("dailies")[0];
  const obstacles = scopedRows("obstacles").filter(item => item.project === project?.id);
  const safetyItems = scopedRows("safety").filter(item => item.project === project?.id);
  const timeEntries = scopedRows("timeEntries").filter(item => item.project === project?.id);
  const myTime = timeEntries.find(item => item.employeeId === state.user?.personId || item.employee === state.user?.name) || timeEntries[0];
  const certDays = daysUntil(person.nextExpiration);
  const certStatus = certDays !== null && certDays <= 30 ? "Expiring" : person.compliance || "Clear";
  const jsaStatus = ["Complete", "Submitted"].includes(daily?.jsa) ? "Signed" : daily?.jsa || "Pending";
  const timeStatus = myTime?.crewConfirmationStatus || myTime?.approvalStatus || "Pending";
  const hazardStatus = safetyItems.length || obstacles.some(isOpenObstacle) ? "Review" : "Clear";
  const checklist = [
    { number: "1", title: "View assignment", detail: project ? `${project.map || project.id}; ${project.scope}` : "No assigned Map", status: project ? "Ready" : "Pending", action: "Project & Map Hub", focus: "Map detail" },
    { number: "2", title: "Acknowledge safety", detail: `JSA/PPE status: ${jsaStatus}. Review the work area before starting.`, status: jsaStatus, action: "Field Operations", focus: "Daily start" },
    { number: "3", title: "Report hazard or obstacle", detail: obstacles.length ? `${obstacles.length} obstacle(s) linked to this Map.` : "No obstacle reported for your assignment.", status: hazardStatus, action: "Safety & Risk", focus: "Safety" },
    { number: "4", title: "Confirm time", detail: myTime ? `${myTime.date}; ${Number(myTime.regularHours || 0) + Number(myTime.overtimeHours || 0)} hrs; ${myTime.workType || myTime.costCode || "Field work"}` : "No time entry has been created yet.", status: timeStatus, action: "Time Tracking", focus: "Time confirmation" }
  ];

  return `
    <section class="panel crew-today-home">
      <div class="crew-today-head">
        <div>
        <span class="eyebrow">${state.user.fieldType || "Field"} crew member</span>
          <h2>My Work Today</h2>
          <p>${person.name || state.user.name} only needs today’s Map, safety signoff, problem reporting, and time confirmation.</p>
        </div>
        <span class="status ${statusClass(certStatus)}">${certStatus}</span>
      </div>
      <div class="crew-assignment-strip">
        <article><span>Map</span><strong>${project?.map || project?.id || "None"}</strong><small>${project?.scope || "No assigned work"}</small></article>
        <article><span>Crew / role</span><strong>${state.user.crew || "Unassigned"}</strong><small>${person.role || state.user.fieldType || "Crew Member"}</small></article>
        <article><span>Safety</span><strong>${hazardStatus}</strong><small>${safetyItems[0]?.correctiveAction || "No open safety item first in line."}</small></article>
        <article><span>Time</span><strong>${timeStatus}</strong><small>${myTime ? `${Number(myTime.regularHours || 0) + Number(myTime.overtimeHours || 0)} hrs` : "Waiting on time entry"}</small></article>
      </div>
    </section>
    <section class="panel crew-checklist-panel">
      <div class="panel-header">
        <div>
          <h2>My Steps Today</h2>
          <p>Do these steps in order. Anything else belongs to the Foreman, Operations, Office, Safety, or Admin.</p>
        </div>
        <span>${checklist.filter(item => ["Ready", "Clear", "Signed", "Confirmed", "Approved"].includes(item.status)).length}/${checklist.length} clear</span>
      </div>
      <div class="crew-checklist-grid">
        ${checklist.map(item => `
          <button class="crew-check-card ${statusClass(item.status)}" data-workflow-action="${item.action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${item.focus}">
            <span>${item.number}</span>
            <strong>${item.title}</strong>
            <small>${item.detail}</small>
            <em>${plainStatus(item.status)}</em>
          </button>
        `).join("")}
      </div>
    </section>
    ${project ? renderFieldEvidenceCorrectionQueue(project) : ""}
    ${renderCrewTimeConfirmationWorkflow(project)}
  `;
}

function renderPhotoStrip(photos) {
  if (!photos.length) return "";
  return `
    <section class="panel photo-strip-panel">
      <div class="panel-header">
        <h2>Photo proof locations</h2>
        <span>${photos.length} placeholders</span>
      </div>
      <div class="photo-strip">
        ${photos.map(photo => `
          <article class="photo-tile">
            <img src="${photo.imageUrl}" alt="${photo.caption}" loading="lazy">
            <strong>${photo.workflowStage}</strong>
            <span>${photo.category}</span>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function fieldMapsReadiness(project) {
  const gis = project?.arcgis || {};
  const blockers = [];
  if (!gis.mapUrl || !gis.webMapId) blockers.push("ArcGIS map link missing");
  if (!gis.layerName) blockers.push("Field Maps layer missing");
  if (!gis.featureIds) blockers.push("Feature IDs not linked");
  if (!gis.workArea) blockers.push("Work area not defined");
  if (["Missing", "Needs Review", "Rejected", "Not started"].includes(gis.syncStatus || "Missing")) blockers.push(`Sync status ${gis.syncStatus || "Missing"}`);
  if (Number(gis.obstaclePins || 0) > 0 && !["Accepted", "Accepted by prime", "Field Verified"].includes(gis.primeAcceptanceStatus || "")) blockers.push(`${gis.obstaclePins} GIS obstacle pin(s) need review`);
  const ready = blockers.length === 0;
  return {
    ready,
    status: ready ? "Ready" : blockers.some(item => /missing|obstacle/i.test(item)) ? "Blocked" : "Needs Review",
    blockers,
    gis
  };
}

function fieldMapsEvidenceStatus(project) {
  const readiness = fieldMapsReadiness(project);
  const gis = readiness.gis || {};
  const acceptedCaptures = acceptedFieldCaptureEvidence(project);
  const primeAccepted = ["Accepted", "Accepted by prime", "Field Verified"].includes(gis.primeAcceptanceStatus || "");
  const asBuiltAccepted = ["Accepted", "Accepted by prime", "Field Verified"].includes(gis.asBuiltStatus || "");
  const status = readiness.ready
    ? primeAccepted && asBuiltAccepted || acceptedCaptures.rows.length ? "Accepted" : "Ready"
    : acceptedCaptures.rows.length ? "Accepted"
    : readiness.status;
  const blockerText = readiness.blockers.join(", ");
  return {
    key: "arcgis-field-maps",
    label: "ArcGIS Field Maps handoff",
    status,
    detail: readiness.ready
      ? `Web map ${gis.webMapId}; layer ${gis.layerName}; ${Number(gis.gpsPoints || 0)} GPS point(s); ${Number(gis.obstaclePins || 0)} obstacle pin(s); ${acceptedCaptures.rows.length} accepted field capture(s); prime ${gis.primeAcceptanceStatus || "not recorded"}; as-built ${gis.asBuiltStatus || "not recorded"}.`
      : acceptedCaptures.rows.length
      ? `${acceptedCaptures.rows.length} accepted field capture(s) available while GIS readiness still has: ${blockerText || "open review items"}.`
      : `Field Maps handoff blocked: ${blockerText || "GIS readiness not complete"}.`,
    action: "Project & Map Hub",
    gis,
    ready: readiness.ready,
    blockers: readiness.blockers
  };
}

function isAcceptedFieldCaptureRecord(record) {
  return ["Accepted", "Field Verified", "Closed", "Resolved"].includes(record?.reviewStatus || record?.status || "");
}

function isOpenObstacle(item) {
  return !["Resolved", "Field Verified", "Closed", "Accepted"].includes(item?.status || "") && item?.reviewStatus !== "Accepted";
}

function acceptedFieldCaptureEvidence(project) {
  if (!project) return { rows: [], photos: [], markups: [], billingCount: 0, safetyCount: 0, closeoutCount: 0 };
  const rows = fieldCaptureReviewRows(project).filter(row => row.status === "Accepted" || isAcceptedFieldCaptureRecord(row.related));
  const photos = rows.filter(row => row.collection === "photoEvidence");
  const markups = rows.filter(row => row.collection === "obstacles");
  return {
    rows,
    photos,
    markups,
    billingCount: photos.length + markups.filter(row => /billing/i.test(row.blockerImpact || "") || row.related?.acceptedForBilling === "Yes").length,
    safetyCount: rows.filter(row => row.collection === "obstacles" || /safety|release/i.test(row.blockerImpact || "") || row.related?.acceptedForSafety === "Yes").length,
    closeoutCount: rows.filter(row => /closeout|field review|as-built|obstruction|markup/i.test(`${row.kind} ${row.blockerImpact} ${row.summary}`) || row.related?.acceptedForCloseout === "Yes").length
  };
}

function arcgisObstructionRows(project) {
  if (!project) return [];
  const openStatuses = ["Open", "Needs Review", "Evidence Attached", "Field Verified", "Pending Prime Review"];
  const rows = (state.data.obstacles || [])
    .filter(item => item.project === project.id && openStatuses.includes(item.status || "Open") && item.reviewStatus !== "Accepted")
    .map(item => ({
      ...item,
      gisFeatureId: item.gisFeatureId || project.arcgis?.featureIds || "",
      stage: item.status || "Open",
      photoReady: Boolean(item.photoRefs && !/pending/i.test(item.photoRefs)),
      ownerReady: Boolean(item.owner || item.responsibleParty)
    }));
  if (!rows.length && Number(project.arcgis?.obstaclePins || 0) > 0) {
    rows.push({
      id: `GIS-${project.id}-PIN`,
      project: project.id,
      location: project.arcgis?.workArea || project.map || project.id,
      type: "GIS obstruction pin",
      description: project.arcgis?.notes || "ArcGIS Field Maps obstruction pin needs review.",
      photoRefs: project.arcgis?.photoRefs || "Pending field photos",
      impact: "Work release blocker",
      responsibleParty: "Operations",
      status: project.arcgis?.primeAcceptanceStatus === "Pending" ? "Pending Prime Review" : project.arcgis?.syncStatus || "Open",
      notes: project.arcgis?.notes || "",
      gisFeatureId: project.arcgis?.featureIds || "",
      stage: project.arcgis?.syncStatus || "Open",
      photoReady: Boolean(project.arcgis?.photoRefs && !/pending/i.test(project.arcgis.photoRefs)),
      ownerReady: true
    });
  }
  return rows;
}

function arcgisObstructionResolution(project) {
  const rows = arcgisObstructionRows(project);
  const gis = project?.arcgis || {};
  const ownerReady = rows.length > 0 && rows.every(item => item.ownerReady);
  const evidenceReady = rows.length > 0 && rows.every(item => item.photoReady);
  const fieldVerified = rows.length > 0 && rows.every(item => ["Field Verified", "Pending Prime Review", "Resolved", "Closed"].includes(item.status || ""));
  const primeAccepted = ["Accepted", "Accepted by prime"].includes(gis.primeAcceptanceStatus || "") && Number(gis.obstaclePins || 0) === 0;
  const steps = [
    { key: "owner", label: "Owner assigned", status: ownerReady ? "Ready" : rows.length ? "Needs Review" : "Clear", detail: ownerReady ? "Every obstruction has an owner." : "Assign Operations/Safety owner before release." },
    { key: "evidence", label: "Photos / potholing proof", status: evidenceReady ? "Ready" : rows.length ? "Needs Review" : "Clear", detail: evidenceReady ? "Photo proof is linked." : "Attach field photo, potholing, or survey proof." },
    { key: "field", label: "Field verified", status: fieldVerified ? "Field Verified" : rows.length ? "Blocked" : "Clear", detail: fieldVerified ? "Field verification recorded." : "Foreman/Operations must verify the obstruction." },
    { key: "prime", label: "Prime acceptance", status: primeAccepted ? "Accepted" : rows.length ? gis.primeAcceptanceStatus || "Pending" : "Clear", detail: primeAccepted ? "Prime accepted the obstruction resolution." : "Submit resolution to prime and record acceptance." }
  ];
  return {
    rows,
    steps,
    ready: rows.length === 0 || steps.every(item => ["Ready", "Clear", "Field Verified", "Accepted"].includes(item.status)),
    status: rows.length === 0 ? "Clear" : primeAccepted ? "Accepted" : fieldVerified ? "Pending Prime Review" : "Blocked"
  };
}

function renderFieldMapsDailyConfirmation(project) {
  const readiness = fieldMapsReadiness(project);
  const gis = readiness.gis;
  return `
    <section class="daily-gis-confirmation">
      <div class="section-heading compact">
        <h3>ArcGIS Field Maps check</h3>
        <span class="status ${statusClass(readiness.status)}">${plainStatus(readiness.status)}</span>
      </div>
      <div class="daily-gis-grid">
        <span>Web map<strong>${gis.webMapId || "Missing"}</strong></span>
        <span>Layer<strong>${gis.layerName || "Missing"}</strong></span>
        <span>Work area<strong>${gis.workArea || "Not set"}</strong></span>
        <span>Sync<strong>${gis.syncStatus || "Missing"}</strong></span>
      </div>
      <p>${readiness.ready ? "Foreman can confirm the assigned Field Maps route/work area before production starts." : `Confirm with the prime before production: ${readiness.blockers.join(", ")}.`}</p>
    </section>
  `;
}

function renderForemanToday() {
  const context = selectedFieldContext();
  const daily = context.daily;
  const project = context.project;
  const startGate = fieldStartGate(project, daily);
  const blocked = !startGate.clear;
  const preJob = preJobGate(project, daily);
  const obstacles = scopedRows("obstacles").filter(item => item.project === project?.id && isOpenObstacle(item));
  const photos = scopedRows("photoEvidence").filter(item => item.project === project?.id);
  const timeEntries = scopedRows("timeEntries").filter(item => item.project === project?.id);
  const corrections = project ? fieldEvidenceCorrectionRows(project).length + fieldCaptureCorrectionRows(project).length + returnedDailyCorrectionRows(project).length : 0;
  const returnedRows = project ? returnedDailyRows(project) : [];
  const accepted = ["Accepted", "Used for Billing"].includes(dailyAcceptanceStatus(daily));
  const submitted = daily?.status === "Submitted";
  const primary = foremanPrimaryAction(project, daily, { blocked, corrections, returnedRows, submitted, accepted });
  const focused = project && state.workflowFocus ? renderForemanFocusedWork(context) : "";
  return `
    <section class="panel foreman-daily-home">
      <div class="foreman-daily-head">
        <div>
          <span class="eyebrow">Foreman Home</span>
          <h2>${project ? `${project.map || project.id}: Today’s Work` : "No assigned Map"}</h2>
          <p>${foremanHomeMessage({ blocked, returnedRows, corrections, submitted, accepted })}</p>
        </div>
        <div class="foreman-primary-actions">
          <span class="status ${statusClass(primary.status)}">${plainStatus(primary.status)}</span>
          <button class="primary-btn" data-workflow-action="${primary.action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${primary.focus}">${primary.label}</button>
          <button class="secondary-btn" data-workflow-action="Safety & Risk" data-workflow-id="${project?.id || ""}" data-workflow-focus="Report hazard">Report Hazard</button>
        </div>
      </div>
    </section>
    ${focused || `
      ${project ? renderForemanSimpleDailyFlow(context) : ""}
      ${project ? renderReturnedDailyCorrectionQueue(project) : ""}
      ${project ? renderFieldCaptureCorrectionQueue(project) : ""}
      ${project ? renderFieldEvidenceCorrectionQueue(project) : ""}
    `}
  `;
}

function renderForemanSimpleDailyFlow(context = selectedFieldContext()) {
  const project = context.project;
  const daily = context.daily;
  if (!project) return "";
  const rows = foremanSimpleDailyRows(context);
  const readyStatuses = new Set(["Ready", "Submitted", "Accepted", "Done"]);
  const next = rows.find(row => !readyStatuses.has(row.status)) || rows[rows.length - 1];
  const readyCount = rows.filter(row => readyStatuses.has(row.status)).length;
  const waiting = foremanWaitingOnRows(project).slice(0, 4);
  return `
    <section class="panel foreman-simple-work">
      <div class="panel-header">
        <div>
          <h2>Today's work path</h2>
          <p>Work these steps from top to bottom. Open only the step you need.</p>
        </div>
        <span>${readyCount}/${rows.length} done</span>
      </div>
      <div class="foreman-next-card ${statusClass(next?.status || "Pending")}">
        <div>
          <span class="eyebrow">Next step</span>
          <strong>${next?.title || "Open daily"}</strong>
          <small>${next?.detail || "Review today's daily."}</small>
        </div>
        ${next ? renderForemanDailyCommandButton(project, next.button) : ""}
      </div>
      <div class="foreman-simple-steps">
        ${rows.map(row => `
          <article class="foreman-simple-step ${statusClass(row.status)}">
            <span>${row.number}</span>
            <div>
              <strong>${row.title}</strong>
              <small>${row.detail}</small>
            </div>
            <em>${plainStatus(row.status)}</em>
            ${renderForemanDailyCommandButton(project, row.button)}
          </article>
        `).join("")}
      </div>
      ${waiting.length ? `
        <details class="foreman-waiting-details">
          <summary>Waiting on Office or Safety <span>${waiting.length}</span></summary>
          <div>
            ${waiting.map(row => `
              <button data-needs-fix-details="${row.id}" data-project-id="${project.id}" data-path-key="fix-problems">
                <strong>${row.owner}: ${row.title}</strong>
                <small>${row.proof}</small>
              </button>
            `).join("")}
          </div>
        </details>
      ` : ""}
    </section>
  `;
}

function foremanSimpleDailyRows(context = selectedFieldContext()) {
  const project = context.project;
  const daily = context.daily;
  const startGate = fieldStartGate(project, daily);
  const preJob = preJobGate(project, daily);
  const startRows = foremanDailyStartRows(context);
  const proof = startRows.find(row => row.key === "proof") || {};
  const production = startRows.find(row => row.key === "production") || {};
  const materials = startRows.find(row => row.key === "materials") || {};
  const submit = startRows.find(row => row.key === "submit") || {};
  const timeEntries = scopedRows("timeEntries").filter(item => item.project === project?.id);
  const waiting = foremanWaitingOnRows(project);
  const startReady = startGate.clear && preJob.status === "Clear to Start";
  const workReady = ["Ready", "Submitted"].includes(production.status) && ["Ready", "Submitted"].includes(materials.status) && timeEntries.length > 0;
  return [
    {
      number: "1",
      title: "Pre-Check",
      status: startReady ? "Ready" : waiting.length ? "Waiting" : "Needs Fix",
      detail: startReady ? "Ready to work. Map, safety, crew, equipment, and 811 are clear." : waiting.length ? `${waiting.length} item(s) are waiting on Office or Safety.` : "Finish Pre-Check before production starts.",
      button: { label: startReady ? "View" : "Open", workflow: "Field Operations", focus: "Daily start" }
    },
    {
      number: "2",
      title: "Photos and obstacles",
      status: proof.status || "Pending",
      detail: proof.detail || "Add job photos, obstacle notes, or hazard photos.",
      button: proof.button || { label: "Open", dailyAction: "add-photo" }
    },
    {
      number: "3",
      title: "Work, material, and time",
      status: workReady ? "Ready" : startReady ? "Needs Fix" : "Pending",
      detail: workReady ? `${timeEntries.length} time line(s), production, and materials are entered.` : "Enter footage/units, materials used, equipment, and crew time.",
      button: { label: "Open", workflow: "Field Operations", focus: "Production capture" }
    },
    {
      number: "4",
      title: "Send daily",
      status: submit.status || "Pending",
      detail: submit.detail || "Send the daily to Office when the shift is complete.",
      button: { label: daily?.status === "Submitted" ? "Review" : "Open", workflow: "Field Operations", focus: "Daily closeout" }
    }
  ];
}

function foremanWaitingOnRows(project) {
  if (!project) return [];
  return guidedNeedsFixRows(project, "fix-problems")
    .filter(row => row.owner !== "Foreman" && row.action !== "Field Operations")
    .slice(0, 6);
}

function renderForemanHome() {
  const context = selectedFieldContext();
  const project = context.project;
  const daily = context.daily;
  const startGate = fieldStartGate(project, daily);
  const preJob = preJobGate(project, daily);
  const photos = scopedRows("photoEvidence").filter(item => item.project === project?.id);
  const obstacles = scopedRows("obstacles").filter(item => item.project === project?.id && isOpenObstacle(item));
  const timeEntries = scopedRows("timeEntries").filter(item => item.project === project?.id);
  const production = scopedRows("dailyProduction").filter(item => item.project === project?.id && (!daily?.id || item.dailyId === daily.id));
  const materials = scopedRows("dailyMaterials").filter(item => item.project === project?.id && (!daily?.id || item.dailyId === daily.id));
  const returnedRows = project ? returnedDailyRows(project) : [];
  const corrections = project ? fieldEvidenceCorrectionRows(project).length + fieldCaptureCorrectionRows(project).length + returnedRows.length : 0;
  const accepted = ["Accepted", "Used for Billing"].includes(dailyAcceptanceStatus(daily));
  const submitted = daily?.status === "Submitted";
  const primary = foremanPrimaryAction(project, daily, { blocked: !startGate.clear, corrections, returnedRows, submitted, accepted });
  const ownedFixes = project ? foremanOwnedNeedsFixRows(project) : [];
  const waitingRows = project ? guidedNeedsFixRows(project, "fix-problems")
    .filter(row => !(row.owner === "Foreman" || row.task?.role === "Foreman" || row.action === "Field Operations"))
    .slice(0, 4) : [];
  const endRows = [
    { label: "Photos", ok: photos.length > 0, detail: `${photos.length} uploaded`, action: "Field Operations", focus: "Photos / obstacles" },
    { label: "Work done", ok: production.length > 0 || Boolean(daily?.production), detail: production.length ? `${production.length} production line(s)` : daily?.production || "Not entered", action: "Field Operations", focus: "Production capture" },
    { label: "Materials", ok: materials.length > 0 || Boolean(daily?.materials), detail: materials.length ? `${materials.length} material line(s)` : daily?.materials || "Not entered", action: "Field Operations", focus: "Production capture" },
    { label: "Crew time", ok: timeEntries.length > 0, detail: `${timeEntries.length} time line(s)`, action: "Time Tracking", focus: "Daily time" },
    { label: "Daily sent", ok: submitted || accepted, detail: foremanDailyStatusLabel(daily), action: "Field Operations", focus: "Daily closeout" }
  ];
  return `
    <section class="panel foreman-home-command">
      <div class="foreman-home-hero">
        <div>
          <span class="eyebrow">Foreman Home</span>
          <h2>${project ? project.map || project.id : "No Map assigned"}</h2>
          <p>${foremanHomeMessage({ blocked: !startGate.clear, returnedRows, corrections, submitted, accepted })}</p>
        </div>
        <div class="foreman-primary-actions">
          <span class="status ${statusClass(primary.status)}">${plainStatus(primary.status)}</span>
          <button class="primary-btn" data-workflow-action="${primary.action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${primary.focus}">${primary.label}</button>
        </div>
      </div>
      <div class="foreman-home-status">
        <article class="${startGate.clear ? "ready" : "blocked"}">
          <span>Ready to work?</span>
          <strong>${startGate.clear ? "Yes" : "Not yet"}</strong>
          <small>${startGate.clear ? "Pre-Check is clear." : startGate.blockers.map(item => item.label).join(", ")}</small>
          <button class="secondary-btn" data-workflow-action="Field Operations" data-workflow-id="${project?.id || ""}" data-workflow-focus="Daily start">Open</button>
        </article>
        <article class="${preJob.status === "Clear to Start" ? "ready" : "blocked"}">
          <span>Safety check</span>
          <strong>${preJob.status === "Clear to Start" ? "Clear" : "Needs fix"}</strong>
          <small>${preJob.items.filter(item => !item.ok).map(item => item.label).join(", ") || "JSA, PPE, equipment, and 811 are ready."}</small>
          <button class="secondary-btn" data-workflow-action="Field Operations" data-workflow-id="${project?.id || ""}" data-workflow-focus="JSA / PPE">Open</button>
        </article>
        <article>
          <span>Today’s proof</span>
          <strong>${photos.length} photo(s)</strong>
          <small>${obstacles.length} open obstacle(s), ${timeEntries.length} time line(s)</small>
          <button class="secondary-btn" data-workflow-action="Field Operations" data-workflow-id="${project?.id || ""}" data-workflow-focus="Photos / obstacles">Open</button>
        </article>
      </div>
    </section>

    <section class="foreman-home-grid">
      <section class="panel foreman-home-card">
        <div class="panel-header">
          <div>
            <h2>Needs Fix</h2>
            <p>Only items you can fix are here.</p>
          </div>
          <span>${ownedFixes.length} item${ownedFixes.length === 1 ? "" : "s"}</span>
        </div>
        <div class="foreman-home-list">
          ${ownedFixes.length ? ownedFixes.map(row => `
            <article>
              <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
              <div>
                <strong>${row.title}</strong>
                <small>${row.next}</small>
              </div>
              <div class="row-actions">
                <button class="primary-btn" data-needs-fix-open="${row.id}" data-project-id="${project.id}" data-path-key="fix-problems">Open</button>
                <button class="secondary-btn" data-needs-fix-details="${row.id}" data-project-id="${project.id}" data-path-key="fix-problems">Details</button>
              </div>
            </article>
          `).join("") : `<p class="empty-state">No Foreman fixes are waiting.</p>`}
        </div>
      </section>

      <section class="panel foreman-home-card">
        <div class="panel-header">
          <div>
            <h2>Before You Leave</h2>
            <p>These feed Office, Safety, Payroll, and billing proof.</p>
          </div>
          <span>${endRows.filter(item => item.ok).length}/${endRows.length} done</span>
        </div>
        <div class="foreman-home-list compact">
          ${endRows.map(row => `
            <article>
              <span class="status ${row.ok ? "good" : "warn"}">${row.ok ? "Done" : "Needed"}</span>
              <div>
                <strong>${row.label}</strong>
                <small>${row.detail}</small>
              </div>
              <button class="secondary-btn" data-workflow-action="${row.action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${row.focus}">Open</button>
            </article>
          `).join("")}
        </div>
      </section>
    </section>

    <section class="panel foreman-home-card">
      <div class="panel-header">
        <div>
          <h2>Waiting On</h2>
          <p>These are not your fixes. They show why work may be blocked.</p>
        </div>
        <span>${waitingRows.length} item${waitingRows.length === 1 ? "" : "s"}</span>
      </div>
      <div class="foreman-home-list waiting">
        ${waitingRows.length ? waitingRows.map(row => `
          <article>
            <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
            <div>
              <strong>${row.owner}: ${row.title}</strong>
              <small>${row.proof}</small>
            </div>
            <button class="secondary-btn" data-needs-fix-details="${row.id}" data-project-id="${project.id}" data-path-key="fix-problems">Details</button>
          </article>
        `).join("") : `<p class="empty-state">Nothing is waiting on another role.</p>`}
      </div>
    </section>
  `;
}

function foremanDailyStartRows(context = selectedFieldContext()) {
  const project = context.project;
  const daily = context.daily;
  const startGate = fieldStartGate(project, daily);
  const preJob = preJobGate(project, daily);
  const checklist = foremanStartChecklist(project, daily);
  const production = scopedRows("dailyProduction").filter(item => item.project === project?.id && (!daily?.id || item.dailyId === daily.id));
  const photos = scopedRows("photoEvidence").filter(item => item.project === project?.id && (!daily?.id || item.linkedRecord === daily.id || item.dailyId === daily.id));
  const materials = scopedRows("dailyMaterials").filter(item => item.project === project?.id && (!daily?.id || item.dailyId === daily.id));
  const jsaReady = checklist.find(item => item.key === "jsa")?.ok && checklist.find(item => item.key === "ppe")?.ok;
  const checksReady = startGate.clear && preJob.status === "Clear to Start" && checklist.every(item => item.ok);
  const productionReady = production.length > 0 || Boolean(daily?.production && !/no production|ready for field/i.test(daily.production));
  const photoReady = photos.length > 0;
  const materialReady = materials.length > 0 || Boolean(daily?.materials && !/none/i.test(daily.materials));
  const canSubmit = checksReady && productionReady && photoReady;
  return [
    {
      key: "gate",
      label: "Ready to work?",
      status: startGate.clear ? "Ready" : "Blocked",
      detail: startGate.clear ? "Map release, crew, equipment, 811, and safety are clear." : startGate.blockers.map(item => item.label).join(", "),
      button: { label: startGate.clear ? "View" : "Open", workflow: "Field Operations", focus: "Daily start" }
    },
    {
      key: "jsa",
      label: "Safety check",
      status: jsaReady ? "Ready" : startGate.clear ? "Needs Review" : "Blocked",
      detail: jsaReady ? "JSA, PPE, and inspection forms are complete." : startGate.clear ? "Complete the safety check before work starts." : "Pre-Check must clear first.",
      button: jsaReady ? { label: "View", workflow: "Field Operations", focus: "JSA / PPE" } : { label: "Complete Safety Check", dailyAction: "complete-jsa" }
    },
    {
      key: "proof",
      label: "Photos / obstacles",
      status: photoReady ? "Ready" : checksReady ? "Needs Review" : "Pending",
      detail: photoReady ? `${photos.length} photo item(s) linked.` : "Add progress, obstacle, or safety photo notes.",
      button: { label: photoReady ? "Add more" : "Add photo", dailyAction: "add-photo" }
    },
    {
      key: "production",
      label: "Work done",
      status: productionReady ? "Ready" : checksReady ? "Needs Review" : "Pending",
      detail: productionReady ? `${production.length || 1} production line(s) started.` : "Enter footage, units, hourly support, equipment, and material usage.",
      button: { label: "Enter work", workflow: "Field Operations", focus: "Production capture" }
    },
    {
      key: "materials",
      label: "Materials",
      status: materialReady ? "Ready" : checksReady ? "Needs Review" : "Pending",
      detail: materialReady ? `${materials.length || 1} material line(s) documented.` : "Record SQUAN material used and remaining notes.",
      button: { label: "Enter material", workflow: "Field Operations", focus: "Production capture" }
    },
    {
      key: "submit",
      label: "Submit daily",
      status: daily?.status === "Submitted" ? "Submitted" : canSubmit ? "Ready" : "Blocked",
      detail: daily?.status === "Submitted" ? "Daily is sent to Office and locked from casual edits." : canSubmit ? "Review the daily form, then submit to Office." : "Finish Pre-Check, production, and photo proof first.",
      button: daily?.status === "Submitted" ? { label: "Review package", workflow: "Field Operations", focus: "Daily closeout" } : { label: canSubmit ? "Submit daily" : "See missing", dailyAction: canSubmit ? "submit" : "show-missing" }
    }
  ];
}

function renderForemanDailyCommandButton(project, button = {}) {
  if (button.workflow) return `<button class="secondary-btn" data-workflow-action="${button.workflow}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${button.focus || ""}">${button.label}</button>`;
  if (button.dailyAction) return `<button class="${button.dailyAction === "submit" ? "primary-btn" : "secondary-btn"}" data-daily-command-action="${button.dailyAction}">${button.label}</button>`;
  return "";
}

function renderForemanDailyStartCommand(context = selectedFieldContext()) {
  const project = context.project;
  const daily = context.daily;
  if (!project) return "";
  const rows = foremanDailyStartRows(context);
  const clearStatuses = new Set(["Ready", "Submitted"]);
  const next = rows.find(item => !clearStatuses.has(item.status)) || rows.at(-1);
  const readyCount = rows.filter(item => clearStatuses.has(item.status)).length;
  return `
    <section class="panel foreman-start-command">
      <div class="panel-header">
        <div>
          <h2>Start today’s work</h2>
          <p>Work this top to bottom. The detailed daily form is below when you need to enter the actual values.</p>
        </div>
        <span>${readyCount}/${rows.length} ready</span>
      </div>
      <div class="foreman-start-next">
        <div>
          <span class="eyebrow">Do this next</span>
          <strong>${next?.label || "Open daily"}</strong>
          <small>${next?.detail || "Review the daily before submitting."}</small>
        </div>
        ${next ? renderForemanDailyCommandButton(project, next.button) : ""}
      </div>
      <div class="foreman-start-command-grid">
        ${rows.map(item => `
          <article class="${statusClass(item.status)}">
            <span class="status ${statusClass(item.status)}">${plainStatus(item.status)}</span>
            <div>
              <strong>${item.label}</strong>
              <small>${item.detail}</small>
            </div>
            ${renderForemanDailyCommandButton(project, item.button)}
          </article>
        `).join("")}
      </div>
      <p class="readiness-note">${daily?.status === "Submitted" ? "Submitted daily is locked. Operations will accept, return, or ask a question." : "Submit creates the daily report, SOT, photos, material usage, crew time support, and Office proof package."}</p>
    </section>
  `;
}

function foremanPrimaryAction(project, daily, context = {}) {
  if (!project) return { label: "No Map Assigned", action: "Field Operations", focus: "Daily start", status: "Pending" };
  if (context.returnedRows?.length) return { label: "Fix Returned Daily", action: "Field Operations", focus: "returned corrections", status: "Needs Review" };
  if (context.corrections) return { label: "Fix Returned Items", action: "Field Operations", focus: "Evidence corrections", status: "Needs Review" };
  if (context.blocked) return { label: "Finish Pre-Check", action: "Field Operations", focus: "Daily start", status: "Blocked" };
  if (context.accepted) return { label: "View Accepted Daily", action: "Field Operations", focus: "Daily closeout", status: "Accepted" };
  if (context.submitted) return { label: "Review Submitted Daily", action: "Field Operations", focus: "Daily closeout", status: "Submitted" };
  return { label: "Start Today’s Work", action: "Field Operations", focus: "Daily start", status: "Ready" };
}

function foremanHomeMessage(context = {}) {
  if (context.returnedRows?.length) return "A daily was returned. Fix only the returned items and resubmit.";
  if (context.corrections) return "A field item needs correction before today’s work can be accepted.";
  if (context.blocked) return "Do not start production yet. Finish Pre-Check first.";
  if (context.accepted) return "This daily is accepted and is now feeding Billing proof.";
  if (context.submitted) return "The daily is submitted and locked. Wait for Operations to accept or return it.";
  return "Start the daily, complete safety checks, capture work, enter time, and submit once.";
}

function foremanDailyStatusLabel(daily) {
  const status = dailyAcceptanceStatus(daily);
  if (!status || status === "Missing") return "Not sent";
  if (status === "Used for Billing" || status === "Accepted") return "Accepted";
  if (status === "Submitted") return "Sent to Office";
  return plainStatus(status);
}

function foremanOwnedNeedsFixRows(project) {
  return guidedNeedsFixRows(project, "fix-problems")
    .filter(row => row.owner === "Foreman" || row.task?.role === "Foreman" || row.action === "Field Operations")
    .slice(0, 4);
}

