function renderForemanFocusedWork(context) {
  const focus = String(state.workflowFocus || "").toLowerCase();
  const includesAny = (...terms) => terms.some(term => focus.includes(term));
  if (includesAny("returned", "correction")) {
    return renderForemanStepDetail(context, "corrections");
  }
  if (includesAny("daily start", "jsa", "ppe", "start")) {
    return renderForemanStepDetail(context, "start");
  }
  if (includesAny("photo", "obstacle", "hazard")) {
    return renderForemanStepDetail(context, "photos");
  }
  if (includesAny("production", "time", "work done", "material")) {
    return renderForemanStepDetail(context, "work");
  }
  if (includesAny("closeout", "submit", "handoff")) {
    return renderForemanStepDetail(context, "submit");
  }
  return renderForemanStepDetail(context, "work");
}

