function incompleteDailyRows() {
  return scopedRows("projects")
    .map(project => {
      const projectDailies = scopedRows("dailies")
        .filter(daily => daily.project === project.id)
        .sort((a, b) => String(b.modifiedAt || b.date || "").localeCompare(String(a.modifiedAt || a.date || "")));
      const latest = projectDailies[0];
      const startGate = fieldStartGate(project, latest);
      const activeMap = !/completed|billed/i.test(project.status || "");
      const submittedToday = projectDailies.some(daily => daily.status === "Submitted" && daily.date === isoDate(today));
      const hasDraft = latest && latest.status !== "Submitted";
      const missingDaily = activeMap && !submittedToday;
      const needsAction = hasDraft || missingDaily || (activeMap && !startGate.clear);
      return {
        project,
        daily: latest,
        status: hasDraft ? "Draft" : submittedToday ? "Submitted" : activeMap ? "Missing" : "Closed",
        detail: hasDraft
          ? `${latest.id} saved ${formatShortDateTime(latest.modifiedAt || latest.date)}`
          : submittedToday
            ? "Today’s daily is submitted"
            : activeMap
              ? "No submitted daily for today"
              : "Map is completed / billed",
        gate: startGate,
        needsAction,
        task: endOfDayDailyTaskForProject(project.id)
      };
    })
    .filter(row => row.needsAction)
    .sort((a, b) => {
      const rank = { Draft: 3, Missing: 2, Blocked: 1, Submitted: 0, Closed: 0 };
      const aRank = rank[a.status] || (a.gate.clear ? 0 : 1);
      const bRank = rank[b.status] || (b.gate.clear ? 0 : 1);
      return bRank - aRank || String(a.project.map || a.project.id).localeCompare(String(b.project.map || b.project.id));
    });
}

function endOfDayDailyTaskId(projectId) {
  return `TASK-DAILY-EOD-${String(projectId).replace(/[^A-Z0-9]+/gi, "-").toUpperCase()}`;
}

function endOfDayDailyTaskForProject(projectId) {
  return (state.data.tasks || []).find(task => task.id === endOfDayDailyTaskId(projectId) && task.status !== "Closed");
}

function syncEndOfDayDailyTasks() {
  if (!state.user || !["Admin", "Operations", "Foreman"].includes(state.role)) return;
  const now = new Date().toISOString();
  const rows = incompleteDailyRows().filter(row => ["Draft", "Missing"].includes(row.status));
  const activeIds = new Set(rows.map(row => endOfDayDailyTaskId(row.project.id)));
  let changed = false;

  rows.forEach(row => {
    const id = endOfDayDailyTaskId(row.project.id);
    const existing = (state.data.tasks || []).find(task => task.id === id);
    const blocked = !row.gate.clear;
    const owner = blocked ? "Operations Coordinator" : row.daily?.foreman || roleConfig.Foreman.person;
    const role = blocked ? "Operations" : "Foreman";
    const title = row.status === "Draft"
      ? `Submit draft daily for ${row.project.map || row.project.id}`
      : `Submit missing daily for ${row.project.map || row.project.id}`;
    const notes = `${row.project.map || row.project.id}: ${row.detail}. ${blocked ? `Gate blockers: ${row.gate.blockers.map(item => item.label).join(", ")}.` : "Open Field Daily, confirm production/time/evidence, and submit before closeout."}`;
    const next = {
      id,
      title,
      relatedType: "Daily",
      relatedId: row.daily?.id || row.project.id,
      project: row.project.id,
      owner,
      role,
      dueDate: row.daily?.date || isoDate(today),
      priority: blocked ? "High" : row.status === "Missing" ? "High" : "Medium",
      status: "Open",
      workflowArea: "Field Operations",
      notes,
      source: "End-of-day daily",
      dailyStatus: row.status,
      gateStatus: row.gate.status,
      blockerLabels: row.gate.blockers.map(item => item.label),
      createdAt: existing?.createdAt || now,
      modifiedAt: now,
      activityLog: [
        ...(existing?.activityLog || []),
        ...(!existing || existing.dailyStatus !== row.status || existing.gateStatus !== row.gate.status
          ? [{ at: now, by: "System", note: `End-of-day daily task synced: ${row.status}; ${row.gate.status}.` }]
          : [])
      ]
    };
    const changedFields = !existing || ["title", "relatedId", "owner", "role", "dueDate", "priority", "status", "workflowArea", "notes", "dailyStatus", "gateStatus"].some(field => existing[field] !== next[field]);
    if (!changedFields) return;
    state.data.tasks = state.data.tasks || [];
    if (existing) Object.assign(existing, next);
    else state.data.tasks.push(next);
    changed = true;
    void saveToApi("tasks", existing || next, !existing);
  });

  (state.data.tasks || [])
    .filter(task => task.source === "End-of-day daily" && task.status !== "Closed" && !activeIds.has(task.id))
    .forEach(task => {
      task.status = "Closed";
      task.closedAt = now;
      task.closedBy = "System";
      task.modifiedAt = now;
      task.notes = appendInlineNote(task.notes, "Auto-closed because the daily was submitted or no longer requires end-of-day action.");
      task.activityLog = [...(task.activityLog || []), { at: now, by: "System", note: "End-of-day daily task auto-closed." }];
      changed = true;
      void saveToApi("tasks", task, false);
    });

  if (changed) {
    appendAuditLocal("field.daily-eod-task.sync", { activeTasks: activeIds.size, by: "System" });
    persist("End-of-day daily tasks synced");
  }
}

