function dailyAuditRows(project) {
  if (!project) return [];
  const projectId = project.id;
  const dailies = (state.data.dailies || [])
    .filter(item => item.project === projectId)
    .map(item => ({
      at: item.modifiedAt || item.createdAt || item.date,
      by: item.foreman || item.owner || "Field",
      type: "Daily",
      status: item.status || item.jsa || "Open",
      note: `${item.id}: ${item.production || "Daily record"}`
    }));
  const forms = (state.data.formSubmissions || [])
    .filter(item => item.project === projectId)
    .map(item => ({
      at: item.modifiedAt || item.submittedAt || item.createdAt,
      by: item.submittedBy || "Field",
      type: "Form",
      status: item.status,
      note: `${item.type} generated from ${item.dailyId || "daily workflow"}`
    }));
  const tasks = (state.data.tasks || [])
    .filter(item => item.project === projectId && /daily/i.test(`${item.source} ${item.title} ${item.notes}`))
    .map(item => ({
      at: item.modifiedAt || item.createdAt || item.dueDate,
      by: item.owner || "System",
      type: "Task",
      status: item.status,
      note: `${item.id}: ${item.title}`
    }));
  const audits = (state.data.auditLog || [])
    .filter(item => item.detail?.project === projectId && /daily|submitDaily|field/i.test(item.action || ""))
    .map(item => ({
      at: item.at || item.createdAt,
      by: item.detail?.by || "System",
      type: "Audit",
      status: item.action,
      note: JSON.stringify(item.detail || {})
    }));
  const approvals = (project.approvalLog || [])
    .filter(item => /daily|evidence|qc/i.test(`${item.decision || ""} ${item.reason || ""}`))
    .map(item => ({
      at: item.at,
      by: item.by || "System",
      type: "Map log",
      status: item.status || item.decision,
      note: item.reason || item.decision
    }));
  return [...dailies, ...forms, ...tasks, ...audits, ...approvals]
    .filter(item => item.at || item.note)
    .sort((a, b) => String(b.at || "").localeCompare(String(a.at || "")))
    .slice(0, 10);
}

