function operationsDailyReviewRows(projects = scopedRows("projects")) {
  const selectedId = state.selectedProjectId;
  return dailySupervisorReviewRows(projects).map(row => {
    const pkg = dailySupervisorReviewPackage(row.daily);
    const evidenceChecks = pkg.checklist.filter(item => item.label !== "Supervisor decision");
    const missing = evidenceChecks.filter(item => !item.ok);
    const readyCount = evidenceChecks.length - missing.length;
    const isSelected = selectedId && row.project.id === selectedId;
    const openTask = row.task || (state.data.tasks || []).find(task => task.dailyId === row.daily.id && task.status !== "Closed");
    const nextLabel = row.status === "Returned"
      ? "Waiting on Foreman fix"
      : ["Accepted", "Used for Billing"].includes(row.status)
        ? "Accepted"
        : "Review daily";
    return {
      ...row,
      pkg,
      evidenceChecks,
      missing,
      readyCount,
      isSelected,
      openTask,
      nextLabel
    };
  }).sort((a, b) => Number(b.isSelected) - Number(a.isSelected) || String(b.sortAt).localeCompare(String(a.sortAt)));
}

function renderOperationsDailyReviewActions(row) {
  if (row.status === "Returned") {
    return `
      ${row.openTask ? `<button class="secondary-btn" data-task-open="${row.openTask.id}">Task</button>` : ""}
      <button class="secondary-btn" data-daily-review-open="${row.daily.id}">Preview</button>
      <button class="primary-btn" data-workflow-action="Field Operations" data-workflow-id="${row.project.id}" data-workflow-focus="Daily correction">Open fix</button>
    `;
  }
  if (["Accepted", "Used for Billing"].includes(row.status)) {
    return `
      <button class="secondary-btn" data-daily-review-open="${row.daily.id}">Preview</button>
      <button class="primary-btn" data-workflow-action="Billing" data-workflow-id="${row.project.id}" data-workflow-focus="Invoice package">Open billing proof</button>
    `;
  }
  return `
    <button class="secondary-btn" data-daily-review-open="${row.daily.id}">Preview</button>
    <button class="secondary-btn" data-daily-supervisor-review="clarify" data-daily-id="${row.daily.id}">Ask question</button>
    <button class="secondary-btn" data-daily-supervisor-review="return" data-daily-id="${row.daily.id}">Return</button>
    <button class="primary-btn" data-daily-supervisor-review="accept" data-daily-id="${row.daily.id}">Accept</button>
  `;
}

function dailyCorrectionReviewSummary(daily) {
  const versions = daily?.correctionVersions || [];
  const latest = versions.at(-1);
  const previous = daily?.supervisorReview?.previousReview || (latest ? {
    by: latest.returnedBy,
    at: latest.returnedAt,
    note: latest.returnNote
  } : null);
  return {
    hasCorrection: Boolean(latest || Number(daily?.correctionCount || 0) > 0),
    version: latest?.version || daily?.correctionCount || 0,
    returnedBy: previous?.by || "Reviewer",
    returnedAt: previous?.at || "",
    returnNote: previous?.note || "No return note recorded.",
    resubmittedBy: latest?.resubmittedBy || daily?.supervisorReview?.by || daily?.foreman || "Foreman",
    resubmittedAt: latest?.resubmittedAt || daily?.supervisorReview?.at || daily?.modifiedAt || "",
    production: latest?.production || daily?.production || "No production summary",
    laborHours: latest?.laborHours ?? daily?.laborHours ?? 0,
    materials: latest?.materials || daily?.materials || "No material note",
    photoCaption: latest?.photoCaption || "No corrected photo caption"
  };
}

function renderDailyCorrectionReviewCard(row) {
  const correction = dailyCorrectionReviewSummary(row.daily);
  if (!correction.hasCorrection) return "";
  return `
    <div class="daily-correction-review">
      <div>
        <span class="status ${statusClass("Returned")}">Original return</span>
        <strong>${correction.returnNote}</strong>
        <small>${correction.returnedBy} · ${formatShortDateTime(correction.returnedAt)}</small>
      </div>
      <div>
        <span class="status ${statusClass("Corrected")}">Corrected v${correction.version}</span>
        <strong>${correction.production}</strong>
        <small>${correction.resubmittedBy} · ${formatShortDateTime(correction.resubmittedAt)} · ${Number(correction.laborHours || 0)} labor hr(s)</small>
      </div>
    </div>
  `;
}

function renderOperationsDailyReviewQueue(projects = scopedRows("projects"), selectedProject = null) {
  if (!["Admin", "Operations"].includes(state.role)) return "";
  const rows = operationsDailyReviewRows(projects);
  const pending = rows.filter(row => !["Accepted", "Used for Billing", "Returned"].includes(row.status));
  const returned = rows.filter(row => row.status === "Returned");
  const accepted = rows.filter(row => ["Accepted", "Used for Billing"].includes(row.status));
  const selectedRows = selectedProject ? rows.filter(row => row.project.id === selectedProject.id) : rows;
  const visibleRows = (selectedRows.length ? selectedRows : rows).slice(0, 6);
  return `
    <section class="panel operations-daily-review">
      <div class="panel-header">
        <div>
          <h2>Daily review</h2>
          <p>Operations checks submitted dailies here. Accept it, return it to the Foreman, or ask a question.</p>
        </div>
        <span>${rows.length} daily package(s)</span>
      </div>
      <div class="operations-daily-review-stats">
        ${metric("Need review", pending.length, "Operations decision needed")}
        ${metric("Returned", returned.length, "Foreman must fix")}
        ${metric("Accepted", accepted.length, "Can feed proof and billing")}
      </div>
      <div class="operations-daily-review-list">
        ${visibleRows.map(row => `
          <article class="${row.isSelected ? "selected" : ""}">
            <div class="daily-review-primary">
              <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
              <div>
                <strong>${row.project.map || row.project.id} · ${row.daily.id}</strong>
                <small>${row.daily.date || "No date"} · ${row.daily.foreman || "Foreman"} · ${row.versionLabel}</small>
              </div>
            </div>
            <div class="daily-review-summary">
              <strong>${row.nextLabel}</strong>
              <small>${row.daily.production || "No production summary entered."}</small>
              <small>${row.readyCount}/${row.evidenceChecks.length} checks ready${row.missing.length ? ` · Missing: ${row.missing.map(item => item.label).join(", ")}` : ""}</small>
              ${renderDailyCorrectionReviewCard(row)}
            </div>
            <div class="daily-review-actions compact">
              ${renderOperationsDailyReviewActions(row)}
            </div>
          </article>
        `).join("") || `
          <p class="empty-state">No submitted dailies need Operations review right now.</p>
        `}
      </div>
    </section>
  `;
}

function returnedDailyRows(project = null) {
  const projectIds = project ? new Set([project.id]) : new Set(scopedRows("projects").map(item => item.id));
  return (state.data.dailies || [])
    .filter(daily => projectIds.has(daily.project))
    .filter(daily => daily.status === "Submitted" && daily.supervisorReview?.status === "Returned")
    .map(daily => {
      const task = (state.data.tasks || []).find(item => item.dailyId === daily.id && item.status !== "Closed" && ["Daily supervisor review", "Billing line review"].includes(item.source))
        || (state.data.tasks || []).find(item => item.dailyId === daily.id && item.status !== "Closed");
      const map = (state.data.projects || []).find(item => item.id === daily.project) || {};
      const source = daily.supervisorReview?.source || task?.source || "Daily supervisor review";
      const billingReview = task?.billingLineReview || task?.extra?.billingLineReview;
      const sourceLabel = source === "Billing line review" ? "Fix returned billing line" : daily.supervisorReview?.requestType === "Clarification" ? "Answer daily question" : "Fix returned daily";
      const proofNeeded = source === "Billing line review"
        ? "Correct the production, hourly, equipment, or rate support that Billing returned."
        : "Correct the daily fields, photos, forms, or notes that Operations returned.";
      const next = source === "Billing line review"
        ? "Open the daily, correct the returned invoice-source line, then resubmit the daily for review."
        : "Open the daily, make the requested correction, then resubmit it for Operations review.";
      return {
        daily,
        task,
        project: map,
        source,
        sourceLabel,
        proofNeeded,
        next,
        billingReview,
        status: dailyAcceptanceStatus(daily)
      };
    })
    .sort((a, b) => String(b.daily.supervisorReview?.at || b.daily.modifiedAt || "").localeCompare(String(a.daily.supervisorReview?.at || a.daily.modifiedAt || "")));
}

function returnedDailyCorrectionRows(project = null) {
  return returnedDailyRows(project);
}

function returnedDailyFixRows(project) {
  return returnedDailyRows(project).map(row => {
    const checklist = returnedDailyCorrectionChecklist(row.project, row.daily);
    const readyCount = checklist.filter(item => item.ok).length;
    return {
      ...row,
      checklist,
      readyCount,
      reason: row.daily.supervisorReview?.note || row.task?.notes || "Correction requested.",
      returnedBy: row.daily.supervisorReview?.by || row.task?.owner || "Reviewer",
      returnedAt: row.daily.supervisorReview?.at || row.task?.modifiedAt || row.daily.modifiedAt
    };
  });
}

function renderForemanReturnedFixLoop(project) {
  if (!project || !["Foreman", "Admin", "Operations"].includes(state.role)) return "";
  const rows = returnedDailyFixRows(project);
  if (!rows.length) return "";
  return `
    <section class="panel foreman-returned-loop">
      <div class="panel-header">
        <div>
          <h2>Fix returned daily</h2>
          <p>These are the returned items stopping the daily from being accepted. Open starts the correction path; Preview only shows the package.</p>
        </div>
        <span>${rows.length} returned</span>
      </div>
      <div class="foreman-returned-list">
        ${rows.map(row => `
          <article>
            <div class="returned-fix-main">
              <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
              <div>
                <strong>${row.sourceLabel}: ${row.daily.id}</strong>
                <small>${row.reason}</small>
                <small>${row.returnedBy} · ${formatShortDateTime(row.returnedAt)}</small>
              </div>
            </div>
            <div class="returned-fix-proof">
              <strong>Proof needed</strong>
              <small>${row.proofNeeded}</small>
              <small>${row.readyCount}/${row.checklist.length} correction checks ready</small>
            </div>
            <div class="daily-row-actions">
              ${row.task ? `<button class="secondary-btn" data-task-open="${row.task.id}">Task</button>` : ""}
              <button class="secondary-btn" data-daily-review-open="${row.daily.id}">Preview</button>
              <button class="primary-btn" data-workflow-action="Field Operations" data-workflow-id="${project.id}" data-workflow-focus="Returned daily correction">Open</button>
            </div>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function renderReturnedDailyCorrectionQueue(project) {
  if (!["Foreman", "Admin", "Operations"].includes(state.role)) return "";
  const rows = returnedDailyFixRows(project);
  if (!rows.length) return "";
  return `
    <section class="panel returned-daily-queue">
      <div class="panel-header">
        <div>
          <h2>Correction details</h2>
          <p>Use this detail list after opening the returned daily. Correct the source values and resubmit for acceptance.</p>
        </div>
        <span>${rows.length} returned</span>
      </div>
      <div class="returned-daily-list">
        ${rows.map(row => {
          return `
            <article>
              <span class="status bad">Returned</span>
              <div>
                <strong>${row.sourceLabel}: ${row.daily.id}</strong>
                <small>${row.reason}</small>
                <small>${row.returnedBy} · ${formatShortDateTime(row.returnedAt)}</small>
                <div class="returned-daily-mini-checks">
                  ${row.checklist.map(item => `<span class="${item.ok ? "ready" : "blocked"}">${item.ok ? "✓" : "!"} ${item.label}</span>`).join("")}
                </div>
              </div>
              <div class="daily-row-actions">
                <small>${row.readyCount}/${row.checklist.length} ready</small>
                ${row.task ? `<button class="secondary-btn" data-task-open="${row.task.id}">Task</button>` : ""}
                <button class="secondary-btn" data-daily-review-open="${row.daily.id}">Preview</button>
                <button class="primary-btn" data-workflow-action="Field Operations" data-workflow-id="${row.daily.project}" data-workflow-focus="Returned daily correction">Open</button>
              </div>
            </article>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function handleDailySupervisorReview(button) {
  const daily = (state.data.dailies || []).find(item => item.id === button.dataset.dailyId);
  if (!daily) return;
  const project = (state.data.projects || []).find(item => item.id === daily.project);
  const action = button.dataset.dailySupervisorReview;
  const now = new Date().toISOString();
  const note = prompt(action === "accept" ? "Operations acceptance note" : action === "clarify" ? "Clarification request" : "Correction note", action === "accept" ? "Daily accepted for downstream billing/QC support." : action === "clarify" ? "Clarify daily details before Operations acceptance." : "Return daily for correction before Operations acceptance.") || "";
  daily.supervisorReview = {
    status: action === "accept" ? "Accepted" : "Returned",
    by: state.user?.name || state.role,
    at: now,
    note: action === "clarify" ? `Clarification requested: ${note}` : note,
    requestType: action === "clarify" ? "Clarification" : action === "return" ? "Correction" : "Acceptance"
  };
  daily.modifiedAt = now;
  daily.activityLog = [...(daily.activityLog || []), {
    at: now,
    by: daily.supervisorReview.by,
    note: `${daily.supervisorReview.status}: ${note}`
  }];
  if (project) {
    project.approvalLog = [...(project.approvalLog || []), {
      decision: `daily-${action}`,
      status: daily.supervisorReview.status,
      by: daily.supervisorReview.by,
      at: now,
      reason: `${daily.id}: ${note}`
    }];
    project.modifiedAt = now;
  }
  if (["return", "clarify"].includes(action) && project) {
    createAdminTask(project, action === "clarify" ? `Clarify returned daily ${daily.id}` : `Correct returned daily ${daily.id}`, "Field Operations", daily.supervisorReview.note || `Operations returned daily ${daily.id} for follow-up.`, {
      id: `TASK-DAILY-${action === "clarify" ? "CLARIFY" : "RETURN"}-${daily.id}`.replace(/[^A-Z0-9-]/gi, "-").toUpperCase(),
      owner: daily.foreman || roleConfig.Foreman.person,
      role: "Foreman",
      dueDate: isoDate(today),
      priority: "High",
      source: "Daily supervisor review",
      extra: { dailyId: daily.id, supervisorReviewStatus: "Returned", requestType: daily.supervisorReview.requestType }
    });
  }
  if (action === "accept") {
    autoCloseReturnedDailyTasks(daily.id, `Auto-closed after ${daily.id} was accepted by ${daily.supervisorReview.by}.`);
  }
  if (project) recomputeBillingReadinessLocal(project.id);
  appendAuditLocal(`field.daily-supervisor-${action}`, {
    project: daily.project,
    dailyId: daily.id,
    by: daily.supervisorReview.by,
    note
  });
  persist(`Daily ${daily.supervisorReview.status.toLowerCase()}`);
  render();
}

function autoCloseReturnedDailyTasks(dailyId, note) {
  const now = new Date().toISOString();
  (state.data.tasks || [])
    .filter(task => task.source === "Daily supervisor review" && task.dailyId === dailyId && task.status !== "Closed")
    .forEach(task => {
      task.status = "Closed";
      task.closedAt = now;
      task.closedBy = "System";
      task.modifiedAt = now;
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), { at: now, by: "System", note }];
      void saveToApi("tasks", task, false);
    });
}

function markReturnedDailyTasksPendingReview(dailyId, note) {
  const now = new Date().toISOString();
  (state.data.tasks || [])
    .filter(task => task.dailyId === dailyId && task.status !== "Closed" && ["Daily supervisor review", "Billing line review"].includes(task.source))
    .forEach(task => {
      task.status = "Pending Review";
      task.modifiedAt = now;
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), { at: now, by: state.user?.name || "Foreman", note }];
      void saveToApi("tasks", task, false);
    });
}

function canCompleteReturnedDailyTask(task) {
  if (task.source !== "Daily supervisor review") return true;
  const daily = (state.data.dailies || []).find(item => item.id === task.dailyId || item.id === task.relatedId);
  return daily?.supervisorReview?.status === "Accepted";
}

function dailySupervisorReviewPackage(daily) {
  const project = (state.data.projects || []).find(item => item.id === daily.project) || {};
  const forms = (state.data.formSubmissions || []).filter(item => item.project === daily.project && item.dailyId === daily.id);
  const documents = (state.data.documents || []).filter(item => item.project === daily.project && item.dailyId === daily.id);
  const photos = (state.data.photoEvidence || []).filter(item => item.project === daily.project && item.linkedRecord === daily.id);
  const production = (state.data.dailyProduction || []).filter(item => item.dailyId === daily.id);
  const labor = (state.data.dailyLabor || []).filter(item => item.dailyId === daily.id);
  const equipment = (state.data.dailyEquipment || []).filter(item => item.dailyId === daily.id);
  const materials = (state.data.dailyMaterials || []).filter(item => item.dailyId === daily.id);
  const timeEntries = (state.data.timeEntries || []).filter(item => item.project === daily.project && (String(item.id || "").includes(daily.id) || item.date === daily.date));
  const review = daily.supervisorReview || {};
  const status = review.status || "Pending Review";
  const generatedCount = forms.length + documents.length + photos.length;
  const laborHours = Number(daily.laborHours || 0) || sum(labor, "hours") || sum(timeEntries, "hours");
  const productionQuantity = sum(production, "quantity");
  const checklist = [
    { label: "Daily submitted", ok: daily.status === "Submitted", detail: `${daily.id} is ${daily.status || "missing status"}.` },
    { label: "Production posted", ok: production.length > 0 || productionQuantity > 0 || Boolean(daily.production), detail: production.length ? `${production.length} production line(s), ${productionQuantity} unit(s).` : daily.production || "No production line found." },
    { label: "Crew time support", ok: labor.length > 0 || timeEntries.length > 0 || laborHours > 0, detail: `${laborHours.toFixed(1)} labor hour(s); ${timeEntries.length} crew time line(s).` },
    { label: "Generated evidence", ok: generatedCount > 0, detail: `${forms.length} form(s), ${documents.length} document(s), ${photos.length} photo item(s).` },
    { label: "Supervisor decision", ok: status === "Accepted", detail: review.note || (status === "Returned" ? "Returned daily still needs correction and resubmission." : "Admin/Operations review is pending.") }
  ];
  return { project, forms, documents, photos, production, labor, equipment, materials, timeEntries, review, status, checklist, laborHours, productionQuantity };
}

function openDailySupervisorReviewDrawer(dailyId) {
  const daily = (state.data.dailies || []).find(item => item.id === dailyId);
  if (!daily) return;
  const pkg = dailySupervisorReviewPackage(daily);
  const project = pkg.project;
  if (project?.id) state.selectedProjectId = project.id;
  const canReview = ["Admin", "Operations"].includes(state.role);
  const canCorrect = state.role === "Foreman" && pkg.status === "Returned";
  const auditRows = dailyAuditRows(project).filter(row => JSON.stringify(row).includes(daily.id) || row.type !== "Audit").slice(0, 8);
  const drawer = document.getElementById("drawer");
  const backdrop = document.getElementById("drawerBackdrop");
  drawer.innerHTML = `
    <header>
      <div>
        <h2>Daily review package</h2>
        <span>${daily.id} · ${project.map || project.id || daily.project} · ${pkg.status}</span>
      </div>
      <button class="icon-btn" id="closeDrawer" title="Close">×</button>
    </header>
    <div class="drawer-body packet-task-detail daily-review-detail">
      <section>
        <div class="card-topline">
          <h3>Submission summary</h3>
          <span class="status ${statusClass(pkg.status)}">${pkg.status}</span>
        </div>
        <p>${daily.production || "No production summary was entered on the submitted daily."}</p>
        <dl>
          <div><dt>Map</dt><dd>${project.map || project.id || daily.project}</dd></div>
          <div><dt>Foreman</dt><dd>${daily.foreman || "Foreman"}</dd></div>
          <div><dt>Date</dt><dd>${daily.date || "No date"}</dd></div>
          <div><dt>Labor</dt><dd>${pkg.laborHours.toFixed(1)} hr(s)</dd></div>
          <div><dt>Equipment</dt><dd>${sum(pkg.equipment, "hours").toFixed(1)} hr(s)</dd></div>
          <div><dt>Materials</dt><dd>${pkg.materials.length} line(s)</dd></div>
        </dl>
        <div class="packet-task-guard ${pkg.status === "Accepted" ? "clear" : pkg.status === "Returned" ? "blocked" : "pending"}">
          <strong>${pkg.status === "Accepted" ? (state.role === "Foreman" ? "Accepted and sent to Office" : "Accepted for billing evidence") : pkg.status === "Returned" ? "Correction required" : "Supervisor decision needed"}</strong>
          <span>${pkg.review.note || "Review generated evidence, crew time, production, and photos before accepting or returning the daily."}</span>
        </div>
        ${renderDailyCorrectionReviewCard({ daily })}
      </section>
      <section>
        <div class="section-heading">
          <h3>Review checklist</h3>
          <span>${pkg.checklist.filter(item => item.ok).length}/${pkg.checklist.length} ready</span>
        </div>
        <div class="packet-task-checklist">
          ${pkg.checklist.map(item => `
            <div>
              <span class="status ${statusClass(item.ok ? "Ready" : "Needs Review")}">${item.ok ? "Ready" : "Needs Review"}</span>
              <strong>${item.label}</strong>
              <small>${item.detail}</small>
            </div>
          `).join("")}
        </div>
      </section>
      <section>
        <div class="section-heading">
          <h3>Generated evidence</h3>
          <span>${pkg.forms.length + pkg.documents.length + pkg.photos.length} item(s)</span>
        </div>
        <div class="daily-review-evidence-list">
          ${[
            ...pkg.forms.map(item => ({ type: "Form", title: item.type || item.id, detail: `${item.submittedBy || "System"} · ${formatShortDateTime(item.submittedAt)}`, status: "Submitted" })),
            ...pkg.documents.map(item => ({ type: "Document", title: item.name || item.id, detail: `${item.folder || item.category || "Map documents"} · ${item.type || "Document"}`, status: item.status || "Available" })),
            ...pkg.photos.map(item => ({ type: "Photo", title: item.caption || item.id, detail: `${item.category || "Photo"} · ${item.workflowStage || "Field evidence"}`, status: item.status || "Available" }))
          ].map(item => `
            <article>
              <span class="status ${statusClass(item.status)}">${item.type}</span>
              <div>
                <strong>${item.title}</strong>
                <small>${item.detail}</small>
              </div>
            </article>
          `).join("") || `<p class="empty-state">No generated evidence is tied to this daily yet.</p>`}
        </div>
      </section>
      <section>
        <div class="section-heading">
          <h3>Correction history</h3>
          <span>${daily.correctionVersions?.length || 0} version(s)</span>
        </div>
        <div class="daily-version-list in-drawer">
          ${(daily.correctionVersions || []).map(version => `
            <article>
              <span class="status warn">v${version.version}</span>
              <div>
                <strong>Returned by ${version.returnedBy || "Supervisor"}</strong>
                <small>${version.returnNote || "No return note"}</small>
                <small>Resubmitted by ${version.resubmittedBy || "Foreman"} · ${formatShortDateTime(version.resubmittedAt)}</small>
              </div>
            </article>
          `).join("") || `<p class="empty-state">No returned/resubmitted versions are recorded for this daily.</p>`}
        </div>
      </section>
      <section>
        <div class="section-heading">
          <h3>Review audit</h3>
          <span>${auditRows.length} event(s)</span>
        </div>
        <div class="packet-task-list">
          ${auditRows.map(row => `
            <article>
              <div class="card-topline">
                <strong>${row.status || row.type || "Event"}</strong>
                <span class="status ${statusClass(row.status)}">${row.type || "Audit"}</span>
              </div>
              <small>${row.note || "No details"}</small>
              <small>${row.by || "System"} · ${formatShortDateTime(row.at)}</small>
            </article>
          `).join("") || `<p class="empty-state">No review audit activity is recorded for this daily yet.</p>`}
        </div>
      </section>
    </div>
    <footer>
      <button class="secondary-btn" id="dailyReviewClose">Close</button>
      <button class="secondary-btn" id="dailyReviewOpenField">${canCorrect ? "Correct Daily" : "Open Field Daily"}</button>
      <button class="secondary-btn" id="dailyReviewOpenMap">Open Map</button>
      ${canReview && pkg.status !== "Accepted" ? `
        <button class="secondary-btn" id="dailyReviewClarify">Ask Clarification</button>
        <button class="secondary-btn" id="dailyReviewReturn">Return for Correction</button>
        <button class="primary-btn" id="dailyReviewAccept">Accept Daily</button>
      ` : ""}
    </footer>
  `;
  drawer.classList.add("open");
  backdrop.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");
  document.getElementById("closeDrawer").addEventListener("click", closeDrawer);
  document.getElementById("dailyReviewClose").addEventListener("click", closeDrawer);
  document.getElementById("dailyReviewOpenField").addEventListener("click", () => {
    closeDrawer();
    handleWorkflowClick({ dataset: { workflowAction: "Field Operations", workflowId: daily.project, workflowFocus: canCorrect ? "Returned daily correction" : "Daily review" } });
  });
  document.getElementById("dailyReviewOpenMap").addEventListener("click", () => {
    closeDrawer();
    handleWorkflowClick({ dataset: { workflowAction: "Project & Map Hub", workflowId: daily.project, workflowFocus: "Daily review" } });
  });
  document.getElementById("dailyReviewReturn")?.addEventListener("click", () => handleDailySupervisorReview({ dataset: { dailyId: daily.id, dailySupervisorReview: "return" } }));
  document.getElementById("dailyReviewClarify")?.addEventListener("click", () => handleDailySupervisorReview({ dataset: { dailyId: daily.id, dailySupervisorReview: "clarify" } }));
  document.getElementById("dailyReviewAccept")?.addEventListener("click", () => handleDailySupervisorReview({ dataset: { dailyId: daily.id, dailySupervisorReview: "accept" } }));
}

function renderFieldEvidenceCorrectionQueue(project) {
  const tasks = evidenceCorrectionTasks(project)
    .filter(task => task.status !== "Closed" && ["Foreman", "Crew Member", project.crew].some(owner => `${task.role} ${task.owner}`.includes(owner)));
  if (!tasks.length) return "";
  return `
    <section class="panel field-correction-queue">
      <div class="panel-header">
        <div>
          <h2>Evidence corrections sent back from Billing/Admin</h2>
          <p>Fix these items before the Map packet can be accepted for SQUAN billing.</p>
        </div>
        <span>${tasks.length} open</span>
      </div>
      <div class="field-correction-list">
        ${tasks.map(task => {
          const attachments = evidenceCorrectionAttachments(project, task.evidenceKey);
          const review = evidenceReviewFor(project, task.evidenceKey);
          const status = review?.status || task.status;
          return `
            <article>
              <span class="status ${statusClass(status)}">${status}</span>
              <div>
                <strong>${task.evidenceLabel || task.title}</strong>
                <small>${task.dueDate || "No due date"} · ${displayWorkflowArea(task.workflowArea)} · ${attachments.length} corrected attachment(s)</small>
                <p>${review?.note || task.notes}</p>
                <div class="field-correction-steps">
                  ${correctionStepPill("1", "Review request", "Ready", "Read Billing/Admin note")}
                  ${correctionStepPill("2", "Attach proof", attachments.length ? "Ready" : "Open", attachments.length ? `${attachments.length} linked` : "Add corrected document/photo")}
                  ${correctionStepPill("3", "Resubmit", status === "Pending Review" || status === "Accepted" ? "Ready" : "Open", status === "Pending Review" ? "Waiting on Admin/Billing" : status === "Accepted" ? "Accepted" : "Mark corrected")}
                </div>
              </div>
              <div class="field-correction-actions">
                <button class="secondary-btn" data-task-open="${task.id}">Open</button>
                <button class="secondary-btn" data-workflow-action="${taskWorkflowAction(task)}" data-workflow-id="${task.project}">Source</button>
                <button class="secondary-btn" data-field-correction-attach="${task.id}" ${status === "Accepted" ? "disabled" : ""}>Attach</button>
                <button class="primary-btn" data-field-correction-resubmit="${task.id}" ${status === "Accepted" ? "disabled" : ""}>Resubmit</button>
              </div>
            </article>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function correctionStepPill(number, label, status, detail) {
  return `
    <span class="correction-step-pill ${statusClass(status)}">
      <strong>${number}</strong>
      <em>${label}</em>
      <small>${detail}</small>
    </span>
  `;
}

function renderOperationsBoard() {
  const projects = scopedRows("projects").filter(matches).filter(projectMatchesMapFilter).filter(projectMatchesEvidenceFilter);
  const selectedProject = projects.find(project => project.id === state.selectedProjectId) || projects[0];
  if (selectedProject && selectedProject.id !== state.selectedProjectId) state.selectedProjectId = selectedProject.id;
  const focused = renderOperationsFocusedDetail(selectedProject, projects);
  return `
    ${renderOperationsMapMover(selectedProject)}
    ${renderOperationsDailyReviewQueue(projects, selectedProject)}
    ${focused || `
      ${renderOperationsSetupPath(selectedProject)}
      ${renderOperationsMapQueue(projects, selectedProject)}
      ${renderOperationsQuickTools(selectedProject)}
    `}
  `;
}

function renderOperationsMapMover(project) {
  const path = project ? mapCriticalPath(project) : null;
  const release = project ? releaseGateReview(project) : null;
  const ctx = project ? erpSpineContext(project) : null;
  return `
    <section class="panel operations-mover-home">
      <div class="operations-mover-head">
        <div>
          <span class="eyebrow">Operations</span>
          <h2>${project ? `Get ${project.map || project.id} ready for work` : "Select a Map to get ready"}</h2>
          <p>Operations gets the Map ready before the Foreman starts: intake, map/site survey, 811/permits, obstacles, crew/equipment checks, and owner approval.</p>
        </div>
        <span class="status ${statusClass(path?.status || "Pending")}">${plainStatus(path?.status || "Pending")}</span>
      </div>
      <div class="operations-status-strip">
        <article><span>Phase</span><strong>${plainStatus(project?.status || "None")}</strong><small>${project?.scope || "No Map selected"}</small></article>
        <article><span>Next move</span><strong>${path?.next?.label || "Select Map"}</strong><small>${path?.next?.detail || "Choose a Map to review."}</small></article>
        <article><span>Crew / equipment</span><strong>${ctx ? `${ctx.crewGate.status} / ${ctx.equipmentGate.status}` : "N/A"}</strong><small>${project?.crew || "No crew selected"}</small></article>
        <article><span>Ready to work?</span><strong>${release?.released ? "Approved" : release?.ready ? "Ready" : "Blocked"}</strong><small>${release?.blockers?.map(item => item.label).join(", ") || "No problems stopping work"}</small></article>
      </div>
    </section>
  `;
}

function renderOperationsSetupPath(project) {
  if (!project) return "";
  const path = mapCriticalPath(project);
  const steps = path.steps.filter(step => ["intake", "survey", "locates", "obstacles", "resources", "release", "daily"].includes(step.key));
  return `
    <section class="panel operations-setup-path">
      <div class="panel-header">
        <div>
          <h2>Get Map Ready</h2>
          <p>Work these in order. When approval is clear, the Foreman daily can start.</p>
        </div>
        <span>${path.complete}% complete</span>
      </div>
      <div class="operations-step-grid">
        ${steps.map((step, index) => `
          <button class="operations-step-card ${statusClass(step.status)}" data-workflow-action="${step.action}" data-workflow-id="${project.id}" data-workflow-focus="${step.focus}">
            <span>${index + 1}</span>
            <strong>${step.label}</strong>
            <small>${step.detail}</small>
            <em>${plainStatus(step.status)}</em>
          </button>
        `).join("")}
      </div>
      <div class="operations-next-action">
        <div>
          <span class="eyebrow">Next Step</span>
          <h3>${path.next?.label || "Review Map"}</h3>
          <p>${path.next?.detail || "No setup blocker is first in line."}</p>
        </div>
        <button class="primary-btn" data-workflow-action="${path.next?.action || "Project & Map Hub"}" data-workflow-id="${project.id}" data-workflow-focus="${path.next?.focus || "Beginning phase"}">Open next step</button>
      </div>
    </section>
  `;
}

function renderOperationsMapQueue(projects, selectedProject) {
  return `
    <section class="panel operations-map-queue">
      <div class="panel-header">
        <div>
          <h2>Maps Operations is getting ready</h2>
          <p>Select a Map to see its steps. Completed and billed Maps stay visible but should not crowd daily dispatch.</p>
        </div>
        <span>${projects.length} Map(s)</span>
      </div>
      <div class="operations-map-list">
        ${projects.map(project => {
          const path = mapCriticalPath(project);
          const isSelected = project.id === selectedProject?.id;
          return `
            <button class="${isSelected ? "selected" : ""}" data-workflow-action="Project & Map Hub" data-workflow-id="${project.id}" data-workflow-focus="Dispatch">
              <span class="status ${statusClass(path.status)}">${plainStatus(path.status)}</span>
              <strong>${project.map || project.id}</strong>
              <small>${project.status}; next: ${path.next?.label || "Review"}</small>
            </button>
          `;
        }).join("") || `<p class="empty-state">No Maps are visible for Operations.</p>`}
      </div>
    </section>
  `;
}

function renderOperationsQuickTools(project) {
  const tools = [
    ["Setup details", "Intake, site survey, 811/permits, and setup files", "Project & Map Hub", "Beginning phase"],
    ["Crew ready?", "Training cards, required checks, and assignment problems", "People & Compliance", "Release gate"],
    ["Equipment ready?", "Truck/tool assignment, inspections, calibration, dielectric", "Equipment", "Release gate"],
    ["Obstacles / photos", "Photos, GPS pins, and obstruction proof", "Project & Map Hub", "Field capture review"],
    ["Ready to work?", "Final check before field work starts", "Project & Map Hub", "Release gate"],
    ["Board view", "All Maps by dispatch status", "Project & Map Hub", "Operations board"]
  ];
  return `
    <section class="panel operations-tools-panel">
      <div class="panel-header">
        <div>
          <h2>Operations tools</h2>
          <p>Open a detail tool only when the setup steps point you there.</p>
        </div>
        <span>${project?.map || project?.id || "No Map"}</span>
      </div>
      <div class="operations-tool-grid">
        ${tools.map(([title, detail, action, focus]) => `
          <button class="operations-tool-card" data-workflow-action="${action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${focus}">
            <strong>${title}</strong>
            <small>${detail}</small>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function operationsDispatchStatus(project) {
  if (!project) return { status: "Pending", detail: "Select a Map to review dispatch status.", steps: [] };
  const ctx = erpSpineContext(project);
  const beginning = beginningPhaseReview(project);
  const daily = ctx.dailies.find(item => item.status === "Submitted") || ctx.dailies[0];
  const startGate = fieldStartGate(project, daily);
  const closeout = closeoutReview(project);
  const fieldDailies = ctx.dailies.filter(item => item.status === "Submitted");
  const setupReady = beginning.ready || ctx.intake.status === "Field Ready";
  const assignmentReady = ctx.crewGate.status === "Clear" && ctx.equipmentGate.status === "Available";
  const releaseReady = ctx.release.released || ctx.release.ready;
  const dailyReady = fieldDailies.length > 0;
  const closeoutReady = closeout.ready;
  const steps = [
    { label: "Setup", status: setupReady ? "Ready" : "Needs Review", detail: beginning.blockers.join(", ") || "Map setup is clear.", action: "Project & Map Hub", focus: "Beginning phase" },
    { label: "Assignment", status: assignmentReady ? "Ready" : "Blocked", detail: `Crew ${ctx.crewGate.status}; equipment ${ctx.equipmentGate.status}.`, action: "People & Compliance", focus: "Selected Map" },
    { label: "Release", status: ctx.release.released ? "Released" : ctx.release.ready ? "Ready for Release" : "Blocked", detail: ctx.release.blockers.map(item => item.label).join(", ") || "Ready for Admin release.", action: "Project & Map Hub", focus: "Release gate" },
    { label: "Daily", status: dailyReady ? "Submitted" : startGate.clear ? "Open" : "Pending", detail: dailyReady ? `${fieldDailies.length} submitted daily record(s).` : startGate.clear ? "Foreman can start daily." : startGate.blockers.map(item => item.label).join(", "), action: "Field Operations", focus: "Daily start" },
    { label: "Evidence", status: ctx.support.some(item => ["Missing", "Needs Review", "Pending Review", "Rejected"].includes(item.status)) ? "Needs Review" : "Ready", detail: `${ctx.documents.length} document(s), ${ctx.photos.length} photo(s), ${ctx.support.length} support item(s).`, action: "Documents", focus: "Map evidence" },
    { label: "Closeout", status: closeoutReady ? "Ready" : "Needs Review", detail: closeoutReady ? "Closeout gates are clear." : closeout.missing.map(item => item.label).join(", "), action: "Project & Map Hub", focus: "Closeout" }
  ];
  const blocking = steps.filter(item => ["Blocked", "Needs Review", "Pending", "Missing"].includes(item.status));
  return {
    ctx,
    beginning,
    startGate,
    closeout,
    steps,
    status: ctx.release.released && dailyReady ? "In Field" : blocking.length ? "Needs Dispatch Action" : "Ready",
    detail: blocking.length ? blocking.map(item => item.label).join(", ") : "Dispatch path is clear."
  };
}

function mapCriticalPath(project) {
  if (!project) return { status: "No Map", steps: [], next: null, complete: 0 };
  const ctx = erpSpineContext(project);
  const beginning = beginningPhaseReview(project);
  const release = releaseGateReview(project);
  const daily = ctx.dailies.find(item => item.status === "Submitted") || ctx.dailies[0] || {};
  const startGate = fieldStartGate(project, daily);
  const gis = fieldMapsReadiness(project);
  const acceptedCaptures = acceptedFieldCaptureEvidence(project);
  const hasAcceptedPhoto = acceptedCaptures.photos.length > 0;
  const hasAcceptedMarkup = acceptedCaptures.markups.length > 0;
  const openSetupTasks = (state.data.tasks || []).filter(task => task.project === project.id && task.status !== "Closed" && ["Map intake checklist", "MSA daily/pre-job gate", "Safety risk log", "Release gate"].includes(task.source));
  const steps = [
    {
      key: "intake",
      label: "Map intake",
      owner: "Operations",
      status: beginning.steps[0]?.status || "Needs Review",
      detail: beginning.steps[0]?.detail || "Scope, units, and customer requirements.",
      action: "Project & Map Hub",
      focus: "Beginning phase"
    },
    {
      key: "fieldmaps",
      label: "Field Maps package",
      owner: "Foreman",
      status: gis.ready || (state.data.offlineSyncQueue || []).some(item => item.project === project.id && item.type === "Offline map package downloaded") ? "Ready" : "Needs Review",
      detail: gis.ready ? "ArcGIS/Field Maps route is ready." : gis.blockers.join(", ") || "Download and sync the offline package.",
      action: "Field Operations",
      focus: "GIS / evidence"
    },
    {
      key: "survey",
      label: "Maps / site survey",
      owner: "Operations",
      status: beginning.steps[2]?.status || "Needs Review",
      detail: beginning.steps[2]?.detail || "Walkout/site survey must be reviewed.",
      action: "Documents",
      focus: "Map evidence"
    },
    {
      key: "locates",
      label: "811 / permits",
      owner: "Operations",
      status: beginning.steps[3]?.status || "Needs Review",
      detail: beginning.steps[3]?.detail || "811 and permit review required.",
      action: "Documents",
      focus: "Map evidence"
    },
    {
      key: "obstacles",
      label: "Obstacles / photos",
      owner: "Foreman + Safety",
      status: hasAcceptedPhoto && hasAcceptedMarkup ? "Ready" : beginning.steps[4]?.status || "Needs Review",
      detail: hasAcceptedPhoto && hasAcceptedMarkup ? `${acceptedCaptures.rows.length} accepted field capture(s) linked.` : beginning.steps[4]?.detail || "Obstacle evidence required.",
      action: "Project & Map Hub",
      focus: "Field capture review"
    },
    {
      key: "resources",
      label: "Crew / equipment",
      owner: "Operations",
      status: ctx.crewGate.status === "Clear" && ctx.equipmentGate.status === "Available" ? "Ready" : "Blocked",
      detail: `Crew ${ctx.crewGate.status}; equipment ${ctx.equipmentGate.status}.`,
      action: "People & Compliance",
      focus: "Selected Map"
    },
    {
      key: "release",
      label: "Release-to-field",
      owner: "Admin",
      status: release.released ? "Released" : release.ready ? "Ready for Release" : "Blocked",
      detail: release.released ? "Admin released this Map to field." : release.ready ? "Ready for Admin release." : release.blockers.map(item => item.label).join(", "),
      action: "Project & Map Hub",
      focus: "Release gate"
    },
    {
      key: "daily",
      label: "Daily start",
      owner: "Foreman",
      status: startGate.clear ? "Clear" : "Blocked",
      detail: startGate.clear ? "Foreman can start the daily workflow." : startGate.blockers.map(item => item.label).join(", "),
      action: "Field Operations",
      focus: "Daily start"
    }
  ];
  const doneStatuses = ["Clear", "Ready", "Released", "Submitted", "Accepted", "Active", "Field Ready"];
  const done = steps.filter(step => doneStatuses.includes(step.status)).length;
  const next = steps.find(step => !doneStatuses.includes(step.status)) || steps.at(-1);
  return {
    ctx,
    steps,
    next,
    openSetupTasks,
    acceptedCaptures,
    complete: Math.round(done / Math.max(1, steps.length) * 100),
    status: startGate.clear ? "Clear to Start" : release.ready ? "Ready for Release" : next?.status || "Needs Review"
  };
}

function renderMapCriticalPathPanel(project, embedded = false) {
  if (!project) return "";
  const path = mapCriticalPath(project);
  const canOps = ["Admin", "Operations"].includes(state.role);
  return `
    <section class="${embedded ? "section-block map-critical-path embedded" : "panel map-critical-path"}">
      <div class="${embedded ? "section-heading" : "panel-header"}">
        <div>
          <h2>${project.map || project.id} critical path</h2>
          <p>One operating path from intake through Field Maps, release-to-field, and daily start.</p>
        </div>
        <span class="status ${statusClass(path.status)}">${path.complete}% · ${path.status}</span>
      </div>
      <div class="critical-path-next">
        <strong>Next required move</strong>
        <span>${path.next?.label || "Review Map"} · ${path.next?.owner || "Operations"} · ${path.next?.detail || "No detail"}</span>
        <button class="secondary-btn" data-workflow-action="${path.next?.action || "Project & Map Hub"}" data-workflow-id="${project.id}" data-workflow-focus="${path.next?.focus || "Beginning phase"}">Open next step</button>
      </div>
      <div class="critical-path-grid">
        ${path.steps.map((step, index) => `
          <button class="critical-path-step ${statusClass(step.status)}" data-workflow-action="${step.action}" data-workflow-id="${project.id}" data-workflow-focus="${step.focus}">
            <span>${index + 1}</span>
            <strong>${step.label}</strong>
            <small>${step.owner} · ${step.detail}</small>
            <em class="status ${statusClass(step.status)}">${step.status}</em>
          </button>
        `).join("")}
      </div>
      ${canOps ? `
        <div class="map-preview-actions">
          <button class="secondary-btn" data-critical-path-action="reconcile-field-captures" data-project-id="${project.id}">Reconcile accepted captures</button>
          <button class="secondary-btn" data-release-completion-action="complete-setup-docs" data-project-id="${project.id}">Complete setup docs</button>
          <button class="secondary-btn" data-release-completion-action="stage-resources" data-project-id="${project.id}">Stage resources</button>
          <button class="secondary-btn" data-release-completion-action="create-daily-starter" data-project-id="${project.id}">Create daily starter</button>
          <button class="primary-btn" data-beginning-action="ready-release" data-project-id="${project.id}">Request release</button>
        </div>
      ` : ""}
    </section>
  `;
}

function renderOperationsDispatchCommandCenter(project) {
  const dispatch = operationsDispatchStatus(project);
  return `
    <section class="panel operations-command-center">
      <div class="panel-header">
        <div>
          <h2>Map dispatch command center</h2>
          <p>Move the selected Map from setup to assignment, release, daily field capture, evidence, and closeout.</p>
        </div>
        <span class="status ${statusClass(dispatch.status)}">${dispatch.status}</span>
      </div>
      <div class="field-mobile-steps operations-workflow-steps">
        ${dispatch.steps.map((step, index) => `
          <button class="field-mobile-step ${statusClass(step.status)}" data-workflow-action="${step.action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${step.focus}">
            <span>${index + 1}</span>
            <strong>${step.label}</strong>
            <small>${step.detail || "Review"}</small>
          </button>
        `).join("")}
      </div>
    </section>
    ${project ? renderMapCriticalPathPanel(project, true) : ""}
  `;
}

function renderOperationsPriorityQueue(projects, selectedProject) {
  const selected = selectedProject ? operationsDispatchStatus(selectedProject) : null;
  const endOfDayRows = incompleteDailyRows().slice(0, 5);
  const dailyReviews = dailySupervisorReviewRows(projects).filter(row => row.status !== "Accepted").slice(0, 5);
  const captureReviews = fieldCaptureReviewRows(selectedProject).filter(row => !["Accepted", "Closed"].includes(row.status)).slice(0, 5);
  const rows = [
    ...(selected ? selected.steps.filter(item => ["Blocked", "Needs Review", "Pending", "Missing"].includes(item.status)).map(item => ({
      title: `${selectedProject.map || selectedProject.id}: ${item.label}`,
      detail: item.detail,
      status: item.status,
      project: selectedProject.id,
      action: item.action,
      focus: item.focus
    })) : []),
    ...projects.filter(project => project.status === "Beginning Phase").slice(0, 5).map(project => {
      const review = beginningPhaseReview(project);
      return {
        title: `${project.map || project.id}: beginning-phase setup`,
        detail: review.blockers.length ? `Blocking: ${review.blockers.join(", ")}` : "Ready for release review.",
        status: review.releaseApproved ? "Released" : review.ready ? "Ready for Release" : "Needs Review",
        project: project.id,
        action: "Project & Map Hub",
        focus: "Beginning phase"
      };
    }),
    ...endOfDayRows.map(row => ({
      title: `${row.project.map || row.project.id}: ${row.status === "Draft" ? "draft daily" : "missing daily"}`,
      detail: row.gate.clear ? row.detail : `Gate blockers: ${row.gate.blockers.map(item => item.label).join(", ")}`,
      status: row.gate.clear ? row.status : "Blocked",
      project: row.project.id,
      task: row.task,
      action: "Field Operations",
      focus: row.gate.clear ? "Daily closeout" : "Daily start"
    })),
    ...dailyReviews.map(row => ({
      title: `${row.project.map || row.project.id}: daily supervisor review`,
      detail: row.daily ? `${row.daily.id}; ${row.status}` : "No daily found.",
      status: row.status,
      project: row.project.id,
      action: "Field Operations",
      focus: "Daily closeout"
    })),
    ...captureReviews.map(row => ({
      title: `${row.project.map || row.project.id}: ${row.kind}`,
      detail: row.summary,
      status: row.status,
      project: row.project.id,
      action: "Project & Map Hub",
      focus: "Field capture review"
    }))
  ].slice(0, 12);
  return `
    <section class="panel operations-priority-actions">
      <div class="panel-header">
        <div>
          <h2>Dispatch priority queue</h2>
          <p>Setup blockers, release blockers, missing dailies, and supervisor review items that affect field movement.</p>
        </div>
        <span>${rows.length} item(s)</span>
      </div>
      <div class="packet-home-list">
        ${rows.map(row => `
          <article>
            <span class="status ${statusClass(row.status)}">${row.status}</span>
            <div>
              <strong>${row.title}</strong>
              <small>${row.detail}</small>
            </div>
            <div class="packet-home-actions">
              ${row.task ? `<button class="secondary-btn" data-task-open="${row.task.id}">Task</button>` : ""}
              <button class="secondary-btn" data-workflow-action="${row.action}" data-workflow-id="${row.project}" data-workflow-focus="${row.focus}">Open</button>
            </div>
          </article>
        `).join("") || `<p class="empty-state">No dispatch blocker is currently open.</p>`}
      </div>
    </section>
  `;
}

function renderOperationsWorkflowDrillIns(project) {
  const cards = [
    ["Selected Map", "Dispatch lane for setup, assignment, release, daily, evidence, closeout", "Project & Map Hub", "Dispatch"],
    ["Beginning Phase", "Intake, maps/site survey, 811/permits, obstacles, release prep", "Project & Map Hub", "Beginning phase"],
    ["Assignment", "Crew and equipment readiness for release", "People & Compliance", "Selected Map"],
    ["Release Gate", "Go/no-go review before daily start", "Project & Map Hub", "Release gate"],
    ["Field Daily", "Pre-Check, production, photos, and submit", "Field Operations", "Daily start"],
    ["Field Captures", "Review offline GPS photos, markups, blockers, and sync evidence", "Project & Map Hub", "Field capture review"],
    ["Closeout", "QC, evidence, billing readiness, and closeout blockers", "Project & Map Hub", "Closeout"],
    ["Board", "All Maps by dispatch status", "Project & Map Hub", "Operations board"]
  ];
  return `
    <section class="panel operations-drillins">
      <div class="panel-header">
        <div>
          <h2>Open dispatch tools</h2>
          <p>Use the command center first. Open detailed tools when a setup, assignment, release, daily, or closeout path needs work.</p>
        </div>
        <span>${project?.map || project?.id || "All Maps"}</span>
      </div>
      <div class="linked-records">
        ${cards.map(([title, detail, action, focus]) => `
          <button class="linked-count" data-workflow-action="${action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${focus}">
            <strong>${title}</strong>
            <span>${detail}</span>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function renderOperationsFocusedDetail(project, projects) {
  if (!state.workflowFocus) return "";
  const focus = String(state.workflowFocus).toLowerCase();
  const includesAny = (...terms) => terms.some(term => focus.includes(term));
  if (project && includesAny("dispatch", "selected")) {
    return `
      ${workflowFocusPanel(project, "Operations")}
      ${renderOperationsSelectedMapLane(project, projects)}
    `;
  }
  if (project && includesAny("beginning", "setup", "intake")) {
    return `
      ${workflowFocusPanel(project, "Operations")}
      ${renderOperationsReleasePrep(project)}
      ${renderBeginningPhaseWorkflow(project)}
    `;
  }
  if (project && includesAny("assignment", "crew", "equipment")) {
    return `
      ${workflowFocusPanel(project, "Operations")}
      ${renderAssignmentSelectedMapLane(project, "People")}
    `;
  }
  if (project && includesAny("release")) {
    return `
      ${workflowFocusPanel(project, "Operations")}
      ${renderOperationsReleasePrep(project)}
      ${renderReleaseGateReview(project)}
    `;
  }
  if (project && includesAny("daily", "field")) {
    return `
      ${workflowFocusPanel(project, "Operations")}
      ${includesAny("capture") ? renderFieldCaptureReviewPanel(project, "Operations") : ""}
      ${renderOperationsDailyReviewQueue([project], project)}
      ${renderEndOfDayDailyHomeSummary([project])}
      ${renderDailySupervisorReview(project)}
      ${renderFieldStartGate(selectedFieldContext())}
    `;
  }
  if (project && includesAny("capture", "offline", "markup")) {
    return `
      ${workflowFocusPanel(project, "Operations")}
      ${renderFieldCaptureReviewPanel(project, "Operations")}
    `;
  }
  if (project && includesAny("closeout", "qc")) {
    return `
      ${workflowFocusPanel(project, "Operations")}
      ${renderMapEvidenceCloseoutSection(project, erpSpineContext(project))}
      ${renderOperationsDailyReviewQueue([project], project)}
      ${renderDailySupervisorReview(project)}
    `;
  }
  if (includesAny("board", "all maps")) {
    return `
      ${project ? workflowFocusPanel(project, "Operations") : ""}
      ${renderOperationsKanban(projects)}
    `;
  }
  return "";
}

function renderOperationsSelectedMapLane(project, projects) {
  if (!project) return renderOperationsKanban(projects);
  const dispatch = operationsDispatchStatus(project);
  const ctx = dispatch.ctx || erpSpineContext(project);
  const complete = ctx.production.length ? Math.round(sum(ctx.production, "quantity") / Math.max(1, sum(scopedRows("projectUnits").filter(item => item.project === project.id), "contractQuantity")) * 100) : 0;
  return `
    <section class="panel operations-selected-map-lane">
      <div class="panel-header">
        <div>
          <h2>Selected Map dispatch lane</h2>
          <p>Default operations view for this Map: setup, assignment, release, daily, evidence, and closeout readiness.</p>
        </div>
        <span class="status ${statusClass(dispatch.status)}">${project.map || project.id} · ${dispatch.status}</span>
      </div>
      <div class="packet-home-metrics">
        ${metric("Setup", dispatch.beginning.ready ? "Ready" : "Needs Review", dispatch.beginning.blockers.join(", ") || "Clear")}
        ${metric("Release", ctx.release.released ? "Released" : ctx.release.ready ? "Ready" : "Blocked", `${ctx.release.blockers.length} blocker(s)`)}
        ${metric("Daily", ctx.dailies.filter(item => item.status === "Submitted").length, "Submitted daily records")}
        ${metric("Production", `${complete}%`, `${ctx.production.length} production line(s)`)}
        ${metric("Closeout", dispatch.closeout.ready ? "Ready" : "Needs Review", dispatch.closeout.missing.map(item => item.label).join(", ") || "Clear")}
      </div>
    </section>
    ${renderMapCriticalPathPanel(project, true)}
    ${renderFieldCaptureReviewPanel(project, "Operations")}
    ${renderBeginningPhaseWorkflow(project, true)}
    ${renderReleaseGateReview(project)}
    ${renderEndOfDayDailyHomeSummary([project])}
  `;
}

function renderOperationsKanban(projects) {
  const buckets = [
    { title: "Beginning Phase", rows: projects.filter(project => project.status === "Beginning Phase") },
    { title: "Blocked", rows: projects.filter(project => ["At Risk", "Blocked"].includes(project.status) || !releaseGateReview(project).ready && !releaseGateReview(project).released) },
    { title: "Ready / Released", rows: projects.filter(project => releaseGateReview(project).ready || releaseGateReview(project).released) },
    { title: "Field Active", rows: projects.filter(project => scopedRows("dailies").some(daily => daily.project === project.id && daily.status === "Submitted")) },
    { title: "Needs Closeout", rows: projects.filter(project => !closeoutReview(project).ready && project.status !== "Beginning Phase") },
    { title: "Completed / Billed", rows: projects.filter(project => project.status === "Completed / Billed") }
  ];
  return `
    <section class="ops-board">
      ${buckets.map(bucket => `
        <div class="panel board-lane">
          <div class="panel-header">
            <h2>${bucket.title}</h2>
            <span>${bucket.rows.length} maps</span>
          </div>
          <div class="queue-list">
            ${bucket.rows.map(project => operationCard(project)).join("") || `<div class="empty">No maps</div>`}
          </div>
        </div>
      `).join("")}
    </section>
  `;
}

function operationCard(project) {
  const readiness = scopedRows("billingReadiness").find(item => item.project === project.id);
  const units = scopedRows("projectUnits").filter(item => item.project === project.id);
  const openObstacles = scopedRows("obstacles").filter(item => item.project === project.id && isOpenObstacle(item));
  const openBlockers = scopedRows("costBlockers").filter(item => item.project === project.id && item.status === "Open");
  const complete = units.length
    ? Math.round(sum(units, "completedQuantity") / Math.max(1, sum(units, "contractQuantity")) * 100)
    : 0;
  return `
    <article class="queue-card">
      <div class="card-topline">
        <h3>${project.id}</h3>
        <span class="status ${statusClass(project.status)}">${project.status}</span>
      </div>
      <p>${project.scope}</p>
      <dl>
        <div><dt>Crew</dt><dd>${project.crew}</dd></div>
        <div><dt>Progress</dt><dd>${complete}%</dd></div>
        <div><dt>Billing</dt><dd>${readiness?.status || "Not reviewed"}</dd></div>
        <div><dt>Last daily</dt><dd>${lastDaily(project.id)?.date || "None"}</dd></div>
        <div><dt>Obstacles</dt><dd>${openObstacles.length + openBlockers.length} open</dd></div>
      </dl>
      <button class="secondary-btn" data-project-id="${project.id}">${project.status === "Beginning Phase" ? "Open setup path" : "Resolve Blocker"}</button>
    </article>
  `;
}

function beginningPhaseReview(project) {
  const documents = scopedRows("documents").filter(item => item.project === project.id);
  const surveys = scopedRows("siteSurveys").filter(item => item.project === project.id);
  const obstacles = scopedRows("obstacles").filter(item => item.project === project.id);
  const intake = intakeReadiness(project, documents, surveys, obstacles);
  const crew = crewReadiness(project);
  const equipment = equipmentReadiness(project);
  const has811 = documents.some(item => item.type === "811" && !["Missing", "Needs Review", "Pending Review", "Pending"].includes(item.status));
  const hasPermit = documents.some(item => item.type === "Permit" && !["Missing", "Needs Review", "Pending Review", "Pending"].includes(item.status));
  const openObstacles = obstacles.filter(item => isOpenObstacle(item));
  const releaseRequested = Boolean(project.adminApprovals?.releaseRequest);
  const releaseApproved = Boolean(project.adminApprovals?.release);
  const gis = fieldMapsReadiness(project);
  const steps = [
    { label: "Intake", status: intake.status, detail: "Map, scope, unit schedule, bill-by date, customer requirements" },
    { label: "ArcGIS Field Maps", status: gis.status, detail: gis.ready ? `${gis.gis.layerName}; ${gis.gis.featureIds}` : gis.blockers.join(", ") },
    { label: "Map / site survey", status: intake.items.find(item => item.label === "Map viewable")?.status === "Clear" && intake.items.find(item => item.label === "Site survey")?.status === "Clear" ? "Clear" : "Needs Review", detail: "Route map and walkout/site survey must be viewable" },
    { label: "811 / permits", status: has811 && hasPermit ? "Clear" : "Needs Review", detail: `${has811 ? "811 attached" : "811 missing"}; ${hasPermit ? "permit attached" : "permit missing"}` },
    { label: "Obstacles", status: openObstacles.length ? "Blocked" : "Clear", detail: openObstacles.length ? `${openObstacles.length} open obstacle(s)` : "No open obstacles" },
    { label: "Crew readiness", status: crew.status, detail: crew.members.map(item => `${item.person.name}: ${item.status}`).join(", ") || "No crew assigned" },
    { label: "Equipment readiness", status: equipment.status, detail: equipment.assets.map(item => `${item.item.id}: ${item.status}`).join(", ") || "No equipment assigned" },
    { label: "Release to field", status: releaseApproved ? "Active" : releaseRequested ? "Ready for Release" : "Needs Review", detail: releaseApproved ? "Admin released this map to field" : releaseRequested ? "Waiting on Admin approval" : "Admin release required before field daily starts" }
  ];
  const readyStatuses = ["Clear", "Available", "Field Ready", "Ready"];
  const ready = steps.slice(0, 7).every(step => readyStatuses.includes(step.status));
  if (!releaseApproved && !releaseRequested && ready) steps[7].status = "Ready for Release";
  return {
    steps,
    ready,
    releaseRequested,
    releaseApproved,
    blockers: steps.slice(0, 7).filter(step => !readyStatuses.includes(step.status)).map(step => step.label)
  };
}

function renderBeginningPhaseWorkflow(project, embedded = false) {
  const review = beginningPhaseReview(project);
  const canAct = ["Admin", "Operations"].includes(state.role);
  return `
    <section class="${embedded ? "section-block beginning-workflow embedded" : "panel beginning-workflow"}">
      <div class="${embedded ? "section-heading" : "panel-header"}">
        <h2>${project.map || project.id} beginning-phase path</h2>
        <span class="status ${statusClass(review.releaseApproved ? "Active" : review.releaseRequested || review.ready ? "Ready for Release" : "Needs Review")}">${review.releaseApproved ? "Released" : review.releaseRequested || review.ready ? "Ready for Release" : "Needs Review"}</span>
      </div>
      <div class="beginning-step-grid">
        ${review.steps.map((step, index) => `
          <article class="beginning-step ${statusClass(step.status)}">
            <span>${index + 1}</span>
            <div>
              <strong>${step.label}</strong>
              <small>${step.detail}</small>
            </div>
            <em class="status ${statusClass(step.status)}">${step.status}</em>
          </article>
        `).join("")}
      </div>
      ${renderReleaseCompletionPanel(project)}
      <div class="invoice-actions">
        <button class="secondary-btn" data-workflow-action="Documents" data-workflow-id="${project.id}">Review maps/docs</button>
        <button class="secondary-btn" data-workflow-action="Safety & Risk" data-workflow-id="${project.id}">Review obstacles</button>
        <button class="secondary-btn" data-workflow-action="People & Compliance" data-workflow-id="${project.id}">Review crew</button>
        ${canAct ? `
          <button class="secondary-btn" data-beginning-action="request-docs" data-project-id="${project.id}">Request missing setup docs</button>
          <button class="secondary-btn" data-beginning-action="clear-obstacles" data-project-id="${project.id}">Mark obstacles field verified</button>
          <button class="primary-btn" data-beginning-action="ready-release" data-project-id="${project.id}">Mark ready for Admin release</button>
        ` : ""}
        ${state.role === "Admin" ? `<button class="primary-btn" data-admin-decision="approve-release" data-project-id="${project.id}">Release to field</button>` : ""}
        <button class="secondary-btn" data-workflow-action="Field Operations" data-workflow-id="${project.id}">Open Field Daily</button>
      </div>
      ${review.blockers.length ? `<p class="readiness-note">Release blockers: ${review.blockers.join(", ")}.</p>` : `<p class="readiness-note">Setup gates are clear. Admin can release this map to field.</p>`}
    </section>
  `;
}

function operationsReleasePrepRows(project) {
  const beginning = beginningPhaseReview(project);
  const release = releaseGateReview(project);
  const completion = releaseCompletionState(project);
  const handoff = releaseHandoffReadiness(project);
  const gis = fieldMapsReadiness(project);
  const accepted = acceptedFieldCaptureEvidence(project);
  const setupStep = completion.steps.find(item => item.key === "setup");
  const resourcesStep = completion.steps.find(item => item.key === "resources");
  const dailyStep = completion.steps.find(item => item.key === "daily");
  const releaseStep = completion.steps.find(item => item.key === "release");
  const row = (key, title, owner, status, detail, button) => ({ key, title, owner, status, detail, button });
  return [
    row("setup", "Setup documents", "Operations", completion.setupReady ? "Ready" : "Needs Review", setupStep?.detail || "811, permits, traffic plan, and site survey must be ready.", completion.setupReady
      ? { label: "Open files", workflow: "Documents", focus: "Map evidence" }
      : { label: "Complete setup docs", releaseAction: "complete-setup-docs" }),
    row("gis", "ArcGIS / obstruction proof", "Operations", gis.ready || accepted.rows.length ? "Ready" : gis.status || "Needs Review", gis.ready ? "Field Maps route is ready." : accepted.rows.length ? `${accepted.rows.length} accepted field capture(s) linked.` : gis.blockers.join(", ") || "Field Maps package or obstruction proof needs review.", gis.ready || accepted.rows.length
      ? { label: "Open map proof", workflow: "Documents", focus: "Map evidence" }
      : { label: "Review proof", workflow: "Project & Map Hub", focus: "Field capture review" }),
    row("resources", "Crew and equipment", "Operations", completion.resourceReady ? "Ready" : "Blocked", resourcesStep?.detail || "Crew and equipment must be staged before release.", completion.resourceReady
      ? { label: "Review assignment", workflow: "People & Compliance", focus: "Selected Map" }
      : { label: "Stage resources", releaseAction: "stage-resources" }),
    row("daily", "Foreman daily starter", "Operations", completion.dailyStarterReady ? "Ready" : "Needs Review", dailyStep?.detail || "Create the JSA/daily starter so the Foreman opens a real workflow.", completion.dailyStarterReady
      ? { label: "Open daily start", workflow: "Field Operations", focus: "Daily start" }
      : { label: "Create daily starter", releaseAction: "create-daily-starter" }),
    row("release", "Admin release", "Admin", release.released ? "Released" : release.ready ? "Ready for Release" : "Blocked", releaseStep?.detail || (release.blockers.map(item => item.label).join(", ") || "Admin release required."), release.released
      ? { label: "Verify handoff", handoffAction: "verify" }
      : release.ready
        ? { label: state.role === "Admin" ? "Release to field" : "Request Admin release", adminAction: state.role === "Admin" ? "approve-release" : "", beginningAction: state.role === "Admin" ? "" : "ready-release" }
        : { label: "Create blocker tasks", beginningAction: "ready-release" }),
    row("handoff", "Foreman can start", "Operations", handoff.startGate.clear ? "Clear" : "Blocked", handoff.startGate.clear ? "Daily start opens cleanly for the Foreman." : `Still blocked by: ${handoff.startGate.blockers.map(item => item.label).join(", ")}`, handoff.startGate.clear
      ? { label: "Open Foreman start", workflow: "Field Operations", focus: "Daily start" }
      : { label: "Create follow-ups", handoffAction: "create-followups" })
  ];
}

function renderOperationsReleasePrepButton(project, button = {}) {
  if (button.workflow) return `<button class="secondary-btn" data-workflow-action="${button.workflow}" data-workflow-id="${project.id}" data-workflow-focus="${button.focus || ""}">${button.label}</button>`;
  if (button.releaseAction) return `<button class="secondary-btn" data-release-completion-action="${button.releaseAction}" data-project-id="${project.id}">${button.label}</button>`;
  if (button.handoffAction) return `<button class="secondary-btn" data-release-handoff-action="${button.handoffAction}" data-project-id="${project.id}">${button.label}</button>`;
  if (button.adminAction) return `<button class="primary-btn" data-admin-decision="${button.adminAction}" data-project-id="${project.id}">${button.label}</button>`;
  if (button.beginningAction) return `<button class="primary-btn" data-beginning-action="${button.beginningAction}" data-project-id="${project.id}">${button.label}</button>`;
  return "";
}

function renderOperationsReleasePrep(project) {
  if (!project) return "";
  const rows = operationsReleasePrepRows(project);
  const clearStatuses = new Set(["Ready", "Released", "Clear"]);
  const next = rows.find(item => !clearStatuses.has(item.status)) || rows.at(-1);
  const readyCount = rows.filter(item => clearStatuses.has(item.status)).length;
  return `
    <section class="panel operations-release-prep">
      <div class="panel-header">
        <div>
          <h2>Release prep for ${project.map || project.id}</h2>
          <p>Use this board to move the Map from setup to a clean Foreman daily start. Work the first item that is not ready.</p>
        </div>
        <span>${readyCount}/${rows.length} ready</span>
      </div>
      <div class="operations-release-next">
        <div>
          <span class="eyebrow">Do this next</span>
          <strong>${next?.title || "Review release"}</strong>
          <small>${next?.detail || "No release detail available."}</small>
        </div>
        ${next ? renderOperationsReleasePrepButton(project, next.button) : ""}
      </div>
      <div class="operations-release-grid">
        ${rows.map(item => `
          <article class="${statusClass(item.status)}">
            <span class="status ${statusClass(item.status)}">${plainStatus(item.status)}</span>
            <div>
              <strong>${item.title}</strong>
              <small>${item.detail}</small>
              <small>Owner: ${item.owner}</small>
            </div>
            ${renderOperationsReleasePrepButton(project, item.button)}
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function releaseCompletionState(project) {
  const release = releaseGateReview(project);
  const daily = scopedRows("dailies").find(item => item.project === project.id) || {};
  const preJob = preJobGate(project, daily);
  const docs = scopedRows("documents").filter(item => item.project === project.id);
  const hasPermit = docs.some(item => item.type === "Permit" && !["Missing", "Needs Review", "Pending Review", "Pending"].includes(item.status));
  const has811 = docs.some(item => item.type === "811" && !["Missing", "Needs Review", "Pending Review", "Pending"].includes(item.status));
  const surveyReady = docs.some(item => item.type === "Site Survey" && !["Missing", "Needs Review", "Pending Review", "Pending"].includes(item.status));
  const crew = crewReadiness(project);
  const equipment = equipmentReadiness(project);
  const gis = fieldMapsReadiness(project);
  const startGate = fieldStartGate(project, daily);
  const resourceReady = crew.status === "Clear" && equipment.status === "Available";
  const setupReady = has811 && hasPermit && surveyReady;
  const dailyStarterReady = ["Draft", "Submitted"].includes(daily.status) || ["Draft", "Complete", "Submitted"].includes(daily.jsa);
  const steps = [
    { key: "setup", label: "Setup docs", status: setupReady ? "Ready" : "Needs Review", detail: `${has811 ? "811 ready" : "811 pending"}; ${hasPermit ? "permit ready" : "permit missing"}; ${surveyReady ? "survey ready" : "survey pending"}` },
    { key: "gis", label: "GIS obstruction", status: gis.ready ? "Ready" : gis.status, detail: gis.ready ? "Field Maps route is accepted for release." : gis.blockers.join(", ") },
    { key: "resources", label: "Crew / equipment", status: resourceReady ? "Ready" : "Blocked", detail: `Crew ${crew.status}; equipment ${equipment.status}` },
    { key: "daily", label: "Daily starter", status: dailyStarterReady ? "Ready" : "Needs Review", detail: dailyStarterReady ? `${daily.id || "Daily starter"} is available.` : "Create a foreman daily/JSA starter before field start." },
    { key: "release", label: "Admin release", status: release.released ? "Released" : release.ready ? "Ready for Release" : "Blocked", detail: release.released ? "Admin released the Map to field." : release.ready ? "Ready for Admin release." : release.blockers.map(item => item.label).join(", ") },
    { key: "start", label: "Foreman start", status: startGate.clear ? "Clear" : "Blocked", detail: startGate.clear ? "Foreman can start the daily workflow." : startGate.blockers.map(item => item.label).join(", ") }
  ];
  return {
    release,
    preJob,
    startGate,
    steps,
    setupReady,
    resourceReady,
    dailyStarterReady,
    ready: steps.every(item => ["Ready", "Released", "Clear"].includes(item.status))
  };
}

function releaseHandoffReadiness(project) {
  const stateRow = releaseCompletionState(project);
  const acceptedCaptures = acceptedFieldCaptureEvidence(project);
  const releaseTasks = (state.data.tasks || []).filter(task => task.project === project.id && task.status !== "Closed" && (task.source === "Release gate" || ["TASK-MAP3-SURVEY", "TASK-MAP3-811", "TASK-MAP3-SAFETY"].includes(task.id)));
  const items = [
    { key: "setup", label: "Setup documents", ok: stateRow.setupReady, detail: stateRow.steps.find(item => item.key === "setup")?.detail || "811, permit, and site survey must be ready." },
    { key: "resources", label: "Crew / equipment", ok: stateRow.resourceReady, detail: stateRow.steps.find(item => item.key === "resources")?.detail || "Crew and equipment must be staged." },
    { key: "captures", label: "Field capture evidence", ok: acceptedCaptures.rows.length > 0, detail: acceptedCaptures.rows.length ? `${acceptedCaptures.rows.length} accepted capture(s) linked to release evidence.` : "Accepted GPS photo or markup evidence is required when obstacles exist." },
    { key: "daily", label: "Foreman daily starter", ok: stateRow.dailyStarterReady, detail: stateRow.steps.find(item => item.key === "daily")?.detail || "Daily/JSA starter must exist." },
    { key: "release", label: "Admin release", ok: stateRow.release.released, detail: stateRow.release.released ? "Admin released this Map to field." : stateRow.release.ready ? "Ready for Admin release." : stateRow.release.blockers.map(item => item.label).join(", ") },
    { key: "start", label: "Pre-Check", ok: stateRow.startGate.clear, detail: stateRow.startGate.clear ? "Foreman sees a clear Pre-Check." : stateRow.startGate.blockers.map(item => item.label).join(", ") },
    { key: "tasks", label: "Release blocker tasks", ok: releaseTasks.length === 0, detail: releaseTasks.length ? `${releaseTasks.length} release blocker task(s) still open.` : "No open release blocker tasks." }
  ];
  return {
    ...stateRow,
    acceptedCaptures,
    releaseTasks,
    items,
    ready: items.every(item => item.ok),
    status: items.every(item => item.ok) ? "Handoff Ready" : stateRow.release.released ? "Released with Follow-up" : stateRow.release.ready ? "Ready for Admin Release" : "Blocked"
  };
}

function renderReleaseHandoffPanel(project) {
  const handoff = releaseHandoffReadiness(project);
  const canOps = ["Admin", "Operations"].includes(state.role);
  return `
    <div class="release-handoff-panel">
      <div class="section-heading compact">
        <div>
          <h3>Field handoff QA</h3>
          <p>Confirms the release actions produce a clean foreman daily-start screen.</p>
        </div>
        <span class="status ${statusClass(handoff.status)}">${handoff.status}</span>
      </div>
      <div class="release-handoff-grid">
        ${handoff.items.map(item => `
          <article class="${item.ok ? "ok" : "warn"}">
            <span class="status ${statusClass(item.ok ? "Ready" : "Needs Review")}">${item.ok ? "Ready" : "Needs Review"}</span>
            <strong>${item.label}</strong>
            <small>${item.detail}</small>
          </article>
        `).join("")}
      </div>
      <div class="release-handoff-next">
        <strong>Foreman next screen</strong>
        <span>${handoff.startGate.clear ? "Daily start opens with release, 811, crew, equipment, and safety gates clear." : `Daily start remains blocked by: ${handoff.startGate.blockers.map(item => item.label).join(", ")}`}</span>
        <button class="secondary-btn" data-workflow-action="Field Operations" data-workflow-id="${project.id}" data-workflow-focus="Daily start">Open Foreman Pre-Check</button>
      </div>
      ${canOps ? `
        <div class="map-preview-actions">
          <button class="secondary-btn" data-release-handoff-action="verify" data-project-id="${project.id}">Verify handoff</button>
          <button class="secondary-btn" data-release-handoff-action="create-followups" data-project-id="${project.id}">Create follow-ups</button>
        </div>
      ` : ""}
    </div>
  `;
}

function renderReleaseCompletionPanel(project) {
  const stateRow = releaseCompletionState(project);
  const canOps = ["Admin", "Operations"].includes(state.role);
  const canAdmin = state.role === "Admin";
  return `
    <div class="release-completion-panel">
      <div class="section-heading compact">
        <div>
          <h3>Release-to-field completion</h3>
          <p>Use this sequence to turn a beginning-phase Map into a field-start-ready assignment.</p>
        </div>
        <span class="status ${statusClass(stateRow.startGate.clear ? "Clear" : stateRow.release.ready ? "Ready for Release" : "Blocked")}">${stateRow.startGate.clear ? "Clear to Start" : stateRow.release.ready ? "Ready for Release" : "Blocked"}</span>
      </div>
      <div class="release-completion-grid">
        ${stateRow.steps.map((item, index) => `
          <article class="${statusClass(item.status)}">
            <span>${index + 1}</span>
            <div>
              <strong>${item.label}</strong>
              <small>${item.detail || "Review"}</small>
            </div>
            <em class="status ${statusClass(item.status)}">${item.status}</em>
          </article>
        `).join("")}
      </div>
      ${canOps ? `
        <div class="map-preview-actions">
          <button class="secondary-btn" data-release-completion-action="complete-setup-docs" data-project-id="${project.id}">Complete setup docs</button>
          <button class="secondary-btn" data-release-completion-action="stage-resources" data-project-id="${project.id}">Stage resources</button>
          <button class="secondary-btn" data-release-completion-action="create-daily-starter" data-project-id="${project.id}">Create daily starter</button>
          <button class="secondary-btn" data-beginning-action="ready-release" data-project-id="${project.id}">Request Admin release</button>
          ${canAdmin ? `<button class="primary-btn" data-admin-decision="approve-release" data-project-id="${project.id}" ${stateRow.release.ready ? "" : "disabled"}>Admin release</button>` : ""}
          <button class="secondary-btn" data-workflow-action="Field Operations" data-workflow-id="${project.id}" data-workflow-focus="Daily start">Open daily start</button>
        </div>
      ` : ""}
      ${renderReleaseHandoffPanel(project)}
    </div>
  `;
}

function renderBillingCashQueue() {
  const readiness = scopedRows("billingReadiness");
  const invoices = scopedRows("invoices");
  const retainageLedger = scopedRows("retainageLedger");
  const ready = readiness.filter(item => item.status === "Ready to Bill");
  const blocked = readiness.filter(item => item.status !== "Ready to Bill");
  const awaiting = invoices.filter(item => item.status !== "Paid");
  const paymentFollowUps = paymentFollowUpRows();
  const retainageRows = retainageReleaseRows();
  const selectedProject = scopedRows("projects").find(project => project.id === state.selectedProjectId) || scopedRows("projects")[0];
  const selectedReadiness = selectedProject ? readiness.find(item => item.project === selectedProject.id) : null;
  const focused = renderBillingFocusedDetail(selectedProject, {
    readiness,
    paymentFollowUps,
    retainageRows
  });
  return `
    ${renderBillingTodayCommand({
      ready,
      blocked,
      awaiting,
      paymentFollowUps,
      retainageRows,
      selectedReadiness,
      retainageLedger
    })}
    ${focused || `
      ${renderBillingPaymentActionQueue({ ready, blocked, paymentFollowUps, retainageRows })}
      ${renderBillingMapBillingPath(selectedProject, { selectedReadiness, paymentFollowUps, retainageRows })}
      ${renderProductionToInvoiceLedger(selectedProject)}
      ${renderBillingCloseGuardPanel(selectedProject)}
      ${renderBillingAgingBuckets({ paymentFollowUps, retainageRows })}
      ${renderBillingMapQueue(readiness, selectedProject)}
      ${renderBillingQuickTools(selectedProject)}
    `}
  `;
}

function renderBillingTodayCommand(context) {
  const ledgerRows = mapPaymentLedgerRows(scopedRows("projects"));
  const readyToInvoice = context.ready || [];
  const paymentDue = ledgerRows.filter(row => row.ledger.invoiceSent && row.ledger.unpaid90 > 0);
  const depositMissing = ledgerRows.filter(row => row.ledger.depositProofStatus === "Needs Proof");
  const heldSoon = (context.retainageRows || []).filter(row => !row.isPaid && row.daysUntilRelease !== null && row.daysUntilRelease <= 60);
  const closeReady = ledgerRows.filter(row => row.ledger.closeBillingStatus === "Ready to Close");
  const topAction = readyToInvoice[0]
    ? { label: "Build invoice", detail: `${projectLabel(readyToInvoice[0].project)} is ready to bill.`, action: "Billing", project: readyToInvoice[0].project, focus: "Invoice package" }
    : paymentDue[0]
      ? { label: "Collect 90%", detail: `${paymentDue[0].project.map || paymentDue[0].project.id}: ${currency(paymentDue[0].ledger.unpaid90)} unpaid.`, action: "Billing", project: paymentDue[0].project.id, focus: "Payment Ledger" }
      : depositMissing[0]
        ? { label: "Verify deposit", detail: `${depositMissing[0].project.map || depositMissing[0].project.id} needs bank proof verified.`, action: "Billing", project: depositMissing[0].project.id, focus: "Payment Ledger" }
        : heldSoon[0]
          ? { label: "Check 10%", detail: `${heldSoon[0].map}: release ${heldSoon[0].releaseDate || "not set"}.`, action: "Billing", project: heldSoon[0].project, focus: "10% Held Back" }
          : closeReady[0]
            ? { label: "Close billing", detail: `${closeReady[0].project.map || closeReady[0].project.id} is ready to close.`, action: "Reports", project: closeReady[0].project.id, focus: "Financial Closeout" }
            : { label: "Review ledger", detail: "No urgent billing work is due right now.", action: "Billing", project: state.selectedProjectId || ledgerRows[0]?.project.id || "", focus: "Payment Ledger" };
  return `
    <section class="panel billing-today-command">
      <div class="billing-simple-head">
        <div>
          <span class="eyebrow">Billing Today</span>
          <h2>What needs money action now?</h2>
          <p>Start with ready invoices, then unpaid 90%, deposit proof, 10% held back, and Maps ready to close billing.</p>
        </div>
        <button class="primary-btn" data-workflow-action="${topAction.action}" data-workflow-id="${topAction.project}" data-workflow-focus="${topAction.focus}" ${topAction.action === "Reports" ? `data-report-scope="Financial Closeout"` : ""}>${topAction.label}</button>
      </div>
      <div class="billing-today-grid">
        ${billingTodayCard("Ready to invoice", readyToInvoice.length, readyToInvoice[0] ? `${projectLabel(readyToInvoice[0].project)} · ${currency(readyToInvoice[0].billableAmount || 0)}` : "No invoice package waiting", "Billing", readyToInvoice[0]?.project, "Invoice package")}
        ${billingTodayCard("90% to collect", paymentDue.length, paymentDue[0] ? `${currency(paymentDue[0].ledger.unpaid90)} unpaid on ${paymentDue[0].project.map || paymentDue[0].project.id}` : "No unpaid 90% due", "Billing", paymentDue[0]?.project.id, "Payment Ledger")}
        ${billingTodayCard("Deposit proof", depositMissing.length, depositMissing[0] ? `${depositMissing[0].project.map || depositMissing[0].project.id} needs proof` : "Deposit proof clear", "Billing", depositMissing[0]?.project.id, "Payment Ledger")}
        ${billingTodayCard("10% held back", heldSoon.length, heldSoon[0] ? `${currency(heldSoon[0].heldAmount)} · release ${heldSoon[0].releaseDate || "not set"}` : "No release due soon", "Billing", heldSoon[0]?.project, "10% Held Back")}
        ${billingTodayCard("Close billing", closeReady.length, closeReady[0] ? `${closeReady[0].project.map || closeReady[0].project.id} is ready` : "No Map ready to close", "Reports", closeReady[0]?.project.id, "Financial Closeout")}
      </div>
      <p class="readiness-note">Next best action: ${topAction.detail}</p>
    </section>
  `;
}

function billingTodayCard(title, count, detail, action, projectId, focus) {
  return `
    <button class="billing-today-card" data-workflow-action="${action}" data-workflow-id="${projectId || state.selectedProjectId || ""}" data-workflow-focus="${focus}" ${action === "Reports" ? `data-report-scope="Financial Closeout"` : ""}>
      <span>${title}</span>
      <strong>${count}</strong>
      <small>${detail}</small>
    </button>
  `;
}

function renderBillingCanWeBillHome(project, context) {
  const invoice = scopedRows("invoices").find(item => item.project === project?.id);
  const submission = scopedRows("invoiceSubmissions").find(item => item.project === project?.id || item.invoice === invoice?.id);
  const retainage = scopedRows("retainageLedger").find(item => item.project === project?.id || item.invoice === invoice?.id);
  const readiness = context.selectedReadiness;
  const packageGate = project ? billingPackageBuildGate(project) : { status: "Pending", ready: false, blockers: [] };
  const submissionGate = project ? billingSubmissionGate(project) : { status: "Pending", ready: false };
  const arRow = project ? postSubmissionArRows(scopedRows("projects")).find(item => item.project.id === project.id) : null;
  const canBill = readiness?.status === "Ready to Bill" || packageGate.ready || Boolean(invoice);
  return `
    <section class="panel billing-simple-home">
      <div class="billing-simple-head">
        <div>
          <span class="eyebrow">Billing</span>
          <h2>${project ? `Can we bill ${project.map || project.id}?` : "Select a Map to bill"}</h2>
          <p>Billing starts with accepted proof, then builds the SQUAN package, records what was sent, collects 90%, and tracks the 10% held back.</p>
        </div>
        <span class="status ${statusClass(canBill ? "Ready" : readiness?.status || packageGate.status || "Pending")}">${plainStatus(canBill ? "Ready" : readiness?.status || packageGate.status || "Pending")}</span>
      </div>
      <div class="billing-status-strip">
        <article><span>Proof</span><strong>${plainStatus(readiness?.status || "Not Ready")}</strong><small>${readiness?.missingItems || "No ready-to-bill record"}</small></article>
        <article><span>Billing package</span><strong>${plainStatus(packageGate.status)}</strong><small>${packageGate.ready ? "Billing package can be built." : (packageGate.blockers || []).map(item => item.label).join(", ") || "Waiting on proof."}</small></article>
        <article><span>Sent to SQUAN</span><strong>${plainStatus(submission?.status || submissionGate.status)}</strong><small>${submission ? submission.confirmationNumber || submission.invoiceNumber || "Receipt recorded" : "Not sent to SQUAN"}</small></article>
        <article><span>Payment ledger</span><strong>${plainStatus(arRow?.status || retainage?.status || "Pending")}</strong><small>${arRow ? `${currency(arRow.open90)} unpaid 90%` : retainage ? `${currency(retainage.heldAmount || 0)} 10% held back` : "No unpaid invoice record yet"}</small></article>
      </div>
    </section>
  `;
}

function renderBillingMapBillingPath(project, context) {
  if (!project) return "";
  const invoice = scopedRows("invoices").find(item => item.project === project.id);
  const submission = scopedRows("invoiceSubmissions").find(item => item.project === project.id || item.invoice === invoice?.id);
  const retainage = scopedRows("retainageLedger").find(item => item.project === project.id || item.invoice === invoice?.id);
  const readiness = context.selectedReadiness;
  const packageGate = billingPackageBuildGate(project);
  const submissionGate = billingSubmissionGate(project);
  const ledgerRow = mapPaymentLedgerRows(scopedRows("projects")).find(item => item.project.id === project.id);
  const paymentReceipt = ledgerRow?.receipts.find(receipt => receipt.type !== "Retainage");
  const closeGate = mapFinancialCloseoutGate(project);
  const steps = [
    { number: "1", title: "Build invoice package", detail: packageGate.ready ? "Proof is accepted. Build the SQUAN package." : (packageGate.blockers || []).map(item => item.label).join(", ") || "Accepted proof is needed first.", status: packageGate.status, action: "Billing", focus: "Invoice package" },
    { number: "2", title: "Send to SQUAN", detail: submission ? `${submission.invoiceNumber || submission.invoice || "Invoice"} sent.` : "Send only after package gates are clear.", status: submission ? "Submitted" : submissionGate.status, action: "Billing", focus: "SQUAN submission" },
    { number: "3", title: "Record SQUAN receipt", detail: ledgerRow?.confirmation || "Record portal/email confirmation.", status: ledgerRow?.confirmation ? "Complete" : submission ? "Needs Receipt" : "Pending", action: "Billing", focus: "SQUAN contacts" },
    { number: "4", title: "Collect 90%", detail: ledgerRow ? `${currency(ledgerRow.ledger.unpaid90)} unpaid of ${currency(ledgerRow.ledger.expected90)} expected.` : "Record payment or follow-up date.", status: ledgerRow?.ledger.unpaid90 > 0 ? "Open" : ledgerRow?.ledger.received90 > 0 ? "Complete" : invoice?.status || "Pending", action: "Billing", focus: "Payment Ledger" },
    { number: "5", title: "Verify deposit", detail: paymentReceipt ? `${paymentReceipt.bankProof || "Proof missing"}; ${paymentReceipt.depositStatus || "pending"}.` : "Attach bank proof after payment is recorded.", status: ledgerRow?.ledger.depositProofStatus || "Pending", action: "Billing", focus: "Payment Ledger" },
    { number: "6", title: "Track 10%", detail: retainage ? `${currency(retainage.heldAmount || 0)} held; release ${retainage.releaseDate || "not set"}.` : "Create or track held-back money record.", status: retainage?.status || "Pending", action: "Billing", focus: "10% Held Back" },
    { number: "7", title: "Close billing", detail: closeGate.ready ? "All payment gates clear." : closeGate.blockers.map(item => item.label).join(", ") || "Close guard needs review.", status: ledgerRow?.ledger.closeBillingStatus || "Open", action: "Reports", focus: "Financial Closeout" }
  ];
  return `
    <section class="panel billing-simple-path">
      <div class="panel-header">
        <div>
          <h2>Bill SQUAN</h2>
          <p>Every Map follows the same payment path from invoice package to closed billing.</p>
        </div>
        <span>${project.map || project.id}</span>
      </div>
      <div class="billing-step-grid">
        ${steps.map(step => `
          <button class="billing-step-card ${statusClass(step.status)}" data-workflow-action="${step.action}" data-workflow-id="${project.id}" data-workflow-focus="${step.focus}">
            <span>${step.number}</span>
            <strong>${step.title}</strong>
            <small>${step.detail}</small>
            <em>${plainStatus(step.status)}</em>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function renderBillingPaymentActionQueue(context) {
  const ledgerRows = mapPaymentLedgerRows(scopedRows("projects"));
  const readyRows = (context.ready || []).map(item => ({
    title: "Build invoice package",
    detail: `${projectLabel(item.project)} · ${currency(item.billableAmount || 0)} billable.`,
    status: "Ready",
    project: item.project,
    action: "Billing",
    focus: "Invoice package",
    label: "Build"
  }));
  const receiptRows = ledgerRows.filter(row => row.ledger.invoiceSent && !row.confirmation).map(row => ({
    title: "Record SQUAN receipt",
    detail: `${row.project.map || row.project.id} was sent but receipt is missing.`,
    status: "Needs Receipt",
    project: row.project.id,
    action: "Billing",
    focus: "SQUAN contacts",
    label: "Record receipt"
  }));
  const paymentRows = ledgerRows.filter(row => row.ledger.unpaid90 > 0).map(row => ({
    title: "Collect 90%",
    detail: `${row.project.map || row.project.id} · ${currency(row.ledger.unpaid90)} unpaid.`,
    status: row.followUpDays !== null && row.followUpDays < 0 ? "Overdue" : "Open",
    project: row.project.id,
    action: "Billing",
    focus: "Payment Ledger",
    label: "Payment detail"
  }));
  const proofRows = ledgerRows.filter(row => row.ledger.depositProofStatus === "Needs Proof").map(row => ({
    title: "Verify deposit proof",
    detail: `${row.project.map || row.project.id} payment is recorded but proof is not verified.`,
    status: "Needs Proof",
    project: row.project.id,
    action: "Billing",
    focus: "Payment Ledger",
    label: "Verify"
  }));
  const retainageRows = (context.retainageRows || []).filter(row => !row.isPaid && row.daysUntilRelease !== null && row.daysUntilRelease <= 60).map(row => ({
    title: "Track 10% held back",
    detail: `${row.map} · ${currency(row.heldAmount)} held; release ${row.releaseDate || "not set"}.`,
    status: row.status,
    project: row.project,
    action: "Billing",
    focus: "10% Held Back",
    label: "Track 10%"
  }));
  const closeRows = ledgerRows.filter(row => row.ledger.closeBillingStatus === "Ready to Close").map(row => ({
    title: "Close billing",
    detail: `${row.project.map || row.project.id} has payment gates clear.`,
    status: "Ready",
    project: row.project.id,
    action: "Reports",
    focus: "Financial Closeout",
    label: "Close"
  }));
  const groups = [
    ["Invoice work", [...readyRows, ...receiptRows]],
    ["Payment work", [...paymentRows, ...proofRows]],
    ["10% and close", [...retainageRows, ...closeRows]]
  ].filter(([, rows]) => rows.length);
  return `
    <section class="panel billing-payment-actions">
      <div class="panel-header">
        <div>
          <h2>Work to do</h2>
          <p>These are the billing actions that need attention before reviewing record tables.</p>
        </div>
        <span>${groups.reduce((total, [, rows]) => total + rows.length, 0)} item(s)</span>
      </div>
      <div class="billing-payment-groups">
        ${groups.map(([title, rows]) => `
          <article>
            <div class="card-topline">
              <h3>${title}</h3>
              <span>${rows.length}</span>
            </div>
            <div class="billing-action-list">
              ${rows.slice(0, 5).map(row => `
                <button data-workflow-action="${row.action}" data-workflow-id="${row.project}" data-workflow-focus="${row.focus}" ${row.action === "Reports" ? `data-report-scope="Financial Closeout"` : ""}>
                  <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
                  <strong>${row.title}</strong>
                  <small>${row.detail}</small>
                  <em>${row.label}</em>
                </button>
              `).join("")}
            </div>
          </article>
        `).join("") || `<p class="empty-state">No billing action is due right now.</p>`}
      </div>
    </section>
  `;
}

function renderBillingCloseGuardPanel(project) {
  if (!project) return "";
  const row = mapPaymentLedgerRows(scopedRows("projects")).find(item => item.project.id === project.id);
  const gate = mapFinancialCloseoutGate(project);
  const guardItems = [
    { label: "Invoice sent", ok: row?.ledger.invoiceSent, detail: row?.ledger.invoiceSentLabel || "No SQUAN invoice submission." },
    { label: "SQUAN receipt", ok: Boolean(row?.confirmation), detail: row?.confirmation || "Receipt confirmation missing." },
    { label: "90% payment", ok: row ? row.ledger.unpaid90 <= 0 || project.adminApprovals?.exception : false, detail: row ? `${currency(row.ledger.unpaid90)} unpaid.` : "No payment ledger row." },
    { label: "Deposit proof", ok: row?.ledger.depositProofStatus === "Verified" || row?.receipts.length === 0 && !row?.ledger.received90, detail: row?.ledger.depositProofLabel || "No deposit proof." },
    { label: "10% status", ok: Boolean(row?.retainage) || project.adminApprovals?.exception, detail: row?.retainage ? `${currency(row.ledger.held10)} held; ${row.ledger.heldStatus}.` : "No 10% held-back record." },
    { label: "Open billing tasks", ok: !row?.openTasks.length, detail: `${row?.openTasks.length || 0} open task(s).` },
    { label: "Evidence / QC", ok: gate.items.filter(item => ["documents", "qc", "safety"].includes(item.key)).every(item => item.ok), detail: gate.blockers.map(item => item.label).join(", ") || "Evidence gates clear." }
  ];
  return `
    <section class="panel billing-close-guard">
      <div class="panel-header">
        <div>
          <h2>Can we close billing?</h2>
          <p>Close billing only when payment, proof, 10%, tasks, and evidence gates are clear or approved by exception.</p>
        </div>
        <span class="status ${statusClass(gate.ready ? "Ready" : "Needs Review")}">${gate.ready ? "Ready" : `${guardItems.filter(item => !item.ok).length} open`}</span>
      </div>
      <div class="billing-guard-grid">
        ${guardItems.map(item => `
          <article class="${item.ok ? "ok" : "warn"}">
            <span class="status ${statusClass(item.ok ? "Ready" : "Needs Review")}">${item.ok ? "Ready" : "Needs check"}</span>
            <strong>${item.label}</strong>
            <small>${item.detail}</small>
          </article>
        `).join("")}
      </div>
      <div class="invoice-actions">
        <button class="secondary-btn" data-post-submission-ar-detail="${project.id}">Payment detail</button>
        <button class="secondary-btn" data-workflow-action="Reports" data-workflow-id="${project.id}" data-report-scope="Financial Closeout">Closeout packet</button>
        ${gate.ready ? `<button class="primary-btn" data-admin-decision="close-map" data-project-id="${project.id}">Close billing</button>` : `<button class="secondary-btn" data-workflow-action="Tasks" data-workflow-id="${project.id}">Open tasks</button>`}
      </div>
    </section>
  `;
}

function billingDueBucketRows(paymentFollowUps = [], retainageRows = []) {
  const paymentRows = paymentFollowUps.filter(item => !item.paid90Complete && item.open90 > 0).map(item => ({
    project: item.project,
    map: item.map,
    label: "90% payment",
    amount: item.open90,
    dueDate: item.followUpDate,
    days: item.daysUntilFollowUp,
    status: item.status,
    detail: item.detail,
    focus: "Payment Ledger"
  }));
  const heldRows = retainageRows.filter(item => !item.isPaid).map(item => ({
    project: item.project,
    map: item.map,
    label: "10% held back",
    amount: item.heldAmount,
    dueDate: item.followUpDate || item.releaseDate,
    days: item.daysUntilFollowUp ?? item.daysUntilRelease,
    status: item.status,
    detail: item.paymentNote,
    focus: "10% Held Back"
  }));
  const rows = [...paymentRows, ...heldRows];
  return [
    ["Due now", rows.filter(row => row.days !== null && row.days <= 0 && !/pay-when-paid|disputed|short-paid|chargeback/i.test(row.status))],
    ["1-7 days", rows.filter(row => row.days !== null && row.days > 0 && row.days <= 7)],
    ["8-30 days", rows.filter(row => row.days !== null && row.days > 7 && row.days <= 30)],
    ["Over 30 days", rows.filter(row => row.days === null || row.days > 30)],
    ["Pay-when-paid / disputed", rows.filter(row => /pay-when-paid|disputed|short-paid|chargeback/i.test(row.status))]
  ];
}

function renderBillingAgingBuckets({ paymentFollowUps = [], retainageRows = [] } = {}) {
  const buckets = billingDueBucketRows(paymentFollowUps, retainageRows);
  const total = buckets.reduce((sumValue, [, rows]) => sumValue + sum(rows, "amount"), 0);
  return `
    <section class="panel billing-aging-buckets">
      <div class="panel-header">
        <div>
          <h2>Payment timing</h2>
          <p>Simple buckets for unpaid 90%, 10% held back, pay-when-paid holds, and disputes.</p>
        </div>
        <span>${currency(total)} open</span>
      </div>
      <div class="billing-aging-grid">
        ${buckets.map(([title, rows]) => `
          <article>
            <div class="card-topline">
              <h3>${title}</h3>
              <span>${currency(sum(rows, "amount"))}</span>
            </div>
            ${rows.slice(0, 4).map(row => `
              <button data-workflow-action="Billing" data-workflow-id="${row.project}" data-workflow-focus="${row.focus}">
                <strong>${row.map}</strong>
                <small>${row.label} · ${currency(row.amount)} · ${row.dueDate || "no date"} · ${plainStatus(row.status)}</small>
              </button>
            `).join("") || `<p class="empty-state">No items.</p>`}
          </article>
        `).join("")}
      </div>
    </section>
  `;
}


function renderBillingMapQueue(readiness, selectedProject) {
  const rows = readiness.slice().sort((a, b) => {
    const priority = { "Ready to Bill": 0, Blocked: 1, "3 Days Left": 2, "7 Days Left": 3, "Not Ready": 4 };
    return (priority[a.status] ?? 5) - (priority[b.status] ?? 5);
  });
  return `
    <section class="panel billing-map-queue">
      <div class="panel-header">
        <div>
          <h2>Maps to bill</h2>
          <p>Select a Map, then answer: proof accepted, billing package built, sent, paid, and held-back money tracked.</p>
        </div>
        <span>${rows.length} Map(s)</span>
      </div>
      <div class="billing-map-list">
        ${rows.map(row => `
          <button class="${row.project === selectedProject?.id ? "selected" : ""}" data-workflow-action="Billing" data-workflow-id="${row.project}" data-workflow-focus="Invoice package">
            <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
            <strong>${projectLabel(row.project)}</strong>
            <small>${currency(row.billableAmount || 0)} billable; missing ${row.missingItems || "None"}</small>
          </button>
        `).join("") || `<p class="empty-state">No billing readiness records are visible.</p>`}
      </div>
    </section>
  `;
}

function renderBillingQuickTools(project) {
  const tools = [
    ["Check proof", "Accepted, missing, rejected, and fixed support", "Documents", "Map evidence"],
    ["Build package", "Dailies, SOT, photos, as-builts, QC, invoice", "Billing", "Invoice package"],
    ["SQUAN contact log", "PM/AP notes, receipt, response, disputes", "Billing", "SQUAN contacts"],
    ["Payment ledger", "90% payment, promise dates, pay-when-paid holds", "Billing", "Payment Ledger"],
    ["Money held back", "10% held-back money and follow-up", "Billing", "10% Held Back"],
    ["Cash tools", "13-week cash, collections, dispute controls", "Billing", "Cash forecast"]
  ];
  return `
    <section class="panel billing-tools-panel">
      <div class="panel-header">
        <div>
          <h2>Billing tools</h2>
          <p>Use these when the billing steps point you to details.</p>
        </div>
        <span>${project?.map || project?.id || "No Map"}</span>
      </div>
      <div class="billing-tool-grid">
        ${tools.map(([title, detail, action, focus]) => `
          <button class="billing-tool-card" data-workflow-action="${action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${focus}">
            <strong>${title}</strong>
            <small>${detail}</small>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function renderBillingWorkflowCommandCenter(project, context) {
  const invoice = scopedRows("invoices").find(item => item.project === project?.id);
  const submission = scopedRows("invoiceSubmissions").find(item => item.project === project?.id || item.invoice === invoice?.id);
  const retainage = scopedRows("retainageLedger").find(item => item.project === project?.id || item.invoice === invoice?.id);
  const packageGate = project ? billingPackageBuildGate(project) : { status: "Pending", ready: false };
  const latestDailyPackage = project ? latestDailyEvidencePackage(project) : null;
  const submissionGate = project ? billingSubmissionGate(project) : { status: "Pending", ready: false };
  const arRow = project ? postSubmissionArRows(scopedRows("projects")).find(item => item.project.id === project.id) : null;
  const financialPacket = project ? financialCloseoutPacketLockState(project) : { label: "Pending", status: "Pending" };
  const steps = [
    ["1", "Ready-to-bill", context.selectedReadiness?.status || "Not Ready", context.selectedReadiness?.missingItems || "Billing readiness has not started.", "Documents", "Map evidence"],
    ["2", "Daily package intake", latestDailyPackage?.qa.status || "Missing", latestDailyPackage ? `${latestDailyPackage.qa.packageId}; ${latestDailyPackage.qa.ready ? "QA ready for billing." : `${latestDailyPackage.missing.length} item(s) need review.`}` : "No submitted daily evidence package has reached Billing.", "Billing", "Daily packages"],
    ["3", "Packet build", packageGate.status, packageGate.ready ? "Invoice package can be prepared." : (packageGate.blockers || []).map(item => item.label).join(", "), "Billing", "Invoice package"],
    ["4", "SQUAN submission", submission ? submission.status || "Submitted" : submissionGate.status, submission ? `${submission.invoiceNumber || submission.invoice || "Invoice"} submitted ${submission.submissionDate || "date not recorded"}.` : "Submit only after packet gates are clear.", "Billing", "SQUAN submission"],
    ["5", "90% Payment", arRow ? arRow.status : invoice?.status || "Pending", arRow ? `${currency(arRow.open90)} unpaid 90%.` : "Record SQUAN receipt, response, and 90% payment.", "Billing", "Payment Ledger"],
    ["6", "10% Held Back", retainage?.status || "Pending", retainage ? `${currency(retainage.heldAmount || 0)} held; release ${retainage.releaseDate || "not set"}.` : "Create/track 10% held-back money record.", "Billing", "10% Held Back"],
    ["7", "Unpaid follow-up", arRow?.openTasks?.length ? "Open" : "Tracked", arRow?.openTasks?.length ? `${arRow.openTasks.length} follow-up task(s).` : "No open payment follow-up tasks.", "Billing", "Unpaid follow-up"],
    ["8", "Close Billing", financialPacket.label, financialPacket.detail || "Close final audit packet after cash and 10% held-back money are resolved.", "Reports", "Financial Closeout"]
  ];
  return `
    <section class="panel billing-command-center">
      <div class="panel-header">
        <div>
          <h2>Map Payment Ledger</h2>
          <p>Work left to right: accepted proof, invoice packet, SQUAN receipt, 90% payment, 10% held back, unpaid follow-up, then close billing.</p>
        </div>
        <span>${project?.map || project?.id || "No Map selected"}</span>
      </div>
      <div class="field-mobile-steps billing-workflow-steps">
        ${steps.map(step => `
          <button class="field-mobile-step ${statusClass(step[2])}" data-workflow-action="${step[4]}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${step[5]}" ${step[4] === "Reports" ? `data-report-scope="Financial Closeout"` : ""}>
            <span>${step[0]}</span>
            <strong>${step[1]}</strong>
            <small>${step[3] || "Review"}</small>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function renderBillingPriorityActionQueue(context) {
  const dailyPackageRows = scopedRows("projects")
    .map(project => ({ project, latest: latestDailyEvidencePackage(project) }))
    .filter(row => row.latest && !row.latest.qa.ready)
    .slice(0, 4)
    .map(row => ({
      id: `daily-package-${row.latest.qa.packageId}`,
      title: "Daily package needs billing intake",
      detail: `${row.project.map || row.project.id}: ${row.latest.qa.packageId}; missing ${row.latest.missing.join(", ") || "QA acceptance"}.`,
      status: row.latest.qa.status,
      project: row.project.id,
      action: "Billing",
      focus: "Daily packages",
      label: "Review intake"
    }));
  const blockedRows = context.blocked.slice(0, 4).map(item => ({
      id: `blocked-${item.project}`,
      title: "Proof blocking invoice",
      detail: `${item.project}: ${item.missingItems || "Missing support"}; deadline ${item.billingDeadline || "N/A"}.`,
      status: item.status,
      project: item.project,
      action: "Documents",
      focus: "Map evidence",
      label: "Check proof"
    }));
  const readyRows = context.ready.slice(0, 4).map(item => ({
      id: `ready-${item.project}`,
      title: "Ready to build invoice",
      detail: `${item.project}: ${currency(item.billableAmount || 0)} billable; deadline ${item.billingDeadline || "N/A"}.`,
      status: "Ready",
      project: item.project,
      action: "Billing",
      focus: "Invoice package",
      label: "Build package"
    }));
  const unpaidRows = context.paymentFollowUps.filter(item => item.daysUntilFollowUp !== null && item.daysUntilFollowUp <= 7 && !item.paid90Complete).slice(0, 4).map(item => ({
      id: `ar-${item.id}`,
      title: "SQUAN payment follow-up",
      detail: `${item.map || item.project}: ${currency(Math.max(0, item.expected90 - item.paid90))} open; follow-up ${item.followUpDate || "not set"}.`,
      status: item.riskStatus || "Needs Review",
      project: item.project,
      action: "Billing",
      focus: "Payment Ledger",
      label: "Follow up"
    }));
  const heldRows = context.retainageRows.filter(item => !item.isPaid && item.daysUntilFollowUp !== null && item.daysUntilFollowUp <= 60).slice(0, 4).map(item => ({
      id: `ret-${item.id}`,
      title: "Money held back follow-up",
      detail: `${item.map || item.project}: ${currency(item.heldAmount || 0)} held; follow-up ${item.followUpDate || item.releaseDate || "not set"}.`,
      status: item.status || "Open",
      project: item.project,
      action: "Billing",
      focus: "10% Held Back",
      label: "Track money"
    }));
  const groups = [
    ["Fix proof first", [...dailyPackageRows, ...blockedRows].slice(0, 8)],
    ["Build billing packages", readyRows],
    ["Follow unpaid money", [...unpaidRows, ...heldRows].slice(0, 8)]
  ].filter(([, rows]) => rows.length);
  const count = groups.reduce((total, [, rows]) => total + rows.length, 0);
  return `
    <section class="panel billing-priority-actions">
      <div class="panel-header">
        <div>
          <h2>Billing Work</h2>
          <p>Fix proof first, then build billing packages, then follow unpaid and held-back money.</p>
        </div>
        <span>${count} item(s)</span>
      </div>
      ${groups.map(([title, rows]) => renderBillingWorkGroup(title, rows)).join("") || `<p class="empty-state">No priority billing action is currently due.</p>`}
    </section>
  `;
}

function renderBillingWorkGroup(title, rows) {
  return `
    <div class="proof-checklist-group billing-work-group">
      <div class="proof-group-title"><h3>${title}</h3><span>${rows.length}</span></div>
      <div class="proof-checklist">
        ${rows.map(row => `
          <article class="proof-row">
            <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
            <div>
              <strong>${row.title}</strong>
              <small>${row.detail}</small>
            </div>
            <div class="proof-row-actions">
              <button class="secondary-btn" data-workflow-action="${row.action}" data-workflow-id="${row.project || ""}" data-workflow-focus="${row.focus}">${row.label}</button>
            </div>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

function renderBillingWorkflowDrillIns(project) {
  const cards = [
    ["Readiness Matrix", "All Maps and support blockers", "Billing", "Billing readiness"],
    ["Daily Packages", "Submitted field daily packages feeding invoice readiness", "Billing", "Daily packages"],
    ["Cash Forecast", "13-week cash and pay-when-paid exposure", "Billing", "Cash forecast"],
    ["Payment Ledger", "SQUAN receipt, 90%, response, disputes", "Billing", "Payment Ledger"],
    ["10% Held Back", "Release queue and 10% ledger", "Billing", "10% Held Back"],
    ["Unpaid Follow-Up", "Follow-ups, promises, write-offs, disputes", "Billing", "Unpaid follow-up"],
    ["Close Billing", "Final lock, receipt, and audit handoff", "Reports", "Financial Closeout"]
  ];
  return `
    <section class="panel billing-drillins">
      <div class="panel-header">
        <div>
          <h2>Open detailed billing tools</h2>
          <p>Use these when the command center says a specific area needs work.</p>
        </div>
        <span>${project?.map || project?.id || "All Maps"}</span>
      </div>
      <div class="linked-records">
        ${cards.map(([title, detail, action, focus]) => `
          <button class="linked-count" data-workflow-action="${action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${focus}" ${action === "Reports" ? `data-report-scope="Financial Closeout"` : ""}>
            <strong>${title}</strong>
            <span>${detail}</span>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function renderBillingFocusedDetail(project, context = {}) {
  if (!project || !state.workflowFocus) return "";
  const focus = String(state.workflowFocus).toLowerCase();
  const includesAny = (...terms) => terms.some(term => focus.includes(term));
  if (includesAny("readiness", "support blocker")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderBillingReadinessMatrix()}
    `;
  }
  if (includesAny("daily package", "daily packages", "daily intake", "field package", "evidence package")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderBillingDailyPackageIntake(project)}
      ${renderDailyToBillingHandoff(project)}
    `;
  }
  if (includesAny("cash forecast", "cash")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderCashForecastPanel({ compact: false })}
    `;
  }
  if (includesAny("ar", "payment", "90%")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderCustomerContactLog(project)}
      ${renderPostSubmissionArDashboard(scopedRows("projects"))}
      ${renderArAgingPanel()}
      ${renderPaymentFollowUpQueue(context.paymentFollowUps || paymentFollowUpRows(), { compact: false })}
    `;
  }
  if (includesAny("retainage", "held back", "10% held")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderRetainageReleaseQueue(context.retainageRows || retainageReleaseRows(), { compact: false })}
      ${renderRetainageLifecyclePanel(project)}
      ${renderPacketLockNotice(project, "Retainage and final payment records")}
    `;
  }
  if (includesAny("collection", "dispute", "unpaid follow-up")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderCollectionsResponseDashboard({ compact: false })}
      ${renderBillingEvidenceCorrectionWorkbench()}
    `;
  }
  if (includesAny("evidence", "documents")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderDailyToBillingHandoff(project)}
      ${renderBillingMapEvidenceInbox(project)}
      ${renderBillingEvidenceCorrectionWorkbench()}
    `;
  }
  if (includesAny("submission", "squan")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderCustomerContactLog(project)}
      ${renderSquanSubmissionRecord(project)}
      ${renderPaymentFollowUpQueue(context.paymentFollowUps || paymentFollowUpRows(), { compact: true })}
      ${renderPacketLockNotice(project, "SQUAN submission records")}
    `;
  }
  if (includesAny("invoice", "package", "packet")) {
    return `
      ${workflowFocusPanel(project, "Billing")}
      ${renderDailyToBillingHandoff(project)}
      ${renderBillingMapEvidenceInbox(project)}
      ${renderProductionToInvoiceLedger(project)}
      ${renderInvoicePackageBuilder(project)}
      ${renderCustomerContactLog(project)}
      ${renderPacketLockNotice(project, "Billing and SQUAN submission records")}
    `;
  }
  return "";
}

function renderBillingSelectedMapLane(project) {
  if (!project) return "";
  return `
    <section class="panel billing-selected-map-lane">
      <div class="panel-header">
        <div>
          <h2>Selected Map billing lane</h2>
      <p>Start here for the selected Map. Use the drill-ins above for payment, 10% held-back money, cash, and follow-up views.</p>
        </div>
        <span>${project.map || project.id}</span>
      </div>
    </section>
    ${renderDailyToBillingHandoff(project)}
    ${renderBillingDailyPackageIntake(project)}
    ${renderBillingMapEvidenceInbox(project)}
    ${renderProductionToInvoiceLedger(project)}
    ${renderInvoicePackageBuilder(project)}
    ${renderCustomerContactLog(project)}
    ${renderSquanSubmissionRecord(project)}
    ${renderPacketLockNotice(project, "Billing and SQUAN submission records")}
  `;
}

function paymentFollowUpRows() {
  const submissions = scopedRows("invoiceSubmissions");
  const invoices = scopedRows("invoices");
  return submissions.map(submission => {
    const invoice = invoices.find(item => item.id === submission.invoice || item.project === submission.project) || {};
    const followUpDate = submission.followUpDate || submission.receipt?.followUpDate || "";
    const days = daysUntil(followUpDate);
    const expected90 = Number(submission.expected90 || invoice.gross * 0.9 || 0);
    const paid90 = Number(invoice.paid90 || 0);
    const paid90Complete = paid90 >= expected90 && expected90 > 0;
    const statusText = String(invoice.status || submission.status || "");
    const riskStatus = statusText.includes("Pay-when-paid")
      ? "Pay-when-paid hold"
      : ["Disputed", "Short-paid", "Chargeback received", "Rejected by SQUAN"].includes(statusText)
        ? statusText
        : paid90Complete
          ? "Paid 90% / Retainage Held"
          : days !== null && days < 0
            ? "Past Due"
            : days !== null && days <= 7
              ? "Needs Review"
              : "Monitor";
    return {
      id: submission.id,
      project: submission.project,
      map: projectLabel(submission.project),
      invoice: invoice.id || submission.invoiceNumber || submission.invoice,
      status: riskStatus,
      invoiceStatus: invoice.status || submission.status,
      followUpDate,
      daysUntilFollowUp: days,
      expected90,
      paid90,
      open90: Math.max(0, expected90 - paid90),
      retainage: Number(submission.retainage10 || invoice.retainage10 || 0),
      confirmation: submission.confirmationNumber || submission.receipt?.confirmationNumber || "No receipt",
      contact: submission.squanBillingContact || submission.receipt?.receivedBy || "SQUAN PM / AP",
      method: submission.deliveryMethod || submission.receipt?.method || "SQUAN billing portal / email",
      paid90Complete,
      detail: paid90Complete ? `90% received; retainage ${currency(submission.retainage10 || invoice.retainage10 || 0)} remains.` : `${currency(Math.max(0, expected90 - paid90))} open against expected 90%; follow-up ${followUpDate || "not scheduled"}.`
    };
  }).sort((a, b) => {
    const aDays = a.daysUntilFollowUp ?? 999;
    const bDays = b.daysUntilFollowUp ?? 999;
    if (a.paid90Complete !== b.paid90Complete) return a.paid90Complete ? 1 : -1;
    return aDays - bDays;
  });
}

function collectionResponseRows() {
  return (state.data.collectionSubmissions || []).map(item => {
    const followUpDays = daysUntil(item.nextFollowUpDate);
    const promisedDays = daysUntil(item.promisedPaymentDate);
    const hasResponse = Boolean(item.responseStatus || item.responseAt || item.promisedPaymentDate || item.disputeOutcome);
    const status = item.status === "Closed"
      ? "Closed"
      : item.writeOffStatus === "Approved"
        ? "Written Off"
        : item.writeOffStatus
          ? "Write-off Review"
          : item.escalationStatus
            ? "Dispute Escalated"
            : item.cashReceiptId || item.cashStatus === "Received"
              ? "Cash Received"
              : item.disputeOutcome
                ? "Disputed"
                : item.promisedPaymentDate
                  ? promisedDays !== null && promisedDays < 0 ? "Promised Past Due" : "Payment Promised"
                  : !hasResponse && followUpDays !== null && followUpDays < 0
                    ? "Overdue"
                    : !hasResponse
                      ? "Pending Response"
                      : item.nextFollowUpDate
                        ? "Follow-up Scheduled"
                        : "Response Received";
    return {
      ...item,
      map: item.map || projectLabel(item.project),
      followUpDays,
      promisedDays,
      status,
      closeReady: ["Cash Received", "Response Received", "Payment Promised", "Disputed", "Written Off"].includes(status) && Boolean(item.cashReceiptId || item.responseStatus || item.promisedPaymentDate || item.disputeOutcome || item.writeOffStatus === "Approved")
    };
  }).sort((a, b) => {
    const rank = { Overdue: 0, "Dispute Escalated": 1, Disputed: 2, "Write-off Review": 3, "Promised Past Due": 4, "Pending Response": 5, "Payment Promised": 6, "Follow-up Scheduled": 7, "Response Received": 8, "Cash Received": 9, "Written Off": 10, Closed: 11 };
    return (rank[a.status] ?? 9) - (rank[b.status] ?? 9) || String(a.nextFollowUpDate || "").localeCompare(String(b.nextFollowUpDate || ""));
  });
}

function renderCollectionsResponseDashboard({ compact = false } = {}) {
  const rows = collectionResponseRows();
  const visibleRows = compact ? rows.slice(0, 4) : rows;
  const overdue = rows.filter(item => item.status === "Overdue" || item.status === "Promised Past Due");
  const pending = rows.filter(item => item.status === "Pending Response");
  const promised = rows.filter(item => item.status === "Payment Promised");
  const disputed = rows.filter(item => item.status === "Disputed");
  const escalated = rows.filter(item => item.status === "Dispute Escalated");
  const writeOffReview = rows.filter(item => item.status === "Write-off Review");
  const closeReady = rows.filter(item => item.closeReady);
  const groups = [
    ["Needs follow-up", visibleRows.filter(item => ["Overdue", "Promised Past Due", "Pending Response"].includes(item.status))],
    ["Dispute or owner decision", visibleRows.filter(item => ["Disputed", "Dispute Escalated", "Write-off Review"].includes(item.status))],
    ["Ready to close", visibleRows.filter(item => item.closeReady)]
  ].filter(([, groupRows]) => groupRows.length);
  if (compact && !rows.length) return "";
  return `
    <section class="panel collections-response-dashboard">
      <div class="panel-header">
        <div>
          <h2>Collections Follow-Up</h2>
          <p>Track SQUAN responses, late follow-ups, disputes, and items ready to close.</p>
        </div>
        <button class="secondary-btn" data-workflow-action="Reports" data-workflow-id="${state.selectedProjectId || rows[0]?.project || ""}">Open collections report</button>
      </div>
      <div class="report-metrics">
        ${metric("Pending response", pending.length, "Sent with no response")}
        ${metric("Overdue follow-ups", overdue.length, "Needs Billing action")}
        ${metric("Promised payments", promised.length, "Date committed")}
        ${metric("Disputes", disputed.length, "Outcome documented")}
        ${metric("Escalated", escalated.length, "Admin/SQUAN escalation")}
        ${metric("Write-off review", writeOffReview.length, "Owner approval needed")}
        ${metric("Ready to close", closeReady.length, "Paid or resolved")}
      </div>
      ${groups.map(([title, groupRows]) => renderCollectionsWorkGroup(title, groupRows)).join("") || `<p class="empty-state">No collections submissions have been sent yet.</p>`}
    </section>
  `;
}

function renderCollectionsWorkGroup(title, rows) {
  return `
    <div class="proof-checklist-group collections-work-group">
      <div class="proof-group-title"><h3>${title}</h3><span>${rows.length}</span></div>
      <div class="proof-checklist">
        ${rows.map(item => `
          <article class="proof-row">
            <span class="status ${statusClass(item.status)}">${plainStatus(item.status)}</span>
            <div>
              <strong>${item.map} · ${item.id}</strong>
              <small>${item.responseNote || item.followUpNote || item.notes || "No response note recorded yet."}</small>
            </div>
            <div class="proof-row-actions">
              <button class="secondary-btn" data-collection-submission-action="response" data-project-id="${item.project}" data-submission-id="${item.id}">Response</button>
              <button class="secondary-btn" data-collection-submission-action="followup" data-project-id="${item.project}" data-submission-id="${item.id}">Follow-up</button>
              <button class="secondary-btn" data-collection-submission-action="record-cash" data-project-id="${item.project}" data-submission-id="${item.id}">Cash</button>
              <button class="secondary-btn" data-collection-submission-action="closeout" data-project-id="${item.project}" data-submission-id="${item.id}">Close</button>
            </div>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

function retainageReleaseRows() {
  const retainage = scopedRows("retainageLedger");
  const invoices = scopedRows("invoices");
  return retainage.map(item => {
    const invoice = invoices.find(row => row.id === item.invoice || row.project === item.project) || {};
    const releaseDays = daysUntil(item.releaseDate);
    const followUpDate = item.followUpDate || "";
    const followUpDays = daysUntil(followUpDate);
    const ledgerStatus = item.status || "Held";
    const isPaid = ["Released / Paid", "Paid"].includes(ledgerStatus);
    const disputed = ledgerStatus === "Disputed" || (item.disputeReason && item.disputeReason !== "None");
    const status = isPaid
      ? "Released / Paid"
      : disputed
        ? "Disputed"
        : releaseDays !== null && releaseDays < 0
          ? "Past Due"
          : followUpDays !== null && followUpDays <= 14
            ? "Needs Review"
            : "Held";
    return {
      id: item.id,
      project: item.project,
      map: projectLabel(item.project),
      invoice: item.invoice,
      heldAmount: Number(item.heldAmount || 0),
      gross: Number(invoice.gross || 0),
      releaseDate: item.releaseDate,
      daysUntilRelease: releaseDays,
      followUpDate,
      daysUntilFollowUp: followUpDays,
      followUpStatus: item.followUpStatus || (isPaid ? "Closed" : "Scheduled"),
      status,
      ledgerStatus,
      invoiceStatus: invoice.status || "No invoice status",
      disputeReason: item.disputeReason || "None",
      paymentNote: item.paymentNote || item.notes || "No retainage note recorded.",
      isPaid,
      disputed
    };
  }).sort((a, b) => {
    if (a.isPaid !== b.isPaid) return a.isPaid ? 1 : -1;
    const aFollow = a.daysUntilFollowUp ?? 999;
    const bFollow = b.daysUntilFollowUp ?? 999;
    if (aFollow !== bFollow) return aFollow - bFollow;
    return (a.daysUntilRelease ?? 999) - (b.daysUntilRelease ?? 999);
  });
}

function cashScenarioConfig(key = state.cashScenario) {
  const delays = state.data.company?.cashScenarioDelays || {};
  return {
    baseline: {
      key: "baseline",
      label: "Baseline",
      delayDays: Number(delays.baseline ?? 0),
      note: "Receipt dates use current follow-up and release dates."
    },
    delay15: {
      key: "delay15",
      label: "15-day delay",
      delayDays: Number(delays.delay15 ?? 15),
      note: "Models SQUAN/customer timing slipping one half-month."
    },
    delay30: {
      key: "delay30",
      label: "30-day delay",
      delayDays: Number(delays.delay30 ?? 30),
      note: "Models a full monthly payment slip before cash arrives."
    },
    delay45: {
      key: "delay45",
      label: "45-day delay",
      delayDays: Number(delays.delay45 ?? 45),
      note: "Worst-case view for extended pay-when-paid pressure."
    }
  }[key] || {
    key: "baseline",
    label: "Baseline",
    delayDays: 0,
    note: "Receipt dates use current follow-up and release dates."
  };
}

function cashScenarioOptions() {
  return ["baseline", "delay15", "delay30", "delay45"].map(cashScenarioConfig);
}

function cashForecastRows(scenarioKey = state.cashScenario) {
  const scenario = cashScenarioConfig(scenarioKey);
  const paymentRows = paymentFollowUpRows()
    .filter(item => !item.paid90Complete && item.open90 > 0)
    .map(item => {
      const isHold = item.status === "Pay-when-paid hold";
      const baseDate = isHold ? addDays(item.followUpDate || isoDate(today), 15) : item.followUpDate || addDays(isoDate(today), 30);
      const expectedDate = addDays(baseDate, scenario.delayDays);
      return {
        id: `AR-${item.invoice}`,
        project: item.project,
        map: item.map,
        type: "90% AR",
        expectedDate,
        amount: item.open90,
        confidence: isHold ? "At Risk" : item.status === "Past Due" ? "At Risk" : "Expected",
        status: item.status,
        detail: `${isHold ? "Pay-when-paid adds timing risk." : item.detail}${scenario.delayDays ? ` Scenario adds ${scenario.delayDays} days.` : ""}`
      };
    });
  const retainageRows = retainageReleaseRows()
    .filter(item => !item.isPaid)
    .map(item => ({
      id: `RET-${item.id}`,
      project: item.project,
      map: item.map,
      type: "Retainage",
      expectedDate: item.releaseDate,
      amount: item.heldAmount,
      confidence: item.disputed ? "At Risk" : "Future",
      status: item.status,
      detail: item.disputed ? `Dispute: ${item.disputeReason}` : `10% retainage release tracked for ${item.releaseDate}.`
    }));
  const readyBilling = scopedRows("billingReadiness")
    .filter(item => item.status === "Ready to Bill" && Number(item.billableAmount || 0) > 0)
    .map(item => ({
      id: `UNBILLED-${item.project}`,
      project: item.project,
      map: projectLabel(item.project),
      type: "Ready invoice",
      expectedDate: addDays(item.billingDeadline || isoDate(today), 30 + scenario.delayDays),
      amount: Number(item.billableAmount || 0) * 0.9,
      confidence: "Expected",
      status: "Ready to Bill",
      detail: `Projected 90% cash after SQUAN acceptance once invoice is submitted.${scenario.delayDays ? ` Scenario adds ${scenario.delayDays} days.` : ""}`
    }));
  return [...paymentRows, ...readyBilling, ...retainageRows].sort((a, b) => String(a.expectedDate).localeCompare(String(b.expectedDate)));
}

function cashOutflowRows() {
  const timeRows = scopedRows("timeEntries")
    .filter(item => item.payrollStatus !== "Exported")
    .map(item => {
      const regular = Number(item.regularHours || 0) + Number(item.travelHours || 0) + Number(item.standbyHours || 0);
      const overtime = Number(item.overtimeHours || 0);
      const rate = roleLaborRate(item.role);
      return {
        id: `PAY-${item.id}`,
        project: item.project,
        map: projectLabel(item.project),
        type: "Payroll",
        expectedDate: nextFriday(item.date || isoDate(today)),
        amount: Math.round((regular * rate + overtime * rate * 1.5) * 1.18),
        status: item.payrollStatus || "Pending",
        detail: `${item.employee}: ${regular + overtime} hour(s), burdened payroll estimate.`
      };
    })
    .filter(item => item.amount > 0);
  const equipmentRows = (state.data.dailyEquipment || [])
    .map(item => ({
      id: `EQCOST-${item.dailyId}-${item.equipmentId}`,
      project: item.project,
      map: projectLabel(item.project),
      type: "Equipment cost",
      expectedDate: addDays((state.data.dailies || []).find(daily => daily.id === item.dailyId)?.date || isoDate(today), 14),
      amount: Math.round(Number(item.hours || 0) * Number(item.rate || 0)),
      status: "Scheduled",
      detail: `${item.equipmentId}: ${Number(item.hours || 0)} hour(s) at ${currency(Number(item.rate || 0))}/hr.`
    }))
    .filter(item => item.amount > 0);
  const activeProjects = scopedRows("projects").filter(project => !["Completed / Billed", "Closed"].includes(project.status));
  const projectBurn = activeProjects.flatMap(project => {
    const remaining = Math.max(0, Number(project.forecastCost || 0) - Number(project.actualCost || 0));
    if (!remaining) return [];
    const weeks = 6;
    return Array.from({ length: weeks }, (_, index) => ({
      id: `BURN-${project.id}-${index + 1}`,
      project: project.id,
      map: projectLabel(project.id),
      type: "Forecast burn",
      expectedDate: addDays(isoDate(today), 7 * (index + 1)),
      amount: Math.round(remaining / weeks),
      status: "Forecast",
      detail: `${project.map || project.id}: remaining forecast cost spread across ${weeks} weeks.`
    }));
  });
  const weeklyOverhead = Number(state.data.company?.weeklyOverhead || 8500);
  const overhead = Array.from({ length: 13 }, (_, index) => ({
    id: `OH-${index + 1}`,
    project: "",
    map: "Company overhead",
    type: "Overhead",
    expectedDate: addDays(isoDate(today), 7 * index + 5),
    amount: weeklyOverhead,
    status: "Forecast",
    detail: "Estimated weekly overhead until actual accounting integration exists."
  }));
  return [...timeRows, ...equipmentRows, ...projectBurn, ...overhead].sort((a, b) => String(a.expectedDate).localeCompare(String(b.expectedDate)));
}

function roleLaborRate(role = "") {
  const normal = String(role).toLowerCase();
  if (normal.includes("foreman")) return 42;
  if (normal.includes("operator")) return 38;
  if (normal.includes("traffic")) return 34;
  if (normal.includes("lineman")) return 39;
  return 34;
}

function nextFriday(dateText) {
  const base = new Date(`${dateText || isoDate(today)}T12:00:00`);
  if (Number.isNaN(base.getTime())) return addDays(isoDate(today), 6);
  const day = base.getDay();
  const daysToFriday = (5 - day + 7) % 7 || 7;
  base.setDate(base.getDate() + daysToFriday);
  return isoDate(base);
}

function cashForecastSummary(rows = cashForecastRows(), outflows = cashOutflowRows()) {
  const horizonEnd = addDays(isoDate(today), 91);
  const next13 = rows.filter(item => item.expectedDate && item.expectedDate <= horizonEnd);
  const outflow13 = outflows.filter(item => item.expectedDate && item.expectedDate <= horizonEnd);
  const payWhenPaid = paymentFollowUpRows().filter(item => item.status === "Pay-when-paid hold");
  const disputes = rows.filter(item => ["At Risk", "Disputed", "Short-paid", "Chargeback received"].includes(item.confidence) || ["Disputed", "Short-paid", "Chargeback received", "Pay-when-paid hold"].includes(item.status));
  const reconciliation = cashReconciliationRows();
  const startingCash = Number(state.data.company?.cashOnHand || 50000);
  const endingCash = startingCash + sum(next13, "amount") - sum(outflow13, "amount");
  const minimumCashThreshold = Number(state.data.company?.minimumCashThreshold || 0);
  return {
    next13,
    outflow13,
    startingCash,
    endingCash,
    minimumCashThreshold,
    thresholdGap: endingCash - minimumCashThreshold,
    next13Total: sum(next13, "amount"),
    outflow13Total: sum(outflow13, "amount"),
    net13: sum(next13, "amount") - sum(outflow13, "amount"),
    actualReceived: sum(reconciliation, "actualAmount"),
    receiptVariance: sum(reconciliation, "variance"),
    openReceiptVariance: sum(reconciliation.filter(item => item.status !== "Reconciled"), "variance"),
    expected: sum(next13.filter(item => item.confidence === "Expected"), "amount"),
    atRisk: sum(rows.filter(item => item.confidence === "At Risk"), "amount"),
    futureRetainage: sum(rows.filter(item => item.type === "Retainage" && item.expectedDate > horizonEnd), "amount"),
    payWhenPaidCount: payWhenPaid.length,
    disputeCount: disputes.length
  };
}

function cashReconciliationRows() {
  return (state.data.cashReceipts || [])
    .map(receipt => ({
      id: receipt.id,
      project: receipt.project,
      map: projectLabel(receipt.project),
      invoice: receipt.invoice,
      type: receipt.type || "Cash receipt",
      expectedDate: receipt.expectedDate || "",
      actualDate: receipt.actualDate || receipt.receivedAt || "",
      expectedAmount: Number(receipt.expectedAmount || 0),
      actualAmount: Number(receipt.actualAmount || 0),
      variance: Number(receipt.actualAmount || 0) - Number(receipt.expectedAmount || 0),
      status: receipt.status || "Reconciled",
      depositStatus: receipt.depositStatus || "",
      bankProof: receipt.bankProof || "",
      reference: receipt.reference || "",
      notes: receipt.notes || ""
    }))
    .sort((a, b) => String(b.actualDate || "").localeCompare(String(a.actualDate || "")));
}

function forecastWeekBuckets(rows, outflows = cashOutflowRows(), startingCash = Number(state.data.company?.cashOnHand || 50000)) {
  const horizonEnd = addDays(isoDate(today), 91);
  const next13 = rows.filter(item => item.expectedDate && item.expectedDate <= horizonEnd);
  let runningCash = startingCash;
  return Array.from({ length: 13 }, (_, index) => {
    const start = addDays(isoDate(today), index * 7);
    const end = addDays(isoDate(today), index * 7 + 6);
    const items = next13.filter(item => item.expectedDate >= start && item.expectedDate <= end);
    const costs = outflows.filter(item => item.expectedDate >= start && item.expectedDate <= end);
    const inflow = sum(items, "amount");
    const outflow = sum(costs, "amount");
    runningCash += inflow - outflow;
    return {
      index: index + 1,
      start,
      end,
      items,
      costs,
      expected: sum(items.filter(item => item.confidence !== "At Risk"), "amount"),
      atRisk: sum(items.filter(item => item.confidence === "At Risk"), "amount"),
      inflow,
      outflow,
      net: inflow - outflow,
      runningCash
    };
  });
}

function cashDecisionRecommendations(summary, buckets, watchlist) {
  const firstGap = buckets.find(bucket => bucket.runningCash < 0);
  const firstRisk = watchlist[0];
  const retainageOpen = retainageReleaseRows().filter(item => !item.isPaid);
  const activeProject = scopedRows("projects").find(project => project.id === firstRisk?.project) || scopedRows("projects").find(project => project.status !== "Completed / Billed") || scopedRows("projects")[0];
  const recommendations = [];
  if (firstRisk) {
    recommendations.push({
      action: "escalate-squan-cash",
      label: "Escalate SQUAN payment",
      status: "Recommended",
      detail: `${firstRisk.map} has ${currency(firstRisk.amount)} cash exposure. Assign Billing to document SQUAN status and next response date.`,
      project: firstRisk.project,
      workflowArea: "Billing"
    });
  }
  if (firstGap) {
    recommendations.push({
      action: "pause-hiring",
      label: "Pause hiring / overtime",
      status: "Recommended",
      detail: `Week ${firstGap.index} projects cash at ${currency(firstGap.runningCash)}. Assign Admin to review hiring, overtime, and subcontractor commitments.`,
      project: activeProject?.id,
      workflowArea: "Admin"
    });
    recommendations.push({
      action: "delay-equipment-spend",
      label: "Delay equipment spend",
      status: "Recommended",
      detail: `Hold noncritical equipment spend until cash recovers above zero in the selected scenario.`,
      project: activeProject?.id,
      workflowArea: "Equipment"
    });
  }
  if (retainageOpen.length) {
    const item = retainageOpen[0];
    recommendations.push({
      action: "request-retainage-status",
      label: "Request retainage status",
      status: "Monitor",
      detail: `${item.map} has ${currency(item.heldAmount)} retained. Assign Billing to confirm release clock and next SQUAN response.`,
      project: item.project,
      workflowArea: "Billing"
    });
  }
  recommendations.push({
    action: "approve-work-threshold",
    label: "Approve work by threshold",
    status: summary.endingCash < 0 ? "Blocked" : "Available",
    detail: summary.endingCash < 0
      ? "Do not approve new discretionary work until the selected cash scenario is above zero or mitigation is logged."
      : summary.thresholdGap < 0
        ? "Cash stays above zero but falls below the Admin minimum threshold. Require management review before discretionary work."
        : "Cash stays above the Admin threshold in this scenario. Admin can approve work with threshold note attached.",
    project: activeProject?.id,
    workflowArea: "Project & Map Hub"
  });
  return recommendations;
}

function cashDecisionTaskRows(summary = cashForecastSummary()) {
  return (state.data.tasks || [])
    .filter(task => task.source === "Cash decision workflow")
    .map(task => {
      const originalEnding = Number(task.projectedEndingCash || 0);
      const currentEnding = Number(summary.endingCash || 0);
      const delta = currentEnding - originalEnding;
      const days = daysUntil(task.dueDate);
      return {
        ...task,
        map: projectLabel(task.project),
        daysUntilDue: days,
        originalEnding,
        currentEnding,
        forecastDelta: delta,
        forecastStatus: delta > 0 ? "Improved" : delta < 0 ? "Worse" : "No Change",
        dueStatus: task.status === "Closed" ? "Closed" : days !== null && days < 0 ? "Overdue" : days !== null && days <= 2 ? "Due Soon" : "Open"
      };
    })
    .sort((a, b) => {
      if ((a.status === "Closed") !== (b.status === "Closed")) return a.status === "Closed" ? 1 : -1;
      return (a.daysUntilDue ?? 999) - (b.daysUntilDue ?? 999);
    });
}

function renderCashDecisionFollowThrough(summary) {
  const tasks = cashDecisionTaskRows(summary);
  const openTasks = tasks.filter(task => task.status !== "Closed");
  const overdue = openTasks.filter(task => task.dueStatus === "Overdue");
  return `
    <div class="cash-followthrough-panel">
      <div class="section-heading">
        <h3>Cash decision follow-through</h3>
        <span>${openTasks.length} open · ${overdue.length} overdue</span>
      </div>
      <div class="cash-followthrough-grid">
        ${tasks.slice(0, 6).map(task => `
          <article>
            <div class="card-topline">
              <h3>${task.title}</h3>
              <span class="status ${statusClass(task.dueStatus)}">${task.dueStatus}</span>
            </div>
            <p>${task.notes}</p>
            <dl>
              <div><dt>Owner</dt><dd>${task.owner}</dd></div>
              <div><dt>Due</dt><dd>${formatDateRisk(task.dueDate)}</dd></div>
              <div><dt>Scenario</dt><dd>${task.scenario || "Baseline"}</dd></div>
              <div><dt>Forecast impact</dt><dd>${task.forecastStatus} ${currency(task.forecastDelta)}</dd></div>
            </dl>
            <div class="invoice-actions">
              <button class="secondary-btn" data-task-open="${task.id}">Open</button>
              ${task.status !== "Closed" ? `<button class="secondary-btn" data-cash-task-action="escalate" data-task-id="${task.id}">Escalate</button>` : ""}
              ${task.status !== "Closed" ? `<button class="secondary-btn" data-task-complete="${task.id}">Complete</button>` : ""}
            </div>
          </article>
        `).join("") || `<div class="empty">No cash decision tasks have been created yet.</div>`}
      </div>
    </div>
  `;
}

function cashDecisionHistoryRows(summary = cashForecastSummary()) {
  const tasks = state.data.tasks || [];
  return (state.data.company?.cashDecisionLog || [])
    .map((entry, index) => {
      const task = tasks.find(item => item.id === entry.task) || {};
      const originalEnding = Number(entry.endingCash || task.projectedEndingCash || 0);
      const currentEnding = Number(summary.endingCash || 0);
      const delta = currentEnding - originalEnding;
      return {
        ...entry,
        index,
        task,
        taskStatus: task.status || entry.status || "Logged",
        taskOwner: task.owner || "Unassigned",
        map: projectLabel(entry.project),
        originalEnding,
        currentEnding,
        delta,
        forecastStatus: delta > 0 ? "Improved" : delta < 0 ? "Worse" : "No Change",
        reviewStatus: entry.reviewedAt ? "Reviewed" : task.status === "Closed" || entry.status === "Closed" ? "Ready for Review" : "Open"
      };
    })
    .sort((a, b) => String(b.at || "").localeCompare(String(a.at || "")));
}

