function renderCashForecastPanel({ compact = false } = {}) {
  const scenario = cashScenarioConfig();
  const rows = cashForecastRows(scenario.key);
  const outflows = cashOutflowRows();
  const summary = cashForecastSummary(rows, outflows);
  const buckets = forecastWeekBuckets(rows, outflows, summary.startingCash);
  const watchlist = rows.filter(item => item.confidence === "At Risk" || item.status === "Pay-when-paid hold" || item.status === "Disputed").slice(0, compact ? 3 : 8);
  const lowWeeks = buckets.filter(bucket => bucket.runningCash < 0);
  const recommendations = cashDecisionRecommendations(summary, buckets, watchlist);
  return `
    <section class="panel cash-forecast-panel">
      <div class="panel-header">
        <div>
          <h2>AR cash forecast</h2>
          <p>${scenario.label}: ${scenario.note}</p>
        </div>
        <span>${currency(summary.net13)} net 13 weeks</span>
      </div>
      <div class="cash-scenario-controls">
        ${cashScenarioOptions().map(option => `
          <button class="secondary-btn ${option.key === scenario.key ? "active" : ""}" data-cash-scenario="${option.key}">
            ${option.label}
          </button>
        `).join("")}
      </div>
      <section class="cash-forecast-metrics">
        ${metric("Starting cash", currency(summary.startingCash), `Minimum ${currency(summary.minimumCashThreshold)}`)}
        ${metric("13-week inflow", currency(summary.next13Total), `${summary.next13.length} receipt item(s)`)}
        ${metric("13-week outflow", currency(summary.outflow13Total), "Payroll, equipment, burn, overhead")}
        ${metric("Ending cash", currency(summary.endingCash), summary.thresholdGap < 0 ? `${currency(Math.abs(summary.thresholdGap))} below threshold` : "Above threshold")}
        ${metric("At-risk exposure", currency(summary.atRisk), `${summary.payWhenPaidCount} pay-when-paid hold(s)`)}
        ${metric("Future retainage", currency(summary.futureRetainage), "Outside next 13 weeks")}
        ${metric("Actual receipts", currency(summary.actualReceived), `${currency(summary.receiptVariance)} variance`)}
      </section>
      ${renderCashAssumptionsPanel()}
      ${renderCashReconciliationPanel({ compact })}
      ${compact ? "" : `
        <div class="cash-week-grid">
          ${buckets.map(bucket => `
            <article class="${bucket.runningCash < 0 ? "cash-gap" : ""}">
              <strong>W${bucket.index}</strong>
              <span>${bucket.start.slice(5)}-${bucket.end.slice(5)}</span>
              <b>${currency(bucket.net)}</b>
              <em>In ${currency(bucket.inflow)} / Out ${currency(bucket.outflow)}</em>
              <small>Cash ${currency(bucket.runningCash)}</small>
            </article>
          `).join("")}
        </div>
        <div class="cash-gap-panel">
          <div>
            <strong>${lowWeeks.length ? "Projected cash gap" : "No projected cash gap"}</strong>
            <p>${lowWeeks.length ? `First gap appears in week ${lowWeeks[0].index} with projected cash at ${currency(lowWeeks[0].runningCash)}.` : "Current scenario keeps projected cash above zero across the next 13 weeks."}</p>
          </div>
          <div>
            <strong>Admin actions</strong>
            <p>Use this to decide whether to delay hiring, escalate pay-when-paid holds, pull retainage status, or hold noncritical equipment spend.</p>
          </div>
        </div>
        <div class="cash-decision-panel">
          <div class="section-heading">
            <h3>Admin cash decisions</h3>
            <span>${recommendations.filter(item => item.status === "Recommended").length} recommended</span>
          </div>
          <div class="cash-decision-grid">
            ${recommendations.map(item => `
              <article>
                <div class="card-topline">
                  <h3>${item.label}</h3>
                  <span class="status ${statusClass(item.status)}">${item.status}</span>
                </div>
                <p>${item.detail}</p>
                <button class="secondary-btn" data-cash-decision="${item.action}" data-project-id="${item.project || ""}">${item.label}</button>
              </article>
            `).join("")}
          </div>
        </div>
        ${renderCashDecisionFollowThrough(summary)}
        ${renderCashDecisionHistory(summary)}
      `}
      <div class="cash-watchlist">
        <div class="section-heading">
          <h3>Cash risk watchlist</h3>
          <span>${watchlist.length || "No"} active risk item(s)</span>
        </div>
        ${watchlist.map(item => `
          <article>
            <div class="card-topline">
              <h3>${item.map}</h3>
              <span class="status ${statusClass(item.status)}">${item.status}</span>
            </div>
            <dl>
              <div><dt>Type</dt><dd>${item.type}</dd></div>
              <div><dt>Amount</dt><dd>${currency(item.amount)}</dd></div>
              <div><dt>Expected</dt><dd>${item.expectedDate}</dd></div>
              <div><dt>Risk</dt><dd>${item.confidence}</dd></div>
            </dl>
            <p>${item.detail}</p>
            <button class="secondary-btn" data-workflow-action="Billing" data-workflow-id="${item.project}">Open Billing</button>
          </article>
        `).join("") || `<div class="empty">No pay-when-paid, dispute, short-pay, or chargeback exposure is active.</div>`}
      </div>
    </section>
  `;
}

