function renderSafetyRiskQueue() {
  const audit = safetyAuditSummary();
  const projects = scopedRows("projects");
  const selectedProject = projects.find(project => project.id === state.selectedProjectId) || projects[0];
  if (selectedProject && selectedProject.id !== state.selectedProjectId) state.selectedProjectId = selectedProject.id;
  const focusedDetail = renderSafetyFocusedDetail(selectedProject, audit);
  return `
    ${renderSafetyWorkHome(selectedProject, audit)}
    ${focusedDetail || `
      ${renderSafetyClearReturnPath(selectedProject, audit)}
      ${renderSafetyMapQueue(projects, selectedProject)}
      ${renderSafetyQuickTools(selectedProject)}
    `}
  `;
}

function renderSafetyWorkHome(project, audit) {
  const row = safetyMapRiskRow(project);
  const pendingCaptures = project
    ? fieldCaptureReviewRows(project).filter(item => !["Accepted", "Closed"].includes(item.status)).length
    : 0;
  return `
    <section class="panel safety-simple-home">
      <div class="safety-simple-head">
        <div>
          <span class="eyebrow">Safety</span>
          <h2>Fix safety problems for ${project?.map || project?.id || "selected Map"}</h2>
          <p>Review crew, equipment, photos, incidents, and obstacles. The decision is simple: clear it, send it back to fix, or keep it blocked.</p>
        </div>
        <button class="primary-btn" data-workflow-action="Safety & Risk" data-workflow-id="${project?.id || ""}" data-workflow-focus="${row.status === "Clear" ? "SQUAN score" : "Map risk"}">
          ${row.status === "Clear" ? "Check score" : "Start safety check"}
        </button>
      </div>
      <div class="safety-status-strip">
        <article>
          <span>Crew problems</span>
          <strong>${row.expiringCerts.length}</strong>
          <small>Training cards or required checks</small>
        </article>
        <article>
          <span>Equipment problems</span>
          <strong>${row.equipmentRisk.length}</strong>
          <small>Inspection or calibration risk</small>
        </article>
        <article>
          <span>Photos / notes</span>
          <strong>${pendingCaptures}</strong>
          <small>Photos, notes, obstacles to review</small>
        </article>
        <article>
          <span>SQUAN score</span>
          <strong>${audit.score} pts</strong>
          <small>${audit.rating} rating estimate</small>
        </article>
      </div>
    </section>
  `;
}

function renderSafetyClearReturnPath(project, audit) {
  if (!project) return "";
  const row = safetyMapRiskRow(project);
  const pendingCaptures = fieldCaptureReviewRows(project).filter(item => !["Accepted", "Closed"].includes(item.status));
  const scoreStatus = audit.score >= 90 ? "Clear" : audit.score >= 80 ? "Needs Review" : "Blocked";
  const steps = [
    ["1", "Crew clear?", row.expiringCerts.length ? "Blocked" : "Clear", row.expiringCerts.length ? `${row.expiringCerts.length} training or required check item(s) need action.` : "Assigned crew is not blocking work.", "People & Compliance", "Compliance"],
    ["2", "Equipment clear?", row.equipmentRisk.length ? "Blocked" : "Clear", row.equipmentRisk.length ? `${row.equipmentRisk.length} assigned truck/tool item(s) need inspection review.` : "Assigned equipment is clear for field use.", "Equipment", "Equipment safety"],
    ["3", "Photos and notes checked?", pendingCaptures.length ? "Needs Review" : "Clear", pendingCaptures.length ? `${pendingCaptures.length} photo, markup, or obstacle item(s) need a decision.` : "No photo or note is waiting on safety.", "Safety & Risk", "Field capture review"],
    ["4", "Safety fix closed?", row.incidents.length ? "Open" : "Clear", row.incidents.length ? `${row.incidents.length} safety fix item(s) still open.` : "No open safety fix for this Map.", "Safety & Risk", "Form 12"],
    ["5", "Obstacles controlled?", row.obstacles.length ? "Needs Review" : "Clear", row.obstacles.length ? `${row.obstacles.length} obstacle(s) still need control, acceptance, or documentation.` : "Site obstacles are not blocking safety release.", "Safety & Risk", "Obstacles"],
    ["6", "Safe to start?", scoreStatus, `${audit.score} pts; ${row.detail}`, "Safety & Risk", scoreStatus === "Clear" ? "SQUAN score" : "Map risk"]
  ];
  return `
    <section class="panel safety-simple-path">
      <div class="panel-header">
        <div>
          <h2>Fix or clear steps</h2>
          <p>Work these in order. If something is not acceptable, send it back with what needs to be fixed.</p>
        </div>
        <span class="status ${statusClass(row.status)}">${row.status}</span>
      </div>
      <div class="safety-step-grid">
        ${steps.map(step => `
          <button class="safety-step-card ${statusClass(step[2])}" data-workflow-action="${step[4]}" data-workflow-id="${project.id}" data-workflow-focus="${step[5]}">
            <span>${step[0]}</span>
            <strong>${step[1]}</strong>
            <small>${step[3]}</small>
            <em>${plainStatus(step[2])}</em>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function renderSafetyMapQueue(projects, selectedProject) {
  const rows = projects.map(project => safetyMapRiskRow(project));
  return `
    <section class="panel safety-map-queue">
      <div class="panel-header">
        <div>
          <h2>Maps with safety work</h2>
          <p>Pick a Map to see what is stopping field work, billing proof, or final finish.</p>
        </div>
        <span>${rows.filter(row => row.status !== "Clear").length} need review</span>
      </div>
      <div class="safety-map-list">
        ${rows.map(row => {
          const project = row.project;
          const isSelected = project.id === selectedProject?.id;
          return `
            <button class="${isSelected ? "selected" : ""}" data-workflow-action="Safety & Risk" data-workflow-id="${project.id}" data-workflow-focus="Map risk">
              <span class="status ${statusClass(row.status)}">${plainStatus(row.status)}</span>
              <strong>${project.map || project.id}</strong>
              <small>${row.detail}</small>
            </button>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function renderSafetyQuickTools(project) {
  const tools = [
    ["Crew problems", "Training cards, required checks, assignment blocks", "People & Compliance", "Compliance"],
    ["Equipment problems", "Inspection, calibration, dielectric, availability", "Equipment", "Equipment safety"],
    ["Photos and notes", "Review photos, notes, markups, and obstacle proof", "Safety & Risk", "Field capture review"],
    ["Safety fixes", "Incidents, near misses, 5 Whys, fixes to complete", "Safety & Risk", "Form 12"],
    ["Obstacles / GIS", "Site obstructions, pins, photos, and prime acceptance", "Safety & Risk", "Obstacles"],
    ["Score / report", "SQUAN score estimate and report readiness", "Safety & Risk", "SQUAN score"]
  ];
  return `
    <section class="panel safety-tools-panel">
      <div>
        <h2>Safety detail tools</h2>
        <p>Open these only when the fix-or-clear steps point you to the details.</p>
      </div>
      <div class="safety-tool-grid">
        ${tools.map(([label, detail, action, focus]) => `
          <button class="safety-tool-card" data-workflow-action="${action}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${focus}">
            <strong>${label}</strong>
            <small>${detail}</small>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function renderSafetyCommandCenter(project, audit) {
  const row = safetyMapRiskRow(project);
  const scoreStatus = audit.score >= 90 ? "Ready" : audit.score >= 80 ? "Needs Review" : "Blocked";
  const steps = [
    ["1", "Map risk", row.status, row.detail, "Safety & Risk", "Map risk"],
    ["2", "People / certs", row.expiringCerts.length ? "Needs Review" : "Clear", row.expiringCerts.length ? `${row.expiringCerts.length} cert block(s)` : "Crew certifications are clear.", "Safety & Risk", "Compliance"],
    ["3", "Equipment safety", row.equipmentRisk.length ? "Needs Review" : "Clear", row.equipmentRisk.length ? `${row.equipmentRisk.length} inspection item(s)` : "Assigned equipment inspections are clear.", "Safety & Risk", "Compliance"],
    ["4", "Form 12 / incidents", row.incidents.length ? "Open" : "Clear", row.incidents.length ? `${row.incidents.length} corrective action(s)` : "No open incident or Form 12 action.", "Safety & Risk", "Form 12"],
    ["5", "Obstacles / GIS", row.obstacles.length ? "Needs Review" : "Clear", row.obstacles.length ? `${row.obstacles.length} open obstacle(s)` : "No open site obstacle blocking work.", "Safety & Risk", "Obstacles"],
    ["6", "SQUAN score", scoreStatus, `${audit.score} pts · ${audit.rating} estimate`, "Safety & Risk", "SQUAN score"]
  ];
  return `
    <section class="panel safety-command-center">
      <div class="panel-header">
        <div>
          <h2>Safety risk command center</h2>
          <p>Control release risk, field safety, Form 12 actions, compliance blocks, obstacles, and SQUAN score exposure from the selected Map.</p>
        </div>
        <span class="status ${statusClass(row.status)}">${row.status}</span>
      </div>
      <div class="field-mobile-steps safety-workflow-steps">
        ${steps.map(step => `
          <button class="field-mobile-step ${statusClass(step[2])}" data-workflow-action="${step[4]}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${step[5]}">
            <span>${step[0]}</span>
            <strong>${step[1]}</strong>
            <small>${step[3]}</small>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function safetyMapRiskRow(project) {
  if (!project) {
    return {
      status: "Pending",
      detail: "Select a Map to review safety risk.",
      incidents: [],
      obstacles: [],
      missingSafetyDocs: [],
      expiringCerts: [],
      equipmentRisk: [],
      riskPoints: 0
    };
  }
  const incidents = scopedRows("safety").filter(item => item.project === project.id && item.status !== "Closed");
  const obstacles = scopedRows("obstacles").filter(item => item.project === project.id && isOpenObstacle(item));
  const documents = scopedRows("documents").filter(item => item.project === project.id);
  const missingSafetyDocs = documentRequirements(project, documents).filter(item => item.safety && ["Missing", "Pending Review", "Needs Review"].includes(item.status));
  const crew = scopedRows("people").filter(item => item.crew === project.crew);
  const expiringCerts = crew.filter(item => item.compliance === "Blocked" || daysUntil(item.nextExpiration) !== null && daysUntil(item.nextExpiration) <= 30);
  const equipmentRisk = scopedRows("equipment").filter(item => (item.assigned === project.crew || item.assigned === project.id) && daysUntil(item.inspectionDue) !== null && daysUntil(item.inspectionDue) <= 30);
  const riskPoints = incidents.length * 4 + obstacles.length * 3 + missingSafetyDocs.length * 2 + expiringCerts.length * 2 + equipmentRisk.length * 2;
  const status = riskPoints >= 8 ? "Blocked" : riskPoints ? "Needs Review" : "Clear";
  return {
    project,
    incidents,
    obstacles,
    missingSafetyDocs,
    expiringCerts,
    equipmentRisk,
    riskPoints,
    status,
    detail: riskPoints
      ? `${incidents.length} incident(s), ${obstacles.length} obstacle(s), ${missingSafetyDocs.length} safety doc gap(s), ${expiringCerts.length} cert block(s), ${equipmentRisk.length} equipment item(s).`
      : "Safety release and closeout risk is clear for this Map."
  };
}

function renderSafetyPriorityActionQueue(project) {
  const people = scopedRows("people");
  const equipment = scopedRows("equipment");
  const openIncidents = scopedRows("safety").filter(item => item.status !== "Closed");
  const row = safetyMapRiskRow(project);
  const captureReviews = fieldCaptureReviewRows(project)
    .filter(item => !["Accepted", "Closed"].includes(item.status) && (item.blockerImpact !== "No blocker" || /markup|obstruction|safety|release|closeout/i.test(`${item.kind} ${item.summary}`)))
    .slice(0, 5);
  const proofRows = [
    ...row.missingSafetyDocs.slice(0, 5).map(item => ({
      title: item.label,
      detail: item.document ? item.document.name : "No proof attached",
      status: item.status,
      actionLabel: item.document ? "Open" : "Upload",
      action: "Documents",
      focus: "Required support"
    })),
    ...captureReviews.map(item => ({
      title: item.kind,
      detail: `${item.project.map || item.project.id}; ${item.summary}`,
      status: item.status,
      actionLabel: "Review",
      action: "Safety & Risk",
      focus: "Field capture review"
    }))
  ].slice(0, 8);
  const crewRows = [
    ...people.filter(item => item.compliance === "Blocked" || daysUntil(item.nextExpiration) !== null && daysUntil(item.nextExpiration) <= 30).slice(0, 6).map(item => ({
      title: item.name,
      detail: `${item.role}; ${item.certs}; expires ${item.nextExpiration}`,
      status: item.compliance,
      record: ["people", item.id],
      actionLabel: "Open record",
      action: "People & Compliance",
      focus: "Compliance"
    })),
    ...equipment.filter(item => daysUntil(item.inspectionDue) !== null && daysUntil(item.inspectionDue) <= 30).slice(0, 6).map(item => ({
      title: item.asset,
      detail: `${item.assigned}; due ${item.inspectionDue}; ${item.notes || ""}`,
      status: item.status,
      record: ["equipment", item.id],
      actionLabel: "Open record",
      action: "Equipment",
      focus: "Equipment safety"
    }))
  ].slice(0, 8);
  const safetyRows = [
    ...row.incidents.slice(0, 5).map(item => ({
      title: item.type,
      detail: `${item.project}; ${item.correctiveAction || item.rootCause}; due ${item.due || "not set"}`,
      status: item.status,
      record: ["safety", item.id],
      actionLabel: "Review",
      action: "Safety & Risk",
      focus: "Form 12"
    })),
    ...row.obstacles.slice(0, 5).map(item => ({
      title: item.location,
      detail: `${item.type}; ${item.description}; responsible ${item.responsibleParty || "Unassigned"}`,
      status: item.status,
      record: ["obstacles", item.id],
      actionLabel: "Review",
      action: "Safety & Risk",
      focus: "Obstacles"
    })),
    ...openIncidents.filter(item => item.project !== project?.id).slice(0, 5).map(item => ({
      title: item.type,
      detail: `${item.project}; ${item.correctiveAction || item.rootCause}; due ${item.due || "not set"}`,
      status: item.status,
      record: ["safety", item.id],
      actionLabel: "Review",
      action: "Safety & Risk",
      focus: "Form 12"
    }))
  ].slice(0, 8);
  const total = proofRows.length + crewRows.length + safetyRows.length;
  return `
    <section class="panel safety-work-panel">
      <div class="panel-header">
        <div>
          <h2>Safety Work</h2>
          <p>Handle missing proof, crew/truck problems, and open safety fixes without the long warning bars.</p>
        </div>
        <span>${total} item(s)</span>
      </div>
      ${renderSafetyWorkGroup("Missing safety proof", proofRows, project, "No missing safety proof.")}
      ${renderSafetyWorkGroup("Crew / equipment problems", crewRows, project, "No crew or equipment problems.")}
      ${renderSafetyWorkGroup("Open safety fixes", safetyRows, project, "No open safety fixes.")}
    </section>
  `;
}

