function safetyAuditSummary() {
  const score = scopedRows("squanScores")[0] || {};
  const people = scopedRows("people");
  const equipment = scopedRows("equipment");
  const safety = scopedRows("safety");
  const documents = scopedRows("documents");
  const openIncidents = safety.filter(item => item.status !== "Closed").length;
  const expiringPeople = people.filter(item => daysUntil(item.nextExpiration) !== null && daysUntil(item.nextExpiration) <= 30).length;
  const dueEquipment = equipment.filter(item => daysUntil(item.inspectionDue) !== null && daysUntil(item.inspectionDue) <= 30).length;
  const missingSafetyDocs = scopedRows("projects").reduce((count, project) => {
    return count + documentRequirements(project, documents.filter(item => item.project === project.id)).filter(item => item.safety && ["Missing", "Pending Review", "Needs Review"].includes(item.status)).length;
  }, 0);
  const estimatedScore = Math.max(0, Number(score.score || 100) - openIncidents * 4 - dueEquipment * 2 - expiringPeople * 2 - missingSafetyDocs);
  return {
    score: estimatedScore,
    rating: estimatedScore >= 90 ? "A" : estimatedScore >= 80 ? "B" : "Mitigation",
    openIncidents,
    expiringPeople,
    dueEquipment,
    missingSafetyDocs,
    programDocsPoints: score.programDocsPoints || 0,
    trainingDocsPoints: score.trainingDocsPoints || 0,
    safetyStatsPoints: score.safetyStatsPoints || 0
  };
}

function renderAuditReadiness(audit) {
  return `
    <section class="panel audit-readiness">
      <div class="panel-header">
        <h2>Safety audit packet</h2>
        <span>${audit.score} pt SQUAN estimate</span>
      </div>
      <div class="audit-grid">
        ${auditItem("Safety docs", audit.missingSafetyDocs ? "Needs Review" : "Ready", `${audit.missingSafetyDocs} missing or pending`)}
        ${auditItem("Training / certs", audit.expiringPeople ? "Needs Review" : "Ready", `${audit.expiringPeople} expiring inside 30 days`)}
        ${auditItem("Incident log", audit.openIncidents ? "Open" : "Ready", `${audit.openIncidents} open corrective actions`)}
        ${auditItem("Equipment inspections", audit.dueEquipment ? "Needs Review" : "Ready", `${audit.dueEquipment} due inside 30 days`)}
        ${auditItem("SQUAN scoring", audit.rating, `${audit.programDocsPoints + audit.trainingDocsPoints + audit.safetyStatsPoints} documented points`)}
      </div>
      <div class="invoice-actions">
        <a class="primary-btn" href="/api/reports/audit-package" target="_blank" rel="noreferrer">Export audit package</a>
        <button class="secondary-btn" data-workflow-action="Documents" data-workflow-id="${state.selectedProjectId}">Review safety documents</button>
      </div>
    </section>
  `;
}

function auditItem(label, status, detail) {
  return `
    <article>
      <div class="card-topline">
        <h3>${label}</h3>
        <span class="status ${statusClass(status)}">${status}</span>
      </div>
      <p>${detail}</p>
    </article>
  `;
}

function renderDashboard() {
  const projects = scopedRows("projects");
  const invoices = scopedRows("invoices");
  const safety = scopedRows("safety");
  const dailies = scopedRows("dailies");
  const revenue = sum(projects, "estimatedRevenue");
  const forecastCost = sum(projects, "forecastCost");
  const retainage = sum(invoices, "retainage10");
  const activeRisks = safety.filter(item => item.status !== "Closed").length;
  const blockedDailies = dailies.filter(daily => daily.jsa === "Blocked").length;
  const squanScore = Math.max(0, 100 - activeRisks * 4 - blockedDailies * 3);
  const paymentFollowUps = paymentFollowUpRows();
  const retainageRows = retainageReleaseRows();
  const cashSummary = cashForecastSummary();

  return `
    ${renderRoleLanding()}
    ${state.role === "Admin" ? renderGuidedWorkflow("Owner daily review", [
      ["Review exceptions", "Check maps losing margin, blocked field work, open safety items, and expiring people/equipment requirements.", "Review Tasks", "Tasks", "", "Open"],
      ["Check billing and cash", "Review invoice packages due this week, AR, retainage releases, disputes, and pay-when-paid notes.", "Open Billing", "Billing", "", "Needs Review"],
      ["Confirm field progress", "Open active maps and make sure dailies, photos, production, and blockers are current.", "Open Maps", "Project & Map Hub", state.selectedProjectId || "", "Ready"],
      ["Export audit evidence", "Print executive, billing, and safety packets when SQUAN or year-end audit support is needed.", "Open Reports", "Reports", "", "Ready"]
    ]) : ""}
    ${renderErpSpineHomeSummary(projects)}
    <section class="metrics">
      ${metric("Forecast margin", `${Math.round(((revenue - forecastCost) / revenue) * 100)}%`, `${currency(revenue - forecastCost)} forecast gross profit`)}
      ${metric("13-week cash", currency(cashSummary.next13Total), `${currency(cashSummary.atRisk)} at risk`)}
      ${metric("Retainage outstanding", currency(retainage), "Tracked by 12-month release date")}
      ${metric("SQUAN score estimate", `${squanScore} pts`, "Protects A-rating and payment timing")}
      ${metric("Open safety items", activeRisks, "Near misses, inspections, chargebacks")}
    </section>
    ${state.role === "Admin" ? renderFinancialCloseoutHomeDashboard(projects) : ""}
    ${state.role === "Admin" ? renderBillingCloseoutHomeDashboard(projects) : ""}
    ${state.role === "Admin" ? renderPackageBuildHomeDashboard(projects) : ""}
    ${state.role === "Admin" ? renderCashForecastPanel({ compact: true }) : ""}
    ${state.role === "Admin" ? renderPaymentFollowUpQueue(paymentFollowUps, { compact: true }) : ""}
    ${state.role === "Admin" ? renderRetainageReleaseQueue(retainageRows, { compact: true }) : ""}
    <section class="grid">
      ${renderProjectCards()}
      <div class="panel">
        <div class="panel-header">
          <h2>Today at 4:05 PM</h2>
          <span>Auto outputs from field closeout</span>
        </div>
        <div class="timeline">
          ${[
            "SQUAN Daily Production Report generated",
            "SOT submitted and archived to project folder",
            "Crew timesheet finalized for payroll",
            "SQUAN material consumption deducted",
            "Map production and margin recalculated",
            "Near miss routed to Safety with a corrective-action owner"
          ].map(text => `<div class="timeline-item"><span></span><p>${text}</p></div>`).join("")}
        </div>
      </div>
    </section>
  `;
}

function packageBuildRows(projects = scopedRows("projects")) {
  return projects.map(project => {
    const gate = billingPackageBuildGate(project);
    const tasks = (state.data.tasks || []).filter(task => task.project === project.id && task.source === "Invoice package build gate" && task.status !== "Closed");
    return { project, gate, tasks };
  }).sort((a, b) => Number(a.gate.ready) - Number(b.gate.ready) || b.gate.blockers.length - a.gate.blockers.length);
}

function renderPackageBuildHomeDashboard(projects = scopedRows("projects")) {
  const rows = packageBuildRows(projects);
  const blocked = rows.filter(row => !row.gate.ready);
  const ready = rows.filter(row => row.gate.ready);
  if (!rows.length) return "";
  return `
    <section class="panel package-build-home">
      <div class="panel-header">
        <div>
          <h2>Invoice package build guard</h2>
          <p>Shows which Maps can be prepared for SQUAN and which inputs are still blocking Billing.</p>
        </div>
        <span>${ready.length} ready · ${blocked.length} blocked</span>
      </div>
      <div class="packet-home-metrics">
        ${metric("Ready to build", ready.length, "Package prep can proceed")}
        ${metric("Blocked", blocked.length, "Needs field/evidence/time cleanup")}
        ${metric("Open blocker tasks", sum(rows.map(row => ({ count: row.tasks.length })), "count"), "Auto-linked to guard items")}
      </div>
      <div class="packet-home-list">
        ${rows.slice(0, 5).map(row => `
          <article>
            <span class="status ${statusClass(row.gate.status)}">${row.gate.status}</span>
            <div>
              <strong>${row.project.map || row.project.id}</strong>
              <small>${row.gate.ready ? "Ready for SQUAN package preparation." : `Blocking: ${row.gate.blockers.map(item => item.label).join(", ")}`}</small>
              <small>${row.tasks.length} open build blocker task(s).</small>
            </div>
            <div class="daily-row-actions">
              <button class="secondary-btn" data-workflow-action="Billing" data-workflow-id="${row.project.id}" data-workflow-focus="Invoice package">Billing</button>
              ${row.tasks[0] ? `<button class="secondary-btn" data-task-open="${row.tasks[0].id}">Task</button>` : ""}
            </div>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function renderRoleLanding() {
  if (state.role === "Foreman") {
    const daily = scopedRows("dailies")[0];
    if (!daily) return `
      <section class="role-panel">
        <div>
          <span class="eyebrow">Foreman start screen</span>
          <h2>No assigned dailies</h2>
          <p>There are no field dailies assigned to this foreman role yet.</p>
        </div>
        <button class="primary-btn" data-view-shortcut="field">Open Field Daily</button>
      </section>
    `;
    const project = state.data.projects.find(item => item.id === daily.project);
    return `
      <section class="role-panel">
        <div>
          <span class="eyebrow">Foreman start screen</span>
          <h2>${project.id} - ${project.scope}</h2>
          <p>${daily.crew} has a clear JSA, current 811, ${daily.laborHours} labor hours logged, and closeout outputs ready for review.</p>
        </div>
        <button class="primary-btn" data-view-shortcut="field">Open Field Daily</button>
      </section>
    `;
  }

  if (state.role === "Billing") {
    const dueSoon = scopedRows("projects").filter(project => {
      const days = daysUntil(project.billBy);
      return days !== null && days <= 14;
    }).length;
    return `
      <section class="role-panel">
        <div>
          <span class="eyebrow">Office billing queue</span>
          <h2>${dueSoon} map billing windows need attention</h2>
          <p>Invoice packages are organized around dailies, SOT forms, as-builts, retainage, and pay-when-paid notes.</p>
        </div>
        <button class="primary-btn" data-view-shortcut="money">Open Billing</button>
      </section>
    `;
  }

  if (state.role === "Operations") {
    return `
      <section class="role-panel">
        <div>
          <span class="eyebrow">Operations queue</span>
          <h2>Map schedule, crews, production, and blockers</h2>
          <p>${roleConfig.Operations.description}</p>
        </div>
        <button class="primary-btn" data-view-shortcut="projects">Open Maps</button>
      </section>
    `;
  }

  if (state.role === "Safety/Compliance") {
    return `
      <section class="role-panel">
        <div>
          <span class="eyebrow">Safety and compliance queue</span>
          <h2>Certs, inspections, incidents, and audit readiness</h2>
          <p>${roleConfig["Safety/Compliance"].description}</p>
        </div>
        <button class="primary-btn" data-view-shortcut="risk">Open Safety</button>
      </section>
    `;
  }

  return `
    <section class="role-panel">
      <div>
        <span class="eyebrow">Ronald command view</span>
        <h2>Profit, cash, compliance, and SQUAN score in one pass</h2>
        <p>Use this view for Sunday-night operating review across active maps, safety items, cert expirations, and retainage.</p>
      </div>
      <button class="primary-btn" data-view-shortcut="projects">Open Maps</button>
    </section>
  `;
}

function renderAdminSettings() {
  const company = state.data.company || {};
  const rules = scopedRows("contractRules");
  const users = scopedRows("users");
  const roles = scopedRows("roles");
  const costCodes = scopedRows("costCodes");
  const unitPrices = scopedRows("unitPrices");
  const audit = (state.data.auditLog || []).slice().reverse();
  return `
    ${renderRoleScreenNotice("people", selectedProject)}
    <section class="metrics">
      ${metric("Company", company.name || "Jackson Telcom", company.primaryCustomer ? `Primary customer: ${company.primaryCustomer}` : "Company profile")}
      ${metric("Contract rules", rules.length, "Customer-driven workflow controls")}
      ${metric("Users / roles", `${users.length} / ${roles.length}`, "Access and module permissions")}
      ${metric("Audit events", audit.length, "Logins, workflow submits, record changes")}
    </section>
    ${renderDataControlCenter()}
    ${renderCashControlsSettings(company)}
    ${renderCloseoutReadinessSlaSettings(company)}
    ${renderDailyPackageSlaSettings(company)}
    <section class="settings-grid">
      ${renderSettingsPanel("Company Profile", [
        ["Company", company.name],
        ["Primary customer", company.primaryCustomer],
        ["Default burden", `${company.defaultBurdenPercent || 0}%`],
        ["Document standard", company.documentStandard],
        ["Operating scenario", company.operatingScenario]
      ])}
      ${rules.map(rule => renderSettingsPanel(`${rule.customer} Contract Rules`, [
        ["Daily / SOT SLA", `${rule.dailyDueHours} hours`],
        ["Invoice window", `${rule.invoiceWindowDays} days`],
        ["Retainage", `${rule.retainagePercent}% for ${rule.retainageReleaseMonths} months`],
        ["Required invoice docs", rule.requiredInvoiceDocs],
        ["Safety score minimum", `${rule.safetyScoreMinimum} pts`],
        ["Background checks", `${rule.backgroundScopeYears}-year scope / ${rule.backgroundRefreshYears}-year refresh`],
        ["Pay when paid", rule.payWhenPaid],
        ["COI payment hold", rule.coiPaymentHold]
      ], "contractRules", rule.id)).join("")}
    </section>
    ${renderUserRoleAdministration(users, roles)}
    ${renderCrewSetupAdministration()}
    <section class="settings-grid">
      <div class="panel settings-panel">
        <div class="panel-header">
          <h2>Cost codes</h2>
          <span>${costCodes.length} codes</span>
        </div>
        <div class="settings-table compact">
          ${costCodes.map(code => `
            <article>
              <strong>${code.id}</strong>
              <span>${code.name}</span>
              <small>${code.category}</small>
            </article>
          `).join("")}
        </div>
      </div>
      <div class="panel settings-panel">
        <div class="panel-header">
          <h2>Unit price book</h2>
          <span>${unitPrices.length} unit prices</span>
        </div>
        <div class="settings-table compact">
          ${unitPrices.map(price => `
            <article>
              <strong>${price.id}</strong>
              <span>${price.description}</span>
              <small>${currency(price.price)} / ${price.unit}</small>
            </article>
          `).join("")}
        </div>
      </div>
    </section>
    <section class="panel settings-panel">
      <div class="panel-header">
        <h2>Audit / change log</h2>
        <span>${audit.length} events</span>
      </div>
      <div class="audit-log">
        ${audit.map(item => `
          <article>
            <strong>${item.action}</strong>
            <span>${formatDateTime(item.at)}</span>
            <code>${JSON.stringify(item.detail || {})}</code>
          </article>
        `).join("") || `<div class="empty">No audit events yet.</div>`}
      </div>
    </section>
  `;
}

function renderDataControlCenter() {
  const counts = workflowRecordCounts();
  const collections = [
    ["Maps", "projects"],
    ["Tasks", "tasks"],
    ["Documents", "documents"],
    ["Dailies", "dailies"],
    ["Time entries", "timeEntries"],
    ["Invoices", "invoices"],
    ["Safety items", "safety"],
    ["Packet locks", "packetLocks"],
    ["Audit events", "auditLog"]
  ];
  const stale = localStorage.getItem("jackson-syncerp-data-stale") === "true";
  return `
    <section class="panel data-control-center">
      <div class="panel-header">
        <h2>Data controls</h2>
        <span>${state.apiOnline ? "Server API active" : "Local browser draft"}</span>
      </div>
      <div class="data-control-grid">
        <article class="data-control-card primary">
          <span class="eyebrow">Save status</span>
          <h3>${state.apiOnline ? "Server synced with local backup" : "Saved in this browser"}</h3>
          <p>${state.saveMessage}. Last local save ${formatShortDateTime(state.lastSavedAt) || "not recorded"}${state.lastSyncedAt ? `; last server sync ${formatShortDateTime(state.lastSyncedAt)}` : ""}.</p>
          <div class="data-control-actions">
            <button class="primary-btn" data-data-action="sync-server">Sync server</button>
            <button class="secondary-btn" data-data-action="download-json">Download local JSON</button>
          </div>
        </article>
        <article class="data-control-card">
          <span class="eyebrow">Demo reset</span>
          <h3>Reset local demo data</h3>
          <p>Clears browser edits and reloads the current seed data. This does not erase the server database.</p>
          <div class="data-control-actions">
            <button class="secondary-btn danger-action" data-data-action="reset-local">Reset local demo data</button>
            <button class="secondary-btn" data-data-action="clear-stale" ${stale ? "" : "disabled"}>Clear schema notice</button>
          </div>
        </article>
        <article class="data-control-card">
          <span class="eyebrow">Generated workflow records</span>
          <h3>${counts.dailies + counts.forms + counts.photos + counts.invoices} records</h3>
          <p>Field daily and billing workflows create downstream evidence records automatically.</p>
          <dl class="data-control-counts">
            <div><dt>Dailies</dt><dd>${counts.dailies}</dd></div>
            <div><dt>Forms</dt><dd>${counts.forms}</dd></div>
            <div><dt>Photos</dt><dd>${counts.photos}</dd></div>
            <div><dt>Invoices</dt><dd>${counts.invoices}</dd></div>
          </dl>
        </article>
      </div>
      <div class="settings-table compact data-collection-table">
        ${collections.map(([label, key]) => `
          <article>
            <strong>${label}</strong>
            <span>${(state.data[key] || []).length} records</span>
            <small>${key}</small>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function renderCashControlsSettings(company) {
  const delays = company.cashScenarioDelays || {};
  const canEdit = state.role === "Admin";
  const disabled = canEdit ? "" : "disabled";
  return `
    <section class="panel settings-panel cash-controls-settings">
      <div class="panel-header">
        <div>
          <h2>Admin cash controls</h2>
          <p>These values drive the cash forecast, scenario model, and work-approval threshold.</p>
        </div>
        <span>${currency(company.cashOnHand || 0)} cash on hand</span>
      </div>
      <div class="cash-controls-form">
        <label>
          <span>Cash on hand</span>
          <input id="cashOnHandInput" type="number" min="0" step="100" value="${Number(company.cashOnHand || 0)}" ${disabled}>
        </label>
        <label>
          <span>Weekly overhead</span>
          <input id="weeklyOverheadInput" type="number" min="0" step="100" value="${Number(company.weeklyOverhead || 0)}" ${disabled}>
        </label>
        <label>
          <span>Minimum cash threshold</span>
          <input id="minimumCashThresholdInput" type="number" min="0" step="100" value="${Number(company.minimumCashThreshold || 0)}" ${disabled}>
        </label>
        <label>
          <span>Baseline delay days</span>
          <input id="cashDelayBaselineInput" type="number" min="0" step="1" value="${Number(delays.baseline ?? 0)}" ${disabled}>
        </label>
        <label>
          <span>Delay scenario 1</span>
          <input id="cashDelay15Input" type="number" min="0" step="1" value="${Number(delays.delay15 ?? 15)}" ${disabled}>
        </label>
        <label>
          <span>Delay scenario 2</span>
          <input id="cashDelay30Input" type="number" min="0" step="1" value="${Number(delays.delay30 ?? 30)}" ${disabled}>
        </label>
        <label>
          <span>Delay scenario 3</span>
          <input id="cashDelay45Input" type="number" min="0" step="1" value="${Number(delays.delay45 ?? 45)}" ${disabled}>
        </label>
      </div>
      <div class="invoice-actions">
        ${canEdit ? `<button class="primary-btn" data-save-cash-controls>Save cash controls</button>` : `<span class="readiness-note">Only Admin can edit cash controls.</span>`}
        <button class="secondary-btn" data-workflow-action="Billing">Open cash forecast</button>
      </div>
      ${renderCashControlHistory(company)}
    </section>
  `;
}

function renderCashControlHistory(company) {
  const rows = [
    ...(company.cashControlHistory || []).map(item => ({ source: "Settings", ...item })),
    ...(state.data.auditLog || [])
      .filter(item => item.action === "settings.cash-controls")
      .map(item => ({ source: "Audit", at: item.at, by: item.detail?.by, ...item.detail }))
  ].sort((a, b) => String(b.at || "").localeCompare(String(a.at || "")));
  return `
    <div class="cash-control-history">
      <div class="section-heading">
        <h3>Cash control change history</h3>
        <span>${rows.length} change(s)</span>
      </div>
      <div class="settings-table compact">
        ${rows.slice(0, 8).map(item => `
          <article>
            <strong>${formatDateTime(item.at)}</strong>
            <span>${item.by || "System"} set cash ${currency(item.cashOnHand || 0)}, overhead ${currency(item.weeklyOverhead || 0)}, threshold ${currency(item.minimumCashThreshold || 0)}</span>
            <small>Delays: ${Number(item.cashScenarioDelays?.baseline ?? 0)} / ${Number(item.cashScenarioDelays?.delay15 ?? 15)} / ${Number(item.cashScenarioDelays?.delay30 ?? 30)} / ${Number(item.cashScenarioDelays?.delay45 ?? 45)} days</small>
          </article>
        `).join("") || `<div class="empty">No cash control changes recorded.</div>`}
      </div>
    </div>
  `;
}

function closeoutReadinessSlaSettings(company = state.data.company || {}) {
  const settings = company.closeoutReadinessSla || {};
  return {
    warningDays: Number(settings.warningDays ?? 2),
    escalationDays: Number(settings.escalationDays ?? 3),
    handoffAgingDays: Number(settings.handoffAgingDays ?? 2),
    ownerMismatchEscalates: settings.ownerMismatchEscalates || "Yes"
  };
}

