function renderUserRoleAdministration(users, roles) {
  const roleRows = roles.length ? roles : Object.keys(roleConfig).map(id => ({ id }));
  const roleCounts = roleRows.map(role => ({
    role,
    users: users.filter(user => user.role === role.id).length
  }));
  return `
    <section class="panel user-role-admin">
      <div class="panel-header">
        <h2>User and role administration</h2>
        <span>${users.length} users · ${roleRows.length} roles</span>
      </div>
      <div class="role-card-grid">
        ${roleCounts.map(({ role, users: userCount }) => renderRoleAccessCard(role, userCount)).join("")}
      </div>
      <div class="user-access-list">
        <div class="section-heading">
          <h3>System users</h3>
          <div class="section-actions">
            <span>${users.length} login records</span>
            <button class="primary-btn" data-create-user>New user</button>
          </div>
        </div>
        ${users.map(user => renderUserAccessRow(user)).join("")}
      </div>
      ${renderRolePermissionMatrix(roleRows)}
    </section>
  `;
}

function renderRoleAccessCard(role, userCount) {
  const config = roleConfig[role.id] || role;
  const views = config.views || role.views || [];
  const create = config.create || role.create || [];
  const defaultView = config.defaultView || role.defaultView || "dashboard";
  return `
    <article class="role-access-card">
      <div class="card-topline">
        <h3>${role.id}</h3>
        <span class="status ${userCount ? "ok" : "warn"}">${userCount} users</span>
      </div>
      <p>${role.purpose || config.description || "Role access profile"}</p>
      <dl>
        <div><dt>Landing view</dt><dd>${navLabel(defaultView)}</dd></div>
        <div><dt>Visible workflows</dt><dd>${views.map(navLabel).join(", ")}</dd></div>
        <div><dt>Can create</dt><dd>${create.map(collectionLabel).join(", ") || "Read only"}</dd></div>
      </dl>
      <button class="secondary-btn" data-open-record="roles" data-record-id="${role.id}">View role record</button>
    </article>
  `;
}

function renderUserAccessRow(user) {
  const config = roleConfig[user.role] || {};
  const defaultView = user.defaultView || config.defaultView || "dashboard";
  const visible = config.views || [];
  const userStatus = user.status || "Active";
  const scope = [
    user.crew ? `Crew ${user.crew.replace("Crew ", "")}` : "",
    user.personId ? `Person ${user.personId}` : "",
    user.fieldType || ""
  ].filter(Boolean).join(" · ") || "Company workspace";
  return `
    <article class="user-access-row">
      <div>
        <strong>${user.name}</strong>
        <span>${user.email}</span>
      </div>
      <div>
        <small>Role</small>
        <strong>${user.role}</strong>
      </div>
      <div>
        <small>Landing view</small>
        <strong>${navLabel(defaultView)}</strong>
      </div>
      <div>
        <small>Scope</small>
        <strong>${scope}</strong>
      </div>
      <div>
        <small>Access</small>
        <span>${visible.length} workflows</span>
      </div>
      <span class="status ${statusClass(userStatus)}">${userStatus}</span>
      <div class="user-access-actions">
        <button class="secondary-btn" data-user-access="${user.id}">Edit access</button>
        ${user.personId ? "" : `<button class="secondary-btn" data-create-person-for-user="${user.id}">Create person</button>`}
        <button class="secondary-btn" data-open-record="users" data-record-id="${user.id}">View</button>
      </div>
    </article>
  `;
}

function renderRolePermissionMatrix(roles) {
  const workflows = navItems.filter(item => item.key !== "settings" || roles.some(role => role.id === "Admin"));
  return `
    <div class="permission-matrix">
      <div class="section-heading">
        <h3>Workflow access matrix</h3>
        <span>${workflows.length} workflows</span>
      </div>
      <div class="permission-table">
        <div class="permission-row header">
          <strong>Role</strong>
          ${workflows.map(item => `<span>${item.label}</span>`).join("")}
        </div>
        ${roles.map(role => {
          const config = roleConfig[role.id] || role;
          const views = config.views || role.views || [];
          const create = config.create || role.create || [];
          return `
            <div class="permission-row">
              <strong>${role.id}</strong>
              ${workflows.map(item => {
                const allowed = views.includes(item.key);
                const creates = canRoleCreateForView(create, item.key);
                return `<span class="${allowed ? "allowed" : "blocked"}">${allowed ? (creates ? "Edit" : "View") : "-"}</span>`;
              }).join("")}
            </div>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function navLabel(key) {
  return navItems.find(item => item.key === key)?.label || labelize(key || "");
}

function collectionLabel(key) {
  return {
    projects: "Maps",
    tasks: "Tasks",
    documents: "Documents",
    dailies: "Field dailies",
    timeEntries: "Crew time",
    people: "People",
    equipment: "Equipment",
    invoices: "Invoices",
    packageSnapshots: "Prepared package snapshots",
    safety: "Safety",
    contractRules: "Contract rules"
  }[key] || labelize(key || "");
}

function canRoleCreateForView(create, view) {
  const createMap = {
    projects: "projects",
    tasks: "tasks",
    documents: "documents",
    field: "dailies",
    time: "timeEntries",
    people: "people",
    equipment: "equipment",
    money: "invoices",
    risk: "safety",
    settings: "contractRules"
  };
  return create.includes(createMap[view]);
}

function renderCrewSetupAdministration() {
  const crews = state.data.crews || [];
  const people = state.data.people || [];
  const users = state.data.users || [];
  const unassigned = people.filter(person => !person.crew);
  return `
    <section class="panel crew-setup-admin">
      <div class="panel-header">
        <h2>Crew setup</h2>
        <span>${crews.length} crews · ${unassigned.length} unassigned people</span>
      </div>
      <div class="crew-setup-grid">
        ${crews.map(crew => renderCrewSetupCard(crew, people, users)).join("") || `<div class="empty">No crews configured.</div>`}
      </div>
      ${unassigned.length ? `
        <div class="unassigned-people">
          <div class="section-heading">
            <h3>Unassigned people</h3>
            <span>${unassigned.length} records</span>
          </div>
          <div class="crew-member-strip">
            ${unassigned.map(person => `<button class="secondary-btn" data-open-record="people" data-record-id="${person.id}">${person.name} · ${person.role}</button>`).join("")}
          </div>
        </div>
      ` : ""}
    </section>
  `;
}

function renderCrewSetupCard(crew, people, users) {
  const members = crewMemberRecords(crew, people);
  const linkedUsers = members.filter(person => users.some(user => user.personId === person.id));
  const blocked = members.filter(person => person.compliance === "Blocked");
  const expiring = members.filter(person => {
    const days = daysUntil(person.nextExpiration);
    return days !== null && days <= 30;
  });
  const projects = (state.data.projects || []).filter(project => project.crew === crew.id);
  const readyStatus = blocked.length ? "Blocked" : expiring.length ? "Needs Review" : members.length ? "Clear" : "Needs Setup";
  return `
    <article class="crew-setup-card">
      <div class="card-topline">
        <h3>${crew.id}</h3>
        <span class="status ${statusClass(readyStatus)}">${readyStatus}</span>
      </div>
      <p>${crew.status || "Crew status not set"}</p>
      <dl>
        <div><dt>Foreman</dt><dd>${crew.foreman || "Unassigned"}</dd></div>
        <div><dt>Members</dt><dd>${members.length}</dd></div>
        <div><dt>User links</dt><dd>${linkedUsers.length}/${members.length}</dd></div>
        <div><dt>Assigned maps</dt><dd>${projects.map(project => project.map || project.id).join(", ") || "None"}</dd></div>
      </dl>
      <div class="crew-member-list">
        ${members.map(person => `
          <span>
            <strong>${person.name}</strong>
            <small>${person.role} · ${person.compliance || person.status || "Pending"}</small>
          </span>
        `).join("") || `<div class="empty">No members assigned.</div>`}
      </div>
      <button class="primary-btn" data-crew-setup="${crew.id}">Edit crew</button>
    </article>
  `;
}

function renderMapCrewAssignmentControl(project, crewGate, equipmentGate) {
  if (!["Admin", "Operations"].includes(state.role)) return "";
  const crews = state.data.crews || [];
  const currentCrew = crews.find(crew => crew.id === project.crew);
  const assignedMaps = (state.data.projects || []).filter(item => item.crew === project.crew && item.id !== project.id && !["Completed / Billed", "Closed"].includes(item.status));
  return `
    <div class="map-crew-assignment">
      <div>
        <label for="mapCrewSelect">Assigned crew</label>
        <select id="mapCrewSelect" data-current-crew="${project.crew}">
          ${crews.map(crew => `<option value="${crew.id}" ${crew.id === project.crew ? "selected" : ""}>${crew.id} - ${crew.status || "Available"}</option>`).join("")}
        </select>
      </div>
      <div class="assignment-preview">
        <span>Current foreman<strong>${currentCrew?.foreman || "Unassigned"}</strong></span>
        <span>Crew gate<strong>${crewGate.status}</strong></span>
        <span>Equipment gate<strong>${equipmentGate.status}</strong></span>
        <span>Other active maps<strong>${assignedMaps.length}</strong></span>
      </div>
      <div class="assignment-actions">
        <button class="primary-btn" data-map-crew-save="${project.id}">Save crew assignment</button>
        <button class="secondary-btn" data-workflow-action="People & Compliance" data-workflow-id="${project.id}">Review crew blockers</button>
        <button class="secondary-btn" data-workflow-action="Equipment" data-workflow-id="${project.id}">Review equipment</button>
      </div>
    </div>
  `;
}

function renderMapEquipmentAssignmentControl(project, equipmentGate) {
  if (!["Admin", "Operations"].includes(state.role)) return "";
  const equipment = state.data.equipment || [];
  const assigned = equipment.filter(item => item.assigned === project.id || item.assigned === project.crew);
  const blocked = assigned.filter(item => {
    const days = daysUntil(item.inspectionDue);
    return item.status === "Unavailable" || (days !== null && days < 0);
  });
  return `
    <div class="map-equipment-assignment">
      <div class="section-heading">
        <h3>Map equipment assignment</h3>
        <span class="status ${statusClass(equipmentGate.status)}">${equipmentGate.status}</span>
      </div>
      <div class="equipment-assignment-layout">
        <div class="equipment-picker">
          ${equipment.map(item => {
            const selected = item.assigned === project.id || item.assigned === project.crew;
            const days = daysUntil(item.inspectionDue);
            const risk = item.status === "Unavailable" || (days !== null && days < 0) ? "Blocked" : days !== null && days <= 30 ? "Due Soon" : item.status;
            return `
              <label class="equipment-option ${selected ? "selected" : ""}">
                <input type="checkbox" name="mapEquipment" value="${item.id}" ${selected ? "checked" : ""}>
                <span>
                  <strong>${item.asset}</strong>
                  <small>${item.id} · ${item.assigned || "Unassigned"} · ${item.inspectionDue} · ${risk}</small>
                </span>
              </label>
            `;
          }).join("")}
        </div>
        <div class="equipment-assignment-summary">
          <span>Assigned assets<strong>${assigned.length}</strong></span>
          <span>Blocked assets<strong>${blocked.length}</strong></span>
          <span>Equipment hours<strong>${sum((state.data.dailyEquipment || []).filter(item => item.project === project.id), "hours").toFixed(1)}</strong></span>
          <span>Gate result<strong>${equipmentGate.status}</strong></span>
        </div>
      </div>
      <div class="assignment-actions">
        <button class="primary-btn" data-map-equipment-save="${project.id}">Save equipment assignment</button>
        <button class="secondary-btn" data-workflow-action="Equipment" data-workflow-id="${project.id}">Open Equipment</button>
      </div>
    </div>
  `;
}

function crewMemberRecords(crew, people = state.data.people || []) {
  const memberIds = new Set(crew.members || []);
  return people.filter(person => person.crew === crew.id || memberIds.has(person.id));
}

