function bindUserRoleLandingRefresh() {
  document.getElementById("userRole").addEventListener("change", event => {
    const nextRole = event.target.value;
    const defaultView = roleConfig[nextRole]?.defaultView || "dashboard";
    const viewSelect = document.getElementById("userDefaultView");
    viewSelect.innerHTML = navItems
      .filter(item => (roleConfig[nextRole]?.views || []).includes(item.key))
      .map(item => `<option value="${item.key}" ${item.key === defaultView ? "selected" : ""}>${item.label}</option>`)
      .join("");
    const preview = document.getElementById("roleAccessPreview");
    if (preview) preview.textContent = (roleConfig[nextRole]?.views || []).map(navLabel).join(", ");
  });
}

