async function saveNewUser() {
  const form = new FormData(document.getElementById("newUserForm"));
  const name = String(form.get("name") || "").trim();
  const email = String(form.get("email") || "").trim().toLowerCase();
  if (!name || !email) {
    alert("Name and email are required to create a user.");
    return;
  }
  if ((state.data.users || []).some(user => String(user.email).toLowerCase() === email)) {
    alert("A user with this email already exists.");
    return;
  }
  const now = new Date().toISOString();
  let linkedPersonId = form.get("personId");
  let createdPerson = null;
  if (!linkedPersonId && form.get("createPersonRecord") === "on") {
    createdPerson = createPersonFromUser({ name }, form, now);
    linkedPersonId = createdPerson.id;
  }
  const user = {
    id: nextUserId(),
    name,
    email,
    role: form.get("role"),
    defaultView: form.get("defaultView"),
    status: form.get("status"),
    crew: form.get("crew"),
    personId: linkedPersonId,
    fieldType: form.get("fieldType"),
    notes: form.get("note") || "Created from Settings user administration.",
    activityLog: [{
      at: now,
      by: state.user?.name || "Admin",
      note: form.get("note") || "User created."
    }],
    createdAt: now,
    modifiedAt: now
  };
  if (createdPerson) {
    state.data.people = state.data.people || [];
    state.data.people.push(createdPerson);
  }
  state.data.users = state.data.users || [];
  state.data.users.push(user);
  appendAuditLocal("user.create", {
    user: user.id,
    person: linkedPersonId || "",
    role: user.role,
    defaultView: user.defaultView,
    status: user.status,
    by: state.user?.name || "Admin"
  });
  if (createdPerson) appendAuditLocal("people.create-from-user", { person: createdPerson.id, user: user.id, by: state.user?.name || "Admin" });
  persist("User created");
  if (createdPerson) await saveToApi("people", createdPerson, true);
  await saveToApi("users", user, true);
  closeDrawer();
  render();
}

function createPersonFromUser(user, form, now) {
  const fieldType = form.get("fieldType");
  const personRole = String(form.get("personRole") || "").trim() || defaultPersonRole(form.get("role"), fieldType);
  const certs = String(form.get("personCerts") || "").trim() || defaultCertsForFieldType(fieldType);
  return {
    id: nextPersonId(),
    name: user.name,
    role: personRole,
    crew: form.get("crew"),
    certs,
    nextExpiration: dateFromToday(365),
    compliance: "Pending Review",
    backgroundRefresh: dateFromToday(1095),
    drugTest: "Needs setup",
    workersComp: String(form.get("workersComp") || "").trim() || defaultWorkersComp(fieldType),
    notes: "Created from Settings user setup. Safety/Compliance must verify certifications, background check, drug test, and acknowledgments before field release.",
    activityLog: [{
      at: now,
      by: state.user?.name || "Admin",
      note: "People compliance record created with user login."
    }],
    status: "Pending Review",
    createdAt: now,
    modifiedAt: now,
    owner: user.name
  };
}

async function createPersonForExistingUser(userId) {
  const index = (state.data.users || []).findIndex(user => user.id === userId);
  if (index === -1) return;
  const user = state.data.users[index];
  const existingPerson = (state.data.people || []).find(person => person.name === user.name);
  if (existingPerson) {
    state.data.users[index] = {
      ...user,
      personId: existingPerson.id,
      modifiedAt: new Date().toISOString(),
      activityLog: [...(user.activityLog || []), {
        at: new Date().toISOString(),
        by: state.user?.name || "Admin",
        note: `Linked to existing People record ${existingPerson.id}.`
      }]
    };
    appendAuditLocal("user.link-existing-person", { user: user.id, person: existingPerson.id, by: state.user?.name || "Admin" });
    persist("User linked to existing person");
    await saveToApi("users", state.data.users[index], false);
    render();
    return;
  }
  const now = new Date().toISOString();
  const formShim = new Map([
    ["role", user.role],
    ["fieldType", user.fieldType],
    ["crew", user.crew],
    ["personRole", ""],
    ["personCerts", ""],
    ["workersComp", ""]
  ]);
  const person = createPersonFromUser(user, formShim, now);
  state.data.people = state.data.people || [];
  state.data.people.push(person);
  state.data.users[index] = {
    ...user,
    personId: person.id,
    modifiedAt: now,
    activityLog: [...(user.activityLog || []), {
      at: now,
      by: state.user?.name || "Admin",
      note: `Created and linked People record ${person.id}.`
    }]
  };
  appendAuditLocal("people.create-from-existing-user", { person: person.id, user: user.id, by: state.user?.name || "Admin" });
  persist("People record created and linked");
  await saveToApi("people", person, true);
  await saveToApi("users", state.data.users[index], false);
  render();
}

function nextUserId() {
  const max = (state.data.users || []).reduce((highest, user) => {
    const match = String(user.id || "").match(/^U-(\d+)$/);
    return match ? Math.max(highest, Number(match[1])) : highest;
  }, 0);
  return `U-${String(max + 1).padStart(3, "0")}`;
}

function nextPersonId() {
  const max = (state.data.people || []).reduce((highest, person) => {
    const match = String(person.id || "").match(/^E-(\d+)$/);
    return match ? Math.max(highest, Number(match[1])) : highest;
  }, 0);
  return `E-${String(max + 1).padStart(3, "0")}`;
}

function dateFromToday(days) {
  const date = new Date(today);
  date.setDate(date.getDate() + days);
  return date.toISOString().slice(0, 10);
}

function defaultPersonRole(role, fieldType) {
  if (role === "Foreman") return "Foreman";
  if (fieldType === "Traffic Control") return "Traffic Control";
  if (fieldType === "Aerial") return "Ground Hand";
  if (fieldType === "Underground") return "Underground Crew Member";
  if (role === "Safety/Compliance") return "Safety Compliance";
  if (role === "Operations") return "Operations Coordinator";
  if (role === "Billing") return "Office Billing";
  return "Crew Member";
}

function defaultCertsForFieldType(fieldType) {
  return {
    "Traffic Control": "OSHA 10, Traffic Control, Flagger",
    Aerial: "OSHA 10, Aerial Awareness",
    Underground: "OSHA 10, Trenching Awareness",
    Safety: "OSHA 30, First Aid/CPR",
    Operations: "OSHA 10",
    Billing: "Office onboarding"
  }[fieldType] || "Needs certification setup";
}

function defaultWorkersComp(fieldType) {
  return {
    "Traffic Control": "7720",
    Aerial: "7600",
    Underground: "6217"
  }[fieldType] || "7600";
}

