async function saveUserAccess(userId) {
  const index = (state.data.users || []).findIndex(item => item.id === userId);
  if (index === -1) return;
  const form = new FormData(document.getElementById("userAccessForm"));
  const previous = state.data.users[index];
  const next = {
    ...previous,
    role: form.get("role"),
    defaultView: form.get("defaultView"),
    status: form.get("status"),
    crew: form.get("crew"),
    personId: form.get("personId"),
    fieldType: form.get("fieldType"),
    modifiedAt: new Date().toISOString(),
    activityLog: [
      ...(previous.activityLog || []),
      {
        at: new Date().toISOString(),
        by: state.user?.name || "Admin",
        note: form.get("note") || `Access updated: ${previous.role} to ${form.get("role")}`
      }
    ]
  };
  state.data.users[index] = next;
  appendAuditLocal("user.access-update", {
    user: next.id,
    role: next.role,
    defaultView: next.defaultView,
    status: next.status,
    by: state.user?.name || "Admin"
  });
  persist("User access updated");
  await saveToApi("users", next, false);
  closeDrawer();
  render();
}

