function reportPacketRows(project) {
  const scopes = reportPrintScopes().filter(scope => scope !== "Full Report Set");
  return scopes.map(scope => {
    const checklist = project ? reportPacketChecklist(project, scope) : [];
    const ready = checklist.filter(item => item.ok).length;
    const lock = project ? currentPacketLock(project.id, scope) : null;
    const status = lock ? "Locked" : checklist.length && ready === checklist.length ? "Ready" : "Needs Review";
    const blockers = checklist.filter(item => !item.ok);
    return {
      scope,
      status,
      ready,
      total: checklist.length,
      lock,
      blockers,
      detail: lock ? `Finalized ${formatDateTime(lock.finalizedAt)} by ${lock.finalizedBy || "System"}.` : blockers.length ? blockers.map(item => item.label).join(", ") : "Ready to review, print, export, or finalize."
    };
  });
}

function renderReportPacketCommandCenter(project) {
  const rows = reportPacketRows(project);
  const active = rows.find(row => row.scope === state.reportPrintScope) || rows[0];
  const locked = rows.filter(row => row.status === "Locked").length;
  const ready = rows.filter(row => row.status === "Ready").length;
  const needsReview = rows.filter(row => row.status === "Needs Review").length;
  const packetSteps = [
    ["1", "Select packet", state.reportPrintScope || "Full Report Set", project ? `${project.map || project.id} selected.` : "Select a Map.", "Reports", state.reportPrintScope],
    ["2", "Review checklist", active?.status || "Needs Review", active ? `${active.ready}/${active.total} ready; ${active.detail}` : "No packet selected.", "Reports", state.reportPrintScope],
    ["3", "Resolve blockers", active?.blockers.length ? "Needs Review" : "Ready", active?.blockers.length ? active.blockers.map(item => item.label).join(", ") : "No packet blockers.", active?.blockers[0]?.action || "Reports", state.reportPrintScope],
    ["4", "Finalize / export", active?.lock ? "Locked" : active?.status || "Needs Review", active?.lock ? active.detail : "Finalize, print, or download after review.", "Reports", state.reportPrintScope],
    ["5", "Audit trail", "Tracked", `${locked} locked · ${ready} ready · ${needsReview} needing review.`, "Reports", "Packet audit"]
  ];
  return `
    <section class="panel report-packet-command-center">
      <div class="panel-header">
        <div>
          <h2>Audit packet command center</h2>
          <p>Choose the packet, review checklist readiness, resolve blockers, then print/export or finalize for submission.</p>
        </div>
        <span class="status ${statusClass(active?.status || "Needs Review")}">${active?.scope || state.reportPrintScope || "Full Report Set"} · ${active?.status || "Needs Review"}</span>
      </div>
      <div class="field-mobile-steps report-workflow-steps">
        ${packetSteps.map(step => `
          <button class="field-mobile-step ${statusClass(step[2])}" data-workflow-action="${step[4]}" data-workflow-id="${project?.id || ""}" data-workflow-focus="${step[5]}" data-report-scope="${step[5]}">
            <span>${step[0]}</span>
            <strong>${step[1]}</strong>
            <small>${step[3]}</small>
          </button>
        `).join("")}
      </div>
    </section>
  `;
}

function renderReportPacketPriorityQueue(projects, selectedProject) {
  const packetRows = reportPacketRows(selectedProject);
  const packetBlockers = packetRows
    .filter(row => row.blockers.length)
    .flatMap(row => row.blockers.slice(0, 3).map(item => ({
      title: `${row.scope}: ${item.label}`,
      detail: item.detail,
      status: "Needs Review",
      action: item.action || "Reports",
      scope: row.scope
    })));
  const reopenTasks = (state.data.tasks || [])
    .filter(task => task.source === "Packet reopen" && task.status !== "Closed" && (!selectedProject || task.project === selectedProject.id))
    .slice(0, 5)
    .map(task => ({
      title: `Packet reopen task: ${task.title}`,
      detail: `${task.project || "No Map"}; due ${task.dueDate || "not set"}; ${task.notes || ""}`,
      status: task.status,
      task,
      action: "Reports",
      scope: task.reopenScopes?.[0] || state.reportPrintScope
    }));
  const mismatchRows = packetScopeMismatchEvents()
    .filter(event => !selectedProject || event.detail?.project === selectedProject.id)
    .slice(0, 5)
    .map(event => ({
      title: "Packet scope mismatch",
      detail: event.detail?.reason || event.action || "Scope mismatch needs review.",
      status: "Needs Review",
      action: "Reports",
      scope: event.detail?.scope || state.reportPrintScope
    }));
  const rows = [...reopenTasks, ...mismatchRows, ...packetBlockers].slice(0, 12);
  return `
    <section class="panel report-priority-actions">
      <div class="panel-header">
        <div>
          <h2>Packet priority queue</h2>
          <p>Open packet tasks, scope mismatches, and checklist blockers that prevent clean submission or audit export.</p>
        </div>
        <span>${rows.length} item(s)</span>
      </div>
      <div class="packet-home-list">
        ${rows.map(row => `
          <article>
            <span class="status ${statusClass(row.status)}">${row.status}</span>
            <div>
              <strong>${row.title}</strong>
              <small>${row.detail}</small>
            </div>
            <div class="packet-home-actions">
              ${row.task ? `<button class="secondary-btn" data-task-open="${row.task.id}">Task</button>` : ""}
              <button class="secondary-btn" data-workflow-action="${row.action}" data-workflow-id="${selectedProject?.id || ""}" data-workflow-focus="${row.scope}" data-report-scope="${row.scope}">Open</button>
            </div>
          </article>
        `).join("") || `<p class="empty-state">No packet blocker is currently open.</p>`}
      </div>
    </section>
  `;
}

