function renderReportFocusedDetail(project, projects, exceptionProjects) {
  if (!state.workflowFocus && state.reportPrintScope === "Full Report Set") return "";
  const focus = String(state.workflowFocus || state.reportPrintScope || "").toLowerCase();
  const scope = state.reportPrintScope || "Full Report Set";
  const includesAny = (...terms) => terms.some(term => focus.includes(term) || scope.toLowerCase().includes(term));
  if (project && includesAny("billing packet")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${renderBillingPacketFinalizationHelper(project)}
      ${renderReportPacketChecklist(project)}
      ${renderPacketExportPreview(project)}
      ${renderBillingExportPackage(project)}
      ${renderReportPrintShell(project)}
    `;
  }
  if (project && includesAny("billing closeout")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${renderBillingTaskCloseoutReport(project)}
      ${renderReportPrintShell(project)}
    `;
  }
  if (project && includesAny("financial closeout")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${renderFinancialCloseoutFinalizationHelper(project)}
      ${renderReportPacketChecklist(project)}
      ${renderFinancialCloseoutReport(project)}
      ${renderReportPrintShell(project)}
    `;
  }
  if (project && includesAny("collections packet")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${renderCollectionsPacketFinalizationHelper(project)}
      ${renderCollectionsResponseDashboard({ compact: false })}
      ${renderCollectionsPacketReport()}
      ${renderReportPrintShell(project)}
    `;
  }
  if (includesAny("collections decision")) {
    return `
      ${project ? workflowFocusPanel(project, "Reports") : ""}
      ${renderCollectionsDecisionAuditReport()}
      ${project ? renderReportPrintShell(project) : ""}
    `;
  }
  if (project && includesAny("closeout package")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${renderReportPacketChecklist(project)}
      ${renderMapCloseoutPackage(project)}
      ${renderReportPrintShell(project)}
    `;
  }
  if (project && includesAny("exception")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${exceptionProjects.map(item => renderExceptionExportReport(item)).join("") || renderExceptionExportReport(project)}
      ${renderReportPrintShell(project)}
    `;
  }
  if (includesAny("retainage", "ar", "payment ledger")) {
    return `
      ${project ? workflowFocusPanel(project, "Reports") : ""}
      ${renderRetainageArExport()}
      ${project ? renderReportPrintShell(project) : ""}
    `;
  }
  if (project && includesAny("field capture")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${renderReportPacketChecklist(project)}
      ${renderFieldCaptureAuditReport(project)}
      ${renderReportPrintShell(project)}
    `;
  }
  if (project && includesAny("daily package")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${renderDailyPackageAuditReport(project)}
      ${renderCompletedFormsExportPackage(project)}
      ${renderReportPrintShell(project)}
    `;
  }
  if (project && includesAny("completed forms", "forms")) {
    return `
      ${workflowFocusPanel(project, "Reports")}
      ${renderCompletedFormsExportPackage(project)}
      ${renderReportPrintShell(project)}
    `;
  }
  if (includesAny("safety")) {
    return `
      ${project ? workflowFocusPanel(project, "Reports") : ""}
      ${renderSafetyAuditPackage()}
      ${project ? renderReportPrintShell(project) : ""}
    `;
  }
  if (includesAny("compliance")) {
    return `
      ${project ? workflowFocusPanel(project, "Reports") : ""}
      ${renderComplianceExportPackage()}
      ${project ? renderReportPrintShell(project) : ""}
    `;
  }
  if (includesAny("cash")) {
    return `
      ${project ? workflowFocusPanel(project, "Reports") : ""}
      ${renderCashForecastExportPacket()}
      ${project ? renderReportPrintShell(project) : ""}
    `;
  }
  if (includesAny("executive")) {
    return `
      ${project ? workflowFocusPanel(project, "Reports") : ""}
      ${renderExecutiveReport()}
      ${project ? renderErpSpineReport(project) : ""}
      ${project ? renderReportPrintShell(project) : ""}
    `;
  }
  if (includesAny("packet audit", "lock", "mismatch")) {
    return `
      ${project ? workflowFocusPanel(project, "Reports") : ""}
      ${renderPacketLockAuditDashboard(projects)}
      ${project ? renderPacketExportPreview(project) : ""}
      ${renderCsvExportLinks()}
    `;
  }
  if (includesAny("full report")) return renderFullReportSet(project, exceptionProjects);
  return "";
}

function renderReportSelectedPacketLane(project, projects) {
  if (!project) return renderPacketLockAuditDashboard(projects);
  return `
    <section class="panel report-selected-packet-lane">
      <div class="panel-header">
        <div>
          <h2>Selected packet lane</h2>
          <p>Default report view for the selected Map. Review checklist readiness, export preview, and packet lock status before printing.</p>
        </div>
        <span>${project.map || project.id} · ${state.reportPrintScope}</span>
      </div>
    </section>
    ${renderReportPacketChecklist(project)}
    ${renderPacketLockAuditDashboard(projects)}
    ${renderPacketExportPreview(project)}
    ${renderExportPackageCenter(project)}
  `;
}

function renderReportPrintShell(project) {
  if (!project) return "";
  return `
    ${renderReportCoverPage(project)}
    ${renderReportPrintFooter(project)}
  `;
}

function renderFullReportSet(project, exceptionProjects) {
  return `
    ${project ? renderReportPacketChecklist(project) : ""}
    ${project ? renderPacketExportPreview(project) : ""}
    ${project ? renderExportPackageCenter(project) : ""}
    ${project ? renderReportCoverPage(project) : ""}
    ${project ? renderReportPrintFooter(project) : ""}
    ${project ? renderErpSpineReport(project) : ""}
    ${renderExecutiveReport()}
    ${renderCashForecastExportPacket()}
    ${project ? renderBillingExportPackage(project) : ""}
    ${renderBillingTaskCloseoutReport(project)}
    ${renderFinancialCloseoutReport(project)}
    ${project ? renderMapCloseoutPackage(project) : ""}
    ${exceptionProjects.map(item => renderExceptionExportReport(item)).join("")}
    ${renderRetainageArExport()}
    ${renderCollectionsPacketReport()}
    ${renderCollectionsDecisionAuditReport()}
    ${project ? renderFieldCaptureAuditReport(project) : ""}
    ${project ? renderCompletedFormsExportPackage(project) : ""}
    ${renderComplianceExportPackage()}
    ${renderSafetyAuditPackage()}
    ${renderCsvExportLinks()}
  `;
}

function renderReportCoverPage(project) {
  const company = state.data.company || {};
  const scope = state.reportPrintScope || "Full Report Set";
  const exception = project.adminApprovals?.exception;
  const readiness = scopedRows("billingReadiness").find(item => item.project === project.id);
  return `
    <section class="panel report-section printable report-cover-page report-scope-cover">
      <div class="cover-brand">
        <span class="logo-mark">JT</span>
        <div>
          <strong>${company.name || "Jackson Telcom"}</strong>
          <small>${company.primaryCustomer || project.customer || "Customer"} operating packet</small>
        </div>
      </div>
      <div class="cover-title">
        <span>${scope}</span>
        <h1>${project.map || project.id}</h1>
        <p>${project.scope}</p>
      </div>
      <div class="cover-grid">
        <div><span>Map ID</span><strong>${project.id}</strong></div>
        <div><span>Customer</span><strong>${project.customer || company.primaryCustomer || "SQUAN"}</strong></div>
        <div><span>Status</span><strong>${project.status}</strong></div>
        <div><span>Generated</span><strong>${formatDateTime(new Date().toISOString())}</strong></div>
        <div><span>Prepared by</span><strong>${state.user?.name || "Jackson Telcom ERP"}</strong></div>
        <div><span>Billing readiness</span><strong>${readiness?.status || "Not Ready"}</strong></div>
        <div><span>Exception status</span><strong>${exception?.status || "No Exception"}</strong></div>
        <div><span>Print scope</span><strong>${scope}</strong></div>
      </div>
      <div class="signature-grid">
        ${signatureLine("Admin approval", "Name / signature / date")}
        ${signatureLine("Safety / Compliance review", "Name / signature / date")}
        ${signatureLine("Billing review", "Name / signature / date")}
        ${signatureLine("SQUAN / customer receipt", "Name / signature / date")}
      </div>
    </section>
  `;
}

function signatureLine(label, hint) {
  return `
    <article>
      <strong>${label}</strong>
      <span></span>
      <small>${hint}</small>
    </article>
  `;
}

function renderReportPrintFooter(project) {
  const company = state.data.company || {};
  return `
    <footer class="print-footer">
      <span>${company.name || "Jackson Telcom"}</span>
      <span>${project.map || project.id}</span>
      <span>${state.reportPrintScope || "Full Report Set"}</span>
      <span>Generated ${formatDateTime(new Date().toISOString())}</span>
      <span>Internal audit / SQUAN support packet</span>
    </footer>
  `;
}

function renderBillingPacketFinalizationHelper(project) {
  if (state.reportPrintScope !== "Billing Packet") return "";
  const checklist = reportPacketChecklist(project, "Billing Packet");
  const ready = checklist.filter(item => item.ok).length;
  const packetLock = currentPacketLock(project.id, "Billing Packet");
  const gate = billingSubmissionGate(project);
  const status = packetLock ? "Finalized" : ready === checklist.length ? "Ready" : "Needs Review";
  return `
    <section class="panel report-section no-print billing-packet-helper">
      <div class="panel-header">
        <div>
          <h2>Billing Packet finalization helper</h2>
          <p>Focused SQUAN billing packet review for ${project.map || project.id}.</p>
        </div>
        <span class="status ${statusClass(status)}">${status}</span>
      </div>
      <div class="billing-packet-helper-grid">
        ${metric("Checklist ready", `${ready}/${checklist.length}`, "Billing Packet scope")}
        ${metric("Submission gate", gate.status, gate.blockers.length ? `${gate.blockers.length} blocker(s)` : "Gate clear")}
        ${metric("Packet lock", packetLock ? "Finalized" : "Open", packetLock ? formatDateTime(packetLock.finalizedAt) : "Not locked yet")}
        ${metric("Evidence accepted", fieldEvidenceManifest(project).filter(item => item.status === "Accepted").length, "Accepted by Admin/Billing")}
      </div>
      <div class="billing-helper-steps">
        ${checklist.map(item => `
          <article class="${item.ok ? "ready" : "blocked"}">
            <span class="status ${statusClass(item.ok ? "Ready" : "Needs Review")}">${item.ok ? "Ready" : "Needs Review"}</span>
            <div>
              <strong>${item.label}</strong>
              <small>${item.detail}</small>
            </div>
            <button class="secondary-btn" data-workflow-action="${item.action}" data-workflow-id="${project.id}" data-report-scope="Billing Packet">Open</button>
          </article>
        `).join("")}
      </div>
      <div class="invoice-actions helper-actions">
        ${canManagePackets() ? packetLock ? `
          <button class="secondary-btn" data-packet-reopen="${project.id}">Reopen Billing Packet</button>
        ` : `
          <button class="primary-btn" data-packet-finalize="${project.id}" ${ready === checklist.length ? "" : "disabled"}>Finalize Billing Packet</button>
        ` : `<span class="readiness-note">Packet locking is limited to Admin and Billing.</span>`}
        <button class="secondary-btn" data-workflow-action="Billing" data-workflow-id="${project.id}">Return to Billing Gate</button>
        <a class="secondary-btn" href="/api/reports/billing-package?project=${encodeURIComponent(project.id)}" target="_blank" rel="noreferrer">Download Billing Packet</a>
      </div>
    </section>
  `;
}

function renderCollectionsPacketFinalizationHelper(project) {
  if (state.reportPrintScope !== "Collections Packet") return "";
  const rows = collectionsPacketScopeRows(project);
  const checklist = collectionsPacketChecklist(project);
  const ready = checklist.filter(item => item.ok).length;
  const packetLock = currentPacketLock(project.id, "Collections Packet");
  const status = packetLock ? "Finalized" : ready === checklist.length ? "Ready" : "Needs Review";
  const openTasks = rows.tasks.filter(task => task.status !== "Closed");
  const taskEvidenceCount = rows.tasks.reduce((total, task) => total + collectionEvidenceForTask(task).length, 0);
  return `
    <section class="panel report-section no-print billing-packet-helper collections-packet-helper">
      <div class="panel-header">
        <div>
          <h2>Collections Packet finalization helper</h2>
          <p>Admin/Billing review before sending SQUAN collection follow-up, 10% held-back support, or audit evidence.</p>
        </div>
        <span class="status ${statusClass(status)}">${status}</span>
      </div>
      <div class="billing-packet-helper-grid">
        ${metric("Payment exposure", currency(sum(rows.aging, "amount")), `${rows.aging.length} item(s)`)}
        ${metric("High-risk payment", rows.highRisk.length, "Needs escalation or documented reason")}
        ${metric("Open follow-ups", openTasks.length, `${rows.tasks.length} collection task(s)`)}
        ${metric("Evidence linked", rows.evidence.length + taskEvidenceCount, "Communication records")}
      </div>
      <div class="billing-helper-steps">
        ${checklist.map(item => `
          <article class="${item.ok ? "ready" : "blocked"}">
            <span class="status ${statusClass(item.ok ? "Ready" : "Needs Review")}">${item.ok ? "Ready" : "Needs Review"}</span>
            <div>
              <strong>${item.label}</strong>
              <small>${item.detail}</small>
            </div>
            <button class="secondary-btn" data-workflow-action="${item.action}" data-workflow-id="${project.id}">Open</button>
          </article>
        `).join("")}
      </div>
      <div class="invoice-actions helper-actions">
        ${canManagePackets() ? packetLock ? `
          <button class="secondary-btn" data-packet-reopen="${project.id}">Reopen Collections Packet</button>
          <button class="primary-btn" data-collection-submission-action="send" data-project-id="${project.id}">Log sent to SQUAN</button>
        ` : `
          <button class="primary-btn" data-packet-finalize="${project.id}" ${ready === checklist.length ? "" : "disabled"}>Finalize Collections Packet</button>
        ` : `<span class="readiness-note">Collections packet controls are limited to Admin and Billing.</span>`}
        ${canManageBilling() ? `
          <button class="secondary-btn" data-collection-submission-action="response" data-project-id="${project.id}">Record SQUAN response</button>
          <button class="secondary-btn" data-collection-submission-action="followup" data-project-id="${project.id}">Schedule follow-up</button>
        ` : ""}
        <a class="secondary-btn" href="/api/reports/collections-packet" target="_blank" rel="noreferrer">Download packet data</a>
        <a class="secondary-btn" href="/api/reports/collections-packet.csv" target="_blank" rel="noreferrer">Download CSV</a>
      </div>
      ${renderCollectionsSubmissionLog(project)}
    </section>
  `;
}

function renderFinancialCloseoutFinalizationHelper(project) {
  if (state.reportPrintScope !== "Financial Closeout") return "";
  const gate = mapFinancialCloseoutGate(project);
  const checklist = reportPacketChecklist(project, "Financial Closeout");
  const ready = checklist.filter(item => item.ok).length;
  const packetLock = currentPacketLock(project.id, "Financial Closeout");
  const closeout = project.adminApprovals?.financialCloseout;
  const openFinancialTasks = financialCloseoutOpenTasks(project);
  const status = packetLock ? "Finalized" : ready === checklist.length ? "Ready" : "Needs Review";
  return `
    <section class="panel report-section no-print billing-packet-helper financial-closeout-helper">
      <div class="panel-header">
        <div>
          <h2>Financial Closeout packet lock</h2>
          <p>Admin/Billing lock point after SQUAN billing, payment, retainage, deposit proof, and closeout tasks are reconciled.</p>
        </div>
        <span class="status ${statusClass(status)}">${status}</span>
      </div>
      <div class="billing-packet-helper-grid">
        ${metric("Checklist ready", `${ready}/${checklist.length}`, "Financial Closeout scope")}
        ${metric("Closeout gate", gate.status, gate.blockers.length ? `${gate.blockers.length} blocker(s)` : "Gate clear")}
        ${metric("Admin closeout", closeout?.status || "Pending", closeout?.at ? formatDateTime(closeout.at) : "Not financially closed")}
        ${metric("Packet lock", packetLock ? "Finalized" : "Open", packetLock ? formatDateTime(packetLock.finalizedAt) : "Not locked yet")}
        ${metric("Receipts", gate.receipts.length, "Cash/deposit proof linked")}
        ${metric("Open closeout tasks", openFinancialTasks.length, "Must be closed before lock")}
      </div>
      <div class="billing-helper-steps">
        ${checklist.map(item => `
          <article class="${item.ok ? "ready" : "blocked"}">
            <span class="status ${statusClass(item.ok ? "Ready" : "Needs Review")}">${item.ok ? "Ready" : "Needs Review"}</span>
            <div>
              <strong>${item.label}</strong>
              <small>${item.detail}</small>
            </div>
            <button class="secondary-btn" data-workflow-action="${item.action}" data-workflow-id="${project.id}">Open</button>
          </article>
        `).join("")}
      </div>
      <div class="invoice-actions helper-actions">
        ${canManagePackets() ? packetLock ? `
          <button class="secondary-btn" data-packet-reopen="${project.id}">Reopen Financial Closeout packet</button>
          <button class="primary-btn" data-financial-closeout-submission-action="sent" data-project-id="${project.id}">Log sent / exported</button>
          <button class="secondary-btn" data-financial-closeout-submission-action="receipt" data-project-id="${project.id}">Record receipt</button>
        ` : `
          <button class="primary-btn" data-packet-finalize="${project.id}" ${ready === checklist.length ? "" : "disabled"}>Finalize Financial Closeout packet</button>
        ` : `<span class="readiness-note">Financial closeout packet locking is limited to Admin and Billing.</span>`}
        <button class="secondary-btn" data-post-submission-ar-detail="${project.id}">Open Payment Detail</button>
        <button class="secondary-btn" data-workflow-action="Billing" data-workflow-id="${project.id}">Return to Billing</button>
        <a class="secondary-btn" href="/api/reports/financial-closeouts?project=${encodeURIComponent(project.id)}" target="_blank" rel="noreferrer">Download closeout data</a>
        <a class="secondary-btn" href="/api/reports/financial-closeouts.csv?project=${encodeURIComponent(project.id)}" target="_blank" rel="noreferrer">Download CSV</a>
      </div>
      ${renderFinancialCloseoutSubmissionLog(project)}
    </section>
  `;
}

function renderFinancialCloseoutSubmissionLog(project) {
  const lock = latestPacketLock(project.id, "Financial Closeout");
  const log = (lock?.submissionLog || []).slice().sort((a, b) => String(b.at || "").localeCompare(String(a.at || "")));
  return `
    <div class="submission-receipt-panel financial-closeout-submission-log">
      <div class="section-heading">
        <h3>Financial Closeout submission / receipt log</h3>
        <span>${log.length} event(s)</span>
      </div>
      <div class="submission-receipt-grid">
        ${log.map(item => `
          <article>
            <div class="card-topline">
              <strong>${item.title || item.action || "Packet event"}</strong>
              <span class="status ${statusClass(item.status || item.action || "Submitted")}">${item.status || item.action || "Submitted"}</span>
            </div>
            <dl>
              <div><dt>At</dt><dd>${formatDateTime(item.at)}</dd></div>
              <div><dt>By</dt><dd>${item.by || "Admin/Billing"}</dd></div>
              <div><dt>Recipient</dt><dd>${item.sentTo || item.receivedBy || "N/A"}</dd></div>
              <div><dt>Method</dt><dd>${item.method || "N/A"}</dd></div>
              <div><dt>Reference</dt><dd>${item.confirmationNumber || item.reference || "N/A"}</dd></div>
              <div><dt>Follow-up</dt><dd>${item.followUpDate || "N/A"}</dd></div>
            </dl>
            <p>${item.detail || item.note || "Financial Closeout packet audit event."}</p>
          </article>
        `).join("") || `
          <article>
            <strong>No submission receipt logged yet.</strong>
            <p>${lock?.status === "Finalized" ? "Log the export/sent event after the finalized Financial Closeout packet is delivered or saved for audit." : "Finalize the Financial Closeout packet before logging delivery."}</p>
          </article>
        `}
      </div>
      ${lock?.status === "Finalized" ? `
        <p class="readiness-note">Receipt status: ${financialCloseoutReceiptFollowUpState(lock).status}. ${financialCloseoutReceiptFollowUpState(lock).detail}</p>
      ` : ""}
    </div>
  `;
}

function renderCollectionsSubmissionLog(project) {
  const submissions = collectionsSubmissionsForProject(project.id);
  return `
    <div class="submission-receipt-panel collections-submission-log">
      <div class="section-heading">
        <h3>Collections submission log</h3>
        <span>${submissions.length} SQUAN contact record(s)</span>
      </div>
      <div class="submission-receipt-grid">
        ${submissions.map(item => `
          <article>
            <div class="card-topline">
              <strong>${item.id}</strong>
              <span class="status ${statusClass(item.status || "Sent")}">${item.status || "Sent"}</span>
            </div>
            <dl>
              <div><dt>Sent</dt><dd>${formatDateTime(item.submittedAt || item.createdAt)}</dd></div>
              <div><dt>To</dt><dd>${item.sentTo || "SQUAN PM / AP"}</dd></div>
              <div><dt>Method</dt><dd>${item.method || "Email / portal"}</dd></div>
              <div><dt>Receipt</dt><dd>${item.confirmationNumber || "Not recorded"}</dd></div>
              <div><dt>Response</dt><dd>${item.responseStatus || "Pending response"}</dd></div>
              <div><dt>Next follow-up</dt><dd>${item.nextFollowUpDate || "Not scheduled"}</dd></div>
            </dl>
            <p>${item.responseNote || item.notes || "No SQUAN response note recorded yet."}</p>
            <div class="invoice-actions">
              <button class="secondary-btn" data-collection-submission-action="response" data-project-id="${project.id}" data-submission-id="${item.id}">Record response</button>
              <button class="secondary-btn" data-collection-submission-action="followup" data-project-id="${project.id}" data-submission-id="${item.id}">Schedule follow-up</button>
              <button class="secondary-btn" data-collection-submission-action="record-cash" data-project-id="${project.id}" data-submission-id="${item.id}">Record cash</button>
              <button class="secondary-btn" data-collection-submission-action="escalate-dispute" data-project-id="${project.id}" data-submission-id="${item.id}">Escalate dispute</button>
              <button class="secondary-btn" data-collection-submission-action="writeoff-review" data-project-id="${project.id}" data-submission-id="${item.id}">Write-off review</button>
              <button class="secondary-btn" data-collection-submission-action="closeout" data-project-id="${project.id}" data-submission-id="${item.id}">Closeout</button>
            </div>
          </article>
        `).join("") || `
          <article>
            <strong>No collections submission logged yet.</strong>
            <p>Finalize the Collections Packet, then log when it is sent to SQUAN and track the response.</p>
          </article>
        `}
      </div>
    </div>
  `;
}

function renderReportMapSelector(projects, selectedProject) {
  const exceptionFilters = ["Selected Map", "All Exceptions", "Active / Reopened", "Resolved", "No Exception"];
  return `
    <section class="panel report-section no-print">
      <div class="panel-header">
        <h2>Report map selector</h2>
        <span>${selectedProject?.map || selectedProject?.id || "No Map selected"}</span>
      </div>
      <div class="report-selector-grid">
        <label>
          <span>Map</span>
          <select id="reportProjectSelect">
            ${projects.map(project => `<option value="${project.id}" ${project.id === selectedProject?.id ? "selected" : ""}>${project.map || project.id} · ${project.status}</option>`).join("")}
          </select>
        </label>
        <label>
          <span>Exception report filter</span>
          <select id="reportExceptionFilter">
            ${exceptionFilters.map(filter => `<option value="${filter}" ${state.reportExceptionFilter === filter ? "selected" : ""}>${filter}</option>`).join("")}
          </select>
        </label>
        <label>
          <span>Print scope</span>
          <select id="reportPrintScope">
            ${reportPrintScopes().map(scope => `<option value="${scope}" ${state.reportPrintScope === scope ? "selected" : ""}>${scope}</option>`).join("")}
          </select>
        </label>
      </div>
      <div class="report-scope-shortcuts">
        <button class="${state.reportPrintScope === "Billing Packet" ? "active" : ""}" data-report-scope-shortcut="Billing Packet">Billing Packet</button>
        <button class="${state.reportPrintScope === "Billing Closeouts" ? "active" : ""}" data-report-scope-shortcut="Billing Closeouts">Billing Closeouts</button>
        <button class="${state.reportPrintScope === "Financial Closeout" ? "active" : ""}" data-report-scope-shortcut="Financial Closeout">Financial Closeout</button>
        <button class="${state.reportPrintScope === "Cash Forecast Packet" ? "active" : ""}" data-report-scope-shortcut="Cash Forecast Packet">Cash Forecast</button>
        <button class="${state.reportPrintScope === "Closeout Package" ? "active" : ""}" data-report-scope-shortcut="Closeout Package">Closeout Package</button>
        <button class="${state.reportPrintScope === "Exception Report" ? "active" : ""}" data-report-scope-shortcut="Exception Report">Exception Report</button>
        <button class="${state.reportPrintScope === "Collections Packet" ? "active" : ""}" data-report-scope-shortcut="Collections Packet">Collections Packet</button>
        <button class="${state.reportPrintScope === "Collections Decision Audit" ? "active" : ""}" data-report-scope-shortcut="Collections Decision Audit">Decision Audit</button>
        <button class="${state.reportPrintScope === "Completed Forms" ? "active" : ""}" data-report-scope-shortcut="Completed Forms">Forms</button>
        <button class="${state.reportPrintScope === "Field Capture Audit" ? "active" : ""}" data-report-scope-shortcut="Field Capture Audit">Field Captures</button>
        <button class="${state.reportPrintScope === "Full Report Set" ? "active" : ""}" data-report-scope-shortcut="Full Report Set">Full Report Set</button>
      </div>
      <div class="report-map-list">
        ${projects.map(project => {
          const exception = project.adminApprovals?.exception;
          return `
            <button class="${project.id === selectedProject?.id ? "active" : ""}" data-report-project="${project.id}">
              <strong>${project.map || project.id}</strong>
              <span>${project.status}</span>
              <em class="status ${statusClass(exception?.status || "No Exception")}">${exception?.status || "No Exception"}</em>
            </button>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function renderReportPacketChecklist(project) {
  const items = reportPacketChecklist(project, state.reportPrintScope);
  const ready = items.filter(item => item.ok).length;
  const status = ready === items.length ? "Ready" : "Needs Review";
  const packetLock = currentPacketLock(project.id, state.reportPrintScope);
  return `
    <section class="panel report-section no-print packet-checklist">
      <div class="panel-header">
        <div>
          <h2>Packet review checklist</h2>
          <p>${packetLock ? `Finalized ${formatDateTime(packetLock.finalizedAt)} by ${packetLock.finalizedBy}.` : "Review before printing, exporting, or submitting."}</p>
        </div>
        <span class="status ${statusClass(packetLock ? "Locked" : status)}">${packetLock ? "Locked" : `${ready}/${items.length} ready`}</span>
      </div>
      <div class="packet-lock-actions">
        ${canManagePackets() ? packetLock ? `
          <button class="secondary-btn" data-packet-reopen="${project.id}">Reopen packet</button>
        ` : `
          <button class="primary-btn" data-packet-finalize="${project.id}" ${status === "Ready" ? "" : "disabled"}>Finalize for submission</button>
        ` : `<span class="readiness-note">Read-only packet checklist for this role.</span>`}
        <small>${packetLock ? `Scope: ${packetLock.scope}; lock ID ${packetLock.id}` : status === "Ready" ? "Packet is clean and can be locked." : "Resolve checklist items before finalizing."}</small>
      </div>
      <div class="packet-checklist-grid">
        ${items.map(item => `
          <article class="${item.ok ? "ready" : "needs-review"}">
            <span class="status ${statusClass(item.ok ? "Ready" : "Needs Review")}">${item.ok ? "Ready" : "Needs Review"}</span>
            <div>
              <strong>${item.label}</strong>
              <small>${item.detail}</small>
            </div>
            <button class="secondary-btn" data-workflow-action="${item.action}" data-workflow-id="${project.id}">Open</button>
          </article>
        `).join("")}
      </div>
      ${renderPacketLockHistory(project)}
    </section>
  `;
}

function renderPacketLockHistory(project) {
  const locks = (state.data.packetLocks || []).filter(item => item.project === project.id);
  if (!locks.length) return `
    <div class="packet-history empty">No packet finalization history for this Map yet.</div>
  `;
  return `
    <div class="packet-history">
      <div class="section-heading">
        <h3>Packet lock history</h3>
        <span>${locks.length} packet record(s)</span>
      </div>
      ${locks.map(lock => `
        <article>
          <div class="card-topline">
            <h3>${lock.scope}</h3>
            <span class="status ${statusClass(lock.status)}">${lock.status}</span>
          </div>
          <p>${lock.notes || "Packet lock record"}</p>
          <div class="packet-history-events">
            ${packetLockTimeline(lock).map(item => `
              <div>
                <span class="status ${statusClass(item.status)}">${item.status}</span>
                <strong>${item.title}</strong>
                <small>${item.at ? formatDateTime(item.at) : "No timestamp"} · ${item.by || "System"}</small>
                <p>${item.detail}</p>
              </div>
            `).join("")}
          </div>
        </article>
      `).join("")}
    </div>
  `;
}

function renderPacketLockAuditDashboard(projects) {
  const locks = state.data.packetLocks || [];
  const finalized = locks.filter(lock => lock.status === "Finalized");
  const reopened = locks.filter(lock => lock.status === "Reopened");
  const aging = reopened.filter(lock => (ageDays(lock.reopenedAt || lock.modifiedAt) || 0) >= 2);
  const packetTasks = (state.data.tasks || []).filter(task => task.source === "Packet reopen" && task.status !== "Closed");
  const alertControls = packetAlertControlsForProjects(projects);
  const activeControls = alertControls.filter(control => control.status === "Active");
  const resolvedMismatches = alertControls.filter(control => control.kind === "Resolved" && String(control.alertId || "").startsWith("packet-scope-mismatch:"));
  return `
    <section class="panel report-section no-print packet-audit-dashboard">
      <div class="panel-header">
        <div>
          <h2>Packet lock audit dashboard</h2>
          <p>Admin view of finalized packets, reopened packet change controls, and re-finalization work.</p>
        </div>
        <span>${locks.length} packet record(s)</span>
      </div>
      <div class="report-metrics packet-audit-metrics">
        ${metric("Finalized packets", finalized.length, "Locked and submission-ready")}
        ${metric("Needs re-finalization", reopened.length, "Reopened by edit guard or admin")}
        ${metric("Aging reopen items", aging.length, "Reopened for 2+ days")}
        ${metric("Open packet tasks", packetTasks.length, "Follow-ups still assigned")}
        ${metric("Alert controls", activeControls.length, "Active snoozes/dismissals")}
        ${metric("Resolved mismatches", resolvedMismatches.length, "Reviewed scope issues")}
      </div>
      <div class="packet-audit-queues">
        ${packetAuditQueue("Needs re-finalization", reopened, projects, "No reopened packets.")}
        ${packetTaskAuditQueue("Open packet tasks", packetTasks, projects)}
        ${packetAuditQueue("Aging reopened packets", aging, projects, "No aging packet reopen items.")}
        ${packetAlertControlQueue("Resolved scope mismatch history", resolvedMismatches, projects, "No resolved packet scope mismatches yet.")}
        ${packetAlertControlQueue("Alert control history", alertControls, projects)}
        ${packetAuditQueue("Finalized packet history", finalized.slice().reverse(), projects, "No finalized packet records yet.")}
      </div>
    </section>
  `;
}

function evidenceReviewRows(projects) {
  return projects.flatMap(project => fieldEvidenceManifest(project).map(item => {
    const review = evidenceReviewFor(project, item.key);
    const attachments = evidenceCorrectionAttachments(project, item.key);
    const correctionTask = evidenceCorrectionTasks(project, item.key).find(task => task.status !== "Closed") || evidenceCorrectionTasks(project, item.key)[0];
    return {
      project: project.id,
      map: project.map || project.id,
      customer: project.customer || "",
      key: item.key,
      label: item.label,
      status: review?.status || item.status,
      reviewStatus: review?.status || "Pending Review",
      sourceStatus: review?.sourceStatus || item.rawStatus || item.status,
      by: review?.by || "Unassigned",
      at: review?.at || "",
      note: `${review?.note || item.detail}${attachments.length ? ` (${attachments.length} corrected attachment(s))` : ""}`,
      attachments,
      attachmentCount: attachments.length,
      firstAttachment: attachments[0] || null,
      correctionTask,
      action: item.action
    };
  }));
}

function renderEvidenceReviewDashboard(projects, selectedProject) {
  const allRows = evidenceReviewRows(projects);
  const scopedRows = selectedProject ? allRows.filter(row => row.project === selectedProject.id) : allRows;
  const selectedRows = filterEvidenceReviewRows(scopedRows);
  const accepted = allRows.filter(row => row.reviewStatus === "Accepted").length;
  const rejected = allRows.filter(row => row.reviewStatus === "Rejected").length;
  const pendingReview = allRows.filter(row => row.reviewStatus === "Pending Review").length;
  const actionNeeded = allRows.filter(row => evidenceRowNeedsAction(row)).length;
  const filters = ["Action Needed", "Pending Review", "Rejected", "Accepted", "Has Attachments", "All"];
  return `
    <section class="panel report-section no-print evidence-review-dashboard">
      <div class="panel-header">
        <div>
          <h2>Evidence review dashboard</h2>
          <p>Admin/Billing view of accepted, rejected, and pending Map evidence before SQUAN submission.</p>
        </div>
        <span>${selectedProject?.map || "All Maps"}</span>
      </div>
      <div class="report-metrics evidence-review-metrics">
        ${metric("Accepted evidence", accepted, "Reviewed and cleared")}
        ${metric("Rejected evidence", rejected, "Correction required")}
        ${metric("Pending review", pendingReview, "Corrected and waiting on Admin/Billing")}
        ${metric("Action needed", actionNeeded, "Rejected, missing, or unaccepted")}
      </div>
      <div class="evidence-review-controls">
        ${filters.map(filter => `
          <button class="${state.evidenceReviewFilter === filter ? "active" : ""}" data-evidence-filter="${filter}">
            <span>${filter}</span>
            <strong>${evidenceFilterCount(scopedRows, filter)}</strong>
          </button>
        `).join("")}
      </div>
      <div class="evidence-review-table">
        <div class="evidence-review-head">
          <span>Map</span>
          <span>Evidence</span>
          <span>Review</span>
          <span>Source</span>
          <span>Attachments / note</span>
          <span>Actions</span>
        </div>
        ${selectedRows.map(row => `
          <article class="${evidenceRowNeedsAction(row) ? "needs-action" : ""}">
            <span>
              <strong>${row.map}</strong>
              <small>${row.project}</small>
            </span>
            <strong>${row.label}</strong>
            <em class="status ${statusClass(row.reviewStatus)}">${row.reviewStatus}</em>
            <em class="status ${statusClass(row.sourceStatus)}">${row.sourceStatus}</em>
            <small>
              ${row.attachmentCount ? `${row.attachmentCount} corrected attachment(s)` : "No corrected attachments"}
              <br>${row.by}${row.at ? ` · ${formatDateTime(row.at)}` : ""}
              <br>${row.note}
            </small>
            <div class="evidence-review-actions">
              ${row.firstAttachment ? `<button class="secondary-btn" data-open-record="${row.firstAttachment.collection}" data-record-id="${row.firstAttachment.id}">Preview</button>` : ""}
              ${row.correctionTask ? `<button class="secondary-btn" data-task-open="${row.correctionTask.id}">Correction</button>` : ""}
              <button class="secondary-btn" data-evidence-history="${row.project}" data-evidence-key="${row.key}">History</button>
              <button class="secondary-btn" data-workflow-action="${row.action}" data-workflow-id="${row.project}">Open</button>
              ${canManageBilling() ? `
                <button class="secondary-btn" data-evidence-review="request-correction" data-project-id="${row.project}" data-evidence-key="${row.key}">Request correction</button>
                <button class="primary-btn" data-evidence-review="accept" data-project-id="${row.project}" data-evidence-key="${row.key}">Accept</button>
              ` : ""}
            </div>
          </article>
        `).join("") || `<p class="empty-state">No evidence review rows for this Map yet.</p>`}
      </div>
    </section>
  `;
}

function evidenceRowNeedsAction(row) {
  return row.reviewStatus !== "Accepted" || row.sourceStatus === "Rejected";
}

function filterEvidenceReviewRows(rows) {
  if (state.evidenceReviewFilter === "All") return rows;
  if (state.evidenceReviewFilter === "Action Needed") return rows.filter(evidenceRowNeedsAction);
  if (state.evidenceReviewFilter === "Has Attachments") return rows.filter(row => row.attachmentCount > 0);
  return rows.filter(row => row.reviewStatus === state.evidenceReviewFilter);
}

function evidenceFilterCount(rows, filter) {
  if (filter === "All") return rows.length;
  if (filter === "Action Needed") return rows.filter(evidenceRowNeedsAction).length;
  if (filter === "Has Attachments") return rows.filter(row => row.attachmentCount > 0).length;
  return rows.filter(row => row.reviewStatus === filter).length;
}

function packetAuditQueue(title, locks, projects, emptyText) {
  return `
    <article class="packet-audit-queue">
      <div class="section-heading">
        <h3>${title}</h3>
        <span>${locks.length} item(s)</span>
      </div>
      <div class="packet-audit-list">
        ${locks.length ? locks.map(lock => packetAuditRow(lock, projects)).join("") : `<p class="empty-state">${emptyText}</p>`}
      </div>
    </article>
  `;
}

function packetTaskAuditQueue(title, tasks, projects) {
  return `
    <article class="packet-audit-queue">
      <div class="section-heading">
        <h3>${title}</h3>
        <span>${tasks.length} item(s)</span>
      </div>
      <div class="packet-audit-list">
        ${tasks.length ? tasks.map(task => packetTaskAuditRow(task, projects)).join("") : `<p class="empty-state">No open packet re-finalization tasks.</p>`}
      </div>
    </article>
  `;
}

function renderPacketExportPreview(project) {
  const readiness = packetSubmissionReadiness(project);
  const rows = packetExportPreviewRows(project);
  const counts = rows.reduce((acc, row) => ({ ...acc, [row.type]: (acc[row.type] || 0) + 1 }), {});
  return `
    <section class="panel report-section no-print packet-export-preview">
      <div class="panel-header">
        <div>
          <h2>Packet export preview</h2>
          <p>Review the packet records that will be included before downloading JSON or CSV.</p>
        </div>
        <span class="status ${statusClass(readiness.ready ? "Ready" : "Needs Review")}">${readiness.ready ? "Ready to export" : "Not ready"}</span>
      </div>
      <div class="packet-export-readiness">
        ${metric("Packet timeline", counts["Packet timeline"] || 0, "Lock activity rows")}
        ${metric("Alert controls", counts["Alert control"] || 0, "Snoozes, dismissals, reactivations")}
        ${metric("Scope mismatches", counts["Scope mismatch"] || 0, "Active mismatch rows")}
        ${metric("Packet tasks", counts["Packet task"] || 0, "Re-finalization tasks")}
        ${metric("Evidence reviews", counts["Evidence review"] || 0, "Accepted/rejected/pending evidence")}
      </div>
      <div class="packet-readiness-blockers">
        ${readiness.blockers.length ? readiness.blockers.map(item => `
          <article>
            <span class="status ${statusClass(item.status)}">${item.status}</span>
            <div>
              <strong>${item.label}</strong>
              <small>${item.detail}</small>
            </div>
            <button class="secondary-btn" data-workflow-action="${item.action}" data-workflow-id="${project.id}">Open</button>
          </article>
        `).join("") : `
          <article class="ready">
            <span class="status ${statusClass("Ready")}">Ready</span>
            <div>
              <strong>No export blockers</strong>
              <small>Packet export does not have reopened locks, unresolved scope mismatches, or open packet tasks.</small>
            </div>
            <button class="secondary-btn" data-workflow-action="Reports" data-workflow-id="${project.id}">Review</button>
          </article>
        `}
      </div>
      <div class="packet-preview-table">
        <div class="packet-preview-head">
          <span>Type</span>
          <span>Reference</span>
          <span>Status</span>
          <span>Detail</span>
        </div>
        ${rows.slice(0, 14).map(row => `
          <article>
            <span>${row.type}</span>
            <strong>${row.reference}</strong>
            <em class="status ${statusClass(row.status)}">${row.status}</em>
            <small>${row.detail}</small>
          </article>
        `).join("") || `<p class="empty-state">No packet export rows for this Map yet.</p>`}
      </div>
    </section>
  `;
}

function packetSubmissionReadiness(project) {
  const reopenedLocks = (state.data.packetLocks || []).filter(lock => lock.project === project.id && lock.status === "Reopened");
  const openPacketTasks = (state.data.tasks || []).filter(task => task.project === project.id && task.source === "Packet reopen" && task.status !== "Closed");
  const mismatches = packetScopeMismatchEvents([project]);
  const blockers = [
    ...reopenedLocks.map(lock => ({ label: `${lock.scope} reopened`, detail: lock.reopenReason || "Packet must be re-finalized before submission.", status: "Blocked", action: "Reports" })),
    ...mismatches.map(event => ({ label: "Scope mismatch unresolved", detail: `${event.detail?.finalizedScope || "Different scope"} finalized while task expected ${uniqueList(event.detail?.expectedScopes || []).join(", ") || "another scope"}.`, status: "Needs Review", action: "Reports" })),
    ...openPacketTasks.map(task => ({ label: task.id, detail: `${task.owner || "Unassigned"} must close re-finalization workflow. Due ${task.dueDate || "N/A"}.`, status: task.status, action: "Tasks" }))
  ];
  return { ready: blockers.length === 0, blockers };
}

function packetExportPreviewRows(project) {
  const locks = (state.data.packetLocks || []).filter(lock => lock.project === project.id);
  const snapshots = packageSnapshotsForProject(project.id);
  const controls = packetAlertControlsForProjects([project]);
  const mismatches = packetScopeMismatchEvents([project]);
  const tasks = (state.data.tasks || []).filter(task => task.project === project.id && task.source === "Packet reopen");
  const evidenceRows = fieldEvidenceManifest(project).map(item => {
    const review = evidenceReviewFor(project, item.key);
    const attachments = evidenceCorrectionAttachments(project, item.key);
    return {
      type: "Evidence review",
      reference: item.label,
      status: review?.status || item.status,
      detail: `${review?.by || "Pending Admin/Billing review"}; source ${review?.sourceStatus || item.rawStatus || item.status}; ${attachments.length} corrected attachment(s); ${review?.note || item.detail}`
    };
  });
  const timelineRows = locks.flatMap(lock => packetLockTimeline(lock).map(item => ({
    type: "Packet timeline",
    reference: lock.id,
    status: item.status,
    detail: `${lock.scope}: ${item.detail || item.title}`
  })));
  const controlRows = controls.map(control => ({
    type: "Alert control",
    reference: control.id,
    status: control.kind === "Resolved" ? "Resolved" : control.status,
    detail: `${control.kind || "Control"}: ${control.notes || control.alertId}`
  }));
  const mismatchRows = mismatches.map(event => ({
    type: "Scope mismatch",
    reference: event.id,
    status: "Needs Review",
    detail: `Finalized ${event.detail?.finalizedScope || "different scope"}; expected ${uniqueList(event.detail?.expectedScopes || []).join(", ") || "another scope"}.`
  }));
  const taskRows = tasks.map(task => ({
    type: "Packet task",
    reference: task.id,
    status: task.status,
    detail: `${task.owner || "Unassigned"}; scopes ${(task.reopenScopes || []).join(", ") || "N/A"}; ${task.notes || ""}`
  }));
  const snapshotRows = snapshots.map(snapshot => ({
    type: "Prepared package snapshot",
    reference: snapshot.id,
    status: snapshot.status,
    detail: `v${snapshot.version}; ${currency(snapshot.gross)} gross; ${snapshot.acceptedEvidenceCount}/${snapshot.evidenceCount} evidence accepted; prepared ${formatDateTime(snapshot.preparedAt)} by ${snapshot.preparedBy}.`
  }));
  return [...mismatchRows, ...taskRows, ...snapshotRows, ...evidenceRows, ...controlRows, ...timelineRows];
}

function packetAlertControlsForProjects(projects) {
  const projectIds = new Set(projects.map(project => project.id));
  return (state.data.alertControls || [])
    .filter(control => control.source === "Packet lock" && (!control.project || projectIds.has(control.project)))
    .slice()
    .sort((a, b) => String(b.modifiedAt || b.createdAt || "").localeCompare(String(a.modifiedAt || a.createdAt || "")));
}

function closeoutAlertControlsForProjects(projects) {
  const projectIds = new Set(projects.map(project => project.id));
  return (state.data.alertControls || [])
    .filter(control => control.source === "Billing closeout" && (!control.project || projectIds.has(control.project)))
    .slice()
    .sort((a, b) => String(b.modifiedAt || b.createdAt || "").localeCompare(String(a.modifiedAt || a.createdAt || "")));
}

function dailyPackageAlertControlsForProjects(projects) {
  const projectIds = new Set(projects.map(project => project.id));
  return (state.data.alertControls || [])
    .filter(control => control.source === "Daily package intake" && (!control.project || projectIds.has(control.project)))
    .slice()
    .sort((a, b) => String(b.modifiedAt || b.createdAt || "").localeCompare(String(a.modifiedAt || a.createdAt || "")));
}

function packetAlertControlQueue(title, controls, projects, emptyText = "No packet alert snoozes or dismissals yet.") {
  return `
    <article class="packet-audit-queue packet-alert-history">
      <div class="section-heading">
        <h3>${title}</h3>
        <span>${controls.length} item(s)</span>
      </div>
      <div class="packet-audit-list">
        ${controls.length ? controls.map(control => packetAlertControlRow(control, projects)).join("") : `<p class="empty-state">${emptyText}</p>`}
      </div>
    </article>
  `;
}

function packetAuditRow(lock, projects) {
  const project = projects.find(item => item.id === lock.project) || (state.data.projects || []).find(item => item.id === lock.project) || {};
  const isReopened = lock.status === "Reopened";
  const age = ageDays(lock.reopenedAt || lock.modifiedAt);
  const status = isReopened && age >= 2 ? "Needs Review" : lock.status;
  const timestamp = isReopened ? lock.reopenedAt : lock.finalizedAt;
  const person = isReopened ? lock.reopenedBy : lock.finalizedBy;
  const task = isReopened ? packetReopenTaskForProject(lock.project) : null;
  return `
    <div class="packet-audit-row">
      <div>
        <strong>${project.map || lock.project}</strong>
        <span>${lock.scope}</span>
        <small>${isReopened ? `${lock.reopenReason || "No reopen reason recorded."} ${task ? `Linked task ${task.id} · ${task.owner} · due ${task.dueDate}.` : "No linked task found."}` : lock.notes || "Packet finalized for submission."}</small>
      </div>
      <div>
        <span class="status ${statusClass(status)}">${status}</span>
        <small>${timestamp ? formatDateTime(timestamp) : "No timestamp"} · ${person || "System"}${isReopened && age !== null ? ` · ${age} day(s) open` : ""}</small>
      </div>
      <div class="packet-audit-actions">
        <button class="secondary-btn" data-report-project="${lock.project}">Open Map</button>
        ${task ? `<button class="secondary-btn" data-task-open="${task.id}">Open Task</button>` : ""}
      </div>
    </div>
  `;
}

function packetAlertControlRow(control, projects) {
  const project = projects.find(item => item.id === control.project) || (state.data.projects || []).find(item => item.id === control.project) || {};
  const isSnoozed = control.kind === "Snoozed";
  const activeSnooze = isSnoozed && control.snoozedUntil && new Date(control.snoozedUntil) > new Date();
  const effectiveStatus = isSnoozed && !activeSnooze ? "Expired" : control.status;
  const isResolvedMismatch = control.kind === "Resolved" && String(control.alertId || "").startsWith("packet-scope-mismatch:");
  const title = isResolvedMismatch ? `Resolved scope mismatch · ${project.map || control.project || "Company"}` : `${control.kind || "Alert control"} · ${project.map || control.project || "Company"}`;
  const statusLabel = isResolvedMismatch ? "Resolved" : effectiveStatus;
  return `
    <div class="packet-audit-row">
      <div>
        <strong>${title}</strong>
        <span>${control.alertId || "Packet alert"}</span>
        <small>${control.notes || "Packet alert visibility was changed."}</small>
      </div>
      <div>
        <span class="status ${statusClass(statusLabel)}">${statusLabel}</span>
        <small>${formatDateTime(control.modifiedAt || control.createdAt)} · ${control.updatedBy || "System"}${activeSnooze ? ` · until ${formatDateTime(control.snoozedUntil)}` : ""}</small>
      </div>
      <div class="packet-audit-actions">
        ${control.project ? `<button class="secondary-btn" data-report-project="${control.project}">Open Map</button>` : `<button class="secondary-btn" disabled>Open Map</button>`}
        ${control.status === "Active" ? `<button class="secondary-btn" data-alert-reactivate="${control.id}">Reactivate</button>` : ""}
      </div>
    </div>
  `;
}

function packetTaskAuditRow(task, projects) {
  const projectId = task.project || task.relatedId;
  const project = projects.find(item => item.id === projectId) || (state.data.projects || []).find(item => item.id === projectId) || {};
  const age = ageDays(task.modifiedAt || task.createdAt);
  return `
    <div class="packet-audit-row">
      <div>
        <strong>${task.title}</strong>
        <span>${project.map || projectId || "Unassigned Map"} · ${task.owner || "Unassigned"}</span>
        <small>${task.notes || "Packet reopen task"}</small>
      </div>
      <div>
        <span class="status ${statusClass(task.status)}">${task.status}</span>
        <small>Due ${task.dueDate || "N/A"}${age !== null ? ` · updated ${age} day(s) ago` : ""}</small>
      </div>
      ${projectId ? `<button class="secondary-btn" data-report-project="${projectId}">Open Map</button>` : `<button class="secondary-btn" disabled>Open Map</button>`}
    </div>
  `;
}

function packetLockTimeline(lock) {
  const events = [];
  if (lock.createdAt) events.push({ status: "Created", title: "Packet lock record created", at: lock.createdAt, by: lock.finalizedBy, detail: lock.id });
  (lock.activityLog || []).forEach(item => {
    events.push({
      status: String(item.note || "").toLowerCase().includes("reopened") ? "Reopened" : String(item.note || "").toLowerCase().includes("finalized") ? "Finalized" : "Updated",
      title: item.note || "Packet activity",
      at: item.at,
      by: item.by,
      detail: lock.id
    });
  });
  (lock.submissionLog || []).forEach(item => {
    events.push({
      status: item.status || item.action || "Submitted",
      title: item.title || `Packet ${String(item.action || "submission").toLowerCase()}`,
      at: item.at,
      by: item.by,
      detail: item.detail || item.confirmationNumber || item.sentTo || "Packet submission event."
    });
  });
  if (lock.reopenedAt) events.push({ status: "Reopened", title: "Packet reopened", at: lock.reopenedAt, by: lock.reopenedBy, detail: lock.reopenReason || "No reopen reason recorded." });
  if (lock.finalizedAt) events.push({ status: "Finalized", title: "Current finalization", at: lock.finalizedAt, by: lock.finalizedBy, detail: `${lock.scope}; checklist ${lock.checklistSnapshot?.filter(item => item.ok).length || 0}/${lock.checklistSnapshot?.length || 0} ready.` });
  return events
    .filter(item => item.title)
    .sort((a, b) => String(a.at || "").localeCompare(String(b.at || "")));
}

function packetLockId(projectId, scope) {
  return `PKT-${String(projectId).replace(/[^a-z0-9]/gi, "")}-${printScopeSlug(scope).toUpperCase()}`;
}

function currentPacketLock(projectId, scope) {
  return (state.data.packetLocks || []).find(item => item.project === projectId && item.scope === scope && item.status === "Finalized");
}

function latestPacketLock(projectId, scope) {
  return (state.data.packetLocks || [])
    .filter(item => item.project === projectId && item.scope === scope)
    .slice()
    .sort((a, b) => String(b.modifiedAt || b.finalizedAt || b.reopenedAt || b.createdAt || "").localeCompare(String(a.modifiedAt || a.finalizedAt || a.reopenedAt || a.createdAt || "")))[0];
}

function financialCloseoutPacketLockState(project) {
  const lock = latestPacketLock(project?.id, "Financial Closeout");
  if (!project) return { status: "No Map", label: "No Map", detail: "Select a Map.", lock: null };
  if (!lock) return { status: "Open", label: "Not locked", detail: "Finalize the Financial Closeout packet in Reports after Admin financial closeout.", lock: null };
  if (lock.status === "Finalized") {
    return {
      status: "Locked",
      label: "Locked",
      detail: `Finalized ${formatDateTime(lock.finalizedAt)} by ${lock.finalizedBy || "Admin"}.`,
      lock
    };
  }
  if (lock.status === "Reopened") {
    return {
      status: "Reopened",
      label: "Reopened",
      detail: `${lock.reopenReason || "Financial records changed after packet lock."}${lock.reopenedAt ? ` Reopened ${formatDateTime(lock.reopenedAt)}.` : ""}`,
      lock
    };
  }
  return { status: lock.status || "Open", label: lock.status || "Open", detail: lock.notes || "Packet lock record exists.", lock };
}

function financialCloseoutReceiptFollowUpState(lock) {
  if (!lock || lock.scope !== "Financial Closeout" || lock.status !== "Finalized") {
    return { status: "Not Applicable", alert: false, detail: "No finalized Financial Closeout packet.", sent: null, receipt: null };
  }
  const log = lock.submissionLog || [];
  const sentEvents = log.filter(item => item.action === "Sent" || item.status === "Sent / Exported");
  const receiptEvents = log.filter(item => item.action === "Receipt" || item.status === "Receipt Confirmed");
  const sent = sentEvents.slice().sort((a, b) => String(b.at || "").localeCompare(String(a.at || "")))[0] || null;
  const receipt = receiptEvents.slice().sort((a, b) => String(b.at || "").localeCompare(String(a.at || "")))[0] || null;
  if (!sent) return { status: "Not Sent", alert: false, detail: "Packet is finalized but no sent/exported event is logged.", sent, receipt };
  if (receipt && String(receipt.at || "") >= String(sent.at || "")) {
    return { status: "Receipt Confirmed", alert: false, detail: `Receipt confirmed by ${receipt.receivedBy || receipt.by || "recipient"} ${receipt.at ? formatDateTime(receipt.at) : ""}.`, sent, receipt };
  }
  const followUpDays = sent.followUpDate ? daysUntil(sent.followUpDate) : null;
  const overdue = followUpDays !== null && followUpDays < 0;
  const dueSoon = followUpDays !== null && followUpDays <= 1;
  return {
    status: overdue ? "Receipt Overdue" : dueSoon ? "Receipt Due" : "Awaiting Receipt",
    alert: overdue || dueSoon || !sent.followUpDate,
    severity: overdue ? "High" : "Medium",
    due: sent.followUpDate || String(sent.at || "").slice(0, 10),
    detail: sent.followUpDate
      ? `Sent/exported to ${sent.sentTo || "recipient"}; follow-up ${sent.followUpDate}; no receipt confirmation logged.`
      : `Sent/exported to ${sent.sentTo || "recipient"}; no receipt confirmation or follow-up date logged.`,
    sent,
    receipt
  };
}

function packetLocksForProject(projectId) {
  return (state.data.packetLocks || []).filter(item => item.project === projectId && item.status === "Finalized");
}

function packetGuardProjectId(collectionKey, record) {
  if (!record) return "";
  if (collectionKey === "projects") return record.id;
  return record.project || record.relatedId || "";
}

function packetGuardedCollections() {
  return ["projects", "documents", "photoEvidence", "siteSurveys", "obstacles", "qcCloseouts", "formSubmissions", "dailies", "invoices", "invoiceSubmissions", "billingReadiness", "retainageLedger", "safety"];
}

function guardFinalizedPacketEdit(projectId, context) {
  const locks = packetLocksForProject(projectId);
  if (!locks.length) return true;
  const reason = prompt(`${locks.length} finalized packet(s) exist for this Map. Enter a reopen/change-control reason before changing ${context}.`);
  if (!reason || !reason.trim()) return false;
  const now = new Date().toISOString();
  locks.forEach(lock => {
    lock.status = "Reopened";
    lock.reopenedAt = now;
    lock.reopenedBy = state.user?.name || "User";
    lock.reopenReason = reason.trim();
    lock.modifiedAt = now;
    lock.activityLog = [...(lock.activityLog || []), {
      at: now,
      by: state.user?.name || "User",
      note: `Packet reopened before edit: ${reason.trim()}`
    }];
    void saveToApi("packetLocks", lock, false);
  });
  createPacketReopenTask(projectId, locks, reason.trim(), context);
  appendAuditLocal("packet.edit-guard-reopen", {
    project: projectId,
    locks: locks.map(lock => lock.id),
    context,
    reason: reason.trim(),
    by: state.user?.name || "User"
  });
  return true;
}

function createPacketReopenTask(projectId, locks, reason, context) {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return null;
  state.data.tasks = state.data.tasks || [];
  const now = new Date().toISOString();
  const id = packetReopenTaskId(projectId);
  const existing = state.data.tasks.find(task => task.id === id);
  const reopenedScopes = uniqueList([...(existing?.reopenScopes || []), ...locks.map(lock => lock.scope).filter(Boolean)]);
  const relatedLockIds = uniqueList([...(existing?.relatedLockIds || []), ...locks.map(lock => lock.id).filter(Boolean)]);
  const scopes = reopenedScopes.join(", ");
  locks.forEach(lock => {
    lock.reopenTaskId = id;
    lock.activityLog = [...(lock.activityLog || []), {
      at: now,
      by: state.user?.name || "User",
      note: `Linked re-finalization task ${id}.`
    }];
    void saveToApi("packetLocks", lock, false);
  });
  const taskPatch = {
    title: `Re-finalize reopened packet for ${project.map || project.id}`,
    relatedType: "Map",
    relatedId: project.id,
    project: project.id,
    owner: packetReopenOwner(locks),
    role: "Admin",
    dueDate: dateFromToday(1),
    priority: "High",
    status: "Open",
    workflowArea: "Reports",
    notes: `Finalized packet reopened before ${context}. Scope(s): ${scopes}. Reason: ${reason}. Review packet checklist and finalize again before submission.`,
    source: "Packet reopen",
    reopenScopes: reopenedScopes,
    relatedLockIds,
    modifiedAt: now
  };
  if (existing) {
    Object.assign(existing, taskPatch, {
      activityLog: [...(existing.activityLog || []), {
        at: now,
        by: state.user?.name || "User",
        note: `Packet reopen follow-up refreshed: ${reason}`
      }]
    });
    void saveToApi("tasks", existing, false);
    return existing;
  }
  const task = {
    id,
    ...taskPatch,
    createdAt: now,
    activityLog: [{
      at: now,
      by: state.user?.name || "User",
      note: "Created when a finalized packet was reopened by edit guard."
    }]
  };
  state.data.tasks.push(task);
  void saveToApi("tasks", task, true);
  return task;
}

function packetReopenOwner(locks) {
  const scopes = locks.map(lock => lock.scope).join(" ").toLowerCase();
  if (scopes.includes("billing") || scopes.includes("retainage")) return "Office Billing";
  if (scopes.includes("safety") || scopes.includes("compliance")) return "Safety Compliance";
  return "Ronald Jackson";
}

function renderPacketLockNotice(project, context = "this workflow") {
  const locks = packetLocksForProject(project?.id);
  if (!project || !locks.length) return "";
  return `
    <section class="packet-lock-notice">
      <div>
        <strong>Finalized packet warning</strong>
        <span>${project.map || project.id} has ${locks.length} finalized packet(s). Changes in ${context} may require reopening the packet before resubmission.</span>
      </div>
      <div class="packet-lock-tags">
        ${locks.map(lock => `<span class="status ${statusClass("Locked")}">${lock.scope} · ${formatDateTime(lock.finalizedAt)}</span>`).join("")}
      </div>
      <button class="secondary-btn" data-workflow-action="Reports" data-workflow-id="${project.id}">Review packet locks</button>
    </section>
  `;
}

function finalizePacket(projectId) {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return;
  const items = reportPacketChecklist(project, state.reportPrintScope);
  const missing = items.filter(item => !item.ok);
  if (missing.length) {
    alert(`Packet is not ready. Resolve: ${missing.map(item => item.label).join(", ")}`);
    return;
  }
  state.data.packetLocks = state.data.packetLocks || [];
  const now = new Date().toISOString();
  const id = packetLockId(project.id, state.reportPrintScope);
  const existing = state.data.packetLocks.find(item => item.id === id);
  const lock = {
    id,
    project: project.id,
    scope: state.reportPrintScope,
    status: "Finalized",
    finalizedAt: now,
    finalizedBy: state.user?.name || "Admin",
    checklistSnapshot: items.map(item => ({ label: item.label, ok: item.ok, detail: item.detail })),
    notes: `${state.reportPrintScope} finalized for submission.`,
    createdAt: existing?.createdAt || now,
    reopenTaskId: "",
    modifiedAt: now,
    activityLog: [...(existing?.activityLog || []), { at: now, by: state.user?.name || "Admin", note: "Packet finalized for submission." }]
  };
  if (state.reportPrintScope === "Collections Packet") {
    const rows = collectionsPacketScopeRows(project);
    lock.collectionsSnapshot = {
      arExposure: sum(rows.aging, "amount"),
      arItems: rows.aging.length,
      highRisk: rows.highRisk.length,
      collectionTasks: rows.tasks.length,
      openCollectionTasks: rows.tasks.filter(task => task.status !== "Closed").length,
      communicationEvidence: rows.evidence.length,
      promisedPaymentDates: rows.tasks.filter(task => task.promisedPaymentDate).length,
      disputes: rows.tasks.filter(task => task.disputeReason).length
    };
    lock.notes = `Collections Packet finalized for SQUAN collection follow-up and audit support. AR exposure ${currency(lock.collectionsSnapshot.arExposure)}.`;
  }
  if (state.reportPrintScope === "Financial Closeout") {
    lock.financialCloseoutSnapshot = financialCloseoutPacketSnapshot(project);
    lock.notes = `Financial Closeout packet finalized for audit. Status ${lock.financialCloseoutSnapshot.closeoutStatus}; invoice ${lock.financialCloseoutSnapshot.invoice || "N/A"}.`;
  }
  if (existing) Object.assign(existing, lock);
  else state.data.packetLocks.push(lock);
  const closedTask = closePacketReopenTask(project.id, state.reportPrintScope, now);
  appendAuditLocal("packet.finalize", { project: project.id, scope: state.reportPrintScope, lock: id, by: state.user?.name || "Admin" });
  persist("Packet finalized");
  void saveToApi("packetLocks", lock, !existing);
  if (closedTask) void saveToApi("tasks", closedTask, false);
  render();
}

function closePacketReopenTask(projectId, scope, now = new Date().toISOString()) {
  const task = (state.data.tasks || []).find(item => item.id === packetReopenTaskId(projectId) && item.status !== "Closed");
  if (!task) return null;
  const taskScopes = uniqueList(task.reopenScopes || []);
  if (taskScopes.length && !taskScopes.includes(scope)) {
    appendAuditLocal("packet.refinalization-scope-mismatch", {
      project: projectId,
      finalizedScope: scope,
      task: task.id,
      expectedScopes: taskScopes
    });
    return null;
  }
  const remainingScopes = taskScopes.filter(item => item !== scope);
  const remainingReopenedLocks = (state.data.packetLocks || []).filter(lock => lock.project === projectId && lock.status === "Reopened" && (lock.reopenTaskId === task.id || remainingScopes.includes(lock.scope)));
  if (remainingScopes.length || remainingReopenedLocks.length) {
    task.reopenScopes = uniqueList([...remainingScopes, ...remainingReopenedLocks.map(lock => lock.scope)]);
    task.modifiedAt = now;
    task.notes = appendInlineNote(task.notes, `Packet scope ${scope} re-finalized; remaining scope(s): ${task.reopenScopes.join(", ")}.`);
    task.activityLog = [...(task.activityLog || []), {
      at: now,
      by: state.user?.name || "Admin",
      note: `Partial packet re-finalization for ${scope}; task remains open.`
    }];
    appendAuditLocal("packet.refinalization-task-partial", {
      project: projectId,
      scope,
      task: task.id,
      remainingScopes: task.reopenScopes,
      by: state.user?.name || "Admin"
    });
    return task;
  }
  task.status = "Closed";
  task.reopenScopes = [];
  task.modifiedAt = now;
  task.notes = appendInlineNote(task.notes, `Packet re-finalized for ${scope}; follow-up closed automatically.`);
  task.activityLog = [...(task.activityLog || []), {
    at: now,
    by: state.user?.name || "Admin",
    note: `Closed automatically when ${scope} was finalized.`
  }];
  appendAuditLocal("packet.refinalization-task-closed", {
    project: projectId,
    scope,
    task: task.id,
    by: state.user?.name || "Admin"
  });
  return task;
}

function reopenPacket(projectId) {
  const lock = currentPacketLock(projectId, state.reportPrintScope);
  if (!lock) return;
  const reason = prompt("Why is this finalized packet being reopened?");
  if (!reason || !reason.trim()) return;
  const now = new Date().toISOString();
  createPacketReopenTask(projectId, [lock], reason.trim(), "manual packet reopen");
  lock.status = "Reopened";
  lock.reopenedAt = now;
  lock.reopenedBy = state.user?.name || "Admin";
  lock.reopenReason = reason.trim();
  lock.modifiedAt = now;
  lock.activityLog = [...(lock.activityLog || []), { at: now, by: state.user?.name || "Admin", note: `Packet reopened: ${reason.trim()}` }];
  appendAuditLocal("packet.reopen", { project: projectId, scope: state.reportPrintScope, lock: lock.id, reason: reason.trim(), by: state.user?.name || "Admin" });
  persist("Packet reopened");
  void saveToApi("packetLocks", lock, false);
  render();
}

function financialCloseoutPacketSnapshot(project) {
  const gate = mapFinancialCloseoutGate(project);
  const record = project.adminApprovals?.financialCloseout || {};
  return {
    closeoutStatus: record.status || "Pending",
    closedAt: record.at || "",
    closedBy: record.by || "",
    reopenedAt: record.reopenedAt || "",
    reopenedBy: record.reopenedBy || "",
    reopenReason: record.reopenReason || "",
    invoice: gate.invoice?.id || record.invoice || "",
    invoiceStatus: gate.invoice?.status || "",
    invoiceGross: Number(gate.invoice?.gross || 0),
    paid90: Number(gate.invoice?.paid90 || 0),
    submission: gate.submission?.id || record.submission || "",
    confirmationNumber: gate.submission?.confirmationNumber || gate.submission?.receipt?.confirmationNumber || "",
    retainage: gate.retainage?.id || record.retainage || "",
    retainageStatus: gate.retainage?.status || "",
    retainageHeld: Number(gate.retainage?.heldAmount || 0),
    receipts: gate.receipts.map(receipt => ({
      id: receipt.id,
      type: receipt.type || "Payment",
      amount: Number(receipt.actualAmount || receipt.amount || 0),
      depositStatus: receipt.depositStatus || receipt.status || "",
      bankProof: receipt.bankProof || ""
    })),
    gateStatus: gate.status,
    gateBlockers: gate.blockers.map(item => item.label),
    gateSnapshot: gate.items.map(item => ({ key: item.key, label: item.label, status: item.status, ok: item.ok, detail: item.detail }))
  };
}

function reportPacketChecklist(project, scope) {
  const closeout = closeoutReview(project);
  const closeoutReadiness = closeoutSubmissionReadiness(project);
  const financialGate = mapFinancialCloseoutGate(project);
  const financialCloseout = project.adminApprovals?.financialCloseout;
  const financialTasks = financialCloseoutOpenTasks(project);
  const support = supportPackageManifest(project);
  const exception = project.adminApprovals?.exception;
  const openTasks = scopedRows("tasks").filter(item => item.project === project.id && item.status !== "Closed");
  const openSafety = scopedRows("safety").filter(item => item.project === project.id && item.status !== "Closed");
  const readiness = scopedRows("billingReadiness").find(item => item.project === project.id);
  const invoice = scopedRows("invoices").find(item => item.project === project.id);
  const dailyPackageExceptions = dailyPackageExceptionRows(project);
  const fieldCaptures = fieldCaptureReviewRows(project);
  const acceptedCaptures = fieldCaptures.filter(item => item.status === "Accepted");
  const pendingCaptures = fieldCaptures.filter(item => !["Accepted", "Closed"].includes(item.status));
  const capturesWithCorrections = fieldCaptures.filter(item => (item.sync.correctionVersions || []).length > 0);
  const linkedCaptures = fieldCaptures.filter(item => item.sync.acceptedForBilling === "Yes" || item.sync.acceptedForSafety === "Yes" || item.sync.acceptedForCloseout === "Yes" || item.related?.acceptedForBilling === "Yes" || item.related?.acceptedForSafety === "Yes" || item.related?.acceptedForCloseout === "Yes");
  const docsMissing = support.filter(item => ["Missing", "Needs Review", "Pending Review"].includes(item.status));
  const unresolvedException = exception && ["Accepted", "Blocked", "Reopened"].includes(exception.status);
  const exceptionEvidenceReady = !exception || (exception.evidenceLinks || []).length > 0 || exception.status === "Accepted";
  const base = [
    { label: "Map selected", ok: Boolean(project), detail: project ? `${project.map || project.id} selected for ${scope}.` : "Select a Map.", action: "Project & Map Hub" },
    { label: "Open tasks reviewed", ok: openTasks.length === 0, detail: openTasks.length ? `${openTasks.length} open task(s) remain.` : "No open tasks for selected Map.", action: "Tasks" }
  ];
  const billing = [
    { label: "Billing support complete", ok: docsMissing.length === 0, detail: docsMissing.length ? docsMissing.map(item => item.label).join(", ") : "Required billing support is present.", action: "Documents" },
    { label: "Billing readiness", ok: ["Ready to Bill", "Submitted", "Billed"].includes(readiness?.status) || Boolean(invoice), detail: readiness?.status || invoice?.status || "No invoice/readiness record.", action: "Billing" },
    { label: "Daily package exception disclosure", ok: true, detail: dailyPackageExceptions.length ? `${dailyPackageExceptions.length} approved package exception(s) disclosed in this packet.` : "No daily package exceptions to disclose.", action: "Billing" }
  ];
  const closeoutItems = [
    { label: "Closeout gates", ok: closeout.ready, detail: closeout.ready ? "All closeout gates clear." : closeout.missing.map(item => item.label).join(", "), action: "Project & Map Hub" },
    { label: "Admin closeout approval", ok: Boolean(project.adminApprovals?.closeout) || project.status === "Completed / Billed", detail: project.adminApprovals?.closeout?.status || project.status, action: "Project & Map Hub" }
  ];
  const billingCloseoutItems = closeoutReadiness.items.map(item => ({
    label: item.label,
    ok: item.ok,
    detail: item.detail,
    action: item.action
  }));
  const exceptionItems = [
    { label: "Exception status", ok: !unresolvedException, detail: exception ? `${exception.status}: ${exception.reason || "No reason"}` : "No exception on this Map.", action: "Project & Map Hub" },
    { label: "Exception evidence", ok: exceptionEvidenceReady, detail: exception ? `${(exception.evidenceLinks || []).length} linked evidence record(s).` : "No exception evidence required.", action: "Documents" }
  ];
  const safetyItems = [
    { label: "Safety actions closed", ok: openSafety.length === 0, detail: openSafety.length ? `${openSafety.length} open safety item(s).` : "No open safety actions.", action: "Safety & Risk" },
    { label: "Safety/QC clear", ok: closeout.qc ? ["Passed", "Approved Exception"].includes(closeout.qc.status) : openSafety.length === 0, detail: closeout.qc?.status || "No QC record.", action: "Safety & Risk" }
  ];
  if (scope === "Billing Packet") return [...base, ...billing, ...billingCloseoutItems, ...exceptionItems];
  if (scope === "Billing Closeouts") return [...base, ...billingCloseoutItems];
  if (scope === "Closeout Package") return [...base, ...closeoutItems, ...billing, ...safetyItems, ...exceptionItems];
  if (scope === "Exception Report") return [...base, ...exceptionItems];
  if (scope === "Field Capture Audit") return [
    ...base,
    { label: "Capture records synced", ok: fieldCaptures.every(item => ["Synced", "Accepted", "Closed"].includes(item.sync.status) || item.status === "Accepted"), detail: fieldCaptures.length ? `${fieldCaptures.length} capture record(s); ${fieldCaptures.filter(item => item.sync.status === "Synced" || item.status === "Accepted").length} synced/accepted.` : "No field captures recorded for this Map.", action: "Field Daily" },
    { label: "Review decisions complete", ok: pendingCaptures.length === 0, detail: pendingCaptures.length ? `${pendingCaptures.length} capture(s) still need review/correction.` : "All captured evidence has a review outcome.", action: "Operations" },
    { label: "Corrections versioned", ok: capturesWithCorrections.every(item => item.sync.correctedAt || item.status === "Accepted"), detail: capturesWithCorrections.length ? `${capturesWithCorrections.length} capture(s) include correction history.` : "No correction history required.", action: "Field Daily" },
    { label: "Accepted evidence linked", ok: acceptedCaptures.length === 0 || linkedCaptures.length >= acceptedCaptures.length, detail: acceptedCaptures.length ? `${linkedCaptures.length}/${acceptedCaptures.length} accepted capture(s) linked to billing/safety/closeout.` : "No accepted field captures yet.", action: "Documents" }
  ];
  if (scope === "Safety Audit") return [...base, ...safetyItems, ...exceptionItems];
  if (scope === "Compliance") return [...base, ...safetyItems];
  if (scope === "Retainage / AR" || scope === "Payment Ledger") return [...base, { label: "Invoice/payment record", ok: Boolean(invoice), detail: invoice ? `${invoice.id} · ${invoice.status}` : "No invoice record.", action: "Billing" }];
  if (scope === "Financial Closeout") return [
    ...base,
    { label: "Can we close billing?", ok: financialGate.ready, detail: financialGate.ready ? "SQUAN billing, payment, 10% held-back money, documents, safety, and task cleanup are clear." : financialGate.blockers.map(item => item.label).join(", "), action: "Project & Map Hub" },
    { label: "Admin financial closeout", ok: financialCloseout?.status === "Closed", detail: financialCloseout ? `${financialCloseout.status} by ${financialCloseout.by || "Admin"} ${financialCloseout.at ? `on ${formatDateTime(financialCloseout.at)}` : ""}` : "Admin has not financially closed this Map.", action: "Project & Map Hub" },
    { label: "SQUAN submission linked", ok: Boolean(financialGate.submission || ["Submitted to SQUAN", "Paid 90% / Retainage Held", "Paid"].includes(invoice?.status || "")), detail: financialGate.submission ? `${financialGate.submission.id || financialGate.submission.invoiceNumber} submitted ${financialGate.submission.submissionDate || "date not recorded"}.` : "No SQUAN submission/receipt linked.", action: "Billing" },
    { label: "Payment deposit proof", ok: financialGate.items.find(item => item.key === "paymentDeposit")?.ok, detail: financialGate.items.find(item => item.key === "paymentDeposit")?.detail || "Cash receipt and bank proof are required.", action: "Billing" },
    { label: "10% retainage status", ok: financialGate.items.find(item => item.key === "retainage")?.ok, detail: financialGate.items.find(item => item.key === "retainage")?.detail || "10% held-back money must be paid, released, or accepted by exception.", action: "Billing" },
    { label: "10% deposit proof", ok: financialGate.items.find(item => item.key === "retainageDeposit")?.ok, detail: financialGate.items.find(item => item.key === "retainageDeposit")?.detail || "10% deposit proof is required when 10% held-back money is paid.", action: "Billing" },
    { label: "Financial closeout tasks closed", ok: financialTasks.length === 0, detail: financialTasks.length ? `${financialTasks.length} financial closeout task(s) remain open.` : "No open financial closeout tasks.", action: "Tasks" },
    { label: "Report row available", ok: financialCloseoutReportRows(project).length > 0, detail: financialCloseoutReportRows(project).length ? "Financial Closeout Report includes this Map." : "No financial closeout report data available yet.", action: "Reports" }
  ];
  if (scope === "Collections Packet") return collectionsPacketChecklist(project);
  return [...base, ...billing, ...closeoutItems, ...safetyItems, ...exceptionItems];
}

function collectionsPacketScopeRows(project) {
  const aging = arAgingRows().filter(item => item.project === project.id);
  const tasks = (state.data.tasks || []).filter(task => task.source === "AR aging escalation" && task.project === project.id);
  const taskIds = new Set(tasks.map(task => task.id));
  const evidence = (state.data.documents || []).filter(document => document.project === project.id && (document.type === "Collection Communication" || document.collectionTaskId || taskIds.has(document.relatedTask)));
  const submissions = collectionsSubmissionsForProject(project.id);
  const highRisk = aging.filter(item => item.risk === "High");
  const escalatedIds = new Set(tasks.map(task => task.relatedId).filter(Boolean));
  return { aging, tasks, evidence, submissions, highRisk, escalatedIds };
}

function collectionsSubmissionsForProject(projectId) {
  return (state.data.collectionSubmissions || [])
    .filter(item => item.project === projectId)
    .slice()
    .sort((a, b) => String(b.modifiedAt || b.submittedAt || b.createdAt || "").localeCompare(String(a.modifiedAt || a.submittedAt || a.createdAt || "")));
}

function collectionsPacketChecklist(project) {
  const rows = collectionsPacketScopeRows(project);
  const openTasks = rows.tasks.filter(task => task.status !== "Closed");
  const undocumentedOpenTasks = openTasks.filter(task => {
    const attempts = task.collectionAttempts || [];
    const evidence = collectionEvidenceForTask(task);
    return !task.nextFollowUpDate && !task.promisedPaymentDate && !task.disputeReason && !attempts.length && !evidence.length;
  });
  const unlinkedHighRisk = rows.highRisk.filter(item => !rows.tasks.some(task => task.relatedId === item.id || task.project === item.project && task.arKind === item.kind));
  const tasksWithAttemptsMissingEvidence = rows.tasks.filter(task => (task.collectionAttempts || []).length && !collectionEvidenceForTask(task).length);
  const disputesMissingReason = rows.tasks.filter(task => String(task.status || "").toLowerCase().includes("dispute") && !task.disputeReason);
  return [
    { label: "Map selected", ok: Boolean(project), detail: project ? `${project.map || project.id} collections packet selected.` : "Select a Map.", action: "Reports" },
    { label: "Payment rows reviewed", ok: rows.aging.length > 0 || rows.tasks.length === 0, detail: rows.aging.length ? `${rows.aging.length} payment row(s), ${currency(sum(rows.aging, "amount"))} exposure.` : "No open payment exposure for this Map.", action: "Billing" },
    { label: "High-risk payment escalated", ok: unlinkedHighRisk.length === 0, detail: unlinkedHighRisk.length ? `${unlinkedHighRisk.length} high-risk row(s) need collection task escalation.` : "High-risk payment has an escalation record or no high-risk payment exists.", action: "Billing" },
    { label: "Open follow-ups documented", ok: undocumentedOpenTasks.length === 0, detail: undocumentedOpenTasks.length ? `${undocumentedOpenTasks.length} open collection task(s) need contact, promise, dispute, or next follow-up.` : "Open collection work has next action evidence.", action: "Tasks" },
    { label: "Communication evidence linked", ok: tasksWithAttemptsMissingEvidence.length === 0, detail: tasksWithAttemptsMissingEvidence.length ? `${tasksWithAttemptsMissingEvidence.length} task(s) have contact attempts without evidence document.` : `${rows.evidence.length} collection evidence record(s) linked.`, action: "Documents" },
    { label: "Disputes documented", ok: disputesMissingReason.length === 0, detail: disputesMissingReason.length ? `${disputesMissingReason.length} disputed task(s) need reason.` : "Dispute reasons are documented when needed.", action: "Billing" },
    { label: "SQUAN response tracked", ok: rows.submissions.length === 0 || rows.submissions.some(item => item.responseStatus || item.nextFollowUpDate || item.promisedPaymentDate), detail: rows.submissions.length ? `${rows.submissions.length} collections submission(s); latest ${rows.submissions[0].responseStatus || rows.submissions[0].status || "sent"}.` : "No SQUAN collections submission sent yet.", action: "Reports" }
  ];
}

function reportPrintScopes() {
  return ["Full Report Set", "Executive Report", "Cash Forecast Packet", "Billing Packet", "Billing Closeouts", "Financial Closeout", "Closeout Package", "Exception Report", "Payment Ledger", "Collections Packet", "Collections Decision Audit", "Daily Package Audit", "Completed Forms", "Field Capture Audit", "Compliance", "Safety Audit"];
}

function printScopeSlug(scope) {
  return String(scope || "Full Report Set").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function reportExceptionProjects(projects, selectedProject) {
  const selected = selectedProject ? [selectedProject] : [];
  if (state.reportExceptionFilter === "Selected Map") return selected;
  if (state.reportExceptionFilter === "All Exceptions") return projects.filter(project => project.adminApprovals?.exception);
  if (state.reportExceptionFilter === "Active / Reopened") return projects.filter(project => ["Accepted", "Blocked", "Reopened"].includes(project.adminApprovals?.exception?.status));
  if (state.reportExceptionFilter === "Resolved") return projects.filter(project => project.adminApprovals?.exception?.status === "Resolved");
  if (state.reportExceptionFilter === "No Exception") return projects.filter(project => !project.adminApprovals?.exception);
  return selected;
}

function renderExportPackageCenter(project) {
  const readiness = scopedRows("billingReadiness").find(item => item.project === project.id);
  const closeout = closeoutReview(project);
  const invoice = scopedRows("invoices").find(item => item.project === project.id);
  const safety = safetyAuditSummary();
  const packetControls = packetAlertControlsForProjects([project]);
  const scopeMismatches = packetScopeMismatchEvents([project]);
  const resolvedMismatches = packetControls.filter(control => control.kind === "Resolved" && String(control.alertId || "").startsWith("packet-scope-mismatch:"));
  const packetReadiness = packetSubmissionReadiness(project);
  const evidenceRows = fieldEvidenceManifest(project);
  const collectionTasks = (state.data.tasks || []).filter(task => task.source === "AR aging escalation" && task.project === project.id);
  const collectionEvidence = (state.data.documents || []).filter(document => collectionTasks.some(task => document.collectionTaskId === task.id || (task.collectionEvidenceIds || []).includes(document.id)));
  const acceptedEvidence = evidenceRows.filter(item => item.status === "Accepted").length;
  const rejectedEvidence = evidenceRows.filter(item => item.status === "Rejected").length;
  const pendingEvidence = Math.max(0, evidenceRows.length - acceptedEvidence - rejectedEvidence);
  const packages = [
    {
      title: "SQUAN billing packet",
      status: readiness?.status || "Not Ready",
      detail: "Invoice, dailies, SOT, photos, as-builts, QC, and support manifest.",
      href: `/api/reports/billing-package?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Completed forms export",
      status: `${completedFormExportRows(project).length} forms`,
      detail: "Street sheet, daily production report, JSA/PPE, SOT, inspections, signatures, and linked form files.",
      href: `/api/reports/completed-forms?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Map closeout packet",
      status: closeout.ready ? "Ready" : "Needs Review",
      detail: `${closeout.missing.length} closeout blocker(s); field, QC, billing, and documents.`,
      href: `/api/reports/closeout-package?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Financial closeout audit",
      status: project.adminApprovals?.financialCloseout?.status || "Pending",
      detail: "Financial gate snapshot, closed/reopened status, invoice, SQUAN submission, 10% held back, deposit proof, and approval timeline.",
      href: `/api/reports/financial-closeouts?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Exception report",
      status: project.adminApprovals?.exception?.status || "No Exception",
      detail: "Accepted risk, linked evidence, resolution history, reopen/change-control history, and audit trail.",
      href: `/api/reports/exception-report?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Packet lock history",
      status: `${(state.data.packetLocks || []).filter(lock => lock.project === project.id).length} records`,
      detail: `Finalized/reopened packet locks, scope history, task links, and ${packetControls.length} alert control record(s).`,
      href: `/api/reports/packet-locks?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Packet lock CSV",
      status: "CSV",
      detail: "Flat packet timeline, packet tasks, evidence reviews, alert controls, snoozes, dismissals, reactivations, and resolved mismatches.",
      href: `/api/reports/packet-locks.csv?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Evidence review history",
      status: rejectedEvidence ? "Needs Review" : `${acceptedEvidence}/${evidenceRows.length} accepted`,
      detail: `${acceptedEvidence} accepted; ${rejectedEvidence} rejected; ${pendingEvidence} pending before SQUAN billing submission.`,
      href: `/api/reports/packet-locks?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Scope mismatch history",
      status: scopeMismatches.length ? "Needs Review" : `${resolvedMismatches.length} resolved`,
      detail: `${scopeMismatches.length} active scope mismatch item(s); ${resolvedMismatches.length} resolved mismatch record(s).`,
      href: `/api/reports/packet-locks?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Submission readiness",
      status: packetReadiness.ready ? "Ready" : "Needs Review",
      detail: packetReadiness.ready ? "No reopened locks, unresolved scope mismatches, or open packet tasks." : `${packetReadiness.blockers.length} packet blocker(s) must be reviewed before submission.`,
      href: `/api/reports/packet-locks?project=${encodeURIComponent(project.id)}`
    },
    {
      title: "Safety audit packet",
      status: `${safety.score} pts`,
      detail: "Safety events, Form 12, certs, equipment inspections, and safety docs.",
      href: "/api/reports/audit-package"
    },
    {
      title: "Payment Ledger export",
      status: invoice?.status || "Open",
      detail: "Invoices, 90% paid, 10% held back, release dates, disputes, and pay-when-paid.",
      href: "/api/reports/ar-retainage"
    },
    {
      title: "Collections packet",
      status: collectionTasks.length ? `${collectionTasks.length} tasks` : "No escalations",
      detail: `${collectionEvidence.length} communication evidence record(s), promised payment dates, disputes, and follow-up history.`,
      href: "/api/reports/collections-packet"
    },
    {
      title: "People / equipment compliance",
      status: beginningPhaseReview(project).ready ? "Clear" : "Needs Review",
      detail: "Crew certs, background dates, equipment inspections, and release blockers.",
      href: "/api/reports/compliance"
    }
  ];
  return `
    <section class="panel report-section no-print">
      <div class="panel-header">
        <h2>Export packages</h2>
        <span>${project.map || project.id}</span>
      </div>
      <div class="export-package-grid">
        ${packages.map(item => `
          <article>
            <div class="card-topline">
              <h3>${item.title}</h3>
              <span class="status ${statusClass(item.status)}">${item.status}</span>
            </div>
            <p>${item.detail}</p>
            <a class="secondary-btn" href="${item.href}" target="_blank" rel="noreferrer">Download JSON</a>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

function renderExecutiveReport() {
  const projects = scopedRows("projects");
  const invoices = scopedRows("invoices");
  const retainage = scopedRows("retainageLedger");
  const safety = scopedRows("safety");
  const readiness = scopedRows("billingReadiness");
  const revenue = sum(projects, "estimatedRevenue");
  const forecastCost = sum(projects, "forecastCost");
  const openRisks = safety.filter(item => item.status !== "Closed").length;
  const score = Math.max(0, 100 - openRisks * 4);
  return `
    <section class="panel report-section printable report-scope-executive-report">
      <div class="panel-header">
        <h2>Executive Report</h2>
        <span>${formatDateTime(new Date().toISOString())}</span>
      </div>
      <div class="report-metrics">
        ${metric("Active maps", projects.length, "All visible map records")}
        ${metric("Forecast margin", `${Math.round(((revenue - forecastCost) / Math.max(1, revenue)) * 100)}%`, `${currency(revenue - forecastCost)} forecast gross profit`)}
        ${metric("Cash exposure", currency(sum(invoices, "gross") - sum(invoices, "paid90")), "Unpaid 90% and pay-when-paid exposure")}
        ${metric("10% held back", currency(sum(retainage, "heldAmount")), "Future release schedule")}
        ${metric("Open safety items", openRisks, "Safety/Form 12 items")}
        ${metric("SQUAN score", `${score} pts`, "Estimated from open safety items")}
      </div>
      <div class="report-table">
        ${projects.map(project => {
          const ready = readiness.find(item => item.project === project.id);
          return `
            <article>
              <strong>${project.id}</strong>
              <span>${project.scope}</span>
              <small>Margin ${margin(project)}% · ${project.status} · Bill by ${project.billBy} · Billing ${ready?.status || "Not Ready"}</small>
            </article>
          `;
        }).join("")}
      </div>
    </section>
  `;
}

function renderCashForecastExportPacket() {
  const scenario = cashScenarioConfig();
  const rows = cashForecastRows(scenario.key);
  const outflows = cashOutflowRows();
  const summary = cashForecastSummary(rows, outflows);
  const buckets = forecastWeekBuckets(rows, outflows, summary.startingCash);
  const tasks = cashDecisionTaskRows(summary);
  const history = cashDecisionHistoryRows(summary);
  const reconciliation = cashReconciliationRows();
  const company = state.data.company || {};
  const delays = company.cashScenarioDelays || {};
  return `
    <section class="panel report-section printable report-scope-cash-forecast-packet">
      <div class="panel-header">
        <h2>Cash Forecast Packet</h2>
        <span>${scenario.label} · ${formatDateTime(new Date().toISOString())}</span>
      </div>
      <div class="report-metrics">
        ${metric("Starting cash", currency(summary.startingCash), `Minimum threshold ${currency(summary.minimumCashThreshold)}`)}
        ${metric("13-week inflow", currency(summary.next13Total), `${summary.next13.length} receipt item(s)`)}
        ${metric("13-week outflow", currency(summary.outflow13Total), `${summary.outflow13.length} cost item(s)`)}
        ${metric("Ending cash", currency(summary.endingCash), summary.thresholdGap < 0 ? `${currency(Math.abs(summary.thresholdGap))} below threshold` : "Above threshold")}
        ${metric("At-risk exposure", currency(summary.atRisk), `${summary.payWhenPaidCount} pay-when-paid hold(s)`)}
        ${metric("Future retainage", currency(summary.futureRetainage), "Outside next 13 weeks")}
        ${metric("Actual receipts", currency(summary.actualReceived), `${currency(summary.receiptVariance)} variance`)}
      </div>
      <div class="cash-report-block">
        <h3>Forecast assumptions</h3>
        <dl>
          <div><dt>Cash on hand</dt><dd>${currency(company.cashOnHand || 0)}</dd></div>
          <div><dt>Weekly overhead</dt><dd>${currency(company.weeklyOverhead || 0)}</dd></div>
          <div><dt>Minimum cash threshold</dt><dd>${currency(company.minimumCashThreshold || 0)}</dd></div>
          <div><dt>Scenario delay days</dt><dd>${Number(delays.baseline ?? 0)} / ${Number(delays.delay15 ?? 15)} / ${Number(delays.delay30 ?? 30)} / ${Number(delays.delay45 ?? 45)}</dd></div>
        </dl>
      </div>
      <div class="report-table">
        <article>
          <strong>Actual receipt reconciliation</strong>
          <span>${reconciliation.length} receipt(s), ${currency(sum(reconciliation, "variance"))} total variance</span>
        </article>
        ${reconciliation.map(item => `
          <article>
            <strong>${item.id}: ${item.map}</strong>
            <span>${item.type} · expected ${currency(item.expectedAmount)} · actual ${currency(item.actualAmount)} · variance ${currency(item.variance)}</span>
            <small>${item.actualDate || "No receipt date"} · ${item.reference || "No reference"} · ${item.status}</small>
          </article>
        `).join("") || `<div class="empty">No actual cash receipts recorded.</div>`}
      </div>
      <div class="report-table">
        <article>
          <strong>13-week cash buckets</strong>
          <span>Inflow, outflow, net, and running cash by week</span>
        </article>
        ${buckets.map(bucket => `
          <article>
            <strong>Week ${bucket.index}: ${bucket.start} to ${bucket.end}</strong>
            <span>In ${currency(bucket.inflow)} · Out ${currency(bucket.outflow)} · Net ${currency(bucket.net)} · Running ${currency(bucket.runningCash)}</span>
            <small>${bucket.runningCash < summary.minimumCashThreshold ? "Below threshold" : "Above threshold"}</small>
          </article>
        `).join("")}
      </div>
      <div class="report-table">
        <article>
          <strong>Open cash follow-through tasks</strong>
          <span>${tasks.filter(task => task.status !== "Closed").length} open task(s)</span>
        </article>
        ${tasks.map(task => `
          <article>
            <strong>${task.id}: ${task.title}</strong>
            <span>${task.owner} · due ${task.dueDate} · ${task.status}</span>
            <small>${task.notes}</small>
          </article>
        `).join("") || `<div class="empty">No cash decision tasks.</div>`}
      </div>
      <div class="report-table">
        <article>
          <strong>Decision history and manager review</strong>
          <span>${history.length} decision event(s)</span>
        </article>
        ${history.map(item => `
          <article>
            <strong>${labelize(item.action || "cash decision")} · ${item.reviewStatus}</strong>
            <span>${item.by || "Admin"} · ${formatDateTime(item.at)} · ${item.task?.id || item.task || "No task"}</span>
            <small>Original ${currency(item.originalEnding)} · current movement ${item.forecastStatus} ${currency(item.delta)} · ${item.notes || ""}</small>
          </article>
        `).join("") || `<div class="empty">No cash decision history.</div>`}
      </div>
    </section>
  `;
}

