function renderMapAtAGlance(project, context) {
  const readiness = context.readiness;
  const rule = context.rule || {};
  const operationalItems = [
    ["Crew", project.crew],
    ["Required certs", project.requiredCerts],
    ["Billing deadline", formatDateRisk(project.billBy)],
    ["Document control", project.docs],
    ["Open actions", Number(context.openTasks.length || 0) + Number(context.openRisks.length || 0) + Number(context.openObstacles.length || 0)],
    ["Labor hours", `${Number(context.totalHours || 0).toFixed(1)} hrs`],
    ["Documents / dailies", `${context.documents.length} / ${context.dailies.length}`],
    ["Invoices", context.invoices.length]
  ];
  const contractItems = [
    ["Daily/SOT SLA", `${rule.dailyDueHours || 24} hours`],
    ["Invoice window", `${rule.invoiceWindowDays || 30} days`],
    ["Retainage", `${rule.retainagePercent || 10}% / ${rule.retainageReleaseMonths || 12} months`],
    ["SQUAN score floor", `${rule.safetyScoreMinimum || 90} pts`],
    ["Pay when paid", rule.payWhenPaid || "Yes"],
    ["COI payment hold", rule.coiPaymentHold || "Yes"]
  ];
  const financialItems = canViewFinancials() ? [
    ["Revenue", currency(project.estimatedRevenue)],
    ["Actual cost", currency(project.actualCost)],
    ["Forecast", currency(project.forecastCost)],
    ["Margin", `${margin(project)}%`],
    ["Billable", currency(readiness?.billableAmount || 0)],
    ["Readiness", readiness?.status || "Not Ready"]
  ] : [];
  return `
    <section class="section-block map-at-glance">
      <div class="section-heading">
        <div>
          <h3>Map at a glance</h3>
          <p>Core operating facts, contract controls, and role-visible financials in one place.</p>
        </div>
        <span class="status ${statusClass(readiness?.status || project.status)}">${readiness?.status || project.status}</span>
      </div>
      <div class="map-glance-grid">
        <article>
          <h4>Operations</h4>
          <div class="compact-fact-grid">
            ${operationalItems.map(([label, value]) => `<span>${label}<strong>${value}</strong></span>`).join("")}
          </div>
        </article>
        <article>
          <h4>SQUAN controls</h4>
          <div class="compact-fact-grid">
            ${contractItems.map(([label, value]) => `<span>${label}<strong>${value}</strong></span>`).join("")}
          </div>
        </article>
        ${financialItems.length ? `
          <article>
            <h4>Money</h4>
            <div class="compact-fact-grid">
              ${financialItems.map(([label, value]) => `<span>${label}<strong>${value}</strong></span>`).join("")}
            </div>
          </article>
        ` : ""}
      </div>
    </section>
  `;
}

