function renderDailyStartSubmitGuide(project, daily) {
  const startGate = fieldStartGate(project, daily);
  const preJob = preJobGate(project, daily);
  const hasDraftQuantity = Number(daily?.laborHours || 0) > 0 || !["Submitted"].includes(daily?.status || "");
  const productionReady = (state.data.dailyProduction || []).some(item => item.project === project?.id && item.dailyId === daily?.id && Number(item.quantity || 0) > 0) || hasDraftQuantity;
  const evidenceReady = (state.data.photoEvidence || []).some(item => item.project === project?.id) || (daily?.status === "Submitted");
  const handoffReady = daily?.status === "Submitted";
  const steps = [
    { label: "Release", status: startGate.clear ? "Clear" : "Blocked", detail: startGate.clear ? "Admin release and setup gates are clear." : startGate.blockers.map(item => item.label).join(", ") },
    { label: "Pre-job", status: preJob.status === "Clear to Start" ? "Clear" : "Blocked", detail: preJob.items.filter(item => !item.ok).map(item => item.label).join(", ") || "JSA, crew, equipment, 811, and safety checks complete." },
    { label: "Production", status: productionReady ? "Ready" : "Pending", detail: productionReady ? "Production quantity is ready to post." : "Enter production quantity before submit." },
    { label: "Evidence", status: evidenceReady ? "Ready" : "Pending", detail: evidenceReady ? "Photo/GIS evidence exists or will be generated on submit." : "Add or confirm photo/obstacle notes." },
    { label: "Submit", status: handoffReady ? "Submitted" : startGate.clear && preJob.status === "Clear to Start" ? "Ready" : "Blocked", detail: handoffReady ? "Downstream evidence handoff is posted." : "Submit creates Daily Report, SOT, time, materials, photos, QC, and billing readiness." }
  ];
  return `
    <section class="daily-start-submit-guide">
      <div class="section-heading compact">
        <h3>Start-to-submit guide</h3>
        <span class="status ${statusClass(steps.at(-1).status)}">${steps.at(-1).status}</span>
      </div>
      <div class="daily-start-submit-grid">
        ${steps.map((step, index) => `
          <article class="${statusClass(step.status)}">
            <span>${index + 1}</span>
            <div>
              <strong>${step.label}</strong>
              <small>${step.detail}</small>
            </div>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

