function dailyEvidencePackageId(dailyOrId) {
  const id = typeof dailyOrId === "string" ? dailyOrId : dailyOrId?.id || "";
  return `PKG-${id}`.replace(/[^A-Z0-9-]/gi, "-").toUpperCase();
}

function dailyEvidencePackageStatus(projectId, dailyId) {
  const foremanView = state.role === "Foreman";
  const packageId = dailyEvidencePackageId(dailyId);
  const docs = (state.data.documents || []).filter(item => item.project === projectId && (item.dailyId === dailyId || item.packageId === packageId));
  const forms = (state.data.formSubmissions || []).filter(item => item.project === projectId && (item.dailyId === dailyId || item.packageId === packageId));
  const photos = (state.data.photoEvidence || []).filter(item => item.project === projectId && (item.linkedRecord === dailyId || item.packageId === packageId));
  const time = (state.data.timeEntries || []).filter(item => item.project === projectId && (item.dailyId === dailyId || item.packageId === packageId || String(item.notes || "").includes(dailyId)));
  const qc = (state.data.qcCloseouts || []).filter(item => item.project === projectId && (item.dailyId === dailyId || item.packageId === packageId || String(item.notes || "").includes(dailyId)));
  const readiness = (state.data.billingReadiness || []).find(item => item.project === projectId);
  const requiredDocTypes = ["Daily Report", "SOT", "Photos", "As-built", "Material Usage", "Crew Time"];
  const rawItems = [
    { key: "daily-report", label: "Daily Report", ok: docs.some(item => item.type === "Daily Report" && item.status === "Submitted"), detail: docs.find(item => item.type === "Daily Report")?.id || "Generated Daily Report missing." },
    { key: "sot", label: "SOT", ok: docs.some(item => item.type === "SOT" && item.status === "Submitted"), detail: docs.find(item => item.type === "SOT")?.id || "SOT support missing." },
    { key: "forms", label: "JSA / forms", ok: forms.some(item => item.type === "JSA" && item.status === "Submitted"), detail: `${forms.length} form record(s) tied to this daily.` },
    { key: "photos", label: "Photo evidence", ok: photos.length > 0, detail: photos.length ? `${photos.length} photo item(s) tied to package.` : "No photo evidence tied to this daily." },
    { key: "time", label: "Crew time", ok: time.length > 0 && time.every(item => ["Approved", "Ready"].some(status => String(item.approvalStatus || item.payrollStatus || "").includes(status))), detail: time.length ? `${time.length} time row(s); ${time.map(item => item.payrollStatus).join(", ")}` : "No time row tied to this daily." },
    { key: "materials", label: "Materials", ok: docs.some(item => item.type === "Material Usage" && item.status === "Submitted"), detail: docs.find(item => item.type === "Material Usage")?.id || "Material usage support missing." },
    { key: "qc", label: "QC review", ok: qc.length > 0, detail: qc.length ? `${qc[0].id}; ${qc[0].status}` : "QC review packet not opened." },
    { key: "billing", label: foremanView ? "Sent to Office" : "Billing readiness", ok: Boolean(readiness) && readiness.submittedDailies > 0, detail: readiness ? (foremanView ? `${readiness.status}; missing ${readiness.missingItems}` : `${readiness.status}; missing ${readiness.missingItems}`) : (foremanView ? "Office proof status not refreshed yet." : "Billing readiness not recomputed.") }
  ];
  const items = rawItems.map(item => {
    const exception = dailyPackageCorrectionException(projectId, dailyId, item.key);
    if (!exception) return item;
    return {
      ...item,
      ok: true,
      exception,
      detail: `${item.detail} Exception accepted by ${exception.by || "Office"}: ${exception.reason || "Authorized package intake exception."}`
    };
  });
  return {
    packageId,
    docs,
    forms,
    photos,
    time,
    qc,
    readiness,
    requiredDocTypes,
    items,
    ready: items.every(item => item.ok),
    status: items.every(item => item.ok) ? (foremanView ? "Office Proof Ready" : "Evidence QA Ready") : (foremanView ? "Office Proof Needs Review" : "Evidence QA Needs Review")
  };
}

function renderDailyEvidenceQaPanel(project, dailyId = "") {
  const latestDaily = dailyId
    ? (state.data.dailies || []).find(item => item.id === dailyId)
    : (state.data.dailies || []).filter(item => item.project === project?.id && item.status === "Submitted").sort((a, b) => String(b.modifiedAt || b.date || "").localeCompare(String(a.modifiedAt || a.date || "")))[0];
  if (!project || !latestDaily) return "";
  const qa = dailyEvidencePackageStatus(project.id, latestDaily.id);
  const foremanView = state.role === "Foreman";
  return `
    <section class="daily-evidence-qa">
      <div class="section-heading compact">
        <div>
          <h3>${foremanView ? "Daily proof check" : "Daily evidence QA"}</h3>
          <small>${qa.packageId} ties the submitted daily to documents, photos, time, QC, and ${foremanView ? "Office review" : "billing readiness"}.</small>
        </div>
        <span class="status ${statusClass(qa.status)}">${qa.status}</span>
      </div>
      <div class="daily-evidence-qa-grid">
        ${qa.items.map(item => `
          <article class="${item.ok ? "ready" : "blocked"}">
            <span class="status ${statusClass(item.ok ? "Ready" : "Needs Review")}">${item.ok ? "Ready" : "Needs Review"}</span>
            <strong>${item.label}</strong>
            <small>${item.detail}</small>
          </article>
        `).join("")}
      </div>
      <div class="map-preview-actions">
        <button class="secondary-btn" data-workflow-action="Documents" data-workflow-id="${project.id}" data-workflow-focus="Map evidence">Open documents</button>
        <button class="secondary-btn" data-workflow-action="Time Tracking" data-workflow-id="${project.id}">Open crew time</button>
        <button class="secondary-btn" data-workflow-action="Safety & Risk" data-workflow-id="${project.id}">Open QC</button>
        ${foremanView ? "" : `<button class="secondary-btn" data-workflow-action="Billing" data-workflow-id="${project.id}">Open billing readiness</button>`}
      </div>
    </section>
  `;
}

