function renderDailySubmitGuard(startGate, preJob, unitOptions, equipmentOptions) {
  const context = selectedFieldContext();
  const checklist = foremanStartChecklist(context.project, context.daily);
  const blockers = [
    ...(startGate.clear ? [] : startGate.blockers.map(item => `Release gate: ${item.label}`)),
    ...checklist.filter(item => !item.ok).map(item => `Foreman start: ${item.label}`),
    ...preJob.items.filter(item => !item.ok).map(item => `Pre-job: ${item.label}`),
    ...(unitOptions.length ? [] : ["Production: no work unit is available for this Map"]),
    ...(equipmentOptions.length ? [] : ["Equipment: no available equipment record is selected"])
  ].filter((item, index, list) => list.indexOf(item) === index);
  const ready = blockers.length === 0;
  return `
    <section id="dailySubmitGuard" class="daily-submit-guard ${ready ? "ready" : "blocked"}">
      <div class="section-heading compact">
        <span class="step-badge">${ready ? "✓" : "!"}</span>
        <div>
          <h3>${ready ? "Ready for final review" : "Submit blocked"}</h3>
          <small>${ready ? "Review production, time, materials, notes, and photos before submitting." : "Clear these items before the daily can be submitted."}</small>
        </div>
        <span class="status ${statusClass(ready ? "Ready" : "Blocked")}">${ready ? "Ready" : "Blocked"}</span>
      </div>
      <ul data-daily-submit-guard-list>
        ${blockers.length ? blockers.map(item => `<li>${item}</li>`).join("") : `
          <li>Production quantity, labor hours, equipment hours, materials, daily notes, and photo/obstacle notes will be checked when you tap Submit Daily.</li>
        `}
      </ul>
    </section>
  `;
}

function renderDailySubmitRequirements(startGate, unitOptions, equipmentOptions) {
  const context = selectedFieldContext();
  const checklist = foremanStartChecklist(context.project, context.daily);
  const preStartReady = checklist.every(item => item.ok);
  const requirements = [
    { label: "Release-to-field gate clear", ok: startGate.clear, detail: startGate.clear ? "Ready" : startGate.blockers.map(item => item.label).join(", ") },
    { label: "Foreman start checklist clear", ok: preStartReady, detail: preStartReady ? "JSA/PPE, crew, equipment, 811, safety, and Field Maps are clear." : checklist.filter(item => !item.ok).map(item => item.label).join(", ") },
    { label: "Production unit selected", ok: unitOptions.length > 0, detail: unitOptions.length ? `${unitOptions.length} available` : "No work units on this Map" },
    { label: "Equipment available", ok: equipmentOptions.length > 0, detail: equipmentOptions.length ? `${equipmentOptions.length} assets available` : "No equipment records available" },
    { label: "Labor, material, notes, and photo evidence captured", ok: true, detail: "Validated when Submit Daily is clicked" }
  ];
  return `
    <section class="daily-submit-requirements">
      <div class="section-heading compact">
        <h3>Submit requirements</h3>
        <span>Daily report + Office proof</span>
      </div>
      <div class="requirement-grid">
        ${requirements.map(item => `
          <article class="${item.ok ? "ready" : "blocked"}">
            <strong>${item.ok ? "Ready" : "Blocked"}</strong>
            <span>${item.label}</span>
            <small>${item.detail}</small>
          </article>
        `).join("")}
      </div>
    </section>
  `;
}

