function requiredCertList(project) {
  return String(project?.requiredCerts || "")
    .split(",")
    .map(item => item.trim())
    .filter(Boolean);
}

function hasCert(person, cert) {
  const certText = String(person.certs || "").toLowerCase();
  const target = cert.toLowerCase();
  if (target.includes("bucket")) return certText.includes("bucket");
  if (target.includes("traffic") || target.includes("flagger")) return certText.includes("traffic") || certText.includes("flagger");
  if (target.includes("trench")) return certText.includes("trench");
  if (target.includes("first aid") || target.includes("cpr")) return certText.includes("first aid") || certText.includes("cpr");
  if (target.includes("osha")) return certText.includes("osha");
  return certText.includes(target);
}

function crewReadiness(project) {
  const required = requiredCertList(project);
  const people = scopedRows("people").filter(person => person.crew === project?.crew);
  const members = people.map(person => {
    const missing = required.filter(cert => !hasCert(person, cert));
    const days = daysUntil(person.nextExpiration);
    const blocked = person.compliance === "Blocked" || missing.length > 0 || (days !== null && days < 0);
    const warning = !blocked && days !== null && days <= 30;
    return {
      person,
      missing,
      status: blocked ? "Blocked" : warning ? "Expiring" : "Clear",
      detail: missing.length ? `Missing ${missing.join(", ")}` : `${person.certs}; expires ${person.nextExpiration}`
    };
  });
  return {
    status: members.some(item => item.status === "Blocked") ? "Blocked" : members.some(item => item.status === "Expiring") ? "Needs Review" : "Clear",
    required,
    members
  };
}

function equipmentReadiness(project) {
  const rows = scopedRows("equipment").filter(item => item.assigned === project?.crew || item.assigned === project?.id);
  const assets = rows.map(item => {
    const days = daysUntil(item.inspectionDue);
    const blocked = item.status === "Unavailable" || (days !== null && days < 0);
    const warning = !blocked && days !== null && days <= 30;
    return {
      item,
      status: blocked ? "Unavailable" : warning ? "Scheduled" : item.status || "Available",
      detail: item.inspectionDue === "N/A" ? item.notes : `Inspection/calibration due ${item.inspectionDue}`
    };
  });
  return {
    status: assets.some(asset => asset.status === "Unavailable") ? "Unavailable" : assets.some(asset => asset.status === "Scheduled") ? "Needs Review" : "Available",
    assets
  };
}

function preJobGate(project, daily) {
  const crew = crewReadiness(project);
  const equipment = equipmentReadiness(project);
  const documents = scopedRows("documents").filter(item => item.project === project?.id);
  const has811 = documents.some(item => item.type === "811" && !["Needs Review", "Pending"].includes(item.status));
  const safetyDocs = preJobSafetyDocumentGaps(project, documents, daily);
  const items = [
    { label: "JSA started", ok: ["Complete", "Submitted"].includes(daily?.jsa) || (state.data.formSubmissions || []).some(item => item.project === project?.id && item.type === "JSA") },
    { label: "Crew certs checked", ok: crew.status === "Clear" },
    { label: "Equipment inspection checked", ok: equipment.status === "Available" },
    { label: "811 current", ok: has811 },
    { label: "Safety documents checked", ok: safetyDocs.length === 0 }
  ];
  return {
    status: items.every(item => item.ok) ? "Clear to Start" : "Blocked",
    items
  };
}

function preJobSafetyDocumentGaps(project, documents, daily = {}) {
  const jsaStarter = ["Complete", "Submitted", "Draft"].includes(daily?.jsa) || ["Draft", "Submitted"].includes(daily?.status) || (state.data.formSubmissions || []).some(item => item.project === project?.id && item.type === "JSA");
  const truePreJobTypes = new Set(["GIS / Field Maps", "811", "Permit", "Site Survey"]);
  return documentRequirements(project, documents)
    .filter(item => item.safety && truePreJobTypes.has(item.type) && ["Missing", "Pending Review", "Needs Review", "Blocked"].includes(item.status))
    .filter(item => item.type !== "GIS / Field Maps" || !fieldMapsReadiness(project).ready)
    .concat(jsaStarter ? [] : [{ label: "JSA starter", type: "JSA", status: "Missing" }]);
}

