function workflowStep(number, title, body, actionLabel = "", workflowAction = "", workflowId = "", status = "") {
  const target = workflowTarget(workflowAction || actionLabel, workflowId || state.selectedProjectId || "");
  const actionButton = actionLabel && canView(target)
    ? `<button class="secondary-btn" data-workflow-action="${workflowAction || actionLabel}" data-workflow-id="${workflowId || state.selectedProjectId || ""}">${roleWorkflowActionLabel(actionLabel, target)}</button>`
    : "";
  return `
    <article class="workflow-step">
      <span>${number}</span>
      <div>
        <div class="workflow-step-head">
          <h3>${title}</h3>
          ${status ? `<span class="status ${statusClass(status)}">${status}</span>` : ""}
        </div>
        <p>${body}</p>
        ${actionButton}
      </div>
    </article>
  `;
}

function renderGuidedWorkflow(title, steps, embedded = false) {
  return `
    <section class="${embedded ? "section-block guided-workflow embedded" : "panel guided-workflow"}">
      <div class="${embedded ? "section-heading" : "panel-header"}">
        <h2>${title}</h2>
        <span>${steps.length} steps</span>
      </div>
      <div class="workflow">
        ${steps.map((step, index) => {
          if (Array.isArray(step)) return workflowStep(index + 1, ...step);
          return workflowStep(index + 1, step.title, step.body, step.actionLabel, step.workflowAction, step.workflowId, step.status);
        }).join("")}
      </div>
    </section>
  `;
}

