function productionPriceForCode(code) {
  return (state.data.priceSheetItems || []).find(item => item.code === code)
    || (state.data.unitPrices || []).find(item => item.id === code || item.unitCode === code)
    || null;
}

function squanLineKey(line) {
  return [line.project || line.ntp || "", line.workedDate || "", line.code || ""].join("|");
}

function productionLineKey(line) {
  return [line.project || line.ntp || "", line.workedDate || "", line.code || ""].join("|");
}

function productionLedgerRows() {
  const squanByKey = new Map();
  (state.data.squanProductionLines || []).forEach(line => {
    const key = squanLineKey(line);
    const existing = squanByKey.get(key) || { quantity: 0, amount: 0, rows: [] };
    existing.quantity += Number(line.quantity || 0);
    existing.amount += Number(line.squanAmount || 0);
    existing.rows.push(line);
    squanByKey.set(key, existing);
  });
  return (state.data.productionLines || []).map(line => {
    const squan = squanByKey.get(productionLineKey(line)) || { quantity: 0, amount: 0, rows: [] };
    const price = productionPriceForCode(line.code);
    const unitRate = Number(line.unitRate || price?.subRate || price?.price || 0);
    const approved = line.reviewStatus === "Approved";
    return {
      ...line,
      unitRate,
      submittedAmount: Number(line.submittedAmount || 0) || Number(line.quantity || 0) * unitRate,
      squanQuantity: squan.quantity,
      squanAmount: squan.amount,
      varianceQuantity: Number(line.quantity || 0) - squan.quantity,
      status: line.reviewStatus || line.status || "Submitted",
      payableStatus: approved ? line.payableStatus || "Ready to Pay" : line.payableStatus || "Pending Review",
      billableStatus: approved ? line.billableStatus || "Ready to Bill" : line.billableStatus || "Pending Review",
      unitName: price?.unitName || price?.description || "Rate/code review needed"
    };
  });
}

function productionSummary() {
  const rows = productionLedgerRows();
  return {
    submitted: rows.length,
    review: rows.filter(row => ["Submitted", "Needs Review", "Needs Proof"].includes(row.status)).length,
    approved: rows.filter(row => row.status === "Approved").length,
    payable: rows.filter(row => row.payableStatus === "Ready to Pay").reduce((total, row) => total + Number(row.submittedAmount || 0), 0),
    billable: rows.filter(row => row.billableStatus === "Ready to Bill").reduce((total, row) => total + Number(row.squanAmount || row.submittedAmount || 0), 0),
    imported: sum(state.data.squanProductionLines || [], "squanAmount")
  };
}

