function productionBillingPackageRows() {
  const ledger = state.data.billingLedger || [];
  const lines = state.data.productionLines || [];
  const grouped = new Map();
  ledger
    .filter(item => item.billingStatus === "Ready to Bill")
    .forEach(item => {
      const line = lines.find(row => row.id === item.productionLineId) || {};
      const key = [item.project || line.project || "", item.workedDate || line.workedDate || "", item.code || line.code || ""].join("|");
      const existing = grouped.get(key) || {
        project: item.project || line.project || "",
        workedDate: item.workedDate || line.workedDate || "",
        code: item.code || line.code || "",
        lines: 0,
        quantity: 0,
        squanBillableAmount: 0,
        contractorPayableAmount: 0,
        inHouseCostAmount: 0,
        proofStatus: "Accepted"
      };
      existing.lines += 1;
      existing.quantity += Number(line.quantity || 0);
      existing.squanBillableAmount += Number(item.squanBillableAmount || 0);
      existing.contractorPayableAmount += Number(item.contractorPayableAmount || 0);
      existing.inHouseCostAmount += Number(item.inHouseCostAmount || 0);
      if (!["Accepted", "Accepted Exception"].includes(item.proofStatus)) existing.proofStatus = "Needs Review";
      grouped.set(key, existing);
    });
  return [...grouped.values()].sort((a, b) => `${a.project}${a.workedDate}${a.code}`.localeCompare(`${b.project}${b.workedDate}${b.code}`));
}

