function featureLayerForCode(code) {
  const price = productionPriceForCode(code) || {};
  const aspect = String(price.aspect || price.category || code || "Production");
  if (/splice|fs/i.test(`${aspect} ${code}`)) return "Splicing";
  if (/aerial|overlash|wire|cable/i.test(`${aspect} ${code}`)) return "Aerial";
  if (/underground|bore|trench|conduit/i.test(`${aspect} ${code}`)) return "Underground";
  if (/tech|labor|hour/i.test(`${aspect} ${code}`)) return "Tech Labor";
  return aspect || "Production";
}

function squanMapFeatureRows() {
  const explicit = (state.data.squanMapFeatures || []).map(item => ({ ...item, source: item.source || "SQUAN map feature placeholder" }));
  const imported = (state.data.squanProductionLines || []).map((line, index) => ({
    id: `FEATURE-${line.id || index}`,
    sourceLineId: line.id,
    project: line.project || line.ntp || "Unassigned",
    ntp: line.ntp || line.project || "Unassigned",
    layerName: line.layerName || featureLayerForCode(line.code),
    featureCode: line.code || "",
    description: line.description || productionPriceForCode(line.code)?.description || line.code || "Imported SQUAN feature",
    quantity: Number(line.quantity || 0),
    uom: line.uom || productionPriceForCode(line.code)?.uom || "Unit",
    status: line.status || "Imported",
    workDate: line.workedDate || isoDate(new Date()),
    objectId: line.objectId || "",
    globalId: line.globalId || "",
    geometryStatus: line.geometry ? "Stored" : "Placeholder",
    source: "SQUAN Daily Export CSV",
    notes: line.notes || "Feature modeled from SQUAN export until live ArcGIS is approved."
  }));
  const byId = new Map();
  [...imported, ...explicit].forEach(item => byId.set(item.id, item));
  return [...byId.values()].filter(item => item.featureCode || item.quantity || item.project);
}

function squanMapRollups(features = squanMapFeatureRows()) {
  const grouped = new Map();
  features.forEach(feature => {
    const key = [feature.project || feature.ntp || "", feature.layerName || "", feature.featureCode || ""].join("|");
    const existing = grouped.get(key) || {
      project: feature.project || feature.ntp || "",
      layerName: feature.layerName || "Production",
      featureCode: feature.featureCode || "",
      description: feature.description || "",
      quantity: 0,
      features: 0,
      uom: feature.uom || "Unit"
    };
    existing.quantity += Number(feature.quantity || 0);
    existing.features += 1;
    grouped.set(key, existing);
  });
  return [...grouped.values()].sort((a, b) => `${a.project}${a.layerName}${a.featureCode}`.localeCompare(`${b.project}${b.layerName}${b.featureCode}`));
}

