function renderTablePanel(config) {
  const rows = scopedRows(config.key).filter(matches);
  return `
    <div class="panel">
      <div class="panel-header">
        <h2>${config.title}</h2>
        <span>${rows.length} shown</span>
      </div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>${config.columns.map(column => `<th>${column.label}</th>`).join("")}<th>Action</th></tr>
          </thead>
          <tbody>
            ${rows.map(row => `
              <tr>
                ${config.columns.map(column => `<td>${formatCell(row, column)}</td>`).join("")}
                <td>
                  <button class="secondary-btn" data-open-record="${config.key}" data-record-id="${row.id}">View</button>
                  ${canCreate(config.key) ? `<button class="secondary-btn" data-edit="${config.key}" data-index="${state.data[config.key].indexOf(row)}">Edit</button>` : ""}
                </td>
              </tr>
            `).join("") || `<tr><td colspan="${config.columns.length + 1}" class="empty">No records match your search.</td></tr>`}
          </tbody>
        </table>
      </div>
      <div class="mobile-records">
        ${rows.map(row => renderMobileRecord(row, config)).join("") || `<div class="empty">No records match your search.</div>`}
      </div>
    </div>
  `;
}

function renderMobileRecord(row, config) {
  const titleColumn = config.columns[0];
  const subtitleColumn = config.columns[1] || config.columns[0];
  return `
    <article class="mobile-record-card">
      <div class="card-topline">
        <h3>${formatCell(row, titleColumn)}</h3>
        <button class="secondary-btn" data-open-record="${config.key}" data-record-id="${row.id}">View</button>
        ${canCreate(config.key) ? `<button class="secondary-btn" data-edit="${config.key}" data-index="${state.data[config.key].indexOf(row)}">Edit</button>` : ""}
      </div>
      <p>${formatCell(row, subtitleColumn)}</p>
      <dl>
        ${config.columns.slice(2, 7).map(column => `
          <div>
            <dt>${column.label}</dt>
            <dd>${formatCell(row, column)}</dd>
          </div>
        `).join("")}
      </dl>
    </article>
  `;
}

function formatCell(row, column) {
  const value = column.key === "taskType" ? taskCategory(row) : row[column.key];
  if (column.type === "money") return currency(Number(value || 0));
  if (column.type === "status") return `<span class="status ${statusClass(value)}">${value}</span>`;
  if (column.type === "severity") return `<span class="priority ${String(value).toLowerCase()}">${value}</span>`;
  if (column.type === "dateRisk") return formatDateRisk(value);
  if (column.type === "dateTime") return formatDateTime(value);
  if (column.type === "yesNo") return yesNoBadge(value);
  return value;
}

function formatDateRisk(value) {
  const days = daysUntil(value);
  if (days === null) return value;
  const cls = days < 0 ? "bad" : days <= 14 ? "bad" : days <= 30 ? "warn" : "ok";
  return `<span class="status ${cls}">${value}</span>`;
}

function formatDateTime(value) {
  if (!value) return "";
  return String(value).replace("T", " ").replace(".000Z", "");
}

function formatShortDateTime(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString([], {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit"
  });
}

function workflowRecordCounts() {
  return {
    dailies: (state.data.dailies || []).length,
    forms: (state.data.formSubmissions || []).length,
    photos: (state.data.photoEvidence || []).length,
    invoices: (state.data.invoices || []).length
  };
}

function collectionForView() {
  return {
    dashboard: "projects",
    tasks: "tasks",
    documents: "documents",
    projects: "projects",
    field: "dailies",
    production: "productionLines",
    time: "timeEntries",
    people: "people",
    equipment: "equipment",
    money: "invoices",
    risk: "safety",
    reports: "reports",
    settings: "contractRules"
  }[state.view];
}

function openDrawer(collectionKey, index = null) {
  const config = Object.values(tableConfig()).find(item => item.key === collectionKey);
  const record = index === null ? createBlankRecord(collectionKey) : state.data[collectionKey][index];
  const drawer = document.getElementById("drawer");
  const backdrop = document.getElementById("drawerBackdrop");

  drawer.innerHTML = `
    <header>
      <h2>${index === null ? "Create" : "Edit"} ${config.title}</h2>
      <button class="icon-btn" id="closeDrawer" title="Close">×</button>
    </header>
    <form id="recordForm">
      <div class="fields">
        ${Object.entries(record).map(([key, value]) => `
          <div class="field ${String(value).length > 34 ? "full" : ""}">
            <label for="${key}">${labelize(key)}</label>
            ${String(value).length > 70 ? `<textarea id="${key}" name="${key}">${value}</textarea>` : `<input id="${key}" name="${key}" value="${value}">`}
          </div>
        `).join("")}
      </div>
    </form>
    <footer>
      <button class="secondary-btn" id="cancelDrawer">Cancel</button>
      <button class="primary-btn" id="saveRecord">Save</button>
    </footer>
  `;

  drawer.classList.add("open");
  backdrop.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");

  document.getElementById("closeDrawer").addEventListener("click", closeDrawer);
  document.getElementById("cancelDrawer").addEventListener("click", closeDrawer);
  document.getElementById("saveRecord").addEventListener("click", () => saveRecord(collectionKey, index));
}

async function saveRecord(collectionKey, index) {
  const form = new FormData(document.getElementById("recordForm"));
  const numeric = ["estimatedRevenue", "actualCost", "forecastCost", "billed", "laborHours", "equipmentHours", "costRate", "gross", "paid90", "retainage10", "breakMinutes", "regularHours", "overtimeHours", "travelHours", "standbyHours"];
  const nextRecord = {};
  for (const [key, value] of form.entries()) {
    nextRecord[key] = numeric.includes(key) ? Number(value) : value;
  }
  if (packetGuardedCollections().includes(collectionKey)) {
    const projectId = packetGuardProjectId(collectionKey, nextRecord);
    if (projectId && !guardFinalizedPacketEdit(projectId, `${labelize(collectionKey)} record ${nextRecord.id || ""}`)) return;
  }
  if (index === null) {
    state.data[collectionKey].push(nextRecord);
  } else {
    state.data[collectionKey][index] = nextRecord;
  }
  appendAuditLocal(`${collectionKey}.${index === null ? "create" : "update"}`, { id: nextRecord.id });
  persist();
  await saveToApi(collectionKey, nextRecord, index === null);
  closeDrawer();
  render();
}

function createBlankRecord(collectionKey) {
  state.data[collectionKey] = state.data[collectionKey] || [];
  const examples = state.data[collectionKey][0] || {};
  return Object.fromEntries(Object.keys(examples).map(key => [key, ""]));
}

function labelize(key) {
  return key.replace(/([A-Z])/g, " $1").replace(/^./, match => match.toUpperCase());
}

function closeDrawer() {
  document.getElementById("drawer").classList.remove("open", "payment-detail-drawer");
  document.getElementById("drawerBackdrop").classList.remove("open");
  document.getElementById("drawer").setAttribute("aria-hidden", "true");
}

function workflowTarget(actionText, recordId) {
  const action = String(actionText || "").trim().toLowerCase();
  const exactTargets = {
    "project & map hub": "projects",
    "map hub": "projects",
    maps: "projects",
    map: "projects",
    documents: "documents",
    "document vault": "documents",
    "field operations": "field",
    "field daily": "field",
    daily: "field",
    "time tracking": "time",
    "crew time": "time",
    billing: "money",
    money: "money",
    "safety & risk": "risk",
    safety: "risk",
    "people & compliance": "people",
    people: "people",
    equipment: "equipment",
    reports: "reports",
    report: "reports",
    tasks: "tasks",
    task: "tasks",
    settings: "settings"
  };
  if (exactTargets[action]) return exactTargets[action];
  const text = `${actionText || ""} ${recordId || ""}`.toLowerCase();
  if (text.includes("task")) return "tasks";
  if (text.includes("report") || text.includes("export")) return "reports";
  if (text.includes("billing") || text.includes("invoice") || text.includes("payment") || text.includes("retainage") || text.includes("cash")) return "money";
  if (text.includes("time") || text.includes("payroll")) return "time";
  if (text.includes("safety") || text.includes("risk") || text.includes("hazard") || text.includes("corrective") || text.includes("mitigate") || text.includes("form 12")) return "risk";
  if (text.includes("cert") || text.includes("person") || text.includes("people") || text.includes("crew") || text.includes("compliance")) return "people";
  if (text.includes("equipment") || text.includes("inspect") || text.includes("asset") || text.includes("truck")) return "equipment";
  if (text.includes("document")) return "documents";
  if (text.includes("daily") || text.includes("jsa") || text.includes("ppe") || text.includes("photo") || text.includes("field")) return "field";
  return "projects";
}

