function configureWorkflowRoute(target, id, actionText, focusText) {
  const focus = `${focusText || actionText || ""}`.toLowerCase();
  state.workflowFocus = focusText || actionText || "";
  if (id.startsWith("PO-")) state.selectedProjectId = id;

  if (target === "projects") {
    state.search = "";
    if (focus.includes("closeout")) state.mapFilter = "Completed";
    else if (focus.includes("intake") || focus.includes("release")) state.mapFilter = "Beginning";
    else state.mapFilter = "All";
  }

  if (target === "documents") {
    if (id.startsWith("PO-")) state.documentFilter = id;
    if (focus.includes("evidence")) state.evidenceReviewFilter = "Action Needed";
    state.search = "";
  }

  if (target === "field" || target === "time" || target === "risk") {
    state.search = id.startsWith("PO-") ? id : "";
  }

  if (target === "money") {
    state.search = "";
    if (focus.includes("collection")) state.reportPrintScope = "Collections Packet";
    else if (focus.includes("retainage") || focus.includes("held back") || focus.includes("payment")) state.reportPrintScope = "Payment Ledger";
    else if (focus.includes("billing") || focus.includes("invoice")) state.reportPrintScope = "Billing Packet";
  }

  if (target === "reports") {
    state.search = "";
    state.reportExceptionFilter = "Selected Map";
    if (focus.includes("collection") && focus.includes("decision")) state.reportPrintScope = "Collections Decision Audit";
    else if (focus.includes("collection")) state.reportPrintScope = "Collections Packet";
    else if (focus.includes("closeout")) state.reportPrintScope = "Closeout Package";
    else if (focus.includes("billing") || focus.includes("invoice")) state.reportPrintScope = "Billing Packet";
    else if (focus.includes("retainage") || focus.includes("held back") || focus.includes("payment")) state.reportPrintScope = "Payment Ledger";
  }

  if (target === "tasks") {
    if (focus.includes("evidence")) state.taskFilter = "Evidence correction";
    else if (focus.includes("closeout readiness")) state.taskFilter = "Closeout readiness";
    else if (focus.includes("collection") || focus.includes("retainage")) state.taskFilter = "Collections";
    else if (focus.includes("field") || focus.includes("daily")) state.taskFilter = "Field blocker";
    else state.taskFilter = "My open tasks";
    state.search = id.startsWith("PO-") ? id : "";
  }

  if (target === "people" || target === "equipment") {
    state.search = "";
  }
}

function handleWorkflowClick(button) {
  const target = workflowTarget(button.dataset.workflowAction, button.dataset.workflowId);
  const id = button.dataset.workflowId || "";
  configureWorkflowRoute(target, id, button.dataset.workflowAction, button.dataset.workflowFocus);
  if (button.dataset.reportScope) state.reportPrintScope = button.dataset.reportScope;
  if (canView(target)) {
    state.view = target;
    render();
  }
}

function openTaskWorkflow(taskId) {
  const task = (state.data.tasks || []).find(item => item.id === taskId);
  if (!task) return;
  if (task.source === "Needs Fix") {
    const project = (state.data.projects || []).find(item => item.id === task.project);
    const row = guidedNeedsFixRows(project, "fix-problems").find(item => item.task?.id === task.id || needsFixTaskId(project, item) === task.id);
    if (project && row) {
      openNeedsFixDrawer(project.id, row.id, "fix-problems");
      return;
    }
  }
  if (task.source === "Exception approval" && task.project) {
    openExceptionResolutionDrawer(task.project);
    return;
  }
  if (task.source === "Packet reopen" && task.project) {
    openPacketTaskDrawer(task.id);
    return;
  }
  if (task.source === "Evidence correction" && task.project) {
    openEvidenceCorrectionDrawer(task.id);
    return;
  }
  if (task.source === "Collections decision evidence SLA") {
    openCollectionEvidenceSlaTaskDrawer(task.id);
    return;
  }
  if (task.source === "AR aging escalation") {
    openCollectionsTaskDrawer(task.id);
    return;
  }
  if (task.source === "Billing closeout readiness") {
    openCloseoutReadinessTaskDrawer(task.id);
    return;
  }
  if (task.source === "Financial closeout gate") {
    openFinancialCloseoutTaskDrawer(task.id);
    return;
  }
  if (task.source === "Financial closeout receipt") {
    openFinancialCloseoutReceiptTaskDrawer(task.id);
    return;
  }
  if (task.source === "Daily supervisor review") {
    openDailySupervisorReviewDrawer(task.dailyId || task.relatedId);
    return;
  }
  if (task.source === "Daily package SLA") {
    openDailyPackageSlaTaskDrawer(task.id);
    return;
  }
  if (task.source === "Invoice package build gate") {
    openPackageBuildBlockerTaskDrawer(task.id);
    return;
  }
  if (task.source === "End-of-day daily") {
    openEndOfDayDailyTaskDrawer(task.id);
    return;
  }
  if (task.source === "SQUAN submission gate" || task.source === "Package snapshot rebuild") {
    openSubmissionGateTaskDrawer(task.id);
    return;
  }
  if (isPostSubmissionTask(task)) {
    openPostSubmissionTaskDrawer(task.id);
    return;
  }
  if (billingTaskRows([task]).length) {
    openBillingTaskDrawer(task.id);
    return;
  }
  if (task.project) state.selectedProjectId = task.project;
  handleWorkflowClick({
    dataset: {
      workflowAction: taskWorkflowAction(task),
      workflowId: task.project || task.relatedId || ""
    }
  });
}

function endOfDayDailyTaskContext(task) {
  const project = (state.data.projects || []).find(item => item.id === task.project) || { id: task.project || task.relatedId, map: task.project || task.relatedId };
  const dailies = (state.data.dailies || [])
    .filter(item => item.project === project.id)
    .sort((a, b) => String(b.modifiedAt || b.date || "").localeCompare(String(a.modifiedAt || a.date || "")));
  const latest = dailies[0];
  const submittedToday = dailies.some(item => item.status === "Submitted" && item.date === isoDate(today));
  const activeMap = project.id && !/completed|billed/i.test(project.status || "");
  const gate = fieldStartGate(project, latest);
  const status = submittedToday || !activeMap ? "Clear" : latest?.status && latest.status !== "Submitted" ? "Draft" : "Missing";
  const documents = (state.data.documents || []).filter(item => item.project === project.id);
  const photos = (state.data.photoEvidence || []).filter(item => item.project === project.id);
  const timeEntries = (state.data.timeEntries || []).filter(item => item.project === project.id);
  const checklist = [
    { label: "Map still active", ok: activeMap, detail: activeMap ? `${project.status || "Active"} requires daily tracking.` : "Map no longer requires end-of-day daily action." },
    { label: "Start gate clear", ok: gate.clear, detail: gate.clear ? "Release, crew, equipment, documents, and safety gates are clear." : gate.blockers.map(item => item.label).join(", ") },
    { label: "Daily submitted today", ok: submittedToday, detail: submittedToday ? "A submitted daily exists for today." : "Submit today’s field daily before closing this task." },
    { label: "Billing evidence path", ok: documents.length > 0 || photos.length > 0, detail: `${documents.length} document(s), ${photos.length} photo evidence item(s).` },
    { label: "Crew time visible", ok: timeEntries.length > 0, detail: `${timeEntries.length} time line(s) tied to this Map.` }
  ];
  return { project, dailies, latest, submittedToday, activeMap, gate, status, documents, photos, timeEntries, checklist };
}

