function arItemForTask(task) {
  const rows = arAgingRows();
  return rows.find(item => item.id === task.relatedId) || rows.find(item => item.project === task.project && item.kind === task.arKind) || null;
}

function collectionEvidenceForTask(task) {
  return (state.data.documents || []).filter(document => document.collectionTaskId === task.id || document.relatedTask === task.id || (task.collectionEvidenceIds || []).includes(document.id));
}

