  document.getElementById("collectionPromise").addEventListener("click", () => handleCollectionTaskAction(task.id, "promise-date"));
  document.getElementById("collectionDispute").addEventListener("click", () => handleCollectionTaskAction(task.id, "dispute-reason"));
