function fieldCaptureCorrectionDefaults(row) {
  const project = row.project;
  const related = row.related || {};
  if (row.kind === "GPS photo capture") {
    return {
      title: "Correct GPS photo capture",
      intro: row.sync.review?.note || "Update the returned photo capture and resubmit it for Operations/Safety review.",
      fields: [
        ["fieldCaptureCaption", "Photo caption", related.caption || row.summary, "input"],
        ["fieldCaptureStage", "Workflow stage", related.workflowStage || "Progress / closeout", "input"],
        ["fieldCaptureLinkedRecord", "Linked daily or record", related.linkedRecord || row.relatedRecord || project.id, "input"],
        ["fieldCaptureLatitude", "Latitude", related.latitude || row.sync.latitude || "Field GPS pending", "input"],
        ["fieldCaptureLongitude", "Longitude", related.longitude || row.sync.longitude || "Field GPS pending", "input"],
        ["fieldCaptureBlocks", "Blocks release, billing, or closeout?", related.blockerImpact || row.blockerImpact || "No blocker", "select"],
        ["fieldCaptureNotes", "Field notes", related.notes || row.summary, "textarea"]
      ]
    };
  }
  return {
    title: "Correct map markup pin",
    intro: row.sync.review?.note || "Update the returned markup pin and resubmit it for Operations/Safety review.",
    fields: [
      ["fieldCaptureLocation", "Location / station", related.location || project.arcgis?.workArea || project.map || project.id, "input"],
      ["fieldCaptureType", "Markup type", related.type || "Field obstruction", "select"],
      ["fieldCaptureFeatureId", "ArcGIS feature ID", related.gisFeatureId || project.arcgis?.featureIds || "", "input"],
      ["fieldCaptureFootage", "Affected footage", related.affectedFootage || row.sync.affectedFootage || "0", "input"],
      ["fieldCaptureImpact", "Workflow impact", related.impact || row.blockerImpact || "Field review", "select"],
      ["fieldCaptureOwner", "Review owner", related.owner || "Operations Coordinator", "input"],
      ["fieldCaptureDescription", "Description", related.description || row.summary, "textarea"]
    ]
  };
}

function openFieldCaptureCorrectionDrawer(syncId) {
  const sync = (state.data.offlineSyncQueue || []).find(item => item.id === syncId);
  if (!sync) return;
  const project = (state.data.projects || []).find(item => item.id === sync.project);
  if (!project) return;
  if (!guardFinalizedPacketEdit(project.id, `Field capture correction: ${syncId}`)) return;
  const row = fieldCaptureReviewRows(project).find(item => item.id === syncId);
  if (!row) return;
  const config = fieldCaptureCorrectionDefaults(row);
  const drawer = document.getElementById("drawer");
  const backdrop = document.getElementById("drawerBackdrop");
  drawer.innerHTML = `
    <header>
      <div>
        <h2>${config.title}</h2>
        <small>${project.map || project.id} · ${syncId}</small>
      </div>
      <button class="icon-btn" id="closeDrawer" title="Close">×</button>
    </header>
    <form id="fieldCaptureForm">
      <p class="drawer-intro">${escapeAttr(config.intro)}</p>
      <div class="fields">
        ${config.fields.map(([id, label, value, type]) => renderFieldCaptureInput(id, label, value, type)).join("")}
      </div>
    </form>
    <footer>
      <button class="secondary-btn" id="cancelDrawer">Cancel</button>
      <button class="primary-btn" id="saveFieldCaptureCorrection">Save correction</button>
    </footer>
  `;
  drawer.classList.add("open");
  backdrop.classList.add("open");
  drawer.setAttribute("aria-hidden", "false");
  document.getElementById("closeDrawer").addEventListener("click", closeDrawer);
  document.getElementById("cancelDrawer").addEventListener("click", closeDrawer);
  document.getElementById("saveFieldCaptureCorrection").addEventListener("click", () => saveFieldCaptureCorrection(syncId));
}

function fieldCaptureValue(form, key) {
  return String(form.get(key) || "").trim();
}

function saveFieldCapture(projectId, action) {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return;
  const form = new FormData(document.getElementById("fieldCaptureForm"));
  const payload = Object.fromEntries(Array.from(form.keys()).map(key => [key, fieldCaptureValue(form, key)]));
  handleFieldOfflineAction({ dataset: { projectId, fieldOfflineAction: action }, payload });
  closeDrawer();
}

function saveFieldCaptureCorrection(syncId) {
  const sync = (state.data.offlineSyncQueue || []).find(item => item.id === syncId);
  if (!sync) return;
  const project = (state.data.projects || []).find(item => item.id === sync.project);
  if (!project) return;
  const row = fieldCaptureReviewRows(project).find(item => item.id === syncId);
  if (!row) return;
  const form = new FormData(document.getElementById("fieldCaptureForm"));
  const payload = Object.fromEntries(Array.from(form.keys()).map(key => [key, fieldCaptureValue(form, key)]));
  const now = new Date().toISOString();
  const version = (sync.correctionVersions || []).length + 1;
  if (row.kind === "GPS photo capture" && row.related) {
    row.related.caption = payload.fieldCaptureCaption || row.related.caption;
    row.related.workflowStage = payload.fieldCaptureStage || row.related.workflowStage;
    row.related.linkedRecord = payload.fieldCaptureLinkedRecord || row.related.linkedRecord;
    row.related.latitude = payload.fieldCaptureLatitude || row.related.latitude;
    row.related.longitude = payload.fieldCaptureLongitude || row.related.longitude;
    row.related.blockerImpact = payload.fieldCaptureBlocks || row.related.blockerImpact || "No blocker";
    row.related.notes = appendInlineNote(row.related.notes, payload.fieldCaptureNotes || `Corrected field capture v${version}.`);
    row.related.status = "Submitted";
    row.related.reviewStatus = "Corrected";
    row.related.modifiedAt = now;
    row.related.activityLog = [...(row.related.activityLog || []), { at: now, by: state.user?.name || "Foreman", note: `Corrected GPS photo capture v${version}.` }];
    void saveToApi("photoEvidence", row.related, false);
  }
  if (row.kind === "Map markup pin" && row.related) {
    row.related.location = payload.fieldCaptureLocation || row.related.location;
    row.related.type = payload.fieldCaptureType || row.related.type;
    row.related.gisFeatureId = payload.fieldCaptureFeatureId || row.related.gisFeatureId;
    row.related.affectedFootage = Number(payload.fieldCaptureFootage || row.related.affectedFootage || 0);
    row.related.impact = payload.fieldCaptureImpact || row.related.impact;
    row.related.owner = payload.fieldCaptureOwner || row.related.owner;
    row.related.description = payload.fieldCaptureDescription || row.related.description;
    row.related.status = "Needs Review";
    row.related.reviewStatus = "Corrected";
    row.related.modifiedAt = now;
    row.related.activityLog = [...(row.related.activityLog || []), { at: now, by: state.user?.name || "Foreman", note: `Corrected markup pin v${version}.` }];
    void saveToApi("obstacles", row.related, false);
  }
  sync.correctionVersions = [
    ...(sync.correctionVersions || []),
    { version, at: now, by: state.user?.name || "Foreman", payload, note: "Field capture correction saved." }
  ];
  sync.status = "Corrected";
  sync.review = { ...(sync.review || {}), status: "Corrected", correctedBy: state.user?.name || "Foreman", correctedAt: now };
  sync.modifiedAt = now;
  sync.activityLog = [...(sync.activityLog || []), { at: now, by: state.user?.name || "Foreman", note: `Field capture correction v${version} saved.` }];
  appendAuditLocal("field.capture-correction.saved", { project: project.id, sync: sync.id, version, by: state.user?.name || "Foreman" });
  persist("Field capture correction saved");
  void saveToApi("offlineSyncQueue", sync, false);
  closeDrawer();
  render();
}

function handleFieldCaptureReview(button) {
  const sync = (state.data.offlineSyncQueue || []).find(item => item.id === button.dataset.syncId);
  if (!sync) return;
  const project = (state.data.projects || []).find(item => item.id === sync.project);
  if (!project) return;
  const action = button.dataset.fieldCaptureReview;
  if (!guardFinalizedPacketEdit(project.id, `Field capture review: ${action}`)) return;
  const row = fieldCaptureReviewRows(project).find(item => item.id === sync.id);
  if (!row) return;
  const now = new Date().toISOString();
  const reviewer = state.user?.name || "Operations/Safety";
  const noteDefaults = {
    accept: "Accepted as valid field capture evidence.",
    correction: "Correct or clarify this field capture before it can support release, billing, or closeout.",
    task: "Create follow-up task from field capture review.",
    "block-billing": "Field capture blocks billing evidence until resolved.",
    "block-closeout": "Field capture blocks closeout until resolved."
  };
  const note = action === "accept"
    ? noteDefaults.accept
    : prompt("Review note", noteDefaults[action] || "Field capture review note.") || "";
  if (action !== "accept" && !note.trim()) return;
  const reviewStatus = action === "accept" ? "Accepted" : action === "correction" ? "Needs Correction" : action === "task" ? "Task Created" : action === "block-billing" ? "Billing Blocker" : "Closeout Blocker";
  sync.review = {
    status: reviewStatus,
    by: reviewer,
    at: now,
    note: note.trim()
  };
  sync.status = action === "accept" ? "Accepted" : reviewStatus;
  sync.modifiedAt = now;
  sync.activityLog = [...(sync.activityLog || []), { at: now, by: reviewer, note: `Field capture review: ${reviewStatus}. ${note.trim()}` }];

  if (row.related && row.collection !== "offlineSyncQueue") {
    row.related.reviewStatus = reviewStatus;
    row.related.reviewedBy = reviewer;
    row.related.reviewedAt = now;
    row.related.reviewNotes = appendInlineNote(row.related.reviewNotes, note.trim());
    row.related.status = action === "accept"
      ? row.collection === "obstacles" ? "Field Verified" : "Accepted"
      : row.related.status === "Submitted" ? "Needs Review" : row.related.status || "Needs Review";
    if (action === "accept") {
      row.related.acceptedForBilling = "Yes";
      row.related.acceptedForSafety = "Yes";
      row.related.acceptedForCloseout = "Yes";
      row.related.evidenceKey = row.related.evidenceKey || (row.collection === "photoEvidence" ? "photo-evidence" : "accepted-field-captures");
      if (row.collection === "obstacles") {
        row.related.photoRefs = row.related.photoRefs && !/pending/i.test(row.related.photoRefs) ? row.related.photoRefs : "Accepted field capture";
        row.related.notes = appendInlineNote(row.related.notes, "Accepted field capture closes this obstruction for billing/closeout evidence.");
      }
    }
    row.related.modifiedAt = now;
    row.related.activityLog = [...(row.related.activityLog || []), { at: now, by: reviewer, note: `Field capture review: ${reviewStatus}.` }];
    void saveToApi(row.collection, row.related, false);
  }

  if (action === "accept") {
    sync.acceptedForBilling = "Yes";
    sync.acceptedForSafety = "Yes";
    sync.acceptedForCloseout = "Yes";
    closeFieldCaptureReviewTasks(project.id, sync.id, `Field capture ${sync.id} accepted by ${reviewer}.`);
  } else {
    const workflowArea = action === "block-billing" ? "Billing" : action === "block-closeout" ? "Project & Map Hub" : row.collection === "obstacles" ? "Safety & Risk" : "Field Operations";
    const owner = workflowArea === "Billing" ? "Office Billing" : workflowArea === "Safety & Risk" ? "Safety Compliance" : row.collection === "obstacles" ? "Operations Coordinator" : project.crew;
    const role = workflowArea === "Billing" ? "Billing" : workflowArea === "Safety & Risk" ? "Safety/Compliance" : row.collection === "obstacles" ? "Operations" : "Foreman";
    createAdminTask(project, `${reviewStatus}: ${row.kind}`, workflowArea, `${project.map || project.id}: ${note.trim()} Related capture ${sync.id}${row.relatedRecord ? ` / ${row.relatedRecord}` : ""}.`, {
      id: `TASK-FIELD-CAPTURE-${sync.id}-${action.toUpperCase()}`,
      owner,
      role,
      dueDate: addDays(isoDate(today), action === "correction" ? 1 : 2),
      priority: action.startsWith("block") ? "High" : "Normal",
      source: "Field capture review",
      extra: {
        relatedType: row.kind,
        relatedId: row.relatedRecord || sync.id,
        syncId: sync.id,
        captureReviewStatus: reviewStatus
      },
      activityLog: [{ at: now, by: reviewer, note: `Task created from field capture review: ${reviewStatus}.` }]
    });
  }

  project.arcgis = project.arcgis || {};
  project.arcgis.captureReviewStatus = reviewStatus;
  project.arcgis.captureReviewAt = now;
  project.arcgis.notes = appendInlineNote(project.arcgis.notes, `Field capture ${sync.id} reviewed: ${reviewStatus}.`);
  project.modifiedAt = now;
  appendAuditLocal(`field.capture-review.${action}`, {
    project: project.id,
    sync: sync.id,
    related: row.relatedRecord,
    status: reviewStatus,
    by: reviewer
  });
  recomputeBillingReadinessLocal(project.id);
  persist(`Field capture ${reviewStatus.toLowerCase()}`);
  void saveToApi("offlineSyncQueue", sync, false);
  void saveToApi("projects", project, false);
  render();
}

function resubmitFieldCaptureCorrection(syncId) {
  const sync = (state.data.offlineSyncQueue || []).find(item => item.id === syncId);
  if (!sync) return;
  const project = (state.data.projects || []).find(item => item.id === sync.project);
  if (!project) return;
  if (!guardFinalizedPacketEdit(project.id, `Field capture correction resubmit: ${syncId}`)) return;
  const row = fieldCaptureReviewRows(project).find(item => item.id === syncId);
  if (!row) return;
  const now = new Date().toISOString();
  sync.status = "Pending Review";
  sync.review = {
    ...(sync.review || {}),
    status: "Pending Review",
    resubmittedBy: state.user?.name || "Foreman",
    resubmittedAt: now,
    note: "Corrected field capture resubmitted for Operations/Safety review."
  };
  sync.modifiedAt = now;
  sync.activityLog = [...(sync.activityLog || []), { at: now, by: state.user?.name || "Foreman", note: "Corrected field capture resubmitted for review." }];
  if (row.related && row.collection !== "offlineSyncQueue") {
    row.related.reviewStatus = "Pending Review";
    row.related.status = row.collection === "photoEvidence" ? "Submitted" : "Needs Review";
    row.related.reviewNotes = appendInlineNote(row.related.reviewNotes, "Corrected capture resubmitted for Operations/Safety review.");
    row.related.modifiedAt = now;
    row.related.activityLog = [...(row.related.activityLog || []), { at: now, by: state.user?.name || "Foreman", note: "Corrected capture resubmitted." }];
    void saveToApi(row.collection, row.related, false);
  }
  (state.data.tasks || [])
    .filter(task => task.project === project.id && task.source === "Field capture review" && task.syncId === sync.id && task.status !== "Closed")
    .forEach(task => {
      task.captureReviewStatus = "Pending Review";
      task.correctionStatus = "Resubmitted";
      task.notes = appendInlineNote(task.notes, "Foreman resubmitted corrected capture for Operations/Safety review.");
      task.modifiedAt = now;
      task.activityLog = [...(task.activityLog || []), { at: now, by: state.user?.name || "Foreman", note: "Corrected field capture resubmitted." }];
      void saveToApi("tasks", task, false);
    });
  project.arcgis = project.arcgis || {};
  project.arcgis.captureReviewStatus = "Pending Review";
  project.arcgis.captureReviewAt = now;
  project.modifiedAt = now;
  appendAuditLocal("field.capture-correction.resubmitted", { project: project.id, sync: sync.id, by: state.user?.name || "Foreman" });
  persist("Field capture correction resubmitted");
  void saveToApi("offlineSyncQueue", sync, false);
  void saveToApi("projects", project, false);
  render();
}

function closeFieldCaptureReviewTasks(projectId, syncId, note) {
  (state.data.tasks || [])
    .filter(task => task.project === projectId && task.source === "Field capture review" && task.syncId === syncId && task.status !== "Closed")
    .forEach(task => {
      task.status = "Closed";
      task.modifiedAt = new Date().toISOString();
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), { at: new Date().toISOString(), by: state.user?.name || "System", note }];
      void saveToApi("tasks", task, false);
    });
}

function handleFieldOfflineAction(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  if (!guardFinalizedPacketEdit(project.id, `Field offline action: ${button.dataset.fieldOfflineAction}`)) return;
  const action = button.dataset.fieldOfflineAction;
  const payload = button.payload || {};
  const now = new Date().toISOString();
  project.arcgis = project.arcgis || {};
  state.data.photoEvidence = state.data.photoEvidence || [];
  state.data.obstacles = state.data.obstacles || [];

  if (action === "package-download") {
    project.arcgis.offlinePackageStatus = "Downloaded";
    project.arcgis.offlinePackageAt = now;
    project.arcgis.workArea = payload.fieldCaptureWorkArea || project.arcgis.workArea;
    project.arcgis.webMapId = payload.fieldCaptureFeatureId || project.arcgis.webMapId;
    project.arcgis.syncStatus = "Downloaded";
    createOfflineSyncRecord(
      project,
      "Offline map package",
      payload.fieldCaptureNotes || `${project.map || project.id} route, work area, docs, and smart-form starter downloaded to device.`,
      payload.fieldCaptureFeatureId || project.arcgis.webMapId || project.id,
      "Downloaded",
      { device: payload.fieldCaptureDevice || "Mobile field device", workArea: payload.fieldCaptureWorkArea || project.arcgis.workArea }
    );
  }

  if (action === "gps-photo") {
    const photoId = `PHOTO-FIELD-${project.id}-${String(state.data.photoEvidence.filter(item => item.project === project.id && item.category === "GPS field capture").length + 1).padStart(2, "0")}`;
    const latestDaily = latestSubmittedDaily(project) || (state.data.dailies || []).find(item => item.project === project.id);
    const photo = {
      id: photoId,
      project: project.id,
      linkedRecord: payload.fieldCaptureLinkedRecord || latestDaily?.id || project.id,
      workflowStage: payload.fieldCaptureStage || "Field map capture",
      category: "GPS field capture",
      caption: payload.fieldCaptureCaption || `${project.map || project.id} GPS photo captured from Field Map Mode.`,
      imageUrl: "https://commons.wikimedia.org/wiki/Special:FilePath/Fiber_optic_cable_installation.jpg?width=640",
      sourceUrl: "https://commons.wikimedia.org/wiki/File:Fiber_optic_cable_installation.jpg",
      credit: "Wikimedia Commons",
      license: "Public domain / Wikimedia Commons",
      status: "Queued for Sync",
      latitude: payload.fieldCaptureLatitude || project.arcgis.latitude || "Field GPS pending",
      longitude: payload.fieldCaptureLongitude || project.arcgis.longitude || "Field GPS pending",
      evidenceKey: "daily-photos",
      blockerImpact: payload.fieldCaptureBlocks || "No blocker",
      notes: payload.fieldCaptureNotes || "Captured offline from Field Map Mode; sync queue will mark this as submitted.",
      activityLog: [{ at: now, by: state.user?.name || "Field user", note: "GPS photo captured offline." }],
      createdAt: now,
      modifiedAt: now
    };
    state.data.photoEvidence.push(photo);
    createOfflineSyncRecord(project, "GPS photo capture", `${photoId} queued with GPS metadata for daily evidence. ${payload.fieldCaptureBlocks || "No blocker"}.`, photoId, "Queued", {
      latitude: photo.latitude,
      longitude: photo.longitude,
      blockerImpact: payload.fieldCaptureBlocks || "No blocker"
    });
  }

  if (action === "markup-pin") {
    const obstacleId = `OBS-FIELD-${project.id}-${String(state.data.obstacles.filter(item => item.project === project.id && item.type === "Field markup pin").length + 1).padStart(2, "0")}`;
    const obstacle = {
      id: obstacleId,
      project: project.id,
      location: payload.fieldCaptureLocation || project.arcgis.workArea || project.map || project.id,
      type: payload.fieldCaptureType || "Field markup pin",
      description: payload.fieldCaptureDescription || "Foreman added a field markup pin that needs Operations/Safety review before closeout.",
      photoRefs: "Pending GPS photo",
      impact: payload.fieldCaptureImpact || "Field review / possible release or billing evidence blocker",
      responsibleParty: "Operations",
      owner: payload.fieldCaptureOwner || "Operations Coordinator",
      status: "Needs Review",
      gisFeatureId: payload.fieldCaptureFeatureId || project.arcgis.featureIds || "",
      affectedFootage: Number(payload.fieldCaptureFootage || 0),
      notes: "Created from Field Map Mode offline markup.",
      activityLog: [{ at: now, by: state.user?.name || "Field user", note: "Offline markup pin created." }],
      createdAt: now,
      modifiedAt: now
    };
    state.data.obstacles.push(obstacle);
    project.arcgis.obstaclePins = Number(project.arcgis.obstaclePins || 0) + 1;
    project.arcgis.syncStatus = "Needs Sync";
    project.arcgis.primeAcceptanceStatus = project.arcgis.primeAcceptanceStatus || "Pending";
    createOfflineSyncRecord(project, "Map markup pin", `${obstacleId} queued for ${obstacle.impact}; ${obstacle.affectedFootage || 0} affected ft.`, obstacleId, "Queued", {
      gisFeatureId: obstacle.gisFeatureId,
      affectedFootage: obstacle.affectedFootage,
      impact: obstacle.impact
    });
  }

  if (action === "sync-now") {
    const rows = fieldOfflineSyncRows(project).filter(item => !["Synced", "Closed"].includes(item.status));
    rows.forEach(item => {
      item.status = "Synced";
      item.syncedAt = now;
      item.modifiedAt = now;
      item.activityLog = [...(item.activityLog || []), { at: now, by: state.user?.name || "Field user", note: "Field capture synced to ERP." }];
      void saveToApi("offlineSyncQueue", item, false);
    });
    (state.data.photoEvidence || [])
      .filter(item => item.project === project.id && item.status === "Queued for Sync")
      .forEach(item => {
        item.status = "Submitted";
        item.modifiedAt = now;
        item.activityLog = [...(item.activityLog || []), { at: now, by: state.user?.name || "Field user", note: "Photo evidence synced from offline queue." }];
        void saveToApi("photoEvidence", item, false);
      });
    project.arcgis.syncStatus = "Synced";
    project.arcgis.lastSync = now;
    project.arcgis.lastSyncedAt = now;
    createOfflineSyncRecord(project, "Sync confirmation", `${rows.length} queued field capture(s) synced to ERP.`, project.id, "Synced");
  }

  project.modifiedAt = now;
  project.arcgis.notes = appendInlineNote(project.arcgis.notes, `Field offline action recorded: ${action}.`);
  appendAuditLocal(`field.offline.${action}`, {
    project: project.id,
    by: state.user?.name || "Field user",
    syncStatus: project.arcgis.syncStatus,
    obstaclePins: project.arcgis.obstaclePins || 0
  });
  recomputeBillingReadinessLocal(project.id);
  persist(`Field offline ${action.replaceAll("-", " ")} recorded`);
  void saveToApi("projects", project, false);
  render();
}

function handleArcgisObstructionAction(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  if (!guardFinalizedPacketEdit(project.id, `ArcGIS obstruction action: ${button.dataset.gisObstructionAction}`)) return;
  const action = button.dataset.gisObstructionAction;
  const now = new Date().toISOString();
  project.arcgis = project.arcgis || {};

  if (action === "create-tasks") {
    const tasks = createArcgisObstructionTasks(project);
    appendAuditLocal("arcgis.obstruction.tasks", { project: project.id, tasks: tasks.map(task => task.id), by: state.user?.name || "Operations" });
    persist(tasks.length ? "ArcGIS obstruction tasks created" : "No ArcGIS obstruction tasks needed");
    render();
    return;
  }

  if (action === "assign-owner") {
    updateArcgisObstacleRows(project, item => {
      item.owner = item.owner || "Operations Coordinator";
      item.responsibleParty = item.responsibleParty || "Jackson Telcom";
      item.notes = appendInlineNote(item.notes, "ArcGIS obstruction owner assigned for resolution workflow.");
    });
    project.arcgis.notes = appendInlineNote(project.arcgis.notes, "Operations owner assigned to GIS obstruction.");
    closeArcgisObstructionTasks(project.id, "owner", "ArcGIS obstruction owner assigned.");
  }

  if (action === "attach-evidence") {
    state.data.photoEvidence = state.data.photoEvidence || [];
    const photoId = `PHOTO-GIS-${project.id}-${String(state.data.photoEvidence.filter(item => item.project === project.id && item.category === "GIS obstruction").length + 1).padStart(2, "0")}`;
    state.data.photoEvidence.push({
      id: photoId,
      project: project.id,
      linkedRecord: arcgisObstructionRows(project)[0]?.id || project.id,
      workflowStage: "ArcGIS obstruction resolution",
      category: "GIS obstruction",
      caption: `${project.map || project.id} Field Maps obstruction evidence attached for prime review.`,
      imageUrl: "https://commons.wikimedia.org/wiki/Special:FilePath/A_Traffic_cones_in_the_Road_construction_truck.jpg?width=640",
      sourceUrl: "https://commons.wikimedia.org/wiki/File:A_Traffic_cones_in_the_Road_construction_truck.jpg",
      credit: "Peachyeung316 / Wikimedia Commons",
      license: "CC BY-SA 4.0",
      status: "Submitted",
      notes: "Generated placeholder for GIS obstruction evidence handoff.",
      activityLog: [{ at: now, by: state.user?.name || "Operations", note: "GIS obstruction evidence attached." }],
      createdAt: now,
      modifiedAt: now
    });
    updateArcgisObstacleRows(project, item => {
      item.status = item.status === "Open" ? "Evidence Attached" : item.status;
      item.photoRefs = item.photoRefs && !/pending/i.test(item.photoRefs) ? `${item.photoRefs}, ${photoId}` : photoId;
      item.notes = appendInlineNote(item.notes, `GIS obstruction evidence attached: ${photoId}.`);
    });
    project.arcgis.photoRefs = project.arcgis.photoRefs && !/pending/i.test(project.arcgis.photoRefs) ? `${project.arcgis.photoRefs}, ${photoId}` : photoId;
    project.arcgis.syncStatus = "Evidence Attached";
    project.arcgis.lastSyncedAt = now;
    closeArcgisObstructionTasks(project.id, "evidence", `GIS obstruction evidence ${photoId} attached.`);
  }

  if (action === "field-verify") {
    const resolution = arcgisObstructionResolution(project);
    if (!resolution.steps.find(item => item.key === "evidence")?.status.includes("Ready")) {
      createArcgisObstructionTasks(project);
      alert("Attach GIS obstruction photo/potholing evidence before field verification.");
      persist("ArcGIS obstruction evidence task created");
      render();
      return;
    }
    updateArcgisObstacleRows(project, item => {
      item.status = "Field Verified";
      item.notes = appendInlineNote(item.notes, "Field verified against ArcGIS obstruction pin and evidence.");
    });
    project.arcgis.syncStatus = "Field Verified";
    project.arcgis.primeAcceptanceStatus = "Field Verified";
    project.arcgis.lastSyncedAt = now;
    closeArcgisObstructionTasks(project.id, "field", "GIS obstruction field verified.");
  }

  if (action === "request-prime") {
    updateArcgisObstacleRows(project, item => {
      item.status = item.status === "Open" ? "Pending Prime Review" : item.status === "Evidence Attached" ? "Pending Prime Review" : item.status;
      item.notes = appendInlineNote(item.notes, "GIS obstruction resolution sent to prime for acceptance.");
    });
    project.arcgis.syncStatus = "Submitted to Prime";
    project.arcgis.primeAcceptanceStatus = "Pending Prime Review";
    project.arcgis.lastSyncedAt = now;
    createAdminTask(project, "Confirm prime acceptance for GIS obstruction", "Project & Map Hub", `${project.map || project.id}: Follow up with prime on Field Maps obstruction acceptance.`, {
      id: `TASK-GIS-OBSTRUCTION-${project.id}-PRIME`,
      owner: "Operations Coordinator",
      role: "Operations",
      dueDate: addDays(isoDate(today), 2),
      priority: "High",
      source: "ArcGIS obstruction",
      extra: { gisObstructionStep: "prime", relatedType: "ArcGIS Field Maps", relatedId: project.id }
    });
  }

  if (action === "prime-accept") {
    updateArcgisObstacleRows(project, item => {
      item.status = "Resolved";
      item.notes = appendInlineNote(item.notes, "Prime accepted GIS obstruction resolution; release blocker cleared.");
    });
    project.arcgis.syncStatus = "Accepted";
    project.arcgis.primeAcceptanceStatus = "Accepted";
    project.arcgis.asBuiltStatus = project.arcgis.asBuiltStatus === "Not started" ? "Field Verified" : project.arcgis.asBuiltStatus || "Field Verified";
    project.arcgis.obstaclePins = 0;
    project.arcgis.lastSyncedAt = now;
    project.arcgis.notes = appendInlineNote(project.arcgis.notes, "Prime accepted obstruction resolution; GIS obstacle pins cleared.");
    closeArcgisObstructionTasks(project.id, ["owner", "evidence", "field", "prime"], "Prime accepted GIS obstruction resolution.");
    closeEvidenceCorrectionTasks(project, "arcgis-field-maps", "ArcGIS Field Maps handoff accepted by prime.");
  }

  project.modifiedAt = now;
  project.approvalLog = [...(project.approvalLog || []), {
    decision: `arcgis-obstruction-${action}`,
    status: project.arcgis.primeAcceptanceStatus || project.arcgis.syncStatus || "Updated",
    by: state.user?.name || "Operations",
    at: now,
    reason: `ArcGIS obstruction workflow action recorded: ${action}.`
  }];
  appendAuditLocal(`arcgis.obstruction.${action}`, {
    project: project.id,
    status: project.arcgis.syncStatus,
    primeAcceptanceStatus: project.arcgis.primeAcceptanceStatus,
    obstaclePins: project.arcgis.obstaclePins,
    by: state.user?.name || "Operations"
  });
  recomputeBillingReadinessLocal(project.id);
  persist(`ArcGIS obstruction ${action.replaceAll("-", " ")} recorded`);
  void saveToApi("projects", project, false);
  render();
}

function ensureReleaseDocument(project, type, name, folder, path, status = "Reviewed") {
  state.data.documents = state.data.documents || [];
  const existing = state.data.documents.find(item => item.project === project.id && item.type === type);
  const now = new Date().toISOString();
  if (existing) {
    existing.status = status;
    existing.uploadedAt = existing.uploadedAt || now;
    existing.modifiedAt = now;
    existing.notes = appendInlineNote(existing.notes, `${type} cleared for release-to-field.`);
    return existing;
  }
  const id = `DOC-${project.map || project.id}-${type}`.replace(/[^A-Z0-9-]/gi, "-").toUpperCase();
  const document = {
    id,
    project: project.id,
    type,
    name,
    status,
    path,
    folder,
    author: state.user?.name || "Operations Coordinator",
    uploadedAt: now,
    requiredForBilling: project.status === "Beginning Phase" ? "No" : "Yes",
    requiredForSafety: "Yes",
    fileType: "pdf",
    pinned: "Yes",
    notes: `${type} created from release-to-field completion workflow.`,
    activityLog: [{ at: now, by: state.user?.name || "Operations", note: "Release setup document created." }],
    createdAt: now,
    modifiedAt: now,
    owner: state.user?.name || "Operations Coordinator"
  };
  state.data.documents.push(document);
  void saveToApi("documents", document, true);
  return document;
}

function ensureMap3ReleaseCrew(project, now) {
  state.data.people = state.data.people || [];
  const crew = (state.data.crews || []).find(item => item.id === project.crew);
  const peopleToEnsure = [
    {
      id: "E-035",
      name: "Tasha Green",
      role: "Foreman",
      certs: "OSHA 30, First Aid/CPR, Trenching, Traffic Control",
      workersComp: "7600"
    },
    {
      id: "E-036",
      name: "Malik Johnson",
      role: "Ground Hand",
      certs: "OSHA 10, Trenching Awareness",
      workersComp: "6217"
    },
    {
      id: "E-037",
      name: "Nia Carter",
      role: "Traffic Control",
      certs: "OSHA 10, Traffic Control, Flagger",
      workersComp: "7720"
    }
  ];
  peopleToEnsure.forEach(person => {
    const existing = state.data.people.find(item => item.id === person.id);
    if (existing) {
      existing.crew = project.crew;
      existing.compliance = "Clear";
      existing.status = "Clear";
      existing.modifiedAt = now;
      existing.notes = appendInlineNote(existing.notes, `Staged for ${project.map || project.id} release-to-field.`);
    } else {
      state.data.people.push({
        ...person,
        crew: project.crew,
        nextExpiration: "2027-05-14",
        compliance: "Clear",
        backgroundRefresh: "2028-05-14",
        drugTest: "Current",
        notes: `${person.name} added for ${project.map || project.id} release-to-field crew readiness.`,
        activityLog: [{ at: now, by: state.user?.name || "Operations", note: "Crew member staged for release." }],
        status: "Clear",
        createdAt: now,
        modifiedAt: now,
        owner: person.name
      });
      void saveToApi("people", state.data.people.at(-1), true);
    }
  });
  if (crew) {
    crew.members = uniqueList([...(crew.members || []), ...peopleToEnsure.map(item => item.id)]);
    crew.status = "Staged for release";
    crew.modifiedAt = now;
    crew.notes = appendInlineNote(crew.notes, `${project.map || project.id} release crew staged.`);
  }
}

function handleReleaseCompletionAction(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  const action = button.dataset.releaseCompletionAction;
  const now = new Date().toISOString();
  project.adminApprovals = project.adminApprovals || {};
  project.approvalLog = project.approvalLog || [];

  if (action === "complete-setup-docs") {
    ensureReleaseDocument(project, "811", `${project.map || project.id} 811 ticket clear`, "811 / Locate Tickets", `/documents/${project.id}/811/current.pdf`, "Closed");
    ensureReleaseDocument(project, "Permit", `${project.map || project.id} permit and traffic control release`, "Permits", `/documents/${project.id}/permits/release.pdf`, "Closed");
    ensureReleaseDocument(project, "Site Survey", `${project.map || project.id} walkout and site survey`, "Site Surveys", `/documents/${project.id}/surveys/walkout-reviewed.pdf`, "Reviewed");
    (state.data.siteSurveys || [])
      .filter(item => item.project === project.id)
      .forEach(item => {
        item.status = "Reviewed";
        item.permitStatus = "Reviewed";
        item.modifiedAt = now;
        item.notes = appendInlineNote(item.notes, "Walkout, 811, permit, and traffic control reviewed for release-to-field.");
      });
    project.docs = "Map, site survey, 811, permits, traffic plan, GIS route, and obstruction evidence ready for release review";
    project.notes = appendInlineNote(project.notes, "Release setup documents completed.");
    appendAuditLocal("release-completion.setup-docs", { project: project.id, by: state.user?.name || "Operations" });
  }

  if (action === "stage-resources") {
    ensureMap3ReleaseCrew(project, now);
    (state.data.equipment || [])
      .filter(item => item.assigned === project.crew || item.assigned === project.id)
      .forEach(item => {
        if (["Scheduled", "Unavailable", "Needs Review"].includes(item.status)) item.status = "Available";
        if (item.id === "MAT-SQ-FIBER" && item.status === "Allocated") item.status = "Available";
        item.modifiedAt = now;
        item.notes = appendInlineNote(item.notes, `${project.map || project.id} staged for release-to-field.`);
      });
    appendAuditLocal("release-completion.resources", { project: project.id, crew: project.crew, by: state.user?.name || "Operations" });
  }

  if (action === "create-daily-starter") {
    state.data.dailies = state.data.dailies || [];
    let daily = state.data.dailies.find(item => item.project === project.id && item.id === "DLY-MAP3-INTAKE")
      || state.data.dailies.find(item => item.project === project.id && item.status !== "Submitted");
    if (!daily) {
      daily = {
        id: `DLY-${project.id}-START`.replace(/[^A-Z0-9-]/gi, "-"),
        project: project.id,
        date: isoDate(today),
        foreman: "Tasha Green",
        crew: project.crew,
        notes: "Daily starter created from release-to-field completion workflow.",
        activityLog: [],
        createdAt: now
      };
      state.data.dailies.push(daily);
      void saveToApi("dailies", daily, true);
    }
    daily.jsa = "Draft";
    daily.inspections = "Pre-job checklist opened";
    daily.locate = "811 current for release";
    daily.production = "Ready for field start; no production submitted yet";
    daily.output = "Daily starter created; JSA/PPE/equipment inspection ready for foreman completion";
    daily.status = "Draft";
    daily.modifiedAt = now;
    daily.owner = daily.owner || daily.foreman || "Tasha Green";
    daily.activityLog = [...(daily.activityLog || []), { at: now, by: state.user?.name || "Operations", note: "Daily/JSA starter staged for release-to-field." }];
    state.data.formSubmissions = state.data.formSubmissions || [];
    if (!state.data.formSubmissions.some(item => item.project === project.id && item.type === "JSA")) {
      state.data.formSubmissions.push({
        id: `FORM-JSA-${project.id}`.replace(/[^A-Z0-9-]/gi, "-"),
        project: project.id,
        type: "JSA",
        status: "Draft",
        submittedBy: daily.foreman || "Tasha Green",
        submittedAt: now,
        attachments: "JSA draft, PPE checklist, Field Maps confirmation",
        notes: "JSA starter created for foreman completion before work starts.",
        activityLog: [{ at: now, by: state.user?.name || "Operations", note: "JSA starter created." }],
        createdAt: now,
        modifiedAt: now
      });
      void saveToApi("formSubmissions", state.data.formSubmissions.at(-1), true);
    }
    appendAuditLocal("release-completion.daily-starter", { project: project.id, daily: daily.id, by: state.user?.name || "Operations" });
  }

  project.modifiedAt = now;
  project.approvalLog.push({
    decision: `release-completion-${action}`,
    status: releaseGateReview(project).ready ? "Ready for Release" : "Updated",
    by: state.user?.name || "Operations",
    at: now,
    reason: `Release completion action recorded: ${action}.`
  });
  recomputeBillingReadinessLocal(project.id);
  persist(`Release completion ${action.replaceAll("-", " ")} recorded`);
  void saveToApi("projects", project, false);
  render();
}

function handleCriticalPathAction(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  const action = button.dataset.criticalPathAction;
  const now = new Date().toISOString();

  if (action === "reconcile-field-captures") {
    const accepted = acceptedFieldCaptureEvidence(project);
    if (!accepted.rows.length) {
      alert("No accepted field captures are linked to this Map yet.");
      return;
    }
    const closeTaskIds = new Set([
      "TASK-MAP3-OBSPHOTO",
      "TASK-EVID-PO-SQ-24031-photo-evidence",
      "TASK-FIELD-CAPTURE-MAP3-CORRECTION"
    ]);
    (state.data.tasks || [])
      .filter(task => task.project === project.id)
      .filter(task => closeTaskIds.has(task.id) || task.source === "Field capture review" && accepted.rows.some(row => row.sync.id === task.syncId || row.related?.id === task.relatedId))
      .forEach(task => {
        task.status = "Closed";
        task.reviewStatus = task.reviewStatus && task.reviewStatus !== "Closed" ? "Closed" : task.reviewStatus;
        task.correctionStatus = task.correctionStatus ? "Accepted" : task.correctionStatus;
        task.modifiedAt = now;
        task.notes = appendInlineNote(task.notes, "Closed by critical path reconciliation after accepted field capture evidence was linked.");
        task.activityLog = [...(task.activityLog || []), { at: now, by: state.user?.name || "Operations", note: "Accepted field capture evidence reconciled to task." }];
        void saveToApi("tasks", task, false);
      });
    (state.data.offlineSyncQueue || [])
      .filter(item => item.project === project.id && item.review?.status === "Needs Correction" && (item.correctionVersions || []).length)
      .forEach(item => {
        item.review.status = "Closed";
        item.review.reviewedAt = now;
        item.review.note = "Original capture superseded by accepted corrected field capture evidence.";
        item.modifiedAt = now;
        item.activityLog = [...(item.activityLog || []), { at: now, by: state.user?.name || "Operations", note: "Correction loop closed after accepted replacement evidence." }];
        void saveToApi("offlineSyncQueue", item, false);
      });
    project.adminApprovals = project.adminApprovals || {};
    project.adminApprovals.evidenceReviews = (project.adminApprovals.evidenceReviews || []).map(review => review.key === "photo-evidence" ? {
      ...review,
      status: "Accepted",
      by: state.user?.name || "Operations",
      at: now,
      note: "Corrected GPS field capture accepted and linked to the Map 3 release path."
    } : review);
    project.approvalLog = [...(project.approvalLog || []), {
      decision: "critical-path-field-capture-reconciled",
      status: "Accepted",
      by: state.user?.name || "Operations",
      at: now,
      reason: `${accepted.rows.length} accepted field capture record(s) reconciled to release, billing, safety, and closeout evidence.`
    }];
    project.modifiedAt = now;
    appendAuditLocal("critical-path.field-captures-reconciled", { project: project.id, accepted: accepted.rows.length, by: state.user?.name || "Operations" });
    recomputeBillingReadinessLocal(project.id);
    persist("Accepted field captures reconciled");
    void saveToApi("projects", project, false);
    render();
  }
}

function closeReleaseHandoffTasks(project, note = "Release-to-field handoff verified.", now = new Date().toISOString()) {
  const handoff = releaseHandoffReadiness(project);
  const setupReady = handoff.setupReady;
  const captureReady = handoff.acceptedCaptures.rows.length > 0;
  const ids = new Set();
  if (setupReady) {
    ids.add("TASK-MAP3-SURVEY");
    ids.add("TASK-MAP3-811");
  }
  if (setupReady && captureReady) ids.add("TASK-MAP3-SAFETY");
  if (captureReady) ids.add("TASK-MAP3-OBSPHOTO");
  (state.data.tasks || [])
    .filter(task => task.project === project.id && task.status !== "Closed")
    .filter(task => ids.has(task.id) || task.source === "Release gate" && (handoff.release.ready || handoff.release.released))
    .forEach(task => {
      task.status = "Closed";
      task.closedAt = now;
      task.closedBy = state.user?.name || "Operations";
      task.modifiedAt = now;
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), { at: now, by: task.closedBy, note }];
      void saveToApi("tasks", task, false);
    });
}

function createReleaseHandoffFollowups(project, handoff) {
  handoff.items
    .filter(item => !item.ok)
    .forEach(item => {
      const config = item.key === "resources"
        ? { workflowArea: "People & Compliance", owner: "Operations Coordinator", role: "Operations" }
        : item.key === "release"
          ? { workflowArea: "Project & Map Hub", owner: "Ronald Jackson", role: "Admin" }
          : item.key === "start"
            ? { workflowArea: "Field Operations", owner: "Marcus Hill", role: "Foreman" }
            : { workflowArea: "Project & Map Hub", owner: "Operations Coordinator", role: "Operations" };
      createAdminTask(project, `Release handoff follow-up: ${item.label}`, config.workflowArea, item.detail, {
        id: `TASK-HANDOFF-${project.id}-${item.key}`.replace(/[^A-Z0-9-]/gi, "-").toUpperCase(),
        owner: config.owner,
        role: config.role,
        dueDate: addDays(isoDate(today), 1),
        priority: "High",
        source: "Release handoff QA",
        extra: { relatedType: "Release Handoff", relatedId: project.id, handoffKey: item.key }
      });
    });
}

function handleReleaseHandoffAction(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  const action = button.dataset.releaseHandoffAction;
  const now = new Date().toISOString();
  const handoff = releaseHandoffReadiness(project);

  if (action === "verify") {
    closeReleaseHandoffTasks(project, "Release-to-field handoff verified against the foreman daily-start gate.", now);
    project.adminApprovals = project.adminApprovals || {};
    project.adminApprovals.releaseHandoff = {
      status: handoff.ready ? "Verified" : "Verified with Follow-up",
      by: state.user?.name || "Operations",
      at: now,
      reason: handoff.ready ? "Setup, resources, release, and daily start are clean." : `Follow-up remains: ${handoff.items.filter(item => !item.ok).map(item => item.label).join(", ")}`
    };
    project.approvalLog = [...(project.approvalLog || []), {
      decision: "release-handoff-verified",
      status: project.adminApprovals.releaseHandoff.status,
      by: project.adminApprovals.releaseHandoff.by,
      at: now,
      reason: project.adminApprovals.releaseHandoff.reason
    }];
    project.modifiedAt = now;
    appendAuditLocal("release.handoff-verified", { project: project.id, status: project.adminApprovals.releaseHandoff.status, by: state.user?.name || "Operations" });
    persist("Release handoff verified");
    void saveToApi("projects", project, false);
    render();
  }

  if (action === "create-followups") {
    createReleaseHandoffFollowups(project, handoff);
    project.approvalLog = [...(project.approvalLog || []), {
      decision: "release-handoff-followups-created",
      status: "Needs Review",
      by: state.user?.name || "Operations",
      at: now,
      reason: handoff.items.filter(item => !item.ok).map(item => item.label).join(", ") || "No follow-ups needed."
    }];
    project.modifiedAt = now;
    appendAuditLocal("release.handoff-followups-created", { project: project.id, missing: handoff.items.filter(item => !item.ok).map(item => item.label), by: state.user?.name || "Operations" });
    persist("Release handoff follow-ups created");
    void saveToApi("projects", project, false);
    render();
  }
}

function handleBeginningAction(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  const action = button.dataset.beginningAction;
  const now = new Date().toISOString();
  const review = beginningPhaseReview(project);
  project.adminApprovals = project.adminApprovals || {};

  if (action === "request-docs") {
    const missing = review.steps.filter(step => ["Intake", "Map / site survey", "811 / permits"].includes(step.label) && !["Clear", "Field Ready"].includes(step.status));
    if (!missing.length) {
      createAdminTask(project, "Confirm setup documents are ready", "Documents", "Operations requested a final document check before release-to-field.");
    } else {
      missing.forEach(step => createAdminTask(project, `Resolve beginning-phase setup: ${step.label}`, "Documents", step.detail));
    }
  }

  if (action === "clear-obstacles") {
    (state.data.obstacles || [])
      .filter(item => item.project === project.id && isOpenObstacle(item))
      .forEach(item => {
        item.status = "Field Verified";
        item.modifiedAt = now;
        item.notes = appendInlineNote(item.notes, "Operations field-verified obstacle for release review.");
      });
  }

  if (action === "ready-release") {
    const gate = releaseGateReview(project);
    if (!gate.ready) {
      gate.blockers.forEach(blocker => {
        const config = releaseBlockerTaskConfig(blocker);
        createAdminTask(project, `Clear release blocker: ${blocker.label}`, config.workflowArea, blocker.detail, {
          id: `TASK-RELEASE-${project.id}-${String(blocker.key || blocker.label).replace(/[^A-Z0-9]+/gi, "-").toUpperCase()}`,
          owner: config.owner,
          role: config.role,
          source: "Release gate",
          extra: { releaseGateKey: blocker.key, relatedType: "Release Gate", relatedId: project.id }
        });
      });
      project.adminApprovals.releaseRequest = {
        status: "Blocked",
        by: state.user?.name || "Operations",
        at: now,
        reason: `Release request blocked: ${gate.blockers.map(item => item.label).join(", ")}`
      };
    } else {
      project.adminApprovals.releaseRequest = {
        status: "Ready for Release",
        by: state.user?.name || "Operations",
        at: now,
        reason: "Operations marked beginning-phase setup ready for Admin release-to-field."
      };
    }
  }

  if (action === "block-release") {
    const gate = releaseGateReview(project);
    createAdminTask(project, "Release-to-field blocked by Admin/Operations", "Project & Map Hub", gate.blockers.length ? `Blocked until these gates are clear: ${gate.blockers.map(item => item.label).join(", ")}.` : "Release manually blocked for management review.");
    project.adminApprovals.releaseRequest = {
      status: "Blocked",
      by: state.user?.name || "Operations",
      at: now,
      reason: gate.blockers.length ? `Release blocked: ${gate.blockers.map(item => item.label).join(", ")}` : "Release manually blocked for management review."
    };
  }

  project.modifiedAt = now;
  appendAuditLocal(`beginning.${action}`, { project: project.id, status: project.adminApprovals.releaseRequest?.status || "Updated" });
  persist();
  render();
}

function releaseBlockerTaskConfig(gate) {
  if (gate.key === "gis") return { workflowArea: "Project & Map Hub", owner: "Operations Coordinator", role: "Operations" };
  if (gate.key === "crew") return { workflowArea: "People & Compliance", owner: "Safety Compliance", role: "Safety/Compliance" };
  if (gate.key === "equipment") return { workflowArea: "Equipment", owner: "Operations Coordinator", role: "Operations" };
  if (gate.key === "obstacles") return { workflowArea: "Safety & Risk", owner: "Safety Compliance", role: "Safety/Compliance" };
  if (gate.key === "admin") return { workflowArea: "Project & Map Hub", owner: "Ronald Jackson", role: "Admin" };
  return { workflowArea: "Documents", owner: "Operations Coordinator", role: "Operations" };
}

function createReleaseBlockerTasks(projectId) {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return;
  const review = releaseGateReview(project);
  if (!review.blockers.length) {
    alert("Release gate is clear. No blocker tasks were created.");
    return;
  }
  const now = new Date().toISOString();
  const created = review.blockers.map(gate => {
    const config = releaseBlockerTaskConfig(gate);
    const id = `TASK-RELEASE-${project.id}-${String(gate.key || gate.label).replace(/[^A-Z0-9]+/gi, "-").toUpperCase()}`;
    return createAdminTask(project, `Clear release gate: ${gate.label}`, config.workflowArea, `${project.map || project.id}: ${gate.detail}`, {
      id,
      owner: config.owner,
      role: config.role,
      dueDate: addDays(isoDate(today), 1),
      priority: gate.status === "Blocked" ? "High" : "Medium",
      status: "Open",
      source: "Release gate",
      extra: {
        releaseGateKey: gate.key,
        relatedType: "Release Gate",
        relatedId: project.id
      },
      activityLog: [{
        at: now,
        by: state.user?.name || "Operations",
        note: `Created from release-to-field gate blocker: ${gate.label}.`
      }]
    });
  });
  project.adminApprovals = project.adminApprovals || {};
  project.adminApprovals.releaseRequest = {
    status: "Blocked",
    by: state.user?.name || "Operations",
    at: now,
    reason: `Release blocker tasks created: ${review.blockers.map(item => item.label).join(", ")}`
  };
  project.modifiedAt = now;
  appendAuditLocal("release.blocker-tasks-created", {
    project: project.id,
    tasks: created.map(task => task.id),
    blockers: review.blockers.map(item => item.label),
    by: state.user?.name || "Operations"
  });
  persist("Release blocker tasks created");
  render();
}

function handleReleaseBlockerAction(button) {
  const action = button.dataset.releaseAction;
  const recordId = button.dataset.recordId;
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  const now = new Date().toISOString();

  if (["schedule-cert", "clear-person", "replace-crew"].includes(action)) {
    const person = (state.data.people || []).find(item => item.id === recordId);
    if (!person) return;
    if (action === "clear-person") {
      person.compliance = "Clear";
      person.nextExpiration = person.nextExpiration && daysUntil(person.nextExpiration) <= 30 ? "2027-05-10" : person.nextExpiration;
      person.notes = appendInlineNote(person.notes, `Cleared for ${project.id} release-to-field.`);
    }
    if (action === "schedule-cert") {
      person.compliance = person.compliance === "Blocked" ? "Expiring" : person.compliance;
      person.notes = appendInlineNote(person.notes, `Certification renewal scheduled for ${project.id} release review.`);
      createAdminTask(project, `Renew certification for ${person.name}`, "People & Compliance", `${person.name} needs cert renewal or proof uploaded before release-to-field.`);
    }
    if (action === "replace-crew") {
      createAdminTask(project, `Replace blocked crew member ${person.name}`, "People & Compliance", `${person.name} is blocking release. Assign a qualified replacement or clear compliance.`);
    }
    person.modifiedAt = now;
    appendAuditLocal(`release.${action}`, { project: project.id, person: person.id, compliance: person.compliance });
  }

  if (["schedule-inspection", "clear-equipment", "swap-equipment"].includes(action)) {
    const asset = (state.data.equipment || []).find(item => item.id === recordId);
    if (!asset) return;
    if (action === "clear-equipment") {
      asset.status = "Available";
      asset.inspectionDue = asset.inspectionDue && daysUntil(asset.inspectionDue) <= 30 ? "2027-05-10" : asset.inspectionDue;
      asset.notes = appendInlineNote(asset.notes, `Cleared for ${project.id} release-to-field.`);
    }
    if (action === "schedule-inspection") {
      asset.status = asset.status === "Unavailable" ? "Scheduled" : asset.status;
      asset.notes = appendInlineNote(asset.notes, `Inspection/calibration scheduled for ${project.id} release review.`);
      createAdminTask(project, `Complete inspection for ${asset.id}`, "Equipment", `${asset.asset} needs inspection/calibration proof before release-to-field.`);
    }
    if (action === "swap-equipment") {
      createAdminTask(project, `Replace blocked asset ${asset.id}`, "Equipment", `${asset.asset} is blocking release. Assign an available replacement or clear inspection.`);
    }
    asset.modifiedAt = now;
    appendAuditLocal(`release.${action}`, { project: project.id, asset: asset.id, status: asset.status });
  }

  persist();
  render();
}

function ensureInvoiceForProject(project) {
  state.data.invoices = state.data.invoices || [];
  const existing = state.data.invoices.find(item => item.project === project.id);
  if (existing) return existing;
  const amounts = projectBillingAmounts(project);
  const now = new Date().toISOString();
  const invoice = {
    id: `INV-${project.id}`,
    project: project.id,
    submitted: today.toISOString().slice(0, 10),
    gross: amounts.gross,
    paid90: 0,
    retainage10: amounts.retainage,
    retainageRelease: "2027-05-10",
    status: "Draft",
    support: "Invoice package created from admin billing handoff.",
    notes: "Invoice created from map billing package.",
    activityLog: [],
    createdAt: now,
    modifiedAt: now
  };
  state.data.invoices.push(invoice);
  return invoice;
}

function ensureRetainageForProject(project, invoice) {
  state.data.retainageLedger = state.data.retainageLedger || [];
  const existing = state.data.retainageLedger.find(item => item.project === project.id || item.invoice === invoice.id);
  if (existing) return existing;
  const now = new Date().toISOString();
  const retainage = {
    id: `RET-${project.id}`,
    project: project.id,
    invoice: invoice.id,
    heldAmount: invoice.retainage10 || projectBillingAmounts(project).retainage,
    releaseDate: invoice.retainageRelease || "2027-05-10",
    status: "Held",
    disputeReason: "None",
    followUpDate: "2026-06-10",
    followUpStatus: "Scheduled",
    paymentNote: "Retainage created when SQUAN invoice was submitted.",
    notes: "10% retainage tracked from invoice submission.",
    activityLog: [],
    createdAt: now,
    modifiedAt: now
  };
  state.data.retainageLedger.push(retainage);
  closeRetainageLifecycleTasks(project.id, "ledger", `Retainage ledger ${retainage.id} created.`);
  return retainage;
}

function submissionGateTaskWorkflow(item) {
  if (item.action === "Documents") return "Documents";
  if (item.action === "Reports") return "Reports";
  if (item.action === "Tasks") return "Tasks";
  if (/qc|closeout|safety/i.test(item.label)) return "Safety & Risk";
  return "Billing";
}

function createSubmissionGateBlockerTasks(project, gate = billingSubmissionGate(project)) {
  const blockers = gate.blockers || [];
  if (!blockers.length) return [];
  return blockers.map(item => {
    if (item.label === "Prepared package snapshot current") {
      closeSubmissionGateTaskForLabel(project.id, item.label, "Consolidated into Package snapshot rebuild task.");
      return createPackageSnapshotRebuildTask(project, packageSnapshotChangeStatus(project));
    }
    return createAdminTask(
      project,
      `Clear SQUAN submission gate: ${item.label}`,
      submissionGateTaskWorkflow(item),
      `${item.detail}. Required before Billing can submit ${project.map || project.id} to SQUAN.`,
      {
        id: submissionGateTaskId(project.id, item.label),
        owner: item.action === "Documents" ? "Office Billing" : item.action === "Reports" ? "Ronald Jackson" : undefined,
        role: item.action === "Documents" ? "Billing" : item.action === "Reports" ? "Admin" : undefined,
        priority: "High",
        source: "SQUAN submission gate",
        extra: {
          relatedType: "SQUAN Submission Gate",
          relatedId: project.id,
          gateLabel: item.label,
          gateStatus: item.status
        },
        activityLog: [{
          at: new Date().toISOString(),
          by: state.user?.name || "Billing",
          note: "Created from SQUAN submission gate blocker."
        }]
      }
    );
  }).filter(Boolean);
}

function quantityReconciliationTaskId(projectId, unitCode) {
  return `TASK-QUANTITY-RECON-${projectId}-${String(unitCode || "UNIT").replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toUpperCase()}`;
}

function handleQuantityReconciliationAction(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  if (!guardFinalizedPacketEdit(project.id, "quantity reconciliation")) return;
  const unitCode = button.dataset.unitCode;
  const action = button.dataset.quantityReconAction;
  const unit = (state.data.projectUnits || []).find(item => item.project === project.id && item.unitCode === unitCode);
  if (!unit) return;
  const reconciliation = mapQuantityReconciliation(project);
  const row = reconciliation.rows.find(item => item.unitCode === unitCode);
  if (!row) return;
  const now = new Date().toISOString();
  if (action === "accept") {
    const note = prompt("Why is this quantity variance accepted?", row.overContract ? "Customer/prime-approved overage or authorized field quantity variance." : "ArcGIS/field daily variance reviewed and accepted for billing.") || "";
    if (!note.trim()) return;
    unit.quantityReconciliation = {
      status: "Accepted",
      by: state.user?.name || "User",
      at: now,
      note: note.trim(),
      dailyQuantity: row.dailyQuantity,
      arcgisQuantity: row.arcgisQuantity,
      billableQuantity: row.billableQuantity,
      variance: row.variance
    };
    unit.notes = appendInlineNote(unit.notes, `Quantity variance accepted: ${note.trim()}`);
    unit.activityLog = [...(unit.activityLog || []), { at: now, by: state.user?.name || "User", note: `Quantity reconciliation accepted for ${unitCode}.` }];
    closeQuantityReconciliationTask(project.id, unitCode, "Closed after quantity variance was accepted.");
    appendAuditLocal("billing.quantity-reconciliation.accepted", { project: project.id, unitCode, variance: row.variance, billableQuantity: row.billableQuantity, by: state.user?.name || "User" });
  }
  if (action === "task") {
    createAdminTask(project, `Resolve quantity variance: ${unit.description || unitCode}`, "Billing", `${project.map || project.id}: ${unitCode} has daily ${row.dailyQuantity.toLocaleString()}, ArcGIS ${row.arcgisQuantity.toLocaleString()}, prior billed ${row.previouslyBilled.toLocaleString()}, billable ${row.billableQuantity.toLocaleString()}, variance ${row.variance.toLocaleString()}. Resolve before SQUAN packet submission.`, {
      id: quantityReconciliationTaskId(project.id, unitCode),
      owner: "Office Billing",
      role: "Billing",
      priority: "High",
      source: "Quantity reconciliation",
      extra: { relatedType: "Project Unit", relatedId: unitCode, gateLabel: "Quantity reconciled" }
    });
    appendAuditLocal("billing.quantity-reconciliation.task-created", { project: project.id, unitCode, by: state.user?.name || "User" });
  }
  unit.modifiedAt = now;
  recomputeProjectLocal(project.id);
  reconcilePackageBuildGateTasks(project, billingPackageBuildGate(project));
  reconcileSubmissionGateTasks(project, billingSubmissionGate(project));
  persist(action === "accept" ? "Quantity variance accepted" : "Quantity reconciliation task created");
  void saveToApi("projectUnits", unit, false);
  render();
}

function closeQuantityReconciliationTask(projectId, unitCode, note) {
  const now = new Date().toISOString();
  (state.data.tasks || [])
    .filter(task => task.project === projectId && task.status !== "Closed" && (task.id === quantityReconciliationTaskId(projectId, unitCode) || (task.source === "Quantity reconciliation" && task.relatedId === unitCode)))
    .forEach(task => {
      task.status = "Closed";
      task.closedAt = now;
      task.closedBy = state.user?.name || "System";
      task.modifiedAt = now;
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), { at: now, by: state.user?.name || "System", note }];
      void saveToApi("tasks", task, false);
    });
}

function submissionGateTaskId(projectId, label) {
  return `TASK-SUBMIT-GATE-${projectId}-${label.replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toUpperCase()}`;
}

function packageBuildTaskWorkflow(item) {
  if (item.action === "Documents") return "Documents";
  if (item.action === "Field Operations") return "Field Operations";
  if (item.action === "Time Tracking") return "Time Tracking";
  if (item.action === "Project & Map Hub") return "Project & Map Hub";
  return "Billing";
}

function createPackageBuildBlockerTasks(project, gate = billingPackageBuildGate(project)) {
  const blockers = gate.blockers || [];
  if (!blockers.length) return [];
  return blockers.map(item => createAdminTask(
    project,
    `Clear invoice package build blocker: ${item.label}`,
    packageBuildTaskWorkflow(item),
    `${item.detail}. Required before Billing can prepare the SQUAN invoice package for ${project.map || project.id}.`,
    {
      id: `TASK-PACKAGE-BUILD-${project.id}-${item.label.replace(/[^a-z0-9]+/gi, "-").replace(/^-|-$/g, "").toUpperCase()}`,
      owner: item.action === "Field Operations" ? (dailyBillingHandoffStatus(project).daily?.foreman || "Foreman") : item.action === "Documents" ? "Office Billing" : undefined,
      role: item.action === "Field Operations" ? "Foreman" : item.action === "Documents" ? "Billing" : undefined,
      priority: "High",
      source: "Invoice package build gate",
      extra: {
        relatedType: "Invoice Package Build Gate",
        relatedId: project.id,
        gateLabel: item.label,
        gateStatus: item.status
      },
      activityLog: [{
        at: new Date().toISOString(),
        by: state.user?.name || "Billing",
        note: "Created from invoice package build guard."
      }]
    }
  ));
}

function reconcilePackageBuildGateTasks(project, gate = billingPackageBuildGate(project)) {
  const openLabels = new Set((gate.blockers || []).map(item => item.label));
  const now = new Date().toISOString();
  const closed = [];
  (state.data.tasks || [])
    .filter(task => task.project === project.id && task.source === "Invoice package build gate" && task.status !== "Closed")
    .forEach(task => {
      if (openLabels.has(task.gateLabel)) return;
      task.status = "Closed";
      task.closedAt = now;
      task.closedBy = "System";
      task.modifiedAt = now;
      task.notes = appendInlineNote(task.notes, `Auto-closed because invoice package build blocker cleared: ${task.gateLabel || task.title}.`);
      task.activityLog = [...(task.activityLog || []), {
        at: now,
        by: "System",
        note: "Invoice package build guard is now clear for this blocker."
      }];
      closed.push(task.id);
      void saveToApi("tasks", task, false);
    });
  if (closed.length) {
    appendAuditLocal("billing.package-build-tasks-auto-closed", {
      project: project.id,
      tasks: closed,
      status: gate.status
    });
  }
  return closed;
}

function packageSnapshotRebuildTaskId(projectId) {
  return `TASK-PACKAGE-SNAPSHOT-REBUILD-${projectId}`;
}

function createPackageSnapshotRebuildTask(project, changeStatus = packageSnapshotChangeStatus(project)) {
  if (changeStatus.current || !changeStatus.snapshot) return null;
  const reviewStatus = snapshotDiffReviewStatus(project, changeStatus);
  return createAdminTask(
    project,
    `Rebuild stale SQUAN package snapshot ${changeStatus.snapshot.id}`,
    "Billing",
    `${project.map || project.id} package snapshot is stale. Review and acknowledge the snapshot diff, then rebuild a new package version before SQUAN submission. Changes: ${changeStatus.changes.slice(0, 5).join("; ")}${changeStatus.changes.length > 5 ? "..." : ""}`,
    {
      id: packageSnapshotRebuildTaskId(project.id),
      owner: "Office Billing",
      role: "Billing",
      priority: "High",
      status: "Open",
      dueDate: project.billBy || "2026-05-11",
      source: "Package snapshot rebuild",
      extra: {
        relatedType: "Prepared Package Snapshot",
        relatedId: changeStatus.snapshot.id,
        snapshotId: changeStatus.snapshot.id,
        snapshotVersion: changeStatus.snapshot.version,
        snapshotStatus: changeStatus.status,
        snapshotChangeCount: changeStatus.changes.length,
        snapshotDiffReviewed: reviewStatus.reviewed ? "Yes" : "No",
        snapshotDiffReviewAt: reviewStatus.review?.at || "",
        snapshotDiffReviewBy: reviewStatus.review?.by || "",
        gateLabel: "Prepared package snapshot current",
        gateStatus: changeStatus.status
      },
      activityLog: [{
        at: new Date().toISOString(),
        by: state.user?.name || "Billing",
        note: "Created from stale prepared package snapshot guard."
      }]
    }
  );
}

function reconcilePackageSnapshotRebuildTask(project, changeStatus = packageSnapshotChangeStatus(project)) {
  const task = (state.data.tasks || []).find(item => item.id === packageSnapshotRebuildTaskId(project.id));
  if (!task || task.status === "Closed") return null;
  const reviewStatus = snapshotDiffReviewStatus(project, changeStatus);
  const now = new Date().toISOString();
  if (!changeStatus.current) {
    task.snapshotStatus = changeStatus.status;
    task.snapshotChangeCount = changeStatus.changes.length;
    task.snapshotDiffReviewed = reviewStatus.reviewed ? "Yes" : "No";
    task.snapshotDiffReviewAt = reviewStatus.review?.at || "";
    task.snapshotDiffReviewBy = reviewStatus.review?.by || "";
    task.modifiedAt = now;
    task.notes = `${project.map || project.id} package snapshot is stale. Review and acknowledge the snapshot diff, then rebuild a new package version before SQUAN submission. Changes: ${changeStatus.changes.slice(0, 5).join("; ")}${changeStatus.changes.length > 5 ? "..." : ""}`;
    void saveToApi("tasks", task, false);
    return task;
  }
  closeSubmissionGateTaskForLabel(project.id, "Prepared package snapshot current", "Closed because the prepared package snapshot is current.");
  task.status = "Closed";
  task.closedAt = now;
  task.closedBy = "System";
  task.modifiedAt = now;
  task.snapshotStatus = changeStatus.status;
  task.snapshotDiffReviewed = "Yes";
  task.notes = appendInlineNote(task.notes, `Auto-closed because prepared package snapshot is current: ${changeStatus.snapshot?.id || project.id}.`);
  task.activityLog = [...(task.activityLog || []), {
    at: now,
    by: "System",
    note: "Prepared package snapshot now matches current package state."
  }];
  void saveToApi("tasks", task, false);
  appendAuditLocal("billing.package-snapshot-rebuild-task-auto-closed", {
    project: project.id,
    task: task.id,
    snapshot: changeStatus.snapshot?.id || ""
  });
  return task;
}

function reconcilePackageSnapshotRebuildTasks(project, changeStatus = packageSnapshotChangeStatus(project)) {
  if (!changeStatus.snapshot) return null;
  if (changeStatus.current) return reconcilePackageSnapshotRebuildTask(project, changeStatus);
  return createPackageSnapshotRebuildTask(project, changeStatus);
}

function closeSubmissionGateTasks(projectId, note) {
  (state.data.tasks || [])
    .filter(task => task.project === projectId && task.source === "SQUAN submission gate" && task.status !== "Closed")
    .forEach(task => {
      task.status = "Closed";
      task.modifiedAt = new Date().toISOString();
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), {
        at: new Date().toISOString(),
        by: state.user?.name || "Billing",
        note
      }];
      void saveToApi("tasks", task, false);
    });
}

function reconcileSubmissionGateTasks(project, gate = billingSubmissionGate(project)) {
  const openLabels = new Set((gate.blockers || []).map(item => item.label));
  const now = new Date().toISOString();
  const closed = [];
  (state.data.tasks || [])
    .filter(task => task.project === project.id && task.source === "SQUAN submission gate" && task.status !== "Closed")
    .forEach(task => {
      if (openLabels.has(task.gateLabel)) return;
      task.status = "Closed";
      task.closedAt = now;
      task.closedBy = "System";
      task.modifiedAt = now;
      task.notes = appendInlineNote(task.notes, `Auto-closed because SQUAN submission gate blocker cleared: ${task.gateLabel || task.title}.`);
      task.activityLog = [...(task.activityLog || []), {
        at: now,
        by: "System",
        note: "SQUAN submission gate item is now clear."
      }];
      closed.push(task.id);
      void saveToApi("tasks", task, false);
    });
  const snapshotStatus = packageSnapshotChangeStatus(project);
  reconcilePackageSnapshotRebuildTasks(project, snapshotStatus);
  if (gate.ready) closeSubmissionGateTasks(project.id, "Closed automatically when SQUAN submission gate cleared.");
  if (closed.length) {
    appendAuditLocal("billing.submission-gate-tasks-auto-closed", {
      project: project.id,
      tasks: closed,
      status: gate.status
    });
  }
  return closed;
}

function recheckSubmissionGateWithSummary(project) {
  const before = billingSubmissionGate(project);
  const beforeLabels = new Set(before.blockers.map(item => item.label));
  const closedTasks = reconcileSubmissionGateTasks(project, before);
  const after = billingSubmissionGate(project);
  const afterLabels = new Set(after.blockers.map(item => item.label));
  const cleared = [...beforeLabels].filter(label => !afterLabels.has(label));
  const remaining = after.blockers.map(item => item.label);
  const summary = {
    project: project.id,
    map: project.map || project.id,
    at: new Date().toISOString(),
    by: state.user?.name || "Billing",
    beforeStatus: before.status,
    afterStatus: after.status,
    ready: after.ready,
    submitted: after.submitted,
    cleared,
    remaining,
    closedTasks,
    message: after.ready
      ? `${project.map || project.id} is ready to submit to SQUAN. ${cleared.length} blocker(s) cleared.`
      : `${project.map || project.id} still has ${remaining.length} SQUAN submission blocker(s): ${remaining.join(", ")}.`
  };
  state.lastSubmissionGateRecheck = summary;
  appendAuditLocal("billing.submission-gate-recheck", {
    project: project.id,
    before: before.status,
    after: after.status,
    cleared,
    remaining,
    closedTasks,
    by: summary.by
  });
  return summary;
}

function closeSubmissionGateTaskForLabel(projectId, label, note) {
  const now = new Date().toISOString();
  (state.data.tasks || [])
    .filter(task => task.project === projectId && task.source === "SQUAN submission gate" && task.status !== "Closed" && (task.gateLabel === label || task.id === submissionGateTaskId(projectId, label)))
    .forEach(task => {
      task.status = "Closed";
      task.closedAt = now;
      task.closedBy = "System";
      task.modifiedAt = now;
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), {
        at: now,
        by: "System",
        note
      }];
      void saveToApi("tasks", task, false);
    });
}

function arDisciplineTaskId(projectId, key) {
  return `TASK-AR-DISC-${projectId}-${key.toUpperCase()}`;
}

function createArDisciplineTasks(project, submission, invoice) {
  if (!submission) return [];
  const items = submissionDisciplineItems(project, submission, invoice);
  const openItems = items.filter(item => !item.ok && ["Needs Receipt", "Needs Schedule", "Overdue", "Open"].includes(item.status));
  return openItems.map(item => {
    const dueDate = item.status === "Overdue"
      ? isoDate(today)
      : item.key === "receipt"
        ? addDays(submission.submissionDate || isoDate(today), 1)
        : item.key === "payment"
          ? submission.followUpDate || addDays(submission.submissionDate || isoDate(today), 30)
          : submission.followUpDate || addDays(isoDate(today), 3);
    return createAdminTask(project, `AR follow-up: ${item.label}`, "Billing", `${item.detail} Keep SQUAN submission ${submission.invoiceNumber || submission.invoice} current before cash forecast and collections review.`, {
      id: arDisciplineTaskId(project.id, item.key),
      owner: item.key === "escalation" ? "Ronald Jackson" : "Office Billing",
      role: item.key === "escalation" ? "Admin" : "Billing",
      dueDate,
      priority: item.status === "Overdue" ? "High" : "Medium",
      status: item.status === "Overdue" ? "Open" : "Scheduled",
      source: "SQUAN AR discipline",
      extra: {
        relatedType: "Invoice Submission",
        relatedId: submission.id,
        arDisciplineKey: item.key,
        arDisciplineStatus: item.status
      },
      activityLog: [{
        at: new Date().toISOString(),
        by: state.user?.name || "Billing",
        note: `Created from AR discipline check: ${item.label}.`
      }]
    });
  });
}

function setupPostSubmissionArTasks(project, submission, invoice) {
  const items = submissionDisciplineItems(project, submission, invoice);
  const clearedKeys = items.filter(item => item.ok).map(item => item.key);
  if (clearedKeys.length) {
    closeArDisciplineTasks(project.id, clearedKeys, "Closed automatically from SQUAN submission confirmation data.");
  }
  const tasks = createArDisciplineTasks(project, submission, invoice);
  appendAuditLocal("billing.post-submission-ar-tasks-setup", {
    project: project.id,
    submission: submission?.id || "",
    created: tasks.map(task => task.id),
    cleared: clearedKeys,
    by: state.user?.name || "Billing"
  });
  return tasks;
}

function closeArDisciplineTasks(projectId, keys, note) {
  const keySet = new Set(Array.isArray(keys) ? keys : [keys]);
  (state.data.tasks || [])
    .filter(task => task.project === projectId && task.source === "SQUAN AR discipline" && task.status !== "Closed" && keySet.has(task.arDisciplineKey))
    .forEach(task => {
      task.status = "Closed";
      task.modifiedAt = new Date().toISOString();
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), {
        at: new Date().toISOString(),
        by: state.user?.name || "Billing",
        note
      }];
      void saveToApi("tasks", task, false);
    });
}

function prepareSquanPackage(project) {
  if (!guardFinalizedPacketEdit(project.id, "prepare SQUAN billing package")) return;
  const buildGate = billingPackageBuildGate(project);
  if (!buildGate.ready) {
    const tasks = createPackageBuildBlockerTasks(project, buildGate);
    appendAuditLocal("billing.package-build-blocked", {
      project: project.id,
      blockers: buildGate.blockers.map(item => item.label),
      tasks: tasks.map(task => task.id),
      by: state.user?.name || "Billing"
    });
    persist("Invoice package build blocked by open items");
    render();
    return;
  }
  const acceptedPacket = squanPacketAcceptedPayload(project);
  if (!acceptedPacket.ready) {
    appendAuditLocal("billing.accepted-only-packet-blocked", {
      project: project.id,
      blockers: acceptedPacket.blockers,
      by: state.user?.name || "Billing"
    });
    persist("SQUAN package blocked until accepted daily evidence and accepted invoice lines are ready");
    alert(`SQUAN packet cannot be prepared yet: ${acceptedPacket.blockers.join(", ")}`);
    render();
    return;
  }
  const buildApproval = packageBuildApprovalStatus(project);
  if (!buildApproval.approved) {
    appendAuditLocal("billing.prepare-squan-package-approval-blocked", {
      project: project.id,
      status: buildApproval.status,
      by: state.user?.name || "Billing"
    });
    persist("SQUAN package preparation blocked until package build is approved");
    render();
    return;
  }
  const now = new Date().toISOString();
  const invoice = ensureInvoiceForProject(project);
  const retainagePercent = projectBillingAmounts(project).retainagePercent;
  invoice.gross = acceptedPacket.gross;
  invoice.retainage10 = Math.round(acceptedPacket.gross * retainagePercent / 100);
  invoice.support = "Invoice package created from accepted daily evidence and accepted billing ledger lines only.";
  invoice.notes = appendInlineNote(invoice.notes, `Prepared from accepted-only packet contents on ${formatDateTime(now)}.`);
  invoice.modifiedAt = now;
  void saveToApi("invoices", invoice, false);
  const retainage = ensureRetainageForProject(project, invoice);
  retainage.heldAmount = invoice.retainage10;
  retainage.modifiedAt = now;
  if (retainage.status === "Held") {
    retainage.status = "Projected";
    retainage.paymentNote = "Projected 10% retainage created during SQUAN package preparation; becomes held after submission.";
  }
  void saveToApi("retainageLedger", retainage, false);
  const qc = (state.data.qcCloseouts || []).find(item => item.project === project.id);
  const canAcceptEvidence = ["Passed", "Approved Exception"].includes(qc?.status) || Boolean(project.adminApprovals?.exception);
  const ledger = evidenceReviewLedger(project);
  const evidence = fieldEvidenceManifest(project);
  const autoAccepted = [];
  evidence.forEach(item => {
    const rawStatus = item.rawStatus || item.status;
    const alreadyReviewed = ledger.find(review => review.key === item.key);
    if (alreadyReviewed?.status === "Accepted" || alreadyReviewed?.status === "Rejected") return;
    if (canAcceptEvidence && ["Ready", "Submitted", "Accepted", "Passed", "Approved Exception", "Accepted Exception"].includes(rawStatus)) {
      ledger.push({
        key: item.key,
        label: item.label,
        status: "Accepted",
        by: state.user?.name || "Billing",
        at: now,
        note: "Accepted during SQUAN package preparation after QC/exception clearance.",
        sourceStatus: rawStatus
      });
      autoAccepted.push(item.label);
      closeEvidenceCorrectionTasks(project, item.key, `${item.label} accepted during SQUAN package preparation.`);
    }
  });
  recomputeBillingReadinessLocal(project.id);
  const readiness = (state.data.billingReadiness || []).find(item => item.project === project.id);
  if (readiness && readiness.missingItems === "None") {
    readiness.status = ["3 Days Left", "7 Days Left", "Overdue / Forfeiture Risk"].includes(readiness.status) ? readiness.status : "Ready to Bill";
    readiness.notes = appendInlineNote(readiness.notes, "SQUAN package prepared from QC-cleared field evidence.");
    readiness.modifiedAt = now;
  }
  reconcilePackageBuildGateTasks(project);
  const snapshot = createPreparedPackageSnapshot(project, invoice, retainage, billingPackageBuildGate(project));
  markAcceptedPacketContentsUsed(project, acceptedPacket, snapshot.id, now);
  reconcilePackageSnapshotRebuildTask(project, packageSnapshotChangeStatus(project));
  project.approvalLog = [...(project.approvalLog || []), {
    decision: "prepare-squan-package",
    status: autoAccepted.length ? "Evidence Accepted" : "Prepared",
    by: state.user?.name || "Billing",
    at: now,
    reason: `Draft invoice ${invoice.id} prepared; snapshot ${snapshot.id}; ${autoAccepted.length} evidence item(s) accepted; retainage ${retainage.id} staged.`
  }];
  project.modifiedAt = now;
  const gate = billingSubmissionGate(project);
  if (gate.blockers.length) createSubmissionGateBlockerTasks(project, gate);
  else closeSubmissionGateTasks(project.id, "Closed automatically when SQUAN submission gate cleared.");
  reconcileSubmissionGateTasks(project, gate);
  appendAuditLocal("billing.prepare-squan-package", {
    project: project.id,
    invoice: invoice.id,
    retainage: retainage.id,
    snapshot: snapshot.id,
    autoAccepted,
    acceptedDaily: acceptedPacket.acceptedDailyId,
    acceptedLines: acceptedPacket.lineIds,
    blockers: gate.blockers.map(item => item.label),
    by: state.user?.name || "Billing"
  });
  persist(gate.blockers.length ? "SQUAN package prepared with blocker tasks" : "SQUAN package ready for submission");
  render();
}

function markAcceptedPacketContentsUsed(project, acceptedPacket, snapshotId, at = new Date().toISOString()) {
  const by = state.user?.name || "Billing";
  if (acceptedPacket.acceptedDaily) {
    acceptedPacket.acceptedDaily.usedForBilling = true;
    acceptedPacket.acceptedDaily.usedInPacketId = snapshotId;
    acceptedPacket.acceptedDaily.usedInPacketAt = at;
    acceptedPacket.acceptedDaily.usedInPacketBy = by;
    acceptedPacket.acceptedDaily.modifiedAt = at;
    acceptedPacket.acceptedDaily.activityLog = [
      ...(acceptedPacket.acceptedDaily.activityLog || []),
      { at, by, note: `Included in accepted-only SQUAN packet ${snapshotId}.` }
    ];
    void saveToApi("dailies", acceptedPacket.acceptedDaily, false);
  }
  const markRows = (collection, rows) => {
    rows.forEach(row => {
      row.packetStatus = "Used in Packet";
      row.usedInPacketId = snapshotId;
      row.usedInPacketAt = at;
      row.usedInPacketBy = by;
      row.modifiedAt = at;
      row.activityLog = [
        ...(row.activityLog || []),
        { at, by, note: `Included in accepted-only SQUAN packet ${snapshotId}.` }
      ];
      void saveToApi(collection, row, false);
    });
  };
  markRows("formSubmissions", acceptedPacket.forms);
  markRows("documents", acceptedPacket.documents);
  markRows("photoEvidence", acceptedPacket.photos);
  project.adminApprovals = project.adminApprovals || {};
  project.adminApprovals.billingLineReviews = (project.adminApprovals.billingLineReviews || []).map(review => (
    acceptedPacket.lineIds.includes(review.lineId)
      ? { ...review, usedInPacketId: snapshotId, usedInPacketAt: at, packetStatus: "Used in Packet" }
      : review
  ));
  project.modifiedAt = at;
  void saveToApi("projects", project, false);
}

function upsertInvoiceSubmission(project, receiptInput = {}) {
  state.data.invoiceSubmissions = state.data.invoiceSubmissions || [];
  const invoice = ensureInvoiceForProject(project);
  const retainage = ensureRetainageForProject(project, invoice);
  const amounts = projectBillingAmounts(project);
  const acceptedSnapshotGuard = acceptedPacketSubmissionGuard(project);
  const packetSnapshot = acceptedSnapshotGuard.snapshot;
  const packetGross = packetSnapshot?.gross || amounts.gross;
  const packetRetainage = packetSnapshot?.retainageAmount || retainage.heldAmount || amounts.retainage;
  const packetAttachments = (packetSnapshot?.attachments || submissionAttachmentList(project)).map(item => `${item.collection}:${item.id}`);
  const now = new Date().toISOString();
  let submission = state.data.invoiceSubmissions.find(item => item.project === project.id);
  if (!submission) {
    submission = {
      id: `SUB-${project.id}`,
      project: project.id,
      invoice: invoice.id,
      invoiceNumber: invoice.id,
      submittedTo: "SQUAN",
      submissionDate: receiptInput.submissionDate || today.toISOString().slice(0, 10),
      squanBillingContact: receiptInput.contact || "SQUAN PM / AP",
      gross: packetGross,
      expected90: Math.max(0, packetGross - packetRetainage),
      retainage10: packetRetainage,
      packageSnapshot: packetSnapshot?.id || "",
      packageSnapshotVersion: packetSnapshot?.version || "",
      acceptedOnly: packetSnapshot?.acceptedOnly || "No",
      acceptedDailyId: packetSnapshot?.acceptedDailyId || "",
      acceptedInvoiceLineIds: packetSnapshot?.acceptedInvoiceLineIds || [],
      supportPackageStatus: acceptedSnapshotGuard.ready ? "Accepted-only packet locked" : "Needs Review",
      status: "Submitted to SQUAN",
      deliveryMethod: receiptInput.method || "SQUAN billing portal / email",
      confirmationNumber: receiptInput.confirmationNumber || "",
      followUpDate: receiptInput.followUpDate || addDays(isoDate(today), 14),
      followUpStatus: receiptInput.confirmationNumber ? "Receipt recorded" : "Receipt pending",
      attachmentsSent: packetAttachments,
      receipt: {
        confirmationNumber: receiptInput.confirmationNumber || "",
        submittedBy: state.user?.name || "Office Billing",
        receivedBy: receiptInput.contact || "SQUAN PM / AP",
        method: receiptInput.method || "SQUAN billing portal / email",
        receivedAt: receiptInput.confirmationNumber ? now : "",
        followUpDate: receiptInput.followUpDate || addDays(isoDate(today), 14),
        followUpStatus: receiptInput.confirmationNumber ? "Receipt recorded" : "Receipt pending",
        notes: receiptInput.confirmationNumber ? "Receipt/reference captured during SQUAN submission confirmation." : "Awaiting SQUAN portal/email receipt confirmation."
      },
      notes: "Admin approved and recorded SQUAN invoice submission.",
      activityLog: [],
      createdAt: now,
      modifiedAt: now
    };
    state.data.invoiceSubmissions.push(submission);
  } else {
    submission.status = "Submitted to SQUAN";
    submission.invoice = invoice.id;
    submission.invoiceNumber = invoice.id;
    submission.gross = packetGross;
    submission.expected90 = Math.max(0, packetGross - packetRetainage);
    submission.retainage10 = packetRetainage;
    submission.packageSnapshot = packetSnapshot?.id || submission.packageSnapshot || "";
    submission.packageSnapshotVersion = packetSnapshot?.version || submission.packageSnapshotVersion || "";
    submission.acceptedOnly = packetSnapshot?.acceptedOnly || submission.acceptedOnly || "No";
    submission.acceptedDailyId = packetSnapshot?.acceptedDailyId || submission.acceptedDailyId || "";
    submission.acceptedInvoiceLineIds = packetSnapshot?.acceptedInvoiceLineIds || submission.acceptedInvoiceLineIds || [];
    submission.submissionDate = receiptInput.submissionDate || submission.submissionDate || today.toISOString().slice(0, 10);
    submission.deliveryMethod = receiptInput.method || submission.deliveryMethod || "SQUAN billing portal / email";
    submission.squanBillingContact = receiptInput.contact || submission.squanBillingContact || "SQUAN PM / AP";
    submission.confirmationNumber = receiptInput.confirmationNumber || submission.confirmationNumber || "";
    submission.followUpDate = receiptInput.followUpDate || submission.followUpDate || addDays(isoDate(today), 14);
    submission.followUpStatus = receiptInput.confirmationNumber ? "Receipt recorded" : submission.followUpStatus || "Receipt pending";
    submission.supportPackageStatus = acceptedSnapshotGuard.ready ? "Accepted-only packet locked" : "Needs Review";
    submission.attachmentsSent = packetAttachments;
    submission.receipt = submission.receipt || {
      confirmationNumber: submission.confirmationNumber || "",
      submittedBy: state.user?.name || submission.owner || "Office Billing",
      receivedBy: submission.squanBillingContact || "SQUAN PM / AP",
      method: submission.deliveryMethod || "SQUAN billing portal / email",
      receivedAt: "",
      followUpDate: submission.followUpDate || "2026-05-17",
      followUpStatus: submission.followUpStatus || "Receipt pending",
      notes: "Awaiting SQUAN portal/email receipt confirmation."
    };
    submission.receipt = {
      ...(submission.receipt || {}),
      confirmationNumber: receiptInput.confirmationNumber || submission.receipt?.confirmationNumber || submission.confirmationNumber || "",
      submittedBy: state.user?.name || submission.owner || "Office Billing",
      receivedBy: receiptInput.contact || submission.receipt?.receivedBy || submission.squanBillingContact || "SQUAN PM / AP",
      method: receiptInput.method || submission.receipt?.method || submission.deliveryMethod || "SQUAN billing portal / email",
      receivedAt: receiptInput.confirmationNumber ? now : submission.receipt?.receivedAt || "",
      followUpDate: receiptInput.followUpDate || submission.receipt?.followUpDate || submission.followUpDate || addDays(isoDate(today), 14),
      followUpStatus: receiptInput.confirmationNumber ? "Receipt recorded" : submission.receipt?.followUpStatus || submission.followUpStatus || "Receipt pending",
      notes: receiptInput.confirmationNumber ? "Receipt/reference captured during SQUAN submission confirmation." : submission.receipt?.notes || "Awaiting SQUAN portal/email receipt confirmation."
    };
    submission.modifiedAt = now;
  }
  if (retainage.status === "Projected") {
    retainage.status = "Held";
    retainage.paymentNote = "10% retainage is now held from the recorded SQUAN submission.";
    retainage.modifiedAt = now;
    retainage.activityLog = [...(retainage.activityLog || []), {
      at: now,
      by: state.user?.name || "Billing",
      note: "Projected retainage converted to held retainage at SQUAN submission."
    }];
  }
  invoice.status = "Submitted to SQUAN";
  invoice.submitted = submission.submissionDate;
  invoice.modifiedAt = now;
  invoice.notes = appendInlineNote(invoice.notes, "Submitted to SQUAN with support package.");
  return submission;
}

function recordSubmissionReceipt(project, submission, invoice) {
  if (!submission) return null;
  const now = new Date().toISOString();
  const confirmationNumber = prompt("Enter SQUAN confirmation/reference number") || "";
  if (!confirmationNumber.trim()) return null;
  const receivedBy = prompt("SQUAN contact / receipt source", submission.squanBillingContact || "SQUAN PM / AP") || submission.squanBillingContact || "SQUAN PM / AP";
  const method = prompt("Submission method", submission.deliveryMethod || "SQUAN billing portal / email") || submission.deliveryMethod || "SQUAN billing portal / email";
  const followUpDate = prompt("Follow-up date", submission.followUpDate || "2026-05-17") || submission.followUpDate || "2026-05-17";
  const attachments = submissionAttachmentList(project).map(item => `${item.collection}:${item.id}`);
  submission.confirmationNumber = confirmationNumber.trim();
  submission.deliveryMethod = method.trim();
  submission.squanBillingContact = receivedBy.trim();
  submission.followUpDate = followUpDate.trim();
  submission.followUpStatus = "Receipt recorded";
  submission.attachmentsSent = attachments;
  submission.receipt = {
    confirmationNumber: confirmationNumber.trim(),
    submittedBy: state.user?.name || "Office Billing",
    receivedBy: receivedBy.trim(),
    method: method.trim(),
    receivedAt: now,
    followUpDate: followUpDate.trim(),
    followUpStatus: "Receipt recorded",
    notes: `${attachments.length} attachment reference(s) logged with submission receipt.`
  };
  submission.status = "Submitted to SQUAN";
  submission.modifiedAt = now;
  submission.activityLog = [...(submission.activityLog || []), {
    at: now,
    by: state.user?.name || "Billing",
    note: `Receipt recorded: ${confirmationNumber.trim()} via ${method.trim()}; follow-up ${followUpDate.trim()}.`
  }];
  if (invoice) {
    invoice.status = invoice.status === "Draft" ? "Submitted to SQUAN" : invoice.status;
    invoice.notes = appendInlineNote(invoice.notes, `SQUAN receipt ${confirmationNumber.trim()} recorded.`);
    invoice.modifiedAt = now;
  }
  createAdminTask(project, "Follow up on SQUAN invoice receipt", "Billing", `Receipt ${confirmationNumber.trim()} recorded. Follow up by ${followUpDate.trim()} if payment/acceptance is not visible.`, {
    id: `TASK-SUBMISSION-FOLLOWUP-${project.id}`,
    owner: "Office Billing",
    role: "Billing",
    dueDate: followUpDate.trim(),
    priority: "Medium",
    status: "Scheduled",
    source: "Submission receipt",
    extra: {
      relatedType: "Invoice Submission",
      relatedId: submission.id
    }
  });
  closeArDisciplineTasks(project.id, "receipt", `Receipt ${confirmationNumber.trim()} recorded.`);
  return submission;
}

function scheduleSubmissionFollowUp(project, submission) {
  if (!submission) return null;
  const followUpDate = prompt("Follow-up date", submission.followUpDate || submission.receipt?.followUpDate || "2026-05-17") || "";
  if (!followUpDate.trim()) return null;
  const now = new Date().toISOString();
  submission.followUpDate = followUpDate.trim();
  submission.followUpStatus = "Scheduled";
  submission.receipt = {
    ...(submission.receipt || {}),
    followUpDate: followUpDate.trim(),
    followUpStatus: "Scheduled"
  };
  submission.modifiedAt = now;
  submission.activityLog = [...(submission.activityLog || []), {
    at: now,
    by: state.user?.name || "Billing",
    note: `Submission follow-up scheduled for ${followUpDate.trim()}.`
  }];
  createAdminTask(project, "Follow up on SQUAN submission", "Billing", `Confirm SQUAN acceptance/payment status for ${submission.invoiceNumber || submission.invoice}.`, {
    id: `TASK-SUBMISSION-FOLLOWUP-${project.id}`,
    owner: "Office Billing",
    role: "Billing",
    dueDate: followUpDate.trim(),
    priority: "Medium",
    status: "Scheduled",
    source: "Submission receipt",
    extra: {
      relatedType: "Invoice Submission",
      relatedId: submission.id
    }
  });
  closeArDisciplineTasks(project.id, "followup", `AR follow-up scheduled for ${followUpDate.trim()}.`);
  return submission;
}

function recordSquanSubmissionResponse(project, submission, invoice) {
  if (!submission) return null;
  const responseStatus = prompt("SQUAN response status", submission.responseStatus || "Acknowledged / payment status pending") || "";
  if (!responseStatus.trim()) return null;
  const responseNote = prompt("SQUAN response note", submission.responseNote || "SQUAN confirmed receipt and will provide payment status.") || "";
  if (!responseNote.trim()) return null;
  const promisedPaymentDate = prompt("Promised payment date, if any", submission.promisedPaymentDate || "") || "";
  const disputeOutcome = prompt("Dispute / hold outcome, if any", submission.disputeOutcome || "") || "";
  const nextFollowUpDate = prompt("Next follow-up date", submission.followUpDate || submission.receipt?.followUpDate || addDays(isoDate(today), 3)) || "";
  const now = new Date().toISOString();
  submission.responseStatus = responseStatus.trim();
  submission.responseNote = responseNote.trim();
  submission.responseAt = now;
  submission.responseBy = state.user?.name || "Billing";
  submission.promisedPaymentDate = promisedPaymentDate.trim();
  submission.disputeOutcome = disputeOutcome.trim();
  submission.followUpDate = nextFollowUpDate.trim() || submission.followUpDate;
  submission.followUpStatus = promisedPaymentDate.trim()
    ? "Payment promised"
    : disputeOutcome.trim()
      ? "Dispute / hold documented"
      : "Response logged";
  submission.status = promisedPaymentDate.trim()
    ? "Payment promised"
    : disputeOutcome.trim()
      ? "Disputed"
      : "Response received";
  submission.receipt = {
    ...(submission.receipt || {}),
    followUpDate: submission.followUpDate,
    followUpStatus: submission.followUpStatus,
    responseStatus: submission.responseStatus,
    responseAt: now
  };
  submission.activityLog = [...(submission.activityLog || []), {
    at: now,
    by: submission.responseBy,
    note: `SQUAN response: ${submission.responseStatus}. ${submission.responseNote}`
  }];
  if (invoice) {
    invoice.status = submission.status === "Payment promised" ? invoice.status || "Submitted to SQUAN" : submission.status;
    invoice.notes = appendInlineNote(invoice.notes, `SQUAN response logged: ${submission.responseStatus}. ${submission.responseNote}`);
    invoice.modifiedAt = now;
  }
  createAdminTask(project, "Follow up on SQUAN AR response", "Billing", `${project.map || project.id}: ${submission.responseStatus}. ${submission.responseNote}`, {
    id: `TASK-SQUAN-AR-RESPONSE-${project.id}`,
    owner: "Office Billing",
    role: "Billing",
    dueDate: submission.followUpDate || promisedPaymentDate.trim() || addDays(isoDate(today), 3),
    priority: disputeOutcome.trim() ? "High" : "Medium",
    status: "Scheduled",
    source: "SQUAN AR response",
    extra: {
      relatedType: "Invoice Submission",
      relatedId: submission.id
    }
  });
  closeArDisciplineTasks(project.id, ["response", "escalation"], `SQUAN response logged: ${submission.responseStatus}.`);
  return submission;
}

function escalateArFollowUp(project, submission, invoice) {
  if (!submission) return null;
  const reason = prompt("Escalation reason", submission.escalationReason || "SQUAN follow-up is overdue or payment status is unclear.") || "";
  if (!reason.trim()) return null;
  const now = new Date().toISOString();
  submission.escalationReason = reason.trim();
  submission.escalationAt = now;
  submission.escalationBy = state.user?.name || "Billing";
  submission.followUpStatus = "Escalated";
  submission.status = "Escalated";
  submission.activityLog = [...(submission.activityLog || []), {
    at: now,
    by: submission.escalationBy,
    note: `AR follow-up escalated: ${reason.trim()}`
  }];
  if (invoice) {
    invoice.status = invoice.status === "Paid" ? invoice.status : "AR follow-up escalated";
    invoice.notes = appendInlineNote(invoice.notes, `AR follow-up escalated: ${reason.trim()}`);
    invoice.modifiedAt = now;
  }
  createAdminTask(project, "Escalate SQUAN AR follow-up", "Billing", `${project.map || project.id} needs escalation: ${reason.trim()}`, {
    id: `TASK-SQUAN-AR-ESCALATE-${project.id}`,
    owner: "Ronald Jackson",
    role: "Admin",
    dueDate: isoDate(today),
    priority: "High",
    status: "Open",
    source: "SQUAN AR escalation",
    extra: {
      relatedType: "Invoice Submission",
      relatedId: submission.id
    }
  });
  closeArDisciplineTasks(project.id, "escalation", `AR follow-up escalated: ${reason.trim()}.`);
  return submission;
}

function recordCashReceipt(project, { type, invoice, submission, retainage, expectedAmount, expectedDate }) {
  state.data.cashReceipts = state.data.cashReceipts || [];
  state.data.company = state.data.company || {};
  const defaultAmount = Number(expectedAmount || 0);
  const amountText = prompt(`${type} actual amount received`, String(defaultAmount)) || "";
  if (!amountText.trim()) return null;
  const actualAmount = Number(amountText);
  if (!Number.isFinite(actualAmount) || actualAmount < 0) {
    alert("Enter a valid received amount.");
    return null;
  }
  const actualDate = prompt("Actual receipt date", isoDate(today)) || isoDate(today);
  const reference = prompt("Bank/SQUAN payment reference", `${type.toUpperCase().replaceAll(" ", "-")}-${invoice?.id || retainage?.id || project.id}`) || "";
  const bankProof = prompt("Bank proof / deposit reference if available", reference || "") || "";
  const now = new Date().toISOString();
  const id = type === "Retainage" ? `CASH-RET-${retainage?.id || project.id}` : `CASH-90-${invoice?.id || project.id}`;
  const existing = state.data.cashReceipts.find(item => item.id === id);
  const previousActual = Number(existing?.actualAmount || 0);
  const variance = actualAmount - defaultAmount;
  const depositBatchId = existing?.depositBatch || `DEP-${actualDate.trim()}`;
  const receipt = {
    ...(existing || {}),
    id,
    project: project.id,
    invoice: invoice?.id || retainage?.invoice || "",
    submission: submission?.id || "",
    retainage: retainage?.id || "",
    type,
    expectedDate: expectedDate || submission?.followUpDate || retainage?.releaseDate || "",
    actualDate: actualDate.trim(),
    expectedAmount: defaultAmount,
    actualAmount,
    variance,
    status: variance === 0 ? "Reconciled" : "Variance Review",
    reference: reference.trim(),
    bankProof: bankProof.trim() || existing?.bankProof || "",
    depositBatch: depositBatchId,
    depositStatus: bankProof.trim() ? variance === 0 ? "Proof Attached" : "Proof Attached / Variance Review" : "Pending Bank Proof",
    receivedBy: state.user?.name || "Billing",
    receivedAt: now,
    notes: `${type} receipt recorded against ${project.map || project.id}. ${bankProof.trim() ? "Bank proof attached." : "Bank proof still required."}`,
    activityLog: [
      ...(existing?.activityLog || []),
      {
        at: now,
        by: state.user?.name || "Billing",
        note: `${type} receipt ${reference.trim() || "no reference"} recorded for ${currency(actualAmount)}.`
      }
    ],
    createdAt: existing?.createdAt || now,
    modifiedAt: now
  };
  if (existing) Object.assign(existing, receipt);
  else state.data.cashReceipts.push(receipt);
  const depositBatch = ensureDepositBatchForReceipt(receipt);
  createCashReceiptReconciliationTasks(project, receipt);
  state.data.company.cashOnHand = Number(state.data.company.cashOnHand || 0) + actualAmount - previousActual;
  state.data.company.cashReceiptHistory = [
    ...(state.data.company.cashReceiptHistory || []),
    {
      at: now,
      by: state.user?.name || "Billing",
      project: project.id,
      invoice: receipt.invoice,
      type,
      actualAmount,
      previousActual,
      variance: receipt.variance,
      reference: receipt.reference,
      notes: `${type} receipt applied to cash on hand.`
    }
  ];
  appendAuditLocal("cash.receipt-recorded", { project: project.id, receipt: receipt.id, depositBatch: depositBatch.id, variance: receipt.variance, proof: Boolean(receipt.bankProof) });
  return receipt;
}

function ensureDepositBatchForReceipt(receipt) {
  state.data.cashDepositBatches = state.data.cashDepositBatches || [];
  const now = new Date().toISOString();
  const id = receipt.depositBatch || `DEP-${receipt.actualDate || isoDate(today)}`;
  let batch = state.data.cashDepositBatches.find(item => item.id === id);
  const isNew = !batch;
  if (!batch) {
    batch = {
      id,
      depositDate: receipt.actualDate || isoDate(today),
      receiptIds: [],
      bankFeedAmount: 0,
      status: "Needs Review",
      notes: "Auto-created from recorded SQUAN cash receipt.",
      activityLog: [],
      createdAt: now,
      modifiedAt: now
    };
    state.data.cashDepositBatches.push(batch);
  }
  batch.receiptIds = uniqueList([...(batch.receiptIds || []), receipt.id]);
  const batchReceipts = (state.data.cashReceipts || [])
    .filter(item => (batch.receiptIds || []).includes(item.id) || item.depositBatch === batch.id || item.id === receipt.id)
    .map(item => item.id === receipt.id ? receipt : item);
  const receiptTotal = sum(batchReceipts, "actualAmount");
  if (!Number(batch.bankFeedAmount || 0) || batch.status !== "Verified") batch.bankFeedAmount = receiptTotal;
  const missingProof = batchReceipts.filter(item => !item.bankProof);
  const variance = receiptTotal - Number(batch.bankFeedAmount || 0);
  batch.status = variance === 0 && !missingProof.length ? "Ready to Verify" : variance !== 0 ? "Variance Review" : "Needs Review";
  batch.notes = appendInlineNote(batch.notes, `Receipt ${receipt.id} staged; receipt total ${currency(receiptTotal)}; bank feed ${currency(batch.bankFeedAmount)}.`);
  batch.modifiedAt = now;
  batch.activityLog = [...(batch.activityLog || []), {
    at: now,
    by: state.user?.name || "Billing",
    note: `Receipt ${receipt.id} added to deposit batch.`
  }];
  void saveToApi("cashDepositBatches", batch, isNew);
  return batch;
}

function createCashReceiptReconciliationTasks(project, receipt) {
  const tasks = [];
  if (!receipt.bankProof) {
    tasks.push(createAdminTask(project, `Attach bank proof for ${receipt.id}`, "Billing", `${receipt.type} receipt ${receipt.id} needs bank/deposit proof before deposit verification.`, {
      id: `TASK-CASH-PROOF-${receipt.id}`,
      owner: "Office Billing",
      role: "Billing",
      dueDate: addDays(isoDate(today), 1),
      priority: "High",
      source: "Cash receipt reconciliation",
      extra: { relatedType: "Cash Receipt", relatedId: receipt.id, cashReceiptKey: "proof" }
    }));
  }
  if (Number(receipt.variance || 0) !== 0) {
    tasks.push(createAdminTask(project, `Resolve cash variance for ${receipt.id}`, "Billing", `${project.map || project.id} expected ${currency(receipt.expectedAmount)} but received ${currency(receipt.actualAmount)}. Document short-pay, dispute, chargeback, or accepted variance.`, {
      id: `TASK-CASH-VARIANCE-${receipt.id}`,
      owner: "Office Billing",
      role: "Billing",
      dueDate: addDays(isoDate(today), 2),
      priority: "High",
      source: "Cash receipt reconciliation",
      extra: { relatedType: "Cash Receipt", relatedId: receipt.id, cashReceiptKey: "variance" }
    }));
  }
  if (receipt.depositStatus !== "Deposit Verified") {
    tasks.push(createAdminTask(project, `Verify deposit for ${receipt.id}`, "Billing", `${receipt.type} receipt ${receipt.id} is staged in ${receipt.depositBatch || "a deposit batch"}. Verify against bank feed and proof.`, {
      id: `TASK-CASH-DEPOSIT-${receipt.id}`,
      owner: "Office Billing",
      role: "Billing",
      dueDate: addDays(isoDate(today), 2),
      priority: "Medium",
      source: "Cash receipt reconciliation",
      extra: { relatedType: "Cash Receipt", relatedId: receipt.id, cashReceiptKey: "deposit" }
    }));
  }
  return tasks;
}

function retainageTaskId(projectId, key) {
  return `TASK-RET-${projectId}-${key.toUpperCase()}`;
}

function createRetainageLifecycleTasks(project) {
  const invoice = (state.data.invoices || []).find(item => item.project === project.id);
  const retainage = (state.data.retainageLedger || []).find(item => item.project === project.id || item.invoice === invoice?.id);
  const items = retainageLifecycleItems(project);
  const taskItems = items.filter(item => !item.ok && item.key !== "deposit");
  return taskItems.map(item => createAdminTask(project, `Retainage lifecycle: ${item.label}`, "Billing", `${item.detail} Keep retainage exposure current for ${project.map || project.id}.`, {
    id: retainageTaskId(project.id, item.key),
    owner: item.key === "dispute" ? "Ronald Jackson" : "Office Billing",
    role: item.key === "dispute" ? "Admin" : "Billing",
    dueDate: item.key === "release" || item.key === "followup" ? retainage?.followUpDate || retainage?.releaseDate || addDays(isoDate(today), 7) : addDays(isoDate(today), 2),
    priority: ["payment", "dispute"].includes(item.key) ? "High" : "Medium",
    status: item.status === "Scheduled" ? "Scheduled" : "Open",
    source: "Retainage lifecycle",
    extra: {
      relatedType: "Retainage",
      relatedId: retainage?.id || project.id,
      retainageKey: item.key,
      retainageStatus: item.status
    },
    activityLog: [{
      at: new Date().toISOString(),
      by: state.user?.name || "Billing",
      note: `Created from retainage lifecycle check: ${item.label}.`
    }]
  }));
}

function closeRetainageLifecycleTasks(projectId, keys, note) {
  const keySet = new Set(Array.isArray(keys) ? keys : [keys]);
  (state.data.tasks || [])
    .filter(task => task.project === projectId && task.source === "Retainage lifecycle" && task.status !== "Closed" && (!task.retainageKey || keySet.has(task.retainageKey)))
    .forEach(task => {
      task.status = "Closed";
      task.modifiedAt = new Date().toISOString();
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), {
        at: new Date().toISOString(),
        by: state.user?.name || "Billing",
        note
      }];
      void saveToApi("tasks", task, false);
    });
}

function adminCloseoutRequirements(project) {
  const financialGate = mapFinancialCloseoutGate(project);
  const releaseApproved = Boolean(project.adminApprovals?.release) || project.status !== "Beginning Phase";
  const items = [{ label: "Release approved", ok: releaseApproved }, ...financialGate.items.map(item => ({ label: item.label, ok: item.ok }))];
  return {
    ready: items.every(item => item.ok),
    items,
    missing: items.filter(item => !item.ok).map(item => item.label)
  };
}

function closeFinancialCloseout(project, note = "") {
  const gate = mapFinancialCloseoutGate(project);
  if (!gate.ready) return { ok: false, gate };
  const now = new Date().toISOString();
  project.adminApprovals = project.adminApprovals || {};
  const record = {
    status: "Closed",
    by: state.user?.name || "Admin",
    at: now,
    reason: note || "Financial closeout gate cleared and Admin financially closed the Map.",
    gateSnapshot: gate.items.map(item => ({ key: item.key, label: item.label, status: item.status, ok: item.ok })),
    invoice: gate.invoice?.id || "",
    submission: gate.submission?.id || "",
    retainage: gate.retainage?.id || "",
    receipts: gate.receipts.map(item => item.id)
  };
  project.adminApprovals.financialCloseout = record;
  project.adminApprovals.closeout = record;
  project.status = "Completed / Billed";
  project.closedAt = now;
  project.approvalLog = [
    ...(project.approvalLog || []),
    { decision: "financial-closeout", ...record }
  ];
  appendAuditLocal("admin.financial-closeout.closed", {
    project: project.id,
    invoice: record.invoice,
    submission: record.submission,
    retainage: record.retainage,
    receipts: record.receipts,
    by: record.by
  });
  return { ok: true, gate, record };
}

function reopenFinancialCloseout(project, reason = "Financial records changed after closeout.", by = state.user?.name || "Admin") {
  if (project.adminApprovals?.financialCloseout?.status !== "Closed") return null;
  const now = new Date().toISOString();
  const previous = project.adminApprovals.financialCloseout;
  const record = {
    ...previous,
    status: "Reopened",
    reopenedAt: now,
    reopenedBy: by,
    reopenReason: reason
  };
  project.adminApprovals.financialCloseout = record;
  project.adminApprovals.closeout = { ...(project.adminApprovals.closeout || {}), status: "Reopened", at: now, by, reason };
  project.status = "Completed / Billed - Reopened";
  project.approvalLog = [
    ...(project.approvalLog || []),
    { decision: "reopen-financial-closeout", status: "Reopened", by, at: now, reason }
  ];
  createAdminTask(project, "Review reopened financial closeout", "Billing", `${project.map || project.id} financial closeout reopened: ${reason}. Recheck payment, retainage, deposit proof, disputes, and task cleanup before closing again.`, {
    id: `TASK-FIN-REOPEN-${project.id}`,
    owner: "Ronald Jackson",
    role: "Admin",
    dueDate: isoDate(today),
    priority: "High",
    source: "Financial closeout reopen",
    extra: {
      relatedType: "Financial Closeout",
      relatedId: project.id
    },
    activityLog: [{
      at: now,
      by,
      note: reason
    }]
  });
  reopenFinancialCloseoutPacketLock(project, reason, by, now);
  appendAuditLocal("admin.financial-closeout.reopened", { project: project.id, by, reason });
  return record;
}

function reopenFinancialCloseoutPacketLock(project, reason, by = state.user?.name || "Admin", now = new Date().toISOString()) {
  const lock = currentPacketLock(project.id, "Financial Closeout");
  if (!lock) return null;
  createPacketReopenTask(project.id, [lock], reason, "financial closeout record change");
  lock.status = "Reopened";
  lock.reopenedAt = now;
  lock.reopenedBy = by;
  lock.reopenReason = reason;
  lock.modifiedAt = now;
  lock.activityLog = [...(lock.activityLog || []), {
    at: now,
    by,
    note: `Financial Closeout packet reopened: ${reason}`
  }];
  appendAuditLocal("packet.financial-closeout-auto-reopen", {
    project: project.id,
    lock: lock.id,
    reason,
    by
  });
  void saveToApi("packetLocks", lock, false);
  return lock;
}

function handleFinancialCloseoutSubmissionAction(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project || !canManagePackets()) return;
  const lock = currentPacketLock(project.id, "Financial Closeout");
  if (!lock) {
    alert("Finalize the Financial Closeout packet before logging export, delivery, or receipt.");
    state.reportPrintScope = "Financial Closeout";
    render();
    return;
  }
  const action = button.dataset.financialCloseoutSubmissionAction;
  const now = new Date().toISOString();
  lock.submissionLog = lock.submissionLog || [];
  let event = null;

  if (action === "sent") {
    const sentTo = prompt("Sent/exported to", "SQUAN PM / AP / audit file") || "";
    if (!sentTo.trim()) return;
    const method = prompt("Delivery / storage method", "Saved PDF and emailed packet link") || "";
    if (!method.trim()) return;
    const confirmationNumber = prompt("Receipt / email / file reference", `FC-${project.id}-${isoDate(today)}`) || "";
    const followUpDate = prompt("Follow-up date, if any", addDays(isoDate(today), 7)) || "";
    event = {
      id: `FC-SUB-${project.id}-${Date.now()}`.replace(/[^A-Z0-9-]/gi, "-").toUpperCase(),
      action: "Sent",
      status: "Sent / Exported",
      title: "Financial Closeout packet sent/exported",
      at: now,
      by: state.user?.name || "Admin",
      sentTo: sentTo.trim(),
      method: method.trim(),
      confirmationNumber: confirmationNumber.trim(),
      followUpDate: followUpDate.trim(),
      detail: `Financial Closeout packet ${lock.id} delivered/stored by ${method.trim()} for ${sentTo.trim()}.`
    };
  }

  if (action === "receipt") {
    const receivedBy = prompt("Received/acknowledged by", "SQUAN PM / AP / auditor") || "";
    if (!receivedBy.trim()) return;
    const reference = prompt("Receipt / acknowledgement reference", lock.submissionLog.slice().reverse().find(item => item.confirmationNumber)?.confirmationNumber || "") || "";
    const note = prompt("Receipt note", "Financial Closeout packet receipt confirmed.") || "";
    if (!note.trim()) return;
    event = {
      id: `FC-RCPT-${project.id}-${Date.now()}`.replace(/[^A-Z0-9-]/gi, "-").toUpperCase(),
      action: "Receipt",
      status: "Receipt Confirmed",
      title: "Financial Closeout packet receipt confirmed",
      at: now,
      by: state.user?.name || "Admin",
      receivedBy: receivedBy.trim(),
      reference: reference.trim(),
      detail: note.trim()
    };
  }

  if (!event) return;
  lock.submissionLog.push(event);
  lock.modifiedAt = now;
  lock.activityLog = [...(lock.activityLog || []), {
    at: now,
    by: state.user?.name || "Admin",
    note: event.title
  }];
  if (action === "sent") {
    createFinancialCloseoutReceiptTask(project, lock, event);
  }
  if (action === "receipt") {
    closeFinancialCloseoutReceiptTasks(project.id, lock.id, `Receipt confirmed: ${event.reference || event.detail}`);
  }
  appendAuditLocal(`packet.financial-closeout.${String(action || "submission")}`, {
    project: project.id,
    lock: lock.id,
    event: event.id,
    by: state.user?.name || "Admin"
  });
  persist("Financial Closeout packet submission log updated");
  void saveToApi("packetLocks", lock, false);
  render();
}

function financialCloseoutReceiptTaskId(projectId, lockId) {
  return `TASK-FC-RECEIPT-${String(projectId).replace(/[^A-Z0-9]/gi, "")}-${String(lockId).replace(/[^A-Z0-9]/gi, "")}`.toUpperCase();
}

function createFinancialCloseoutReceiptTask(project, lock, event) {
  const followUpDate = event.followUpDate || addDays(isoDate(today), 3);
  return createAdminTask(project, "Confirm Financial Closeout packet receipt", "Billing", `${project.map || project.id} Financial Closeout packet ${lock.id} was sent/exported to ${event.sentTo || "recipient"}. Confirm receipt or acknowledgement by ${followUpDate}. Reference ${event.confirmationNumber || "not recorded"}.`, {
    id: financialCloseoutReceiptTaskId(project.id, lock.id),
    owner: "Office Billing",
    role: "Billing",
    dueDate: followUpDate,
    priority: "High",
    source: "Financial closeout receipt",
    extra: {
      relatedType: "Financial Closeout Packet",
      relatedId: lock.id,
      packetLockId: lock.id,
      packetScope: lock.scope,
      packetSubmissionEventId: event.id,
      receiptStatus: "Awaiting Receipt"
    },
    activityLog: [{
      at: event.at || new Date().toISOString(),
      by: event.by || state.user?.name || "Admin",
      note: `Created from Financial Closeout packet sent/exported event ${event.id}.`
    }]
  });
}

function closeFinancialCloseoutReceiptTasks(projectId, lockId, note) {
  const now = new Date().toISOString();
  const closed = [];
  (state.data.tasks || [])
    .filter(task => task.project === projectId && task.source === "Financial closeout receipt" && task.status !== "Closed" && (!lockId || task.packetLockId === lockId))
    .forEach(task => {
      task.status = "Closed";
      task.closedAt = now;
      task.closedBy = state.user?.name || "Admin";
      task.modifiedAt = now;
      task.receiptStatus = "Receipt Confirmed";
      task.notes = appendInlineNote(task.notes, note);
      task.activityLog = [...(task.activityLog || []), {
        at: now,
        by: state.user?.name || "Admin",
        note
      }];
      closed.push(task.id);
      void saveToApi("tasks", task, false);
    });
  if (closed.length) {
    appendAuditLocal("packet.financial-closeout.receipt-task-closed", {
      project: projectId,
      lock: lockId,
      tasks: closed,
      by: state.user?.name || "Admin"
    });
  }
  return closed;
}

function handleAdminDecision(button) {
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId);
  if (!project) return;
  const decision = button.dataset.adminDecision;
  if (["approve-invoice", "request-support", "escalate-squan", "close-map", "reopen-financial-closeout"].includes(decision) && !guardFinalizedPacketEdit(project.id, `Admin decision: ${decision}`)) return;
  const now = new Date().toISOString();
  const reason = adminDecisionReason(decision, project);
  project.adminApprovals = project.adminApprovals || {};
  project.approvalLog = project.approvalLog || [];
  const approvalRecord = { status: "Approved", by: state.user?.name || "Admin", at: now, reason };

  if (decision === "reopen-financial-closeout") {
    const reopenReason = prompt("Reopen financial closeout reason", "Payment, retainage, deposit proof, dispute, or audit record changed after closeout.") || "";
    if (!reopenReason.trim()) return;
    reopenFinancialCloseout(project, reopenReason.trim(), state.user?.name || "Admin");
    project.modifiedAt = now;
    persist("Financial closeout reopened");
    render();
    return;
  }

  if (decision === "approve-release") {
    const releaseReview = releaseGateReview(project);
    if (!releaseReview.ready && !project.adminApprovals?.exception) {
      project.adminApprovals.release = {
        status: "Blocked",
        by: state.user?.name || "Admin",
        at: now,
        reason: `Release blocked: ${releaseReview.blockers.map(item => item.label).join(", ")}`
      };
      releaseReview.blockers.forEach(blocker => {
        const config = releaseBlockerTaskConfig(blocker);
        createAdminTask(project, `Clear release blocker: ${blocker.label}`, config.workflowArea, blocker.detail, {
          id: `TASK-RELEASE-${project.id}-${String(blocker.key || blocker.label).replace(/[^A-Z0-9]+/gi, "-").toUpperCase()}`,
          owner: config.owner,
          role: config.role,
          source: "Release gate",
          extra: { releaseGateKey: blocker.key, relatedType: "Release Gate", relatedId: project.id }
        });
      });
      appendAuditLocal("admin.approve-release-blocked", { project: project.id, blockers: releaseReview.blockers.map(item => item.label) });
      project.modifiedAt = now;
      persist("Release approval blocked");
      render();
      return;
    }
    project.adminApprovals.release = approvalRecord;
    project.adminApprovals.releaseRequest = {
      ...(project.adminApprovals.releaseRequest || {}),
      status: "Released",
      by: state.user?.name || "Admin",
      at: now,
      reason: "Admin approved release-to-field."
    };
    if (project.status === "Beginning Phase") project.status = "Active";
    closeReleaseHandoffTasks(project, "Admin released this Map to field.", now);
  }
  if (decision === "approve-invoice") {
    const evidenceMissing = fieldEvidenceManifest(project).filter(item => ["Missing", "Needs Review", "Rejected"].includes(item.status));
    const evidenceUnaccepted = fieldEvidenceManifest(project).filter(item => !["Accepted", "Accepted Exception"].includes(item.status));
    const evidenceBlockers = [...evidenceMissing, ...evidenceUnaccepted.filter(item => !evidenceMissing.some(missing => missing.key === item.key))];
    if (evidenceBlockers.length && !project.adminApprovals?.exception) {
      project.adminApprovals.invoice = {
        status: "Blocked",
        by: state.user?.name || "Admin",
        at: now,
        reason: `Invoice approval blocked: ${evidenceBlockers.map(item => item.label).join(", ")}`
      };
      createMissingFieldEvidenceTasks(project, evidenceBlockers);
      appendAuditLocal("admin.approve-invoice-evidence-blocked", { project: project.id, missing: evidenceBlockers.map(item => item.label) });
      project.modifiedAt = now;
      persist("Invoice approval blocked by missing field evidence");
      render();
      return;
    }
    project.adminApprovals.invoice = approvalRecord;
    updateBillingApproval(project.id);
    upsertInvoiceSubmission(project);
  }
  if (decision === "accept-exception") {
    openExceptionDrawer(project.id);
    return;
  }
  if (decision === "close-map") {
    const financialGate = mapFinancialCloseoutGate(project);
    if (!financialGate.ready) {
      project.adminApprovals.closeout = { status: "Blocked", by: state.user?.name || "Admin", at: now, reason: `Financial closeout blocked: ${financialGate.blockers.map(item => item.label).join(", ")}` };
      createFinancialCloseoutTasks(project);
      appendAuditLocal("admin.financial-closeout.blocked", { project: project.id, missing: financialGate.blockers.map(item => item.label) });
      project.modifiedAt = now;
      persist("Financial closeout blocked");
      render();
      return;
    }
    const result = closeFinancialCloseout(project, reason);
    if (!result.ok) return;
  }
  if (decision === "request-support") createAdminTask(project, "Request missing billing support", "Documents", "Admin requested missing billing support before SQUAN submission.");
  if (decision === "escalate-squan") createAdminTask(project, "Escalate billing issue to SQUAN", "Billing", "Admin escalated this map to SQUAN for billing/payment follow-up.");

  if (decision !== "close-map") project.approvalLog.push({ decision, ...approvalRecord });
  project.modifiedAt = now;
  appendAuditLocal(`admin.${decision}`, {
    project: project.id,
    by: state.user?.name || "Admin",
    reason,
    riskAccepted: decision === "accept-exception"
  });
  persist();
  render();
}

function handleCashDecision(button) {
  const action = button.dataset.cashDecision;
  const project = (state.data.projects || []).find(item => item.id === button.dataset.projectId) || (state.data.projects || [])[0];
  if (!project) return;
  const rows = cashForecastRows();
  const outflows = cashOutflowRows();
  const summary = cashForecastSummary(rows, outflows);
  const buckets = forecastWeekBuckets(rows, outflows, summary.startingCash);
  const firstGap = buckets.find(bucket => bucket.runningCash < 0);
  const scenario = cashScenarioConfig();
  const now = new Date().toISOString();
  const config = {
    "escalate-squan-cash": {
      title: "Escalate SQUAN payment for cash forecast",
      workflowArea: "Billing",
      owner: "Office Billing",
      role: "Billing",
      priority: "High",
      dueDate: addDays(isoDate(today), 1),
      notes: `Scenario ${scenario.label}: ${currency(summary.atRisk)} at-risk exposure. Contact SQUAN, record pay-when-paid status, and update receipt/follow-up notes.`
    },
    "pause-hiring": {
      title: "Review hiring, overtime, and subcontractor commitments",
      workflowArea: "Tasks",
      owner: "Ronald Jackson",
      role: "Admin",
      priority: "High",
      dueDate: addDays(isoDate(today), 1),
      notes: firstGap ? `Scenario ${scenario.label}: first cash gap appears week ${firstGap.index} at ${currency(firstGap.runningCash)}. Pause discretionary hiring/overtime unless Admin approves exception.` : `Scenario ${scenario.label}: no projected gap, but Admin requested staffing review.`
    },
    "delay-equipment-spend": {
      title: "Hold noncritical equipment spend",
      workflowArea: "Equipment",
      owner: "Operations Coordinator",
      role: "Operations",
      priority: "Medium",
      dueDate: addDays(isoDate(today), 2),
      notes: `Scenario ${scenario.label}: review equipment purchases, rentals, maintenance timing, and replacement requests against ${currency(summary.endingCash)} projected ending cash.`
    },
    "request-retainage-status": {
      title: "Request SQUAN retainage release status",
      workflowArea: "Billing",
      owner: "Office Billing",
      role: "Billing",
      priority: "Medium",
      dueDate: addDays(isoDate(today), 3),
      notes: `Confirm retainage release clock, SQUAN acceptance date, and next release follow-up. Future retainage exposure is ${currency(summary.futureRetainage)}.`
    },
    "approve-work-threshold": {
      title: summary.endingCash < 0 ? "Block discretionary work until cash mitigation is logged" : "Approve work within cash threshold",
      workflowArea: "Project & Map Hub",
      owner: "Ronald Jackson",
      role: "Admin",
      priority: summary.endingCash < 0 ? "High" : "Medium",
      dueDate: addDays(isoDate(today), 1),
      notes: summary.endingCash < 0
        ? `Scenario ${scenario.label}: projected ending cash is ${currency(summary.endingCash)}. New discretionary work requires mitigation or accepted risk.`
        : `Scenario ${scenario.label}: projected ending cash is ${currency(summary.endingCash)}. Work can proceed if map gates remain clear.`
    }
  }[action];
  if (!config) return;
  const task = createAdminTask(project, config.title, config.workflowArea, config.notes, {
    id: `TASK-CASH-${action.toUpperCase()}-${project.id}`,
    owner: config.owner,
    role: config.role,
    dueDate: config.dueDate,
    priority: config.priority,
    source: "Cash decision workflow",
    extra: {
      scenario: scenario.label,
      projectedEndingCash: summary.endingCash,
      atRiskExposure: summary.atRisk,
      cashDecision: action
    }
  });
  state.data.company.cashDecisionLog = [
    ...(state.data.company.cashDecisionLog || []),
    {
      action,
      task: task.id,
      project: project.id,
      by: state.user?.name || "Admin",
      at: now,
      scenario: scenario.label,
      endingCash: summary.endingCash,
      notes: config.notes
    }
  ];
  appendAuditLocal(`cash.${action}`, { project: project.id, task: task.id, scenario: scenario.label, endingCash: summary.endingCash });
  persist("Cash decision task created");
  render();
}

function handleCashTaskAction(button) {
  const task = (state.data.tasks || []).find(item => item.id === button.dataset.taskId);
  if (!task || task.source !== "Cash decision workflow") return;
  const action = button.dataset.cashTaskAction;
  const now = new Date().toISOString();
  if (action === "escalate") {
    task.priority = "High";
    task.status = task.status === "Closed" ? "Closed" : "Escalated";
    task.notes = appendInlineNote(task.notes, "Escalated from cash decision follow-through queue.");
    task.activityLog = [...(task.activityLog || []), {
      at: now,
      by: state.user?.name || "Admin",
      note: "Cash decision task escalated."
    }];
    state.data.company.cashDecisionLog = [
      ...(state.data.company.cashDecisionLog || []),
      {
        action: "escalate-cash-task",
        task: task.id,
        project: task.project,
        by: state.user?.name || "Admin",
        at: now,
        scenario: task.scenario || cashScenarioConfig().label,
        endingCash: cashForecastSummary().endingCash,
        notes: "Task escalated from cash decision follow-through."
      }
    ];
    appendAuditLocal("cash.task-escalate", { task: task.id, project: task.project });
    persist("Cash decision task escalated");
    render();
  }
}

function handleCashHistoryAction(button) {
  const action = button.dataset.cashHistoryAction;
  const index = Number(button.dataset.historyIndex);
  const log = state.data.company?.cashDecisionLog?.[index];
  if (!log || action !== "review") return;
  const now = new Date().toISOString();
  log.reviewedAt = now;
  log.reviewedBy = state.user?.name || "Admin";
  log.status = log.status || "Reviewed";
  log.reviewNotes = "Manager reviewed cash decision, linked task status, and current forecast movement.";
  appendAuditLocal("cash.manager-review", { action: log.action, task: log.task, project: log.project, reviewedBy: log.reviewedBy });
  persist("Cash decision reviewed");
  render();
}

async function saveCashControls() {
  if (state.role !== "Admin") {
    alert("Only Admin can edit cash controls.");
    return;
  }
  state.data.company = state.data.company || {};
  const company = state.data.company;
  const before = {
    cashOnHand: Number(company.cashOnHand || 0),
    weeklyOverhead: Number(company.weeklyOverhead || 0),
    minimumCashThreshold: Number(company.minimumCashThreshold || 0),
    cashScenarioDelays: { ...(company.cashScenarioDelays || {}) }
  };
  company.cashOnHand = Number(document.getElementById("cashOnHandInput")?.value || 0);
  company.weeklyOverhead = Number(document.getElementById("weeklyOverheadInput")?.value || 0);
  company.minimumCashThreshold = Number(document.getElementById("minimumCashThresholdInput")?.value || 0);
  company.cashScenarioDelays = {
    baseline: Number(document.getElementById("cashDelayBaselineInput")?.value || 0),
    delay15: Number(document.getElementById("cashDelay15Input")?.value || 15),
    delay30: Number(document.getElementById("cashDelay30Input")?.value || 30),
    delay45: Number(document.getElementById("cashDelay45Input")?.value || 45)
  };
  company.modifiedAt = new Date().toISOString();
  company.cashControlHistory = [
    ...(company.cashControlHistory || []),
    {
      at: company.modifiedAt,
      by: state.user?.name || "Admin",
      cashOnHand: company.cashOnHand,
      weeklyOverhead: company.weeklyOverhead,
      minimumCashThreshold: company.minimumCashThreshold,
      cashScenarioDelays: { ...company.cashScenarioDelays },
      previous: before,
      notes: "Admin updated cash forecast control assumptions."
    }
  ];
  appendAuditLocal("settings.cash-controls", {
    by: state.user?.name || "Admin",
    cashOnHand: company.cashOnHand,
    weeklyOverhead: company.weeklyOverhead,
    minimumCashThreshold: company.minimumCashThreshold,
    cashScenarioDelays: company.cashScenarioDelays
  });
  persist("Cash controls updated");
  const serverCompany = await saveCashControlsApi(company, before);
  if (serverCompany) {
    state.data.company = serverCompany;
    persist("Cash controls updated on server");
  }
  render();
}

