function handleCrewTimeConfirm(entryId) {
  const entry = (state.data.timeEntries || []).find(item => item.id === entryId);
  if (!entry) return;
  const ownsEntry = state.role !== "Crew Member" || entry.employee === state.user?.name || entry.employeeId === state.user?.personId || entry.employeeId === state.user?.id;
  if (!ownsEntry) {
    alert("Crew members can only confirm their own time.");
    return;
  }
  const exceptionNote = prompt("Time exception note", entry.crewExceptionNote || "No exception") || "No exception";
  const now = new Date().toISOString();
  entry.crewConfirmationStatus = "Confirmed";
  entry.crewConfirmedBy = state.user?.name || entry.employee;
  entry.crewConfirmedAt = now;
  entry.crewExceptionNote = exceptionNote.trim();
  entry.notes = appendInlineNote(entry.notes, `Crew confirmed time: ${entry.crewExceptionNote}.`);
  entry.activityLog = [...(entry.activityLog || []), { at: now, by: state.user?.name || entry.employee, note: `Time confirmed. Exception: ${entry.crewExceptionNote}.` }];
  entry.modifiedAt = now;
  appendAuditLocal("time.crew-confirmed", { entry: entry.id, project: entry.project, by: entry.crewConfirmedBy });
  persist("Crew time confirmed");
  void saveToApi("timeEntries", entry, false);
  render();
}

