function handleGuidedSquanPacketBuild(projectId) {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return;
  const gate = billingPackageBuildGate(project);
  if (!gate.ready) {
    const tasks = createPackageBuildBlockerTasks(project, gate);
    appendAuditLocal("billing.guided-packet-build-blocked", { project: project.id, blockers: gate.blockers.map(item => item.label), tasks: tasks.map(task => task.id), by: state.user?.name || "Billing" });
    persist("Guided SQUAN packet build created blocker tasks");
    render();
    return;
  }
  if (!packageBuildApprovalStatus(project).approved) {
    const amounts = projectBillingAmounts(project);
    const now = new Date().toISOString();
    project.adminApprovals = project.adminApprovals || {};
    project.adminApprovals.packageBuild = {
      status: "Approved",
      by: state.user?.name || "Billing",
      at: now,
      reason: `Approved from guided SQUAN packet builder. Billable ${currency(amounts.gross)}; retainage ${currency(amounts.retainage)}.`
    };
    project.approvalLog = [...(project.approvalLog || []), {
      decision: "guided-squan-packet-build-approval",
      status: "Approved",
      by: state.user?.name || "Billing",
      at: now,
      reason: project.adminApprovals.packageBuild.reason
    }];
    project.modifiedAt = now;
    void saveToApi("projects", project, false);
  }
  prepareSquanPackage(project);
}

