function recomputeProjectLocal(projectId) {
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return null;
  if (project.baseActualCost === undefined) project.baseActualCost = Number(project.actualCost || 0);
  (state.data.projectUnits || [])
    .filter(unit => unit.project === projectId)
    .forEach(unit => {
      unit.completedQuantity = sum((state.data.dailyProduction || []).filter(line => {
        if (line.project !== projectId || line.unitCode !== unit.unitCode) return false;
        return line.source !== "ArcGIS Field Maps import" || line.reviewStatus === "Accepted";
      }), "quantity");
      unit.billableQuantity = Math.max(0, Number(unit.completedQuantity || 0) - Number(unit.previouslyBilledQuantity || 0));
      unit.modifiedAt = new Date().toISOString();
    });
  const laborCost = (state.data.dailyLabor || [])
    .filter(line => line.project === projectId)
    .reduce((total, line) => total + Number(line.hours || 0) * Number(line.costRate || 0), 0);
  const equipmentCost = (state.data.dailyEquipment || [])
    .filter(line => line.project === projectId)
    .reduce((total, line) => total + Number(line.hours || 0) * Number(line.rate || 0), 0);
  const materialCost = (state.data.dailyMaterials || [])
    .filter(line => line.project === projectId && line.owner !== "SQUAN")
    .reduce((total, line) => total + Number(line.quantity || 0) * Number(line.unitCost || 0), 0);
  project.actualCost = Math.round(Number(project.baseActualCost || 0) + laborCost + equipmentCost + materialCost);
  project.forecastCost = Math.max(Number(project.forecastCost || 0), project.actualCost);
  project.modifiedAt = new Date().toISOString();
  recomputeBillingReadinessLocal(projectId);
  return project;
}

function recomputeBillingReadinessLocal(projectId) {
  state.data.billingReadiness = state.data.billingReadiness || [];
  const project = (state.data.projects || []).find(item => item.id === projectId);
  if (!project) return null;
  const rule = (state.data.contractRules || []).find(item => item.customer === project.customer) || {};
  const submittedDailies = (state.data.dailies || []).filter(daily => daily.project === projectId && daily.status === "Submitted");
  const dailyHandoff = dailyBillingHandoffStatus(project);
  const acceptedCaptures = acceptedFieldCaptureEvidence(project);
  const projectUnits = (state.data.projectUnits || []).filter(unit => unit.project === projectId);
  const documents = (state.data.documents || []).filter(item => item.project === projectId);
  const qcCloseouts = (state.data.qcCloseouts || []).filter(item => item.project === projectId);
  const openObstacles = (state.data.obstacles || []).filter(item => item.project === projectId && isOpenObstacle(item));
  const gisEvidence = fieldMapsEvidenceStatus(project);
  const billableAmount = projectUnits.reduce((total, unit) => total + Number(unit.billableQuantity || 0) * Number(unit.unitPrice || 0), 0);
  const dailyAccepted = ["Accepted", "Used for Billing"].includes(dailyHandoff.status);
  const docs = `${project.docs || ""} ${documents.map(item => `${item.type} ${item.name} ${item.status}`).join(" ")}`.toLowerCase();
  const requiredDocs = String(rule.requiredInvoiceDocs || "dailies, SOT, photos, as-builts")
    .split(",")
    .map(item => item.trim().toLowerCase())
    .filter(Boolean);
  const checks = {
    daily: !requiredDocs.includes("dailies") || dailyHandoff.ready,
    sot: !requiredDocs.includes("sot") || (dailyAccepted && (documents.some(item => item.type === "SOT" && item.status === "Submitted") || submittedDailies.some(daily => daily.id === dailyHandoff.daily?.id && String(daily.output || "").toLowerCase().includes("sot")))),
    photos: !requiredDocs.includes("photos") || (dailyAccepted && dailyHandoff.evidenceCounts.photos > 0) || acceptedCaptures.photos.length > 0,
    gis: ["Accepted", "Ready"].includes(gisEvidence.status),
    asBuilts: !requiredDocs.includes("as-builts") || docs.includes("as-built") || docs.includes("asbuilt") || acceptedCaptures.markups.length > 0,
    qc: !requiredDocs.includes("qc closeout") || qcCloseouts.some(item => item.status === "Passed" || item.status === "Approved Exception"),
    obstacles: openObstacles.length === 0
  };
  const missingItems = Object.entries(checks)
    .filter(([, ok]) => !ok)
    .map(([key]) => ({
      daily: dailyHandoff.blockers.join(", ") || "accepted daily",
      sot: "SOT",
      photos: "photos",
      gis: "ArcGIS Field Maps handoff",
      asBuilts: "as-builts",
      qc: "QC closeout",
      obstacles: "open site obstacles"
    }[key]));
  const daysLeft = daysUntil(project.billBy);
  const status = billableAmount <= 0
    ? "Not Ready"
    : daysLeft !== null && daysLeft < 0
      ? "Overdue / Forfeiture Risk"
      : missingItems.length
      ? "Blocked"
      : daysLeft !== null && daysLeft <= 3
        ? "3 Days Left"
        : daysLeft !== null && daysLeft <= 7
          ? "7 Days Left"
          : "Ready to Bill";
  const next = {
    id: `BR-${projectId}`,
    project: projectId,
    status,
    billableAmount: Math.round(billableAmount),
    missingItems: missingItems.join(", ") || "None",
    billingDeadline: project.billBy,
    daysLeft,
    submittedDailies: submittedDailies.length,
    dailyReviewStatus: dailyHandoff.status,
    dailyReviewDailyId: dailyHandoff.daily?.id || "",
    dailyReviewBlockers: dailyHandoff.blockers.join(", "),
    retainagePercent: Number(rule.retainagePercent || 10),
    payWhenPaid: rule.payWhenPaid === "Yes" ? "Required" : "Not required",
    updatedAt: new Date().toISOString(),
    notes: `Billing readiness recomputed from accepted field daily evidence. Daily review: ${dailyHandoff.status}. Missing: ${missingItems.join(", ") || "None"}.`,
    activityLog: [],
    createdAt: new Date().toISOString(),
    modifiedAt: new Date().toISOString(),
    owner: "Office Billing"
  };
  const index = state.data.billingReadiness.findIndex(item => item.project === projectId);
  if (index === -1) state.data.billingReadiness.push(next);
  else state.data.billingReadiness[index] = { ...state.data.billingReadiness[index], ...next };
  reconcilePackageBuildGateTasks(project, billingPackageBuildGate(project));
  return next;
}

render();
syncFromApi();
